window.BANK_MAINTAIN = {"direction":"maintain","title":"维保方向","chapters":[{"name":"维保方向 · 单选题","type":"single","questions":[{"id":"ms-0001","type":"single","question":"消防应急广播发生敌障时,能在( )s内发出故障声、光信号。","options":[{"value":"A","text":"30","isCorrect":false},{"value":"B","text":"60","isCorrect":false},{"value":"C","text":"80","isCorrect":false},{"value":"D","text":"100","isCorrect":true}],"answer":"D","explanation":"消防应急广播发生故障时,能在100s内发出故障声、光信号。"},{"id":"ms-0002","type":"single","question":"( )是主要的消防水源","options":[{"value":"A","text":"天然水源","isCorrect":false},{"value":"B","text":"消防水池","isCorrect":false},{"value":"C","text":"高位消防水箱高位滑防水相","isCorrect":false},{"value":"D","text":"市政给水","isCorrect":true}],"answer":"D","explanation":"消防水源是指向水灭火设施、车载或手抬等移动消防水泵、固定消防水泵等提供消防用水的水源,是灭火成功的基本保证。消防水源有市政给水、消防水池、天然水源三类。其中,市政给水是主要的消防水源。结合题意,本题应选\"市政给水”,其他项均可排除。"},{"id":"ms-0003","type":"single","question":"无遮挡的大空间或有特殊要求的房间,宜选择( )火灾探测器。","options":[{"value":"A","text":"线型缆式感温","isCorrect":false},{"value":"B","text":"线型光纤感温","isCorrect":false},{"value":"C","text":"线型定温","isCorrect":false},{"value":"D","text":"线型光束感烟","isCorrect":true}],"answer":"D","explanation":"无遮挡的大空间或有特殊要求的房间,宜选择线型光束感烟火灾探测器。"},{"id":"ms-0004","type":"single","question":"( )是电气火灾监控系统的核心控制单元。","options":[{"value":"A","text":"电流互感器","isCorrect":false},{"value":"B","text":"电气火灾监控设备","isCorrect":true},{"value":"C","text":"图形显示装置","isCorrect":false},{"value":"D","text":"电气火灾探测器","isCorrect":false}],"answer":"B","explanation":"中气以监控设多具电气以收控系统的核心电气火灾监控设备是电气火灾监控系统的核心控制单元。"},{"id":"ms-0005","type":"single","question":"对于采用( )消防给水系统的高层或多层建筑,当高位消防水箱的设置不能满足系统最不利点处的静压要求时,应在建筑消防给水系统中设置增（稳）压设施,并采取配套设置气压罐等防止稳压泵频繁启停的技术措施。","options":[{"value":"A","text":"高压","isCorrect":false},{"value":"B","text":"临时高压","isCorrect":true},{"value":"C","text":"低压","isCorrect":false},{"value":"D","text":"常压","isCorrect":false}],"answer":"B","explanation":"对于采用临时高压消防给水系统的高层或多层建筑,当高位消防水箱的设置不能满足系统最不利点处的静压要求时,应在建筑消防给水系统中设置增(稳)压设施,并采取配套设置气压罐等防止稳压泵频繁启停的技术措施。"},{"id":"ms-0006","type":"single","question":"准工作状态时配水管道内充满用于启动系统的有压水的自动喷水灭火系统是（）。","options":[{"value":"A","text":"干式系统","isCorrect":false},{"value":"B","text":"湿式系统","isCorrect":true},{"value":"C","text":"水幕系统","isCorrect":false},{"value":"D","text":"预作用系统","isCorrect":false}],"answer":"B","explanation":"准工作状态时配水管道内充满用于启动系统的有压水的自动喷水灭火系统是湿式系统。"},{"id":"ms-0007","type":"single","question":"复制功能的快捷组合键是( )。","options":[{"value":"A","text":"“Ctrl”+“C”","isCorrect":true},{"value":"B","text":"“Ctrl”+“V”","isCorrect":false},{"value":"C","text":"“Ctrl”+“X”","isCorrect":false},{"value":"D","text":"“Ctrl”+“Z”","isCorrect":false}],"answer":"A","explanation":"“复制”的快捷键为【Ctrl】+【C】键，“粘贴”的快捷键为【Ctrl】+【V】键，“移动（或剪切）”的快捷键为【Ctrl】+【X】键，“全选”的快捷键为【Ctrl】+【A】键。结合题意，本题应选【Ctrl】+【C】键，其他项均可排除。"},{"id":"ms-0008","type":"single","question":"下列不属于文字处理软件的是 （）。","options":[{"value":"A","text":"WPS","isCorrect":false},{"value":"B","text":"WORD","isCorrect":false},{"value":"C","text":"WinRAR","isCorrect":true},{"value":"D","text":"Office","isCorrect":false}],"answer":"C","explanation":"WinRAR属于压缩软件。"},{"id":"ms-0009","type":"single","question":"( )是在特定的职业范围内从事某种职业的人们必须共同遵守的行为准则。","options":[{"value":"A","text":"职业规范","isCorrect":false},{"value":"B","text":"职业纪律","isCorrect":true},{"value":"C","text":"职业准则","isCorrect":false},{"value":"D","text":"职业道德","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材5页。职业纪律是在特定的职业范围内从事某种职业的人们必须共同遵守的行为准则。"},{"id":"ms-0010","type":"single","question":"在湿式和干式自动喷水灭火系统中,()担负着探测火灾、启动系统和喷水灭火的任务。","options":[{"value":"A","text":"开式喷头","isCorrect":false},{"value":"B","text":"闭式喷头","isCorrect":true},{"value":"C","text":"水流指示器","isCorrect":false},{"value":"D","text":"火灾探测器","isCorrect":false}],"answer":"B","explanation":"在湿式和干式自动喷水灭火系统中,闭式喷头担负着探测火灾、启动系统和喷水灭火的任务。"},{"id":"ms-0011","type":"single","question":"通过手动开启排烟阀(排烟口)联动启动排烟风机，应先确认排烟风机电气控制柜处于（）运行模式,同时进入消防联动控制器的（）操作权限。","options":[{"value":"A","text":"自动,自动允许","isCorrect":true},{"value":"B","text":"自动,自动禁止","isCorrect":false},{"value":"C","text":"手动,手动允许","isCorrect":false},{"value":"D","text":"手动,手动禁止","isCorrect":false}],"answer":"A","explanation":"手动开启排烟阀联动启动排烟风(排烟口)联动启动排烟风机:(1)设置排烟风机电气控制柜和消防联动控制器控制状态确认排烟风机电气控制柜处于\"自动\"运行模式,同时进入消防联动控制器的“自动允许\"操作权限。"},{"id":"ms-0012","type":"single","question":"根据《建筑防烟排烟系统技术标准》(GB51251-2017)的规定,应当（）对全部防烟、排烟系统进行一次联动试验和性能检测。","options":[{"value":"A","text":"每月","isCorrect":false},{"value":"B","text":"每季度","isCorrect":false},{"value":"C","text":"每半年","isCorrect":false},{"value":"D","text":"每年","isCorrect":true}],"answer":"D","explanation":"中级223页,根据中级223页,根据《建筑防烟排烟系统技术标《建筑防烟排烟系统技术标立怎年对时合部ECDF1OF2017购规准)(GB51251一2017)的规定,应当每年对全部防烟排烟系统进行一次联动试验和性能检测。"},{"id":"ms-0013","type":"single","question":"下列场所或部位应采取排烟等烟气控制措施的是（）。","options":[{"value":"A","text":"建筑高度为36m的厂房内长度为24m的疏散走道","isCorrect":true},{"value":"B","text":"占地面积为900m²的木器仓库","isCorrect":false},{"value":"C","text":"建筑面积为3000m²的陶瓷烘干车间","isCorrect":false},{"value":"D","text":"建筑面积50mm²的地下或半地下丙类生产场所","isCorrect":false}],"answer":"A","explanation":"厂房或仓库的下列场所或部位应设置排烟设施:人员或可燃物较多的丙类生产场所，丙类厂房内建筑面积大于300m2且经常有人停留或可燃物较多的地上房间;建筑面积大于5000m²的丁类生产车间;占地面积大于1000m²的丙类仓库;高度大于32m的高层。"},{"id":"ms-0014","type":"single","question":"《中华人民共和国劳动法》实行的时间为()","options":[{"value":"A","text":"1995年7月5日","isCorrect":false},{"value":"B","text":"1995年1月1日","isCorrect":true},{"value":"C","text":"1994年7月5日","isCorrect":false},{"value":"D","text":"1994年1月1日","isCorrect":false}],"answer":"B","explanation":"从狭义上讲,劳动法是指1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过,自1995年1月1日起施行的《中华人民共和2019年1国劳动法》(2009年8月27日修正,2018年12月29日第二次修正)"},{"id":"ms-0015","type":"single","question":"打开计算机的任何一个窗口发现的最基本的元素是()。","options":[{"value":"A","text":"快捷方式","isCorrect":false},{"value":"B","text":"文件夹","isCorrect":false},{"value":"C","text":"文件","isCorrect":true},{"value":"D","text":"文字","isCorrect":false}],"answer":"C","explanation":"打开计算机的任何一个窗口发现的最基本的元素是文件。"},{"id":"ms-0016","type":"single","question":"当线型光束感烟火灭探测器光路上出现烟雾时，会使到达接收器的信号（）。","options":[{"value":"A","text":"增强","isCorrect":false},{"value":"B","text":"减弱","isCorrect":true},{"value":"C","text":"c消失","isCorrect":false},{"value":"D","text":"减半","isCorrect":false}],"answer":"B","explanation":"当线型光束感烟火灾探测器光路上出现烟雾时,会使到达接收器的信号减弱。"},{"id":"ms-0017","type":"single","question":"楼层标志灯配电、通信线路的连接应采用()密封。","options":[{"value":"A","text":"密封环","isCorrect":false},{"value":"B","text":"密封圈","isCorrect":false},{"value":"C","text":"密封胶","isCorrect":true},{"value":"D","text":"密封片","isCorrect":false}],"answer":"C","explanation":"楼层标志灯配电、通信线路的连接应采用密封胶密封。"},{"id":"ms-0018","type":"single","question":"组装式水泵接合器的安装,应按()的顺序进行。①控制阀②止回阀③安全阀④放空管⑤连接管⑥本体⑦接口。","options":[{"value":"A","text":"⑦⑥④②③⑤①","isCorrect":false},{"value":"B","text":"⑦⑥③②⑤④①","isCorrect":false},{"value":"C","text":"⑦⑥⑤①②③④","isCorrect":false},{"value":"D","text":"⑦⑥⑤②③④①","isCorrect":true}],"answer":"D","explanation":"组装式消防水泵接合器的安装,应按接口、本体、联接管、止回阀、安全阀、放空管、控制阀的顺序进行,止回阀的安装方向应使消防用水能从消防水泵接合器进入系统;整体式消防水泵接合器的安装,按其使用安装说明书进行。"},{"id":"ms-0019","type":"single","question":"下列属于活动式防火分隔设施的是（）。","options":[{"value":"A","text":"楼板","isCorrect":false},{"value":"B","text":"防火墙","isCorrect":false},{"value":"C","text":"防火隔墙","isCorrect":false},{"value":"D","text":"防火卷帘","isCorrect":true}],"answer":"D","explanation":"防火卷帘属于活动式防火分隔设施。"},{"id":"ms-0020","type":"single","question":"感光火灾探测器又称为（）。","options":[{"value":"A","text":"火焰探测器","isCorrect":true},{"value":"B","text":"红外光束感烟探测器","isCorrect":false},{"value":"C","text":"缆式线型火灾探测器","isCorrect":false},{"value":"D","text":"点型火灾探测器","isCorrect":false}],"answer":"A","explanation":"感光火灾探测器又称为火焰探测器。"},{"id":"ms-0021","type":"single","question":"灭灭时,需将()的火灭灭剂喷洒到燃烧区域闪,燃烧终止后仍需要采取冷却降温措施,防止火灾复燃。","options":[{"value":"A","text":"少量","isCorrect":false},{"value":"B","text":"适量","isCorrect":false},{"value":"C","text":"足量","isCorrect":true},{"value":"D","text":"大量","isCorrect":false}],"answer":"C","explanation":"需将足量的灭火剂喷洒到燃然烧区域灭火时,需将足量的灭火剂喷洒到燃烧区域内,燃烧终止后仍需要采取冷却降温措施,防止火灾复燃。"},{"id":"ms-0022","type":"single","question":"( )肩负着探测火灾早期特征、发出火灾报警信号,为人员疏散、防止火灾蔓延和启动自动灭火设备提供控制与指示的消防任务。","options":[{"value":"A","text":"火灾探测报警系统","isCorrect":false},{"value":"B","text":"火灾预警系统灭灭预警系统","isCorrect":false},{"value":"C","text":"火灾自动报警系统","isCorrect":true},{"value":"D","text":"消防联动控制系统","isCorrect":false}],"answer":"C","explanation":"火灾自动报警系统肩负着探测火灾早期特征、发出火灾报警信号,为人员疏散、防止火灾蔓延和启动自动灭火设备提供控制与指示的消防任务。系统中的集中火灾报警控制器、消防联动控制器、消防控制室图形显示装置一般应设置在消防控制室内或有人值班的房间和场所。"},{"id":"ms-0023","type":"single","question":"火灾显示盘应能接收与其连接的火灾报警控制器发出的火灾报警信号,并在火灾报警控制器发出火灾报警信号后( )s内发出火灾报警声、光信号,显示火灾发生部位。","options":[{"value":"A","text":"3","isCorrect":true},{"value":"B","text":"10","isCorrect":false},{"value":"C","text":"5","isCorrect":false},{"value":"D","text":"7","isCorrect":false}],"answer":"A","explanation":"火灾显示盘应能接收与其连接的火灾报警控制器发出的以报敬信并在以文报控生制器器发出的火灾报警信号,并在火灾报警控制器发出火灾报警信号后3s内发出火灾报警声、光信号,显示火灾发生部位。故而本题选A。"},{"id":"ms-0024","type":"single","question":"泡沫灭火剂是指泡沫液与水混溶,并通过()或化学反应产生灭火泡沫,用于扑救可燃易燃液体","options":[{"value":"A","text":"化合作用","isCorrect":false},{"value":"B","text":"物理方法","isCorrect":false},{"value":"C","text":"机械方法","isCorrect":true},{"value":"D","text":"皂化作用","isCorrect":false}],"answer":"C","explanation":"泡沫灭火剂是指泡沫液与水混溶,并通过机械方法或化学反应产生灭火泡沫,用于扑救可燃易燃液体的有效灭火剂。"},{"id":"ms-0025","type":"single","question":"模拟消防泵组电气控制柜主电源故障时,应确认双电源转换开关处于（）式,切断主电源,备用电源自投后继续保障正常供电。","options":[{"value":"A","text":"手动运行","isCorrect":false},{"value":"B","text":"自动运行","isCorrect":true},{"value":"C","text":"c通电运行","isCorrect":false},{"value":"D","text":"正常运行","isCorrect":false}],"answer":"B","explanation":"新教材中级技能99页,模拟故障操作,模拟主电源故障。检查确认双电源转换开关处于自动运行模式,切断主电源,观察备用电源,应能自动继续保障正常供电。"},{"id":"ms-0026","type":"single","question":"不能使用防火墙分隔的开口部位宜设置（）。","options":[{"value":"A","text":"干式系统","isCorrect":false},{"value":"B","text":"湿式系统","isCorrect":false},{"value":"C","text":"水幕系统","isCorrect":true},{"value":"D","text":"雨淋系统","isCorrect":false}],"answer":"C","explanation":"不能使用防火墙分隔的开口部位宜设置水幕系统。"},{"id":"ms-0027","type":"single","question":"在\"控制面板\"窗口中,双击()图标,弹出\"鼠标属性\"对话框。","options":[{"value":"A","text":"属性","isCorrect":false},{"value":"B","text":"鼠标","isCorrect":true},{"value":"C","text":"输入设备","isCorrect":false},{"value":"D","text":"外设","isCorrect":false}],"answer":"B","explanation":"在\"控制面板窗口中,双击鼠标图标,弹出\"鼠标属性\"对话框。"},{"id":"ms-0028","type":"single","question":"消防设备末端配电装置的清扫和检修一般每年至滑防设备木端配电表直的滑扫和检修一一般海年生少()次,其内容除清扫和摇测绝缘外,还应检查各部连接点和接地处的紧固状况,","options":[{"value":"A","text":"四","isCorrect":false},{"value":"B","text":"两","isCorrect":false},{"value":"C","text":"三","isCorrect":false},{"value":"D","text":"一","isCorrect":true}],"answer":"D","explanation":"消防设备未端配电装置的清扫和检修一般每年至少一次,其内容除清扫和摇测绝缘外,还应检查各部连接点和接地处的紧固状况"},{"id":"ms-0029","type":"single","question":"如果友现配电柜有水分存在,应该用()的抹布擦拭干净,保证配电柜在干燥情况下才能通电。","options":[{"value":"A","text":"潮湿","isCorrect":false},{"value":"B","text":"半干","isCorrect":false},{"value":"C","text":"不太湿","isCorrect":false},{"value":"D","text":"干燥","isCorrect":true}],"answer":"D","explanation":"用抹布将壳体及机柜内设备和线材清洁干净,确保表面无污迹。如果发现柜内有水,应该用确保表面无污迹。如果发现柜内有水,应该用干燥的抹布擦拭干净,保证柜体在干燥情况下才能通电。"},{"id":"ms-0030","type":"single","question":"有大量粉尘、水雾滞留的场所不宜选择()火灾探测器。","options":[{"value":"A","text":"线型缆式感温","isCorrect":false},{"value":"B","text":"线型光纤感温","isCorrect":false},{"value":"C","text":"线型光束感烟","isCorrect":true},{"value":"D","text":"线型定温","isCorrect":false}],"answer":"C","explanation":"符合下列条件之一的场所,不宜选择线型光束感烟火灾探测器:1)有大量粉尘、水雾滞留的场所。2)可能产生蒸气和油雾的场所。3)在正常情况下有烟滞留的场所。4)固定探测器的建筑结构由于振动等原因会产生较大位移的场所。"},{"id":"ms-0031","type":"single","question":"任一台应急照明控制器直接控制灯具的总数量不应大于()只。","options":[{"value":"A","text":"2000","isCorrect":false},{"value":"B","text":"2800","isCorrect":false},{"value":"C","text":"3000","isCorrect":false},{"value":"D","text":"3200","isCorrect":true}],"answer":"D","explanation":"任一台应急照明控制器直接控制灯具的总数量不应大于3200只。"},{"id":"ms-0032","type":"single","question":"防火卷帘门机具有依靠防火卷帘自重()下降的功能,可通过控制器速放控制装置在卷门机电源发生故障时启动速放装置。","options":[{"value":"A","text":"低速","isCorrect":false},{"value":"B","text":"高速","isCorrect":false},{"value":"C","text":"恒速","isCorrect":true},{"value":"D","text":"急速","isCorrect":false}],"answer":"C","explanation":"防火卷帘卷门机具有依靠防火卷帘自重恒速下降的功能,可通过控制器速放控制装置在卷门机电源发生故障时启动速放装置,或人工拉动手动速放装置(钢丝绳拉环),使防火卷帘依靠自重下降。"},{"id":"ms-0033","type":"single","question":"消防应急灯具按()分类可分为自带电源型滑防应急灯具、集中电源型消防应急灯具、子母型消防应急灯具。","options":[{"value":"A","text":"工作方式","isCorrect":false},{"value":"B","text":"应急供电方式","isCorrect":true},{"value":"C","text":"应急控制方式","isCorrect":false},{"value":"D","text":"用途","isCorrect":false}],"answer":"B","explanation":"消防应急灯具按应急供电方式可分为自带电源型消防应急灯具、集中电源型消防应急灯具、子母型消防应急灯具。"},{"id":"ms-0034","type":"single","question":"要求灭火后必须及时停止喷水,减少不必要水渍损失的场所宜设置（）。","options":[{"value":"A","text":"干式系统","isCorrect":false},{"value":"B","text":"湿式系统","isCorrect":false},{"value":"C","text":"预作用系统","isCorrect":false},{"value":"D","text":"重复启闭预作用","isCorrect":true}],"answer":"D","explanation":"要求灭火后必须及时停止喷水,减少不必要水渍损失的场所宜设置重复启闭预作用系统。"},{"id":"ms-0035","type":"single","question":"（）不具备直接灭火的能力,主要用于火灾发生时阻隔火势蔓延及热扩散。","options":[{"value":"A","text":"干式系统","isCorrect":false},{"value":"B","text":"湿式系统","isCorrect":false},{"value":"C","text":"水幕系统","isCorrect":true},{"value":"D","text":"雨淋系统","isCorrect":false}],"answer":"C","explanation":"水幕系统不具备直接灭火的能力,主要用于火灾发生时阻隔火势蔓延及热扩散。"},{"id":"ms-0036","type":"single","question":"机械加压送风系统的风道应采用()材料制作,且宜优先采用光滑管道,不宜采用土建井道。","options":[{"value":"A","text":"难燃","isCorrect":false},{"value":"B","text":"不燃","isCorrect":true},{"value":"C","text":"易燃","isCorrect":false},{"value":"D","text":"可燃","isCorrect":false}],"answer":"B","explanation":"机械加压送风系统的风道应采用不燃材料制作,且宜优先采用光滑管道,不宜采用土建井道。"},{"id":"ms-0037","type":"single","question":"收到消防电话分机呼叫时,消防电话总机在()s内发出声、光呼叫指示信号,指示该消防电话分机为呼叫状态,声指示信号能手动消除。","options":[{"value":"A","text":"5","isCorrect":false},{"value":"B","text":"10","isCorrect":false},{"value":"C","text":"3","isCorrect":true},{"value":"D","text":"6","isCorrect":false}],"answer":"C","explanation":"收到消防电话分机呼叫时,消防电话总机在3s内发出声、光呼叫指示信号指示该消防电话分机为呼叫状态,声指示信号能手动消除。"},{"id":"ms-0038","type":"single","question":"集中火火报警控制器信息显示按火火报警、监管报警及其他状态顺序()排列信息显示等级。","options":[{"value":"A","text":"由低至高","isCorrect":false},{"value":"B","text":"由高至低","isCorrect":true},{"value":"C","text":"按时间先后","isCorrect":false},{"value":"D","text":"按影响大小","isCorrect":false}],"answer":"B","explanation":"集中火灾报警控制器信息显示按火灾报警、监管报警及其他状态顺序由高至低排列信息显示等级。结合题意,本题选B。"},{"id":"ms-0039","type":"single","question":"关闭电气火灾监控设备主电源,电气火灾监控设备处于()状态。","options":[{"value":"A","text":"主、备电源故障","isCorrect":false},{"value":"B","text":"主电工作,备电故障","isCorrect":false},{"value":"C","text":"主备电同时工作","isCorrect":false},{"value":"D","text":"主电故障,备电工作","isCorrect":true}],"answer":"D","explanation":"关闭电气火灾监控设备主电源,电气火灾监控设备处于主电故障,备电工作状态。"},{"id":"ms-0040","type":"single","question":"下列关于排烟防火阀的工作情况说法错误的是","options":[{"value":"A","text":"排烟防火阀外观完整,无变形、损坏","isCorrect":false},{"value":"B","text":"产品标识清晰,安装方向与排烟方向相反","isCorrect":true},{"value":"C","text":"执行机构操作灵活,无卡滞和阻碍","isCorrect":false},{"value":"D","text":"排烟防火阀关闭和复位功能正常,连锁停止排烟风机功能正常,启闭过程中无明显晃动","isCorrect":false}],"answer":"B","explanation":"产品标识清晰,安装方向应与排烟方向一致。"},{"id":"ms-0041","type":"single","question":"公民道德建设要做到()个坚持。","options":[{"value":"A","text":"5","isCorrect":false},{"value":"B","text":"4","isCorrect":false},{"value":"C","text":"3","isCorrect":false},{"value":"D","text":"6","isCorrect":true}],"answer":"D","explanation":"(1) 坚持马克思主义道德观、社会主义道德观,倡导共产主义道德,以为人民服务为核心,以集体主义为原则,以爱祖国、爱人民、爱劳动、爱科学、爱社会主义为基本要求,始终保持公民道德建设的社会主义方向。 (2) 坚持以社会主义核心价值观为引领,将国家、社会、个人层面的价值要求 贯穿于道德建设各方面,以主流价值建构道德规范、强化道德认同、指引道德实践引导人们明大德守公德严秋引道德实践,引导人们明大德、守公德、严私德。 (3) 坚持在继承传统中创新发展,自觉传承中华传统美德,继承我们党领导人......"},{"id":"ms-0042","type":"single","question":"应急照明控制器设置在消防控制室地面上时,设备面板至墙的距离不应小于()m。","options":[{"value":"A","text":"2.5","isCorrect":false},{"value":"B","text":"1.5","isCorrect":false},{"value":"C","text":"3","isCorrect":true},{"value":"D","text":"2","isCorrect":false}],"answer":"C","explanation":"应急照明控制器的设置应符合下列规定。2.在消防控制室地面上设置时,应符合下列规定:(2)在值班人员经常工作的一面,设备面板至墙的距离不应小于3m。"},{"id":"ms-0043","type":"single","question":"总线控制盘操作面板上设有多个手动控制单元，每个单元包括( )个操作按钮和( )个状态指示灯，每个操作按钮均可通过逻辑编程实现对各类、各分区、各具体设备的控制。","options":[{"value":"A","text":"一、两","isCorrect":true},{"value":"B","text":"两、两","isCorrect":false},{"value":"C","text":"两、一","isCorrect":false},{"value":"D","text":"一、一","isCorrect":false}],"answer":"A","explanation":"火灾报警控制器（联动型）总线控制盘操作面板上设有多个手动控制单元，每个单元包括一个操作按钮和两个状态指示灯，每个操作按钮分别对应一个启动指示灯和一个反馈指示灯，分别用于提示按钮状态、显示设备运行状态。"},{"id":"ms-0044","type":"single","question":"依据《中华人民共和国消防法》(以下简称《消防法》)的规定,()对全国的消防工作实施监监督管理。","options":[{"value":"A","text":"公安部门","isCorrect":false},{"value":"B","text":"国务院应急管理部门","isCorrect":true},{"value":"C","text":"各级地方政府","isCorrect":false},{"value":"D","text":"人力资源和社会保障部门","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材9页。依据《中华人民共和国消防法》的规定,国务院应急管理部门对全国的消防工作实施监督管理。"},{"id":"ms-0045","type":"single","question":"水系灭火剂是指由水、渗透剂、()以及其他添加剂组成,一般以液滴或以液滴和泡沫混合的形式灭火的液体灭火剂。","options":[{"value":"A","text":"挥发剂","isCorrect":false},{"value":"B","text":"阻燃剂","isCorrect":true},{"value":"C","text":"沉降物","isCorrect":false},{"value":"D","text":"吸附物","isCorrect":false}],"answer":"B","explanation":"水系灭火剂是指由水、渗透剂、阻燃剂以及其他添加剂组成,一般以液滴或以液滴和泡沫混合的形式灭火的液体灭火剂。"},{"id":"ms-0046","type":"single","question":"根据所安装喷头的(),自动喷水灭火系统可分为闭式系统和开式系统两大类。","options":[{"value":"A","text":"结构形式","isCorrect":true},{"value":"B","text":"动作温度","isCorrect":false},{"value":"C","text":"安装形式","isCorrect":false},{"value":"D","text":"适用范围","isCorrect":false}],"answer":"A","explanation":"根据所安装喷头的结构形式,自动喷水灭火系统可分为闭式系统和开式系统两大类。"},{"id":"ms-0047","type":"single","question":"\"单位全面负责\"是做好消防工作的( )。","options":[{"value":"A","text":"核心","isCorrect":false},{"value":"B","text":"关键","isCorrect":false},{"value":"C","text":"根本","isCorrect":true},{"value":"D","text":"基础","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材11页。“政府统一领导\"是做好消防工作的核心;“部门依法监管“是做好消防工作的关键;“单位全面负责\"是做好消防工作的根本;“公民积极参与\"是做好消防工作的基础。"},{"id":"ms-0048","type":"single","question":"由水源、供水设备、管道、雨淋报警阀（或电动控制阀、气动控制阀）、过滤器和水雾喷头等组成,向保护对象喷射水雾进行灭火或防护冷却的系统是（）","options":[{"value":"A","text":"雨淋系统","isCorrect":false},{"value":"B","text":"细水雾灭火系统","isCorrect":false},{"value":"C","text":"水喷雾灭火系统","isCorrect":true},{"value":"D","text":"泡沫一水喷淋灭火系统","isCorrect":false}],"answer":"C","explanation":"本题所述为水喷雾灭火系统的定义。水雾喷头在较高的水压力作用下，将水流分离成0.2~2mm甚至更小的细小水雾滴，通过表面冷却、室息、稀释、冲击乳化和覆盖等作用实现灭火。结合题意，本题应选”水喷雾灭火系统”，其他项均可排除。"},{"id":"ms-0049","type":"single","question":"应急照明控制器接收到火灾报警控制器的火警信号后，应在（）s内发出系统自动应急启动信号，控制应急启动输出干接点动作，发出启动声光信号，显示并记录系统应急启动类型和系统应急启动时间。","options":[{"value":"A","text":"2","isCorrect":false},{"value":"B","text":"5","isCorrect":false},{"value":"C","text":"3","isCorrect":true},{"value":"D","text":"6","isCorrect":false}],"answer":"C","explanation":"应急照明控制器接收到火灾报警控制器的火警信号后,应在3s内发出系统自动应急启动信号,控制应急启动输出干接点动作,发出启动声光信号,显示并记录系统应急启动类型和系统应急启动时间。"},{"id":"ms-0050","type":"single","question":"消防电话通话期间有新的分机呼叫时,总机（）。","options":[{"value":"A","text":"发出振铃声响","isCorrect":false},{"value":"B","text":"发出声、光报警","isCorrect":false},{"value":"C","text":"面板上该分机对应部位指示灯闪亮","isCorrect":true},{"value":"D","text":"面板上该分机对应部位指示灯常亮","isCorrect":false}],"answer":"C","explanation":"中级33页,当通话期间有新的分机呼叫时,总机面板上该分机对应部位指示灯闪亮,但无振铃声响信号。"},{"id":"ms-0051","type":"single","question":"保养报警阀组时,应检查延迟器的（）,防止异物堵塞影响功能","options":[{"value":"A","text":"漏水接头","isCorrect":true},{"value":"B","text":"阀门","isCorrect":false},{"value":"C","text":"过滤器","isCorrect":false},{"value":"D","text":"管路","isCorrect":false}],"answer":"A","explanation":"中级103页,检查湿式系统延迟器的漏水接头,必要时进行清洗,防止异物堵塞,保证其畅通。"},{"id":"ms-0052","type":"single","question":"通过现场手动按钮启动防火卷帘,应将手动按钮盒的锁定开关设置在（）位置。","options":[{"value":"A","text":"开启","isCorrect":true},{"value":"B","text":"关闭","isCorrect":false},{"value":"C","text":"上升","isCorrect":false},{"value":"D","text":"下降","isCorrect":false}],"answer":"A","explanation":"中级166页,通过现场手动按钮启动防火卷帘应将手动按钮盒的锁定开关设置在开启位置。"},{"id":"ms-0053","type":"single","question":"下列工业建筑耐火等级应为一级的是()。","options":[{"value":"A","text":"丁类物流建筑","isCorrect":false},{"value":"B","text":"多层丁类仓库","isCorrect":false},{"value":"C","text":"建筑高度为54m的高层厂房","isCorrect":true},{"value":"D","text":"多层丁类厂房","isCorrect":false}],"answer":"C","explanation":"(1)基础知识47页,下列工业建筑的耐火等级应为一级:1)建筑高度大于50m的高层厂房。2)建筑高度大于32m的高层丙类仓库,储存可燃然液体的多层丙类仓库,每个防火分隔间建筑面积大于3000m²的其他多层丙类仓库。3)类飞机库。"},{"id":"ms-0054","type":"single","question":"喷头是自动喷水灭火系统的主要组件之一,根据其灵敏性,响应时间指数RTI≤50(m·s)^0.5的喷头属于( )。","options":[{"value":"A","text":"标准响应喷头","isCorrect":false},{"value":"B","text":"早期抑制快速响应喷头","isCorrect":false},{"value":"C","text":"快速响应喷头","isCorrect":true},{"value":"D","text":"特殊响应喷头","isCorrect":false}],"answer":"C","explanation":"基础知识92页,RTI≤50(m·s)0.5属于快速响应喷头; 50(ms)^0.5<RTI≤80(ms)^0.5属于特殊响应喷头;80(ms)^0.5<RTI≤350(m.s)^0.5属于标准响应喷头。"},{"id":"ms-0055","type":"single","question":"用减光率为()的减光片遮挡光路,检查线型光束感烟火灾探测器是否发出火灾报警信号。","options":[{"value":"A","text":"0.9dB/m","isCorrect":false},{"value":"B","text":"1.0dB/m","isCorrect":false},{"value":"C","text":"10.0dB/m","isCorrect":true},{"value":"D","text":"11.5dB/m","isCorrect":false}],"answer":"C","explanation":"中级技能36页,采用减光率为10.0dB的减光片测试线型光束感烟火灾探测器的报警功能。"},{"id":"ms-0056","type":"single","question":"下列民用建筑耐火等级应为一级的是()。","options":[{"value":"A","text":"建筑高度为48m的办公楼","isCorrect":false},{"value":"B","text":"建筑高度为20m的住宅楼","isCorrect":false},{"value":"C","text":"c建筑高度为22m的教学楼","isCorrect":false},{"value":"D","text":"地下1层营业厅","isCorrect":true}],"answer":"D","explanation":"基础知识47页,地下、半地下建筑(室)的耐火等级应为一级。"},{"id":"ms-0057","type":"single","question":"消防电话系保养后,复检系统通话功能,在消防控制室用消防电话总机与所有消防电话分机、消防电话插孔互相呼叫与通话,消防电话总机同时呼叫不少于()消防电话分机。","options":[{"value":"A","text":"两部","isCorrect":true},{"value":"B","text":"三部","isCorrect":false},{"value":"C","text":"四部","isCorrect":false},{"value":"D","text":"五部","isCorrect":false}],"answer":"A","explanation":"中级46页,在消防控制室用消防电话总机与所有消防电注分机、消防电适活互相呼叫与通话，消防电话总机同时呼叫不少于两部消防电话分机。"},{"id":"ms-0058","type":"single","question":"（）是用来进行系统设置和设备管理的一个工作集。","options":[{"value":"A","text":"桌面","isCorrect":false},{"value":"B","text":"控制面板","isCorrect":true},{"value":"C","text":"任务栏","isCorrect":false},{"value":"D","text":"开始菜单","isCorrect":false}],"answer":"B","explanation":"基础知识156页,控制面板是用来进行系统设置和设备管理的一个工作集"},{"id":"ms-0059","type":"single","question":"机房湿度一般控制在（）之间。","options":[{"value":"A","text":"50%~80%","isCorrect":false},{"value":"B","text":"45%~75%","isCorrect":false},{"value":"C","text":"30%~60%","isCorrect":false},{"value":"D","text":"40%~70%","isCorrect":true}],"answer":"D","explanation":"基础知识144页,计算机机房相对湿度一般控制在40%-70%之间,相对湿度不能过高,否则计算机内的线路板很容易腐蚀,使板卡过早老化。"},{"id":"ms-0060","type":"single","question":"电流通过导体会产生热,这种现象称为电流的（）。","options":[{"value":"A","text":"热效应","isCorrect":true},{"value":"B","text":"磁效应","isCorrect":false},{"value":"C","text":"机械效应","isCorrect":false},{"value":"D","text":"电效应","isCorrect":false}],"answer":"A","explanation":"基础知识66页,电流通过导体会产生热量,这种现象称为电流的热效应。"},{"id":"ms-0061","type":"single","question":"下列不属于火灾显示盘接线保养的保养方法是（）。","options":[{"value":"A","text":"发现螺栓、垫片及配件有生锈现象及时予以更换","isCorrect":false},{"value":"B","text":"用专用清洁工具或者清洁的干软布擦拭","isCorrect":true},{"value":"C","text":"检查接线端子有无松动情况,发现松动应用螺丝刀紧固,确保连接紧密","isCorrect":false},{"value":"D","text":"查线路接头处有无氧化或锈蚀痕迹,若有则应采取防潮、防锈措施,如镀锡和涂抹凡士林等","isCorrect":false}],"answer":"B","explanation":"中级技能166页,火灾显示盘接线保养:(1)检查接线端子有无松动情况,发现松动应用螺丝刀紧固,确保连接紧密检查线路接头处有无氧化或锈蚀痕迹,若有则应采取防潮、防锈措施,如镀锡和涂抹凡士林等(3)发现螺栓、垫片及配件有生锈现象应及时予以更换"},{"id":"ms-0062","type":"single","question":"集中报警系统的控制与显示设备机壳内部和外部清洁保养周期至少是每（）保养一次。","options":[{"value":"A","text":"日","isCorrect":false},{"value":"B","text":"周","isCorrect":false},{"value":"C","text":"月","isCorrect":true},{"value":"D","text":"季度","isCorrect":false}],"answer":"C","explanation":"中级43页,集中报警系统的控制与显示类设备机壳内部和外部清洁保养周期至少是每月保养一次。"},{"id":"ms-0063","type":"single","question":"消防水泵不应设置自动（）的控制功能,应由具有管理权限的工作人员根据火灾扑救情况确定。","options":[{"value":"A","text":"启泵","isCorrect":false},{"value":"B","text":"启动","isCorrect":false},{"value":"C","text":"停泵","isCorrect":true},{"value":"D","text":"启停","isCorrect":false}],"answer":"C","explanation":"中级99页,消防水泵不设自动停泵的控制功能,其停止应由具有管理权限的工作人员根据并通过消防控制室多线控火灰扑救情况确定火灾扑救情况确定,并通过消防控制室多线控制盘上启/停按钮或水泵房消防泵组电气控制柜上的停止按钮手动实施。"},{"id":"ms-0064","type":"single","question":"当系统断电时,挡烟垂壁能自动下降至（）位置。","options":[{"value":"A","text":"设计挡烟工作位置","isCorrect":true},{"value":"B","text":"挡烟工作位置的1/4处","isCorrect":false},{"value":"C","text":"挡烟工作位置的1/3处","isCorrect":false},{"value":"D","text":"挡烟工作位置的1/2处","isCorrect":false}],"answer":"A","explanation":"中级150页,当系统断电时,挡烟垂壁能自动下降至设计位置。"},{"id":"ms-0065","type":"single","question":"机械加压送风系统应当与火灾自动报警系统联动,当某一防火分区内火灾确认后,机械加压送风系统应能在（）s内联动开启该防火分区全部楼梯间的加压送风机。","options":[{"value":"A","text":"5s","isCorrect":false},{"value":"B","text":"15s","isCorrect":true},{"value":"C","text":"30s","isCorrect":false},{"value":"D","text":"60s","isCorrect":false}],"answer":"B","explanation":"中级149页,当确认某一防火分区内发生火灾后,机械加压送风系统应能在15s内联动同时开启该防火分区的全部疏散楼梯间、该防火分区所在着火层及其相邻上下各一层疏散楼梯间及其前室或合用前室的加压送风机。"},{"id":"ms-0066","type":"single","question":"疏散出口门的净宽度不应小于()m。","options":[{"value":"A","text":"0.8","isCorrect":true},{"value":"B","text":"1","isCorrect":false},{"value":"C","text":"1.1","isCorrect":false},{"value":"D","text":"1.2","isCorrect":false}],"answer":"A","explanation":"基础知识58页,(1)疏散出口门的净宽度不应(1)疏散出口门的净宽度不应小于0.80m。2)住宅建筑中直通室外地面的住宅户门的净宽度不应小于0.80m。3)首层疏散外门净宽度不应小于1.1m。"},{"id":"ms-0067","type":"single","question":"泡沫系统由于具保护对家的特性或储罐形式的特殊要求等,有多种分类形式，下列属于按系统形式分类的是（）。","options":[{"value":"A","text":"中倍数泡沫灭火系统","isCorrect":false},{"value":"B","text":"液下喷射系统","isCorrect":false},{"value":"C","text":"全淹没系统","isCorrect":true},{"value":"D","text":"固定式系统","isCorrect":false}],"answer":"C","explanation":"基础知识97页,泡沫系统按系统形式分类分为全淹没系统、局部应用系统、移动系统、泡沫-水喷淋系统、泡沫喷雾系统。"},{"id":"ms-0068","type":"single","question":"下列关于自动喷水灭火系统适用范围的说法中错误的是（）。","options":[{"value":"A","text":"湿式系统适合在环境温度不低于4°C且不高A于70°C的环境中使用","isCorrect":false},{"value":"B","text":"严禁系统误喷的忌水场所应采用预作用系统","isCorrect":false},{"value":"C","text":"室内净空高度超过一定高度,且必须迅速扑救的初期火灾和属于中危险级II级及以上的场所应采用雨淋系统","isCorrect":true},{"value":"D","text":"干式系统可以适用于环境温度高于70°C的场所","isCorrect":false}],"answer":"C","explanation":"中级技能78页,火灾危险等级为严重危险级级的场所采用雨淋系统"},{"id":"ms-0069","type":"single","question":"二氧化碳火火剂在常温常压下是一种无色、无味的气体,当储存于密封高压气中,低于临界温度31.4°时,以（）储存。","options":[{"value":"A","text":"气体","isCorrect":false},{"value":"B","text":"液体","isCorrect":false},{"value":"C","text":"气、液两相","isCorrect":true},{"value":"D","text":"固体","isCorrect":false}],"answer":"C","explanation":"基础知识125页,二氧化碳灭火剂在常温常压下当诸存于密封高压无味的气体是一种无色、无味的气体,当储存于密封高压气瓶中,低于临界温度31.4°C时,以气、液两相共存。"},{"id":"ms-0070","type":"single","question":"当火灾确认后,火灾自动报警系统应在15S内联动相应防烟分区的全部活动挡烟垂壁, ()s以内挡烟垂壁应开启到位。","options":[{"value":"A","text":"10","isCorrect":false},{"value":"B","text":"60","isCorrect":true},{"value":"C","text":"15","isCorrect":false},{"value":"D","text":"30","isCorrect":false}],"answer":"B","explanation":"中级技能123页,火灾自动报警系统应在15s内中级技能123页,火灾自动报警系统应在15s内联动相应防烟分区的全部活动挡烟垂壁,60s以内挡烟垂壁应开启到位"},{"id":"ms-0071","type":"single","question":"木材火灾属于( )火灾。","options":[{"value":"A","text":"A类","isCorrect":true},{"value":"B","text":"B类","isCorrect":false},{"value":"C","text":"C类","isCorrect":false},{"value":"D","text":"D类","isCorrect":false}],"answer":"A","explanation":"基础知识28页（1）按照可燃物的类型和燃烧特性，火灾分为A、B、C、D、E、F6类。A类火灾：固体物质火灾，如木材、棉、毛、麻、纸张等。B类火灾：液体或可熔化固体物质火灾，如汽油、煤油、原油、甲醇、乙醇、沥青、石蜡等。C类火灾：气体火灾，如煤气、天然气、甲烷、乙烷、氢气、乙炔等。D类火灾：金属火灾，如钾、钠、镁、钛、锆、锂等。E类火灾：带电火灾，物体带电燃烧的火灾，如变压器等设备的电气火灾等。F类火灾：烹饪器具内的烹饪物（如动植物油脂）火灾。"},{"id":"ms-0072","type":"single","question":"()是在职业分类的基础上,根据职业活动内容,对从业人员的理论知识和技能要求提出的综合性水平规定。","options":[{"value":"A","text":"职业分类","isCorrect":false},{"value":"B","text":"职业道德","isCorrect":false},{"value":"C","text":"行业规范","isCorrect":false},{"value":"D","text":"国家职业技能标准","isCorrect":true}],"answer":"D","explanation":"暂无解析"},{"id":"ms-0073","type":"single","question":"下列组件属于集中报警系统,但不属于区域报警系统的是（）。","options":[{"value":"A","text":"火灾探测器","isCorrect":false},{"value":"B","text":"火灾声光警报器","isCorrect":false},{"value":"C","text":"手动火火报警按钮","isCorrect":false},{"value":"D","text":"消防联动控制器","isCorrect":true}],"answer":"D","explanation":"基础知识82页,(1)区域报警系统应由火灾探测器、手动火灾报警按钮、火灾声光警报器及火灾报警控制器等组成,系统中可包括消防控制室图形显示装置和指示楼层的区域显示器。(2)集中报警系统应由火灾探测器、手动火灾报警按钮、火灾声光警报器、消防专用电话、消防应急广播、消防控制室图形显示装置、火灾报警控制器、消防联动控制器等组成。"},{"id":"ms-0074","type":"single","question":"更换火灾警报装置时,应做的启动功能测试为（）。。","options":[{"value":"A","text":"仅采用联动启动的方式,检查火灾警报装置的声光启动功能","isCorrect":false},{"value":"B","text":"采用手动启动和联动启动的方式,检查火灾警报装置的声光启动功能","isCorrect":true},{"value":"C","text":"仅采用手动启动的方式,检查火灾警报装置的声光启动功能","isCorrect":false},{"value":"D","text":"以上均可","isCorrect":false}],"answer":"B","explanation":"中级技能54页,4.测试更换后的火灾警报装置功能采用手动和联动启动方式,检查火灾警报装置的声光启动功能,具有语音提示功能的火灾声警报器还应检查其语音同步功能。"},{"id":"ms-0075","type":"single","question":"接通应急照明控制器电源,打开控制器电源的主备电开关,控制器进入系统（）状态。","options":[{"value":"A","text":"正常监控","isCorrect":false},{"value":"B","text":"自检","isCorrect":true},{"value":"C","text":"主电工作","isCorrect":false},{"value":"D","text":"备电工作","isCorrect":false}],"answer":"B","explanation":"中级技能168页,检查与应急照明控制器相连的设备线路是否正确,确认无问题后接通电源控制哭进入至打开控制器电源的主备电开关打开控制器电源的主备电开关,控制器进入系统自检状态。自检完成后,进入系统初始化。开机过程结束后,系统进入正常监控状态。"},{"id":"ms-0076","type":"single","question":"民用建筑内消防应急广播扬声器应设置在走道和大厅等公共场所,每个扬声器的额定功率不应小于（）。","options":[{"value":"A","text":"3W","isCorrect":true},{"value":"B","text":"4W","isCorrect":false},{"value":"C","text":"5W","isCorrect":false},{"value":"D","text":"10W","isCorrect":false}],"answer":"A","explanation":"中级技能62页,民用建筑内扬声器应设置在走每个场声哭的额定功率道和大厅等公共场所道和大厅等公共场所,每个扬声器的额定功率不应小于3W;客房设置专用扬声器时,其功率不宜小于1W。"},{"id":"ms-0077","type":"single","question":"消防应急照明与指示系统的测试步骤为,能触发同一防火分区的两个独立的报警触发装置,核查由发生火灾的报警区域开始,建筑内所有疏散通道的消防应急照明和疏散指示系统是否启动,测试系统全部投入应急状态的启动时间不应大于（）。","options":[{"value":"A","text":"1s","isCorrect":false},{"value":"B","text":"5s","isCorrect":true},{"value":"C","text":"60s","isCorrect":false},{"value":"D","text":"120s","isCorrect":false}],"answer":"B","explanation":"中级技能60页,触发同一防火分区的两个独立的报警触发装置核查发生火灾的报警区域的报警触发装置,核查由发生火灾的报警区域开始,建筑内所有疏散通道的消防应急照明和疏散指示系统是否启动,测量系统全部投入应急状态的启动时间且不应大于5s。"},{"id":"ms-0078","type":"single","question":"在对火灾自动报警系统各组件进行功能测试前，首先确认火灾自动报警系统组件与火灾报警控制连接正确,并处于（）。","options":[{"value":"A","text":"火灾报警状态","isCorrect":false},{"value":"B","text":"正常蓝视状态","isCorrect":true},{"value":"C","text":"屏蔽状态","isCorrect":false},{"value":"D","text":"故障报警状态","isCorrect":false}],"answer":"B","explanation":"中级技能64页,如何对火灾自动报警系统各组件进行功能测试在组件功能测试前,首先确认火灾自动报警系统组件与火灾报警控制器连接正确,并处于正常监视状态。"},{"id":"ms-0079","type":"single","question":"测试点型感烟火灾探测器功能时,加烟器的试验烟可由（）材料阴燃产生。","options":[{"value":"A","text":"蚊香","isCorrect":false},{"value":"B","text":"棉绳","isCorrect":false},{"value":"C","text":"香烟","isCorrect":false},{"value":"D","text":"蚊香、棉绳、香烟等","isCorrect":true}],"answer":"D","explanation":"中级技能64页,用火灾探测器加烟器(试验烟可由蚊香、棉绳、香烟等材料阴燃产生)持续向点型感烟以文探测哭面滤网游施加烟气占型咸型感烟火灾探测器侧面滤网施加烟气,点型感烟火灾探测器的报警确认灯应点亮,并保持至被复位。"},{"id":"ms-0080","type":"single","question":"进入应急广播状态后,消防应急广播在（）内发出信息。","options":[{"value":"A","text":"3s","isCorrect":false},{"value":"B","text":"5s","isCorrect":false},{"value":"C","text":"10s","isCorrect":true},{"value":"D","text":"15s","isCorrect":false}],"answer":"C","explanation":"中级技能25页,消防应急广播主机可以分别通过手动和自动控制实现启动或停止应急广播、选择广播分区等操作,并且手动操作优先;在进入应急广播状态后,消防应急广播系统在10s内发出广播信息,而且声频功率放大器的输出功率不能被改变。"},{"id":"ms-0081","type":"single","question":"当火灾确认后,火灾自动报警系统应在15s内联动开启相应防烟分区的全部排烟阀、排烟口、排烟风机和补风设施,并在()S内自动关闭与排烟无关的通风、空调系统。","options":[{"value":"A","text":"10","isCorrect":false},{"value":"B","text":"15","isCorrect":false},{"value":"C","text":"20","isCorrect":false},{"value":"D","text":"30","isCorrect":true}],"answer":"D","explanation":"为了系统及时反应动作,保证人员疏散的需要,当火灾确认后,火灾报警系统应在15s内联动相应防烟分区的全部排烟阀(口)、排烟风动相应防烟分区的全部排烟阀(口)、排烟风机和补风设施。同时为了防止烟气受到通风空调系统的干扰,确保在火灾发生时,烟气能讯调系统的干扰,确保在火灾发生时,烟气能迅速得到控制和排放,不向非火灾区域蔓延、扩散,要求在30s内自动关闭与排烟无关的通风、空调系统"},{"id":"ms-0082","type":"single","question":"除设置在仓库连廊、冷库穿堂或谷物筒仓工作塔内的消防电梯外,消防电梯应设置前室,前室或合用前室的门应采用( )防火门。","options":[{"value":"A","text":"甲级","isCorrect":false},{"value":"B","text":"乙级","isCorrect":true},{"value":"C","text":"丙级","isCorrect":false},{"value":"D","text":"丁级","isCorrect":false}],"answer":"B","explanation":"除设置在合库连廊今库空党或公物管合工作除设置在仓库连廊、冷库穿堂或谷物筒仓工作塔内的消防电梯外,消防电梯应设置前室,前室或合用前室的门应采用乙级防火门。"},{"id":"ms-0083","type":"single","question":"集中火火报警控制器是火火自动报警系统中用于()、显示和传递火灾报警信号,并具有其他辅助功能的控制指示设备。","options":[{"value":"A","text":"反馈","isCorrect":false},{"value":"B","text":"屏蔽","isCorrect":false},{"value":"C","text":"启动","isCorrect":false},{"value":"D","text":"接收","isCorrect":true}],"answer":"D","explanation":"集中火灾报警控制器是火灾自动报警系统中用于接收、显示和传递火灾报警信号,并具有其他辅助功能的控制指示设备。"},{"id":"ms-0084","type":"single","question":"消防控制室图形显示装置应具有火灾报警和消防联动控制的历史记录功能,记录应包括报警时间、报警部位（）消防联动设备的启动和动作反馈等信息。","options":[{"value":"A","text":"报警原因","isCorrect":false},{"value":"B","text":"复位操作","isCorrect":true},{"value":"C","text":"维保操作","isCorrect":false},{"value":"D","text":"通讯时长","isCorrect":false}],"answer":"B","explanation":"消防控制室图形显示装置应具有火灾报警和消防联动控制的历史记录功能,记录应包括报警时间、报警部位、复位操作、消防联动设备的启动和动作反馈等信息。结合题意,本题应选“复位操作\"。"},{"id":"ms-0085","type":"single","question":"地方各级人民政府负责本行政区域内的消防工作,()为第一责任人。","options":[{"value":"A","text":"政府主要负责人","isCorrect":true},{"value":"B","text":"分管负责人","isCorrect":false},{"value":"C","text":"消防工作负责人","isCorrect":false},{"value":"D","text":"班子成员","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材12页。地方各级人民政府负责本行政区域内的消防工作,政府主要负责人为第一责任人,分管负责人为主要责任人,班子其他成员对分管范围内的消防工作负领导责任。"},{"id":"ms-0086","type":"single","question":"( )可以将系统中的水压信号转换为电信号。","options":[{"value":"A","text":"水流指示器","isCorrect":false},{"value":"B","text":"压力开关","isCorrect":true},{"value":"C","text":"信号蝶阀","isCorrect":false},{"value":"D","text":"湿式报警阀","isCorrect":false}],"answer":"B","explanation":"压力开关可以将系统中的水压信号转换为电信号。"},{"id":"ms-0087","type":"single","question":"可燃气体探测器探测到可燃气体浓度值()相应报警浓度设定值时,控制器面板上相应的可燃气体探测器红色报警灯长亮,蜂鸣器长鸣,系统发","options":[{"value":"A","text":"大于或等于","isCorrect":true},{"value":"B","text":"等王","isCorrect":false},{"value":"C","text":"小于","isCorrect":false},{"value":"D","text":"大于","isCorrect":false}],"answer":"A","explanation":"可燃气体探测器探测到可燃气体浓度值大于或等于相应报警浓度设定值时,控制器面板上相应的可燃气体探测器红色报警灯长亮,蜂鸣器长鸣,系统发出声光报警信号。"},{"id":"ms-0088","type":"single","question":"火灾显示盘当采用壁挂式方式安装时,其底边距地高度宜为 （）m。","options":[{"value":"A","text":"1~1.3","isCorrect":false},{"value":"B","text":"1~1.5","isCorrect":false},{"value":"C","text":"1.1 ~ 1.5","isCorrect":false},{"value":"D","text":"1.3 ~ 1.5","isCorrect":true}],"answer":"D","explanation":"火灾显示盘当采用壁挂式方式安装时,其底边距地高度宜为1.3~1.5m。"},{"id":"ms-0089","type":"single","question":"下列属于建筑物的是（）。","options":[{"value":"A","text":"水塔","isCorrect":false},{"value":"B","text":"烟卤","isCorrect":false},{"value":"C","text":"甲酚厂房","isCorrect":true},{"value":"D","text":"堤坝","isCorrect":false}],"answer":"C","explanation":"其他属于构筑物"},{"id":"ms-0090","type":"single","question":"下列说法中错误的是（）。","options":[{"value":"A","text":"集中报警系统应设置消防控制室","isCorrect":false},{"value":"B","text":"控制中心报警系统应至少设置一个主消防控制室","isCorrect":false},{"value":"C","text":"控制中心报警系统各分控制室内消防设备之间可以互相传输信息、相互控制","isCorrect":true},{"value":"D","text":"集中报警系统中起到集中控制作用的消防设备都应置在消防控制室内","isCorrect":false}],"answer":"C","explanation":"新教材基础知识82页,控制中心报警系统设置两个及以上消防控制室,或设置两个及以上集中报警系统,其组成与集中报警系统基本一致。当有两个及以上消防控制室时,应确定一个主消防控制室。所以B正确。主消防控制室应能显示所有火灾报警信号和联动控制状态信号并应能控制重要的消防设备;各分消防控制室内消防设备之间可互相传输、显示状态信息,但不应互相控制。所以C错误。集中报警系统应设置消防控制室,所以A正确;集中报警系统中起到集中控制作用的消防设备,都应设置在消防控制室内所以D正确。"},{"id":"ms-0091","type":"single","question":"下列选项中,不属于泡沫灭火系统组件的是（）。","options":[{"value":"A","text":"泡沫产生装置","isCorrect":false},{"value":"B","text":"水流指示器","isCorrect":true},{"value":"C","text":"泡沫液储罐","isCorrect":false},{"value":"D","text":"泡沫比例混合器","isCorrect":false}],"answer":"B","explanation":"绘组件水流指示器属于自动喷水灭火系统组件。"},{"id":"ms-0092","type":"single","question":"不具备直接灭火能力的系统是()。","options":[{"value":"A","text":"水幕系统","isCorrect":true},{"value":"B","text":"干式系统","isCorrect":false},{"value":"C","text":"预作用系统","isCorrect":false},{"value":"D","text":"雨淋系统","isCorrect":false}],"answer":"A","explanation":"老教材基础知识224页,水幕系统系统不具备直接灭火的能力,主要用于发生火灾时通过密集喷洒形成水墙或水帘,达到阻隔火蔓延及热扩散的目的,或直接喷洒到被保护对象上,达到冷却、降温的目的。"},{"id":"ms-0093","type":"single","question":"在消防设施操作员职业中,消防设施监控操作职业方向分为（）个职业等级,","options":[{"value":"A","text":"4","isCorrect":true},{"value":"B","text":"5","isCorrect":false},{"value":"C","text":"2","isCorrect":false},{"value":"D","text":"3","isCorrect":false}],"answer":"A","explanation":"新教材基础知识6页,消防设施操作员职业一共设五个等级,其中,消防设施监控操作职业方向分为五级/初级工、四级/中级工、三级/高级品工、二级/技师;消防设施检测维修保养职业方向分为四级/中工、三级/高级工、二级/技师、一级/高级技师。"},{"id":"ms-0094","type":"single","question":"手动开启板式排烟口时,先找到板式排烟口的远程执行机构,向开启方向拨动（）即可打开板式排烟口。","options":[{"value":"A","text":"“复位1\"螺杆","isCorrect":false},{"value":"B","text":"\"复位2\"螺杆","isCorrect":false},{"value":"C","text":"复位按钮","isCorrect":false},{"value":"D","text":"火警开关","isCorrect":true}],"answer":"D","explanation":"新教材中级技能145页,找到板式排烟口对应的远程执行机构,向开启方向拨动执行机构火警开关,查看板式排烟口是否打开。复位板式排烟口时,先使用内六角工具顺时针旋转复位1\"螺杆,再使用内六角工具顺时针旋转\"复位2螺杆,查看板式排烟口是否完全复位。"},{"id":"ms-0095","type":"single","question":"通过直接手动控制单元手动启停送风机,应确认送风机电气控制柜处于（）运行模式,进入直接手动控制/单元(也称多线控制盘)的（）操作权限。","options":[{"value":"A","text":"自动,手动禁止","isCorrect":false},{"value":"B","text":"自动,手动允许","isCorrect":true},{"value":"C","text":"手动,手动禁止","isCorrect":false},{"value":"D","text":"手动,手动允许","isCorrect":false}],"answer":"B","explanation":"中级技能155页,3.通过直接手动控制单元手动启停送风机确认送风机电气控制柜处于“自动\"运行模式,进入直接手动控制单元(也称多线控制盘)的\"手动允许\"操作权限,按下送风机启动按钮,送风机启动后,观察反馈信号指示灯是否点亮;再次按下送风机启动按钮,观察送风机是否停止,送风机停止后反馈信号指示灯应熄灭;恢复直接手动控制单元的\"手动禁止“操作权限。"},{"id":"ms-0096","type":"single","question":"使用测力计测试防火门的开启力,开启力不应大于（）。","options":[{"value":"A","text":"50N","isCorrect":false},{"value":"B","text":"60N","isCorrect":false},{"value":"C","text":"70N","isCorrect":false},{"value":"D","text":"80N","isCorrect":true}],"answer":"D","explanation":"中级技能245页,使用测力计测试防火门的开启力,开启力不应大于80N。"},{"id":"ms-0097","type":"single","question":"仓库内顶板下酒水喷头与货架内置酒水喷头应分别设置0)。","options":[{"value":"A","text":"阀门","isCorrect":false},{"value":"B","text":"未端试水装置","isCorrect":false},{"value":"C","text":"报警阀","isCorrect":false},{"value":"D","text":"水流指示器","isCorrect":true}],"answer":"D","explanation":"新教材中级技能123页,水流指示器的功能是及时报告发生火灾的部位。除报警阀组控制的酒水喷头只保护不超过防火分区面积的同层场所外,每个防火分区、每个楼层均应设水流指示器,仓库内顶板下洒水喷头与货架内置洒水喷头应分别设置水流指示器。"},{"id":"ms-0098","type":"single","question":"在干式系统测试过程中,在打升木端试水装直后,测量系统充水时间不宜大于（）min。","options":[{"value":"A","text":"5.0","isCorrect":false},{"value":"B","text":"3.0","isCorrect":false},{"value":"C","text":"2.0","isCorrect":false},{"value":"D","text":"1.0","isCorrect":true}],"answer":"D","explanation":"新教材中级技能130页,在干式系统测试过程中,在打开未端试水装置后,测量系统充水时间不宜大于1min。"},{"id":"ms-0099","type":"single","question":"集中报警系统中的火灾报警控制器、消防联动控制器和消防联动控制设备均处于自动控制方式则整个系统处于（）控制状态","options":[{"value":"A","text":"自动","isCorrect":true},{"value":"B","text":"手动","isCorrect":false},{"value":"C","text":"联动","isCorrect":false},{"value":"D","text":"联锁","isCorrect":false}],"answer":"A","explanation":"中级技能28页,3.确认系统当前控制状态是否正确查看集中报警系统中的全部火灾报警控制器、消防联动控制器和消防联动控制设备,如各控制设备均处于自动控制方式,则确认整人系统完全处于自动控制状态。处于手动控制状态的区域控制器,其分区控制不能实现自动控制。"},{"id":"ms-0100","type":"single","question":"仅需要报警,不需要联动自动消防设备的保护对象宜采用（）。","options":[{"value":"A","text":"独立型报警系统","isCorrect":false},{"value":"B","text":"控制中心报警系统","isCorrect":false},{"value":"C","text":"集中报警系统","isCorrect":false},{"value":"D","text":"区域报警系统","isCorrect":true}],"answer":"D","explanation":"火灾自动报警系统的基本形式有区域报警系统、集中报警系统和控制中心报警系统三种类型。其中,仅需要报警,不需要联动自动消防设备的保护对象宜采用区域报警系统结合题设备的保护对象宜采用区域报警系统。结合题意,本题应选\"区域报警系统”,其他项均可排除。"},{"id":"ms-0101","type":"single","question":"自动喷水火火系统应有备用洒水喷头,其数量不应少于总数的1%,且每种型号均不得少于（）只。","options":[{"value":"A","text":"10","isCorrect":true},{"value":"B","text":"15","isCorrect":false},{"value":"C","text":"20","isCorrect":false},{"value":"D","text":"30","isCorrect":false}],"answer":"A","explanation":"新教材中级技能121页,自动喷水灭火系统应有备用酒水喷头,其数量不应少于总数的1%,且每种型号均不得少于10只。"},{"id":"ms-0102","type":"single","question":"在供电电网经常发生断电的地区,计算机必须配置不间断电源,它的英文缩写是()。","options":[{"value":"A","text":"UPS","isCorrect":true},{"value":"B","text":"WPS","isCorrect":false},{"value":"C","text":"LCD","isCorrect":false},{"value":"D","text":"CFR","isCorrect":false}],"answer":"A","explanation":"老教材基础知识327页,UPS稳压电源能够在计算机工作时提供稳定的电压,以及在突然断电时自动转入后备蓄电池供电(供电时间的长短与LDS移压电源主两应用工电池的功兹有关蓄电池的功率有关)。UPS稳压电源主要应用于机房中心的服务器、应急照明系统、消防安全报警系统等需要不间断电源的用电设备。"},{"id":"ms-0103","type":"single","question":"防火卷帘升降不到位,应重新调整（）位置,检查门体。","options":[{"value":"A","text":"导轨","isCorrect":false},{"value":"B","text":"限位器","isCorrect":false},{"value":"C","text":"行程开关","isCorrect":true},{"value":"D","text":"座板","isCorrect":false}],"answer":"C","explanation":"中级技能196页,防火卷帘的维修内容和维修方法,升降不到位,需重新调整行程开关位置,检查门体。"},{"id":"ms-0104","type":"single","question":"厂房的火灾危险性根据其生产中使用或产生的物方灰灰包险生振据景厂质的性质及其数量等因素,划分为()类。","options":[{"value":"A","text":"4","isCorrect":false},{"value":"B","text":"5","isCorrect":true},{"value":"C","text":"6","isCorrect":false},{"value":"D","text":"8","isCorrect":false}],"answer":"B","explanation":"新教材40页。厂房的火灾危根据《基础知识》险性根据其生产中使用或产生的物质的性质及其数量等因素,划分为甲、乙、丙、丁、戊类。"},{"id":"ms-0105","type":"single","question":"在一段时间内,电路中产生或损耗的电能与该段时间的比称为（）。","options":[{"value":"A","text":"电阻","isCorrect":false},{"value":"B","text":"电动势","isCorrect":false},{"value":"C","text":"电功率","isCorrect":true},{"value":"D","text":"电压","isCorrect":false}],"answer":"C","explanation":"单根据《基础知识》新教材65页。电功率是指单位时间内电路中产生或损耗的电能,用字母P表示, 即P=W / t。"},{"id":"ms-0106","type":"single","question":"如果()指示灯处于()状态,表示多线控制盘功能处于正常状态","options":[{"value":"A","text":"故障”、常亮“故障\"、常亮","isCorrect":false},{"value":"B","text":"“启动”、熄灭","isCorrect":false},{"value":"C","text":"“故障”、熄灭","isCorrect":true},{"value":"D","text":"“反馈\"、闪烁","isCorrect":false}],"answer":"C","explanation":"如果\"故障\"指示灯处于熄灭状态,表示多线控制盘功能处于正常状态。"},{"id":"ms-0107","type":"single","question":"()是指按一定的应用条件进行设计计算,将灭火剂从储存装置经由干管、支管输送至喷放组件实施喷放的灭火系统。","options":[{"value":"A","text":"组合分配灭火系统","isCorrect":false},{"value":"B","text":"预制灭火系统","isCorrect":false},{"value":"C","text":"单元独立灭火系统","isCorrect":false},{"value":"D","text":"管网灭火系统","isCorrect":true}],"answer":"D","explanation":"按装配形式的不同,气体灭火系统分为管网灭火系统和预制灭火系统火系统和预制灭火系统(亦称无管网灭火装(亦称无管网灭火装置)。本题所述为管网灭火系统的定义。结合题意,本题应选\"管网灭火系统\",其他项均可排除。"},{"id":"ms-0108","type":"single","question":"在规定的条件下,可燃物质产生自燃的最低温度叫( )。","options":[{"value":"A","text":"闪点","isCorrect":false},{"value":"B","text":"燃点","isCorrect":false},{"value":"C","text":"自燃点","isCorrect":true},{"value":"D","text":"着火点","isCorrect":false}],"answer":"C","explanation":"在规定的条件下,可燃物质产生自燃的最低温度,称为自燃点。自燃点是衡量可燃物受热升度,称为自燃点。自燃点是衡量可燃物受热升泪形成自燃危险性的依据可燃物的自燃然点越温形成自燃危险性的依据,可燃物的自燃点越低,发生火灾的危险性就越大。结合题意,本题应选\"自燃点”,其他选项均可排除。"},{"id":"ms-0109","type":"single","question":"高位消防水箱的设置位置应高于其所服务的水灭火设施,且最低有效水位应满足水灭火设施最不利点处的静水压力,高层住宅、二类高层公共建筑、多层公共建筑静水压力应()。","options":[{"value":"A","text":"≥0.07MPa","isCorrect":true},{"value":"B","text":"≥0.1MPa,","isCorrect":false},{"value":"C","text":"≥0.15MPa93","isCorrect":false},{"value":"D","text":"≥0.2MPa","isCorrect":false}],"answer":"A","explanation":"高位消防水箱的设置位置应高于其所服务的水灭火设施,且最低有效水位应满足水灭火设施最不利点处的静水压力,高层住宅、二类高层公共建筑、多层公共建筑静水压力应≥0.07MPa。"},{"id":"ms-0110","type":"single","question":"（）是从业人员在职业活动中必须遵守的符合人民根本利益的职业行为准则。","options":[{"value":"A","text":"职业道德行为规范","isCorrect":true},{"value":"B","text":"职业道德物","isCorrect":false},{"value":"C","text":"职业规范","isCorrect":false},{"value":"D","text":"职业准则","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材4页。职业道德行为规范是从业人员在职业活动中必须遵守的符合人民根本利益的职业行为准则。"},{"id":"ms-0111","type":"single","question":"燃烧过程的发生和发展都必须具备以下三个必要条件:可燃物、助燃物和（）。","options":[{"value":"A","text":"光源","isCorrect":false},{"value":"B","text":"引火源","isCorrect":true},{"value":"C","text":"温度","isCorrect":false},{"value":"D","text":"能量","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材17页。燃烧过程的发生和发屏必须同时具各可然物助然物生和发展必须同时具备可燃物、助燃物、引火源3个必要条件,通常称为\"燃烧三要素\"。"},{"id":"ms-0112","type":"single","question":"阴燃是()的燃烧特点。","options":[{"value":"A","text":"可燃固体","isCorrect":true},{"value":"B","text":"可燃液体","isCorrect":false},{"value":"C","text":"可燃气体","isCorrect":false},{"value":"D","text":"液体混合物","isCorrect":false}],"answer":"A","explanation":"新教材20页。可燃固体在空气不流通,加热温度较低或湿度较大的条件下,分解出的可燃挥发物质较少或散逸较快发生只冒烟而无火焰的燃烧现象称为阴燃,又称熏烟燃烧。"},{"id":"ms-0113","type":"single","question":"操作系统主要有( )、共享性、虚拟性和异步性四个基本特征。","options":[{"value":"A","text":"唯一性","isCorrect":false},{"value":"B","text":"并发性","isCorrect":true},{"value":"C","text":"窗口化","isCorrect":false},{"value":"D","text":"人性化","isCorrect":false}],"answer":"B","explanation":"操作系统主要有并发性、共享性、虚拟性和异虚拟性和异操作系统主要有并发性共享性、步性四个基本特征。"},{"id":"ms-0114","type":"single","question":"消防泵串联,在流量不变的情况下,可增大（）。","options":[{"value":"A","text":"扬程","isCorrect":true},{"value":"B","text":"轴功率","isCorrect":false},{"value":"C","text":"效率","isCorrect":false},{"value":"D","text":"转速","isCorrect":false}],"answer":"A","explanation":"消防泵串联,在流量不变的情况下,可增大扬程。"},{"id":"ms-0115","type":"single","question":"计算机是由()和软件系统两部分组成的。","options":[{"value":"A","text":"硬件系统","isCorrect":true},{"value":"B","text":"网络系统","isCorrect":false},{"value":"C","text":"服务系统","isCorrect":false},{"value":"D","text":"监控系统","isCorrect":false}],"answer":"A","explanation":"计算机是由硬件系统和软件系统两部分组成的。"},{"id":"ms-0116","type":"single","question":"（）是用来衡量接地状态良好的一个重要参数。","options":[{"value":"A","text":"剩余电流","isCorrect":false},{"value":"B","text":"绝缘电阻","isCorrect":false},{"value":"C","text":"接地电阻","isCorrect":true},{"value":"D","text":"泄露电流","isCorrect":false}],"answer":"C","explanation":"中级技能61页，接地电阻值就是用来衡量接地状态是否良好的一个重要参数。"},{"id":"ms-0117","type":"single","question":"地方各级人民政府负责本行政区域内的消防工作,()为主要责任人。","options":[{"value":"A","text":"政府主要负责人","isCorrect":false},{"value":"B","text":"分管负责人","isCorrect":true},{"value":"C","text":"消防工作负责人","isCorrect":false},{"value":"D","text":"班子成员","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材12页。地方各级人民根据《基础知识》政府负责本行政区域内的消防工作,政府主要负责人为第一责任人,分管负责人为主要责任人,班子其他成员对分管范围内的消防工作负领导责任。"},{"id":"ms-0118","type":"single","question":"当被保护线路剩余电流达到报警设定值时,剩余电流式电气火灾监控探测器应能在（）内发出报警信号,点亮报警指示灯,向电气火灾监控设备发送报警信号。","options":[{"value":"A","text":"10s","isCorrect":false},{"value":"B","text":"30s","isCorrect":true},{"value":"C","text":"40s","isCorrect":false},{"value":"D","text":"20s","isCorrect":false}],"answer":"B","explanation":"当被保护线路剩余电流达到报警设定值时,剩余电流式电气火灾监控探测器应能在30s内发出报警信号,点亮报警指示灯,向电气火灾监控设备发送报警信号。故而本题选B。"},{"id":"ms-0119","type":"single","question":"通常情况下,CPU的位数（）CPU进行运算时候的速度就会变得越快。","options":[{"value":"A","text":"越高","isCorrect":true},{"value":"B","text":"越低透","isCorrect":false},{"value":"C","text":"越长","isCorrect":false},{"value":"D","text":"越短","isCorrect":false}],"answer":"A","explanation":"CPU进行运算通常情况下，CPU的位数越高,CPU进行运算时候的速度就会变得越快。"},{"id":"ms-0120","type":"single","question":"测试消防应急广播的总线自动控制功能时,消防联动控制设备可通过（）消防应急广系统,设备自动进入应急广播状态进行广播。","options":[{"value":"A","text":"总线自动启动","isCorrect":true},{"value":"B","text":"消防联动控制器启动","isCorrect":false},{"value":"C","text":"火灾报警控制器启动","isCorrect":false},{"value":"D","text":"以上全对","isCorrect":false}],"answer":"A","explanation":"中级技能70页(1)测试总线自动控制功能消防联动控制设备可通过总线自动启动消防应急广播系统,设备自动进入应急广播状态进行广播。"},{"id":"ms-0121","type":"single","question":"()是一种氮气、氩气、二氧化碳气体组成的混合气体(其中含52%的氮气、40%的氩气、8%的二氧化碳）。","options":[{"value":"A","text":"IG-541","isCorrect":true},{"value":"B","text":"IG-54","isCorrect":false},{"value":"C","text":"IG-01","isCorrect":false},{"value":"D","text":"IG-04","isCorrect":false},{"value":"E","text":"共日超柜","isCorrect":false}],"answer":"A","explanation":"暂无解析"},{"id":"ms-0122","type":"single","question":"使用数字接地电阻测试仪进行火灾自动报警系统接地电阻测试时,接地钉彼此间隔的距离是（）m。","options":[{"value":"A","text":"1 ~3","isCorrect":false},{"value":"B","text":"3~5","isCorrect":false},{"value":"C","text":"5 ~ 7","isCorrect":false},{"value":"D","text":"5~ 10","isCorrect":true}],"answer":"D","explanation":"中级技能68页,1.使用数字接地电阻测试仪测试以使用UT521型数字接地电阻测试仪精确测量为例说明测试方法,使用其他类型数字接地电阻测试仪应按照制造商提供的方法进行。(1)将数字接地电阻测试仪放在离测试点1-3m处,放置应平稳。(2)将接地钉打到地深处,使其与待测设备排列成一行(直线),且彼此间隔5-10m。"},{"id":"ms-0123","type":"single","question":"在对线型感温火灾探测器的功能测试时,可使用专用检测装置持续对一段标准报警长度感温电缆进行（）。","options":[{"value":"A","text":"冷却","isCorrect":false},{"value":"B","text":"加热","isCorrect":true},{"value":"C","text":"震动","isCorrect":false},{"value":"D","text":"摩擦","isCorrect":false}],"answer":"B","explanation":"中级技能37-38页,1.测试线型感温火灾探测器的火灾报警功能(1)确认线型感温火灾探测器与火灾报警控制器正常连接,系统处于正常监视状态。(2)对可恢复的线型感温火灾探测器在终端盒0.3m以外的部位,使用可产生不低于设定动作温度环境的专用检测装置(如热水)持续对一段标准报警长度(1m)感温电缆进行加热"},{"id":"ms-0124","type":"single","question":"故障电弧探测器是能够区分()配电正常电弧和故障电弧,消除电气火灾隐患的电气火灾监控探测器。","options":[{"value":"A","text":"低压","isCorrect":true},{"value":"B","text":"常压","isCorrect":false},{"value":"C","text":"中压","isCorrect":false},{"value":"D","text":"高压","isCorrect":false}],"answer":"A","explanation":"故障电弧探测器是能够区分低压配电线路中操作正常电弧和故障电弧,消除电气火灾隐惠的电气火灾监控探测器。"},{"id":"ms-0125","type":"single","question":"按一定应用条件,将灭火剂储存装置和喷放组件等预先设计、组装成套且具有联动控制功能的灭火系统是（）。","options":[{"value":"A","text":"预制灭火系统","isCorrect":true},{"value":"B","text":"管网灭火系统","isCorrect":false},{"value":"C","text":"单元独立灭火系统","isCorrect":false},{"value":"D","text":"组合分配灭火系统","isCorrect":false}],"answer":"A","explanation":"按装配形式的不同,气体灭火系统分为管网灭火系统和预制灭火系统(亦称无管网灭火装。本题所述为预制灭火系统的定义。结合题意,本题应选\"预制灭火系统\",其他项均可排除。"},{"id":"ms-0126","type":"single","question":"下列选项中,属于开式系统的是（）。","options":[{"value":"A","text":"湿式系统","isCorrect":false},{"value":"B","text":"干式系统","isCorrect":false},{"value":"C","text":"预作用系统","isCorrect":false},{"value":"D","text":"水幕系统","isCorrect":true}],"answer":"D","explanation":"属于开式系统的有雨淋系统和水幕系统。"},{"id":"ms-0127","type":"single","question":"湿式系统一个报警阀组控制的洒水喷头数不宜超过( )只。","options":[{"value":"A","text":"1000","isCorrect":false},{"value":"B","text":"500","isCorrect":false},{"value":"C","text":"800","isCorrect":true},{"value":"D","text":"1200","isCorrect":false}],"answer":"C","explanation":"湿式系统一人报警阀组控制的洒水喷头数不宜超过800只。故而本题选C。"},{"id":"ms-0128","type":"single","question":"消除火灾报警控制器报警声音信号后,消音指示灯亮（）。","options":[{"value":"A","text":"绿色","isCorrect":true},{"value":"B","text":"红色","isCorrect":false},{"value":"C","text":"黄色","isCorrect":false},{"value":"D","text":"蓝色","isCorrect":false}],"answer":"A","explanation":"消除火灾报警控制器报警声音信号后,消音指示灯绿色亮"},{"id":"ms-0129","type":"single","question":"对于消防电梯,为方便火灾时消防人员接近和快速使用,其迫降要求是使电梯返回到指定层(一般为首层）并保持()的状态。","options":[{"value":"A","text":"开门停用","isCorrect":false},{"value":"B","text":"开门待用","isCorrect":true},{"value":"C","text":"关门停用","isCorrect":false},{"value":"D","text":"关门待用","isCorrect":false}],"answer":"B","explanation":"对于消防电梯,为方便火灾时消防人员接近和快速使用,其迫降要求是使电梯返回到指定层(一般为首层)并保持开门待用的状态。"},{"id":"ms-0130","type":"single","question":"泡沫灭火剂在可燃易燃液体表面生成凝聚的泡沫漂浮层,可起到（）和冷却作用。","options":[{"value":"A","text":"隔离作用","isCorrect":false},{"value":"B","text":"乳化作用","isCorrect":false},{"value":"C","text":"室息作用","isCorrect":true},{"value":"D","text":"覆盖作用","isCorrect":false}],"answer":"C","explanation":"泡沫灭火剂在可燃易燃液体表面生成凝聚的泡沫漂浮层,可起到室息作用和冷却作用。"},{"id":"ms-0131","type":"single","question":"消防水池最低有效水位是消防水泵吸水管喇叭口以上()m水位。当消防水泵吸水管上设置旋流防止器时,最低有效水位为旋流防止器顶部以上()m水位。","options":[{"value":"A","text":"0.6, 0.2","isCorrect":true},{"value":"B","text":"0.6, 0.3","isCorrect":false},{"value":"C","text":"0.7, 0.2","isCorrect":false},{"value":"D","text":"0.7, 0.3","isCorrect":false}],"answer":"A","explanation":"消防水池最低有效水位是消防水泵吸水管喇叭口或出水口喇叭口以上0.6m水位。当消防水泵吸水管上设置旋流防止器时,最低有效水位为旋流防止器顶部以上0.2m水位。"},{"id":"ms-0132","type":"single","question":"准工作状态时配水管道内充满用于启动系统的有压气体的自动喷水灭火系统是（）。","options":[{"value":"A","text":"干式系统","isCorrect":true},{"value":"B","text":"湿式系统","isCorrect":false},{"value":"C","text":"水幕系统","isCorrect":false},{"value":"D","text":"雨淋系统","isCorrect":false}],"answer":"A","explanation":"准工作状态时配水管道内充满用于启动系统的有压气体的自动喷水灭火系统是干式系统。"},{"id":"ms-0133","type":"single","question":"电气火灾监控设备应能接收来自电气火灾监控探测器的监控报警信号,并在()内发出声、光报警信号,指示报警部位,显示报警时间。","options":[{"value":"A","text":"10s","isCorrect":true},{"value":"B","text":"30s","isCorrect":false},{"value":"C","text":"15s","isCorrect":false},{"value":"D","text":"20s","isCorrect":false}],"answer":"A","explanation":"由气火灾监控没备应能接收来自由电气火灾监控探测器的监控报警信号,并在10s内发出声、光报警信号,指示报警部位,显示报警时间。"},{"id":"ms-0134","type":"single","question":"在空气中遇明火或高温作用的立即起火、微燃或炭化,火源移走后燃烧或微燃仍继续的建筑材料属于（）。","options":[{"value":"A","text":"不燃材料","isCorrect":false},{"value":"B","text":"难燃材料","isCorrect":false},{"value":"C","text":"易燃材料","isCorrect":false},{"value":"D","text":"可燃材料","isCorrect":true}],"answer":"D","explanation":"在空气中遇明火或高温作用时立即起火、微燃或炭化,火源移走后燃烧或微燃仍继续的建筑材料属于可燃材料。"},{"id":"ms-0135","type":"single","question":"下列属于丙类厂房的是（）。","options":[{"value":"A","text":"乙炔站","isCorrect":false},{"value":"B","text":"氢气站","isCorrect":false},{"value":"C","text":"氧气站","isCorrect":false},{"value":"D","text":"服装加工厂","isCorrect":true}],"answer":"D","explanation":"乙炔站、氢气站属于甲类厂房,氧气站属于乙类厂房。"},{"id":"ms-0136","type":"single","question":"（）是指流体中质点发生相对位移而引起的、由空间的一处向另一处传播热能的现象。","options":[{"value":"A","text":"热传导","isCorrect":false},{"value":"B","text":"热辐射","isCorrect":false},{"value":"C","text":"热对流","isCorrect":true},{"value":"D","text":"散热","isCorrect":false}],"answer":"C","explanation":"热对流是指流体中质点发生相对位移而引起的、由空间的一处向另一处传播热能的现象。"},{"id":"ms-0137","type":"single","question":"可燃材料(制品)的燃烧等级为（）。","options":[{"value":"A","text":"级","isCorrect":false},{"value":"B","text":"1级","isCorrect":false},{"value":"C","text":"2级","isCorrect":true},{"value":"D","text":"B3级","isCorrect":false}],"answer":"C","explanation":"可燃材料(制品)的燃烧等级为B2级。"},{"id":"ms-0138","type":"single","question":"田外部引火源作用于可燃物引起燃烧的现象,称为(）。","options":[{"value":"A","text":"引燃","isCorrect":true},{"value":"B","text":"阴燃","isCorrect":false},{"value":"C","text":"自燃","isCorrect":false},{"value":"D","text":"爆炸","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材18页。由外部引火源(如明火、电火花、高温炙烤等)作用于可燃物引起燃烧的现象,称为引燃(又称点燃)。"},{"id":"ms-0139","type":"single","question":"计算机是由硬件系统和()两部分组成的。","options":[{"value":"A","text":"软件系统","isCorrect":true},{"value":"B","text":"网络系统","isCorrect":false},{"value":"C","text":"应用系统","isCorrect":false},{"value":"D","text":"存储系统","isCorrect":false}],"answer":"A","explanation":"计算机是由硬件系统和软件系统两部分组成的。"},{"id":"ms-0140","type":"single","question":"()是以由固体化学混合物(热气溶胶发生剂)经燃烧反应生成具有灭火性质的气溶胶作为灭火介质的灭火系统。","options":[{"value":"A","text":"二氧化碳灭火系统","isCorrect":false},{"value":"B","text":"七氟丙烷灭火系统","isCorrect":false},{"value":"C","text":"热气溶胶灭火系统","isCorrect":true},{"value":"D","text":"情性气体灭火系统","isCorrect":false}],"answer":"C","explanation":"热气溶胶灭火系统是以由固体化学混合物((热气溶胶发生剂)经燃烧反应生成具有灭火性质的气溶胶作为灭火介质的灭火系统。"},{"id":"ms-0141","type":"single","question":"可燃物的自燃点越低,,发生火灾的危险性（）。","options":[{"value":"A","text":"越小","isCorrect":false},{"value":"B","text":"越大","isCorrect":true},{"value":"C","text":"不变","isCorrect":false},{"value":"D","text":"不能判断","isCorrect":false}],"answer":"B","explanation":"可燃物的自燃点越低,发生火灾的危险性越大。"},{"id":"ms-0142","type":"single","question":"扑救F类火灾应选用（）。","options":[{"value":"A","text":"空气隔离法","isCorrect":true},{"value":"B","text":"自行熄灭","isCorrect":false},{"value":"C","text":"用水扑灭","isCorrect":false},{"value":"D","text":"干粉灭火剂","isCorrect":false}],"answer":"A","explanation":"A.空气隔离法:正确。 通过物理隔绝氧气(如锅盖、灭火毯)直接阻断燃烧条件,避免油脂飞溅或复燃。B.自行熄灭:错误。油脂火灾持续高温会蔓延被动等待可能引发更大火势。C.用水扑灭:错误。水会导致高温油脂飞溅或油火扩散,属于严禁操作。D.干粉灭火剂:错误。普通干粉可能无法彻底扑灭深层油脂火,且易污染厨房环境。"},{"id":"ms-0143","type":"single","question":"职业责任有差异性、（）和强制性等特点。","options":[{"value":"A","text":"独特性","isCorrect":false},{"value":"B","text":"独立性","isCorrect":true},{"value":"C","text":"关联性","isCorrect":false},{"value":"D","text":"相关性","isCorrect":false}],"answer":"B","explanation":"职业责任的特点及其与职业道德的关系是什么？职业责任有差异性、独立性和强制性等特点。职业道德和职业责任在人们的职业生活中是相互联系、相互作用的,以什么样的思想、感情、态度、作风、行为来对待本职工作,既是职业责任的问题,也是职业道德的问题。事实证明:职业道德水平高的人,都具有强烈的职业责任感;反之,缺乏职业道德的人,必然是个缺乏职业责任感的人。"},{"id":"ms-0144","type":"single","question":"建筑高度大于()的公共建筑、工业建筑和建筑高度大于()的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室及消防电梯前室应采用机械加压送风系统。","options":[{"value":"A","text":"55m, 120m","isCorrect":false},{"value":"B","text":"55m,100m","isCorrect":false},{"value":"C","text":"50m, 100m","isCorrect":true},{"value":"D","text":"50m, 120m","isCorrect":false}],"answer":"C","explanation":"工业建筑和建建筑高度大于50m的公共建筑、工业建筑和建筑宣度大于100m的空建筑其防烟楼样间筑高度大于100m的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室及消防电梯前室应采用机械加压送风系统。"},{"id":"ms-0145","type":"single","question":"下列选项中,不属于湿式报警阀组组件的是（）。","options":[{"value":"A","text":"水流指示器","isCorrect":true},{"value":"B","text":"水力警铃","isCorrect":false},{"value":"C","text":"湿式报警阀","isCorrect":false},{"value":"D","text":"延迟器","isCorrect":false}],"answer":"A","explanation":"水流指示器是用于自动喷水灭火系统中将水流信号转换成电信号的一种报警装置。结合题意,应排除A选项。"},{"id":"ms-0146","type":"single","question":"下列说法中错误的是（）。","options":[{"value":"A","text":"集中报警系统应设置消防控制室","isCorrect":false},{"value":"B","text":"控制中心报警系统应至少设置一个主消防控制室","isCorrect":false},{"value":"C","text":"控制中心报警系统各分控制室内消防设备之间可以互相传输信息、相互控制","isCorrect":true},{"value":"D","text":"集中报警系统中起到集中控制作用的消防设备,都应设置在消防控制室内","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材82页。控制中心报警系统设置两个及以上消防控制室,或设置两人及以上集中报警系统,其组成与集中报警系统基本一致。当有两个及以上消防控制室时,应确定一个主消防控制室。主消防控制室应能显示所有火灾报警信号和联动控制状态信号,并应能控制重要的消防设备;各分消防控制室内消防设备之间可互相传输、显示状态信息,但不应互相控制。"},{"id":"ms-0147","type":"single","question":"发生火灾时,湿式自动喷水灭火系统是由()探测火灾。","options":[{"value":"A","text":"火灾探测器","isCorrect":false},{"value":"B","text":"闭式喷头","isCorrect":true},{"value":"C","text":"压力开关","isCorrect":false},{"value":"D","text":"水流指示器","isCorrect":false}],"answer":"B","explanation":"在湿式和干式自动喷水灭火系统中,闭式喷头担负着探测火灾、启动系统和喷水灭火的任务,其喷水口平时由热敏感元件组成的释放机构封闭,火灾发生时受热开启。"},{"id":"ms-0148","type":"single","question":"发生火灾时,集中电源非集中控制型消防应急照明和疏散指示系统的()联动控制集中电源和/或应急照明分配电装置的工作状态,进而控制各路消防应急灯具的工作状态。","options":[{"value":"A","text":"火灾报警控制器或消防联动控制器","isCorrect":false},{"value":"B","text":"应急照明集中控制器","isCorrect":false},{"value":"C","text":"消防联动控制器","isCorrect":true},{"value":"D","text":"火灾报警控制器","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》老教材277页。集中电源非集中控制型系统在发生火灾时,消防联动控制器联动控制集中电源和应急照明分配电装置的工作状态,进而控制各路消防应急灯具的工作状态。"},{"id":"ms-0149","type":"single","question":"火灾显示盘的保养项目中,不包含（）。","options":[{"value":"A","text":"接线保养","isCorrect":false},{"value":"B","text":"指示灯喇叭保养","isCorrect":false},{"value":"C","text":"显示屏保养","isCorrect":false},{"value":"D","text":"打印机保养","isCorrect":true}],"answer":"D","explanation":"火灾显示盘保养包括:1.接线保养;2.指示灯喇叭保养;3.显示屏保养;4.开关、按键保养。"},{"id":"ms-0150","type":"single","question":"防火卷帘手动按钮盒底边距地高度宜为（）m。","options":[{"value":"A","text":"1.3~1.5","isCorrect":true},{"value":"B","text":"1.1 ~ 1.5","isCorrect":false},{"value":"C","text":"1.2~1.5","isCorrect":false},{"value":"D","text":"1.0~ 1.3","isCorrect":false}],"answer":"A","explanation":"防火卷帘手动按钮盒底边距地高度宜为1.3~1.5m。"},{"id":"ms-0151","type":"single","question":"如果（）指示灯处于（）状态,表示总线控制盘手动控制单元已发出启动指令,等待反馈。","options":[{"value":"A","text":"“启动”,常亮","isCorrect":false},{"value":"B","text":"“反馈\",常亮","isCorrect":false},{"value":"C","text":"“启动”,闪烁","isCorrect":true},{"value":"D","text":"“反馈\",闪烁","isCorrect":false}],"answer":"C","explanation":"如果“启动\"指示灯处于闪烁状态,表示总线控制盘手动控制单元已发出启动指令,等待反馈;如果“启动\"指示灯处于常亮状态,表示现场设备已启动成功。"},{"id":"ms-0152","type":"single","question":"按下控制地下室发电机房排烟机的启动操作按钮，如果（）指示灯处于（）状态,表示多线控制盘手动控制单元已发出启动指令,等待反馈。","options":[{"value":"A","text":"“反馈\",常亮","isCorrect":false},{"value":"B","text":"“启动”,熄灭","isCorrect":false},{"value":"C","text":"\"反馈\",闪烁","isCorrect":false},{"value":"D","text":"“启动\",闪烁","isCorrect":true}],"answer":"D","explanation":"如果“启动\"指示灯处于闪烁状态,表示多线控制盘手动控制单元发出启动指令，等待反馈;如果“启动\"指示灯处于常亮状态,表示现场设备已启动成功。"},{"id":"ms-0153","type":"single","question":"在正常情况下有烟滞留的场所不宜选择（）火灾探测器。","options":[{"value":"A","text":"线型缆式感温","isCorrect":false},{"value":"B","text":"线型光纤感温","isCorrect":false},{"value":"C","text":"线型定温","isCorrect":false},{"value":"D","text":"线型光束感烟","isCorrect":true}],"answer":"D","explanation":"符合下列条件之一的场所,不宜选择线型光束感烟火灾探测器:1)有大量粉尘、水雾滞留的场所。 2)可能产生蒸气和油雾的场所。 3)在正常情况下有烟滞留的场所。4)固定探测器的建筑结构由于振动等原因会产生较大位移的场所。"},{"id":"ms-0154","type":"single","question":"消防电梯排水井的容量不应小于()m。","options":[{"value":"A","text":"2","isCorrect":true},{"value":"B","text":"3","isCorrect":false},{"value":"C","text":"4","isCorrect":false},{"value":"D","text":"5","isCorrect":false}],"answer":"A","explanation":"火灾时,为防止灭火时的消防积水淹没消防电梯导致消防电梯失去功能,消防电梯的井底应设置排水设施。排水并的容量不应小于2m³,排水泵的排水量不应小于10L/s。消防电梯间前室的门口宜设置挡水设施。"},{"id":"ms-0155","type":"single","question":"线型光束感烟火灭探测器的发射器和接收器之间的距离不宜超过（）m。","options":[{"value":"A","text":"100","isCorrect":true},{"value":"B","text":"120","isCorrect":false},{"value":"C","text":"150","isCorrect":false},{"value":"D","text":"80","isCorrect":false}],"answer":"A","explanation":"线型光束感烟火灾探测器的发射器和接收器之间的距离不宜超过100m。"},{"id":"ms-0156","type":"single","question":"下列不属于高层建筑的是（）。","options":[{"value":"A","text":"建筑高度为54m的办公楼","isCorrect":false},{"value":"B","text":"建筑高度为26m的单层厂房","isCorrect":true},{"value":"C","text":"C建筑高度为26m的门诊楼","isCorrect":false},{"value":"D","text":"建筑高度为30m的住宅楼","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材第38页。高层建筑是指建筑高度大于27m的住宅建筑和建筑高度大于24m的非单层厂房、仓库和其他民用建筑。对于有些单层建筑,如体育馆、高大的单层厂因为具有相对便利的疏散和扑效条件房等,因为具有相对便利的疏散和扑救条件,虽然建筑高度大于24m,但不划分为高层建筑。"},{"id":"ms-0157","type":"single","question":"每台消防水泵出水管上应设置（）试水管,并采取水措施。","options":[{"value":"A","text":"DN50","isCorrect":false},{"value":"B","text":"N65","isCorrect":true},{"value":"C","text":"DN80","isCorrect":false},{"value":"D","text":"N100","isCorrect":false}],"answer":"B","explanation":"新教材中级技能125页,根据《消防给水及消火栓系统技术规范》(GB50974-2014)的规定,消防水泵应在消防水泵房内设置流量和压力测试装置,且每台消防水泵出水管上应设置DN65的试水管,并采取排水措施。"},{"id":"ms-0158","type":"single","question":"粘贴功能的快捷组合键是（）。","options":[{"value":"A","text":"\"Ctrl\"+\"C”","isCorrect":false},{"value":"B","text":"\"Ctrl\"+\"V\"","isCorrect":true},{"value":"C","text":"\"Ctrl\"+\"X\"","isCorrect":false},{"value":"D","text":"\"Ctrl\"+\"Z”","isCorrect":false}],"answer":"B","explanation":"暂无解析"},{"id":"ms-0159","type":"single","question":"保护（）的目的是使火灾调查人员能够发现、提取到客观真实,有效的火灾痕迹和物证,确保火灾原因认定的准确性。","options":[{"value":"A","text":"火灾现场","isCorrect":true},{"value":"B","text":"受损财物","isCorrect":false},{"value":"C","text":"过火痕迹","isCorrect":false},{"value":"D","text":"起火部位","isCorrect":false}],"answer":"A","explanation":"新教材基础知识140页,火灾现场保留着火灾发生、发展和熄灭过程的真实记录,是火灾原因的物质载体。保护火灾现场的目的是使火灾调查人员能够发现直实有效的提取到客观查人员能够发现、提取到客观、真实、有效的火灾痕迹和物证,确保火灾原因认定的准确性。"},{"id":"ms-0160","type":"single","question":"火灾发生后,当自动启动的消防主泵故障时,设定的消防备泵（）接替主泵正常启动。","options":[{"value":"A","text":"能手动","isCorrect":false},{"value":"B","text":"能自动","isCorrect":true},{"value":"C","text":"能联动","isCorrect":false},{"value":"D","text":"能连锁","isCorrect":false}],"answer":"B","explanation":"当自动启动的消防主泵故障时,能自动切换到备泵运行。"},{"id":"ms-0161","type":"single","question":"木材火灾属于（）火灾。","options":[{"value":"A","text":"A类","isCorrect":true},{"value":"B","text":"B类","isCorrect":false},{"value":"C","text":"C类","isCorrect":false},{"value":"D","text":"D类","isCorrect":false}],"answer":"A","explanation":"新教材基础知识28页(1) 按照可燃物的类型和燃烧特性,火灾分为A、B、C、D、E、F6类。A类火灾:固体物质火灾,如木材、棉、毛、麻、纸张等。B类火灾:液体或可熔化固体物质火灾,如汽油、煤油、原油、甲醇、乙醇、 沥青、石蜡等。C类火灾:气体火灾,如煤气、天然气、甲烷、乙烷、氢气、乙焕等。D类火灾:金属火灾,如钾、钠、镁、钛错锂等F米带电火文物体带电钛、错、锂等。E类火灾:带电火灾,物体带电燃烧的火灾,如变压器等设备的电气火灾等。F类火灾:烹饪器具内的烹饪物(如动植物油脂) 火灾。"},{"id":"ms-0162","type":"single","question":"（）是指响应异常温度、温升速率和温变化等参数的探测器。","options":[{"value":"A","text":"火焰探测器","isCorrect":false},{"value":"B","text":"感温火灾探测器","isCorrect":true},{"value":"C","text":"感烟火灾探测器","isCorrect":false},{"value":"D","text":"气体火灾探测器","isCorrect":false}],"answer":"B","explanation":"新教材基础知识83页,感温火灾探测器:响应异常温度、温升速率和温差变化等参数的探测器。"},{"id":"ms-0163","type":"single","question":"通过手动开启常闭式加压送风口联动启动送风机,应确认送风机电气控制柜处于（）运行模式，进入消防联动控制器（）操作权限。","options":[{"value":"A","text":"自动,自动禁止","isCorrect":false},{"value":"B","text":"自动,自动允许","isCorrect":true},{"value":"C","text":"手动,手动禁止","isCorrect":false},{"value":"D","text":"手动,手动允许","isCorrect":false}],"answer":"B","explanation":"中级技能153页,1.手动开启常闭式加压送风口联动启动送风机(1)设置送风机电气控制柜和消防联动控制器控制状态确认送风机电气控制柜处于\"自动\"运行模式,进入消防联动控制器\"自动允许\"操作权限。(2)手动开启常闭式加压送风口打开常闭式加压送风口执行机构护板,找到执行机构钢丝绳拉环,用力向外拉动拉环,常闭式加压送风口应能打开,相应的送风机应能联动启动。查看消防联动控制器,应能收到送风机启动反馈信号。(3)手动停止送风机停止送风机时,先将送风机电气控制柜置于“手动“运行模式,再按下停止按钮,使送风机停止运行。"},{"id":"ms-0164","type":"single","question":"下列燃烧产物中,（）是不完全燃烧产物。","options":[{"value":"A","text":"二氧化碳","isCorrect":false},{"value":"B","text":"一氧化碳","isCorrect":true},{"value":"C","text":"水","isCorrect":false},{"value":"D","text":"二氧化硫","isCorrect":false}],"answer":"B","explanation":"P022,完全燃烧产物是指可燃物中的碳被氧化生成二氧化碳气体、氢被氧化生成液态水、硫被氧化生成二氧化硫气体等:而燃然烧生成的一氧化碳、氨气、醇类、醛类、醚类等是不完全燃烧产物。"},{"id":"ms-0165","type":"single","question":"消防电话分机设置位置不正确的是（）。","options":[{"value":"A","text":"消防电梯内","isCorrect":false},{"value":"B","text":"发电机房侧墙距地面1.3m","isCorrect":false},{"value":"C","text":"变电室侧墙距地面1.4m","isCorrect":false},{"value":"D","text":"消火栓箱内","isCorrect":true}],"answer":"D","explanation":"中级63页,消防水泵房、发电机房、配变电室、计算机网络机房、主要通风和空调机房、防排烟机房、灭火控制系统操作装置处或控制室、企业消防站、消防值班室、总调度室、消防电梯轿厢、消防电梯机房及其他与消防联动控制有关的且经常有人值班的机房应设置消防电话分机。A正确。消防电话分机和消防电话插孔宜安装在明显、便于操作的位置。采用壁挂方式安装时,其底边距地(楼)面的高度宜为消防中数1.3~1.5m;BC正确;在避难层中,消防电话分机或消防电话插孔的安装间距不应大于20m;消防电话分机和消防电话插孔应设置明显的永久性标识。"},{"id":"ms-0166","type":"single","question":"通过消防控制室总线手动控制单元远程启动防火卷帘,按下总线手动控制单元防火卷帘启动按钮后,总线手动控制单元的防火卷帘（）应点亮。","options":[{"value":"A","text":"运行灯","isCorrect":false},{"value":"B","text":"启动灯","isCorrect":true},{"value":"C","text":"反馈灯","isCorrect":false},{"value":"D","text":"复位灯","isCorrect":false}],"answer":"B","explanation":"中级技能166页,1.消防控制室总线手动控制单元远程启动防火卷进入消防联动控制器的“手动允许\"操作权限,按下总线手动控制单元防火卷帘启动按钮,观察防火卷帘启动灯是否点亮,防火卷帘下降到楼板后反馈灯是否点亮;现场按下防火卷帘手动按钮处的”上升“键,手动控制防火卷帘上升至最高限位。"},{"id":"ms-0167","type":"single","question":"高倍泡沫灭火剂是指发泡倍数为（）以上的泡沫灭火剂。","options":[{"value":"A","text":"100","isCorrect":false},{"value":"B","text":"101","isCorrect":false},{"value":"C","text":"200","isCorrect":false},{"value":"D","text":"201","isCorrect":true}],"answer":"D","explanation":"基础知识123页,高倍泡沫灭火剂是指发泡倍数为201以上的泡沫灭火剂。"},{"id":"ms-0168","type":"single","question":"电流表要（）在电路中。","options":[{"value":"A","text":"串联","isCorrect":true},{"value":"B","text":"并联","isCorrect":false},{"value":"C","text":"串并联","isCorrect":false},{"value":"D","text":"混联","isCorrect":false}],"answer":"A","explanation":"基础知识68页,电流表又称安培表,是测量电电流表也有交流和直流的区别,但流的仪表。电流表也有交流和直流的区别,但它们的连接方式都是与被测电路串联。"},{"id":"ms-0169","type":"single","question":"下列场所不宜选择线型光束感烟火灾探测器的是（）。","options":[{"value":"A","text":"可能产生蒸汽和油雾的场所","isCorrect":true},{"value":"B","text":"飞机库","isCorrect":false},{"value":"C","text":"博物馆","isCorrect":false},{"value":"D","text":"商场","isCorrect":false}],"answer":"A","explanation":"中级技能82页,有大量粉尘、水雾滞留的场所、可能产生蒸气和油雾的场所、在正常情况下有烟滞留的场所等特殊环境会线型光束感烟火灾探测器的探测性能产生影响,容易使其产生误报现象,因此这些场所不宜选择线型光束感烟火灾探测器。"},{"id":"ms-0170","type":"single","question":"（）是指物体通过电磁波直接向外传递热量的现象。","options":[{"value":"A","text":"热传导","isCorrect":false},{"value":"B","text":"热辐射","isCorrect":true},{"value":"C","text":"热对流","isCorrect":false},{"value":"D","text":"散热","isCorrect":false}],"answer":"B","explanation":"基础知识31页,热辐射是指物体通过电磁波直接向外传递热量的现象。"},{"id":"ms-0171","type":"single","question":"通过消防控制室图形显示装置查询历史信息时，单击\"（）\"键,可查看所设条件下的所有历史报警数据。","options":[{"value":"A","text":"首页查看","isCorrect":false},{"value":"B","text":"视频预览查询","isCorrect":false},{"value":"C","text":"数据统计查看","isCorrect":false},{"value":"D","text":"数据统计查询","isCorrect":true}],"answer":"D","explanation":"中级30页,单击\"数据统计\",设置事件类别,单击\"查询\"键,可查看所设条件下的所有历史报警数据。"},{"id":"ms-0172","type":"single","question":"劳动法调整的最重要的、最基本的关系是（）。","options":[{"value":"A","text":"劳动关系","isCorrect":true},{"value":"B","text":"与劳动关系有密切联系的其他关系","isCorrect":false},{"value":"C","text":"企业与其劳动者之间的劳动关系","isCorrect":false},{"value":"D","text":"劳动关系以及与劳动关系密切联系的其他关系","isCorrect":false}],"answer":"A","explanation":"基础知识194页,劳动法的调整对象是指劳动关系以及与劳动关系密切相关的其他社会关系。其中,劳动关系是我国劳动法调整的主要对象。"},{"id":"ms-0173","type":"single","question":"焦炭的燃烧属于（）。","options":[{"value":"A","text":"蒸发燃烧","isCorrect":false},{"value":"B","text":"分解燃烧","isCorrect":false},{"value":"C","text":"表面燃烧","isCorrect":true},{"value":"D","text":"沸溢燃烧","isCorrect":false}],"answer":"C","explanation":"基础知识20页,可燃固体经火源加热,在被加热的表面上吸附氧气与可燃物质直接作用发生的燃烧,称为表面燃烧。表面燃烧是一种无焰的燃烧。表面燃烧在这个过程中可燃物受热不件铜等件热超相加本年发生热分解和相变,如木炭、焦炭、铁、铜等的燃烧,均为表面燃烧。"},{"id":"ms-0174","type":"single","question":"区域报警系统适用于仅需要报警,不需要（）自动消防设备的保护对象。","options":[{"value":"A","text":"联动","isCorrect":true},{"value":"B","text":"启动","isCorrect":false},{"value":"C","text":"连动","isCorrect":false},{"value":"D","text":"连锁","isCorrect":false}],"answer":"A","explanation":"基础知识81页,(1)区域报警系统适用于仅需要报警、不需要联动自动消防设备的保护对象。(2)集中报警系统适用于不仅需要报警,同时需要联动自动消防设备,且只设置一台具有集中控制功能的火灾报警控制器和消防联动控制器的保护对象。(3)控制中心报警系统适用于设置两及以上消防控制室的保护对象,也适用于已设置两个及以上集中报警系统的保护对象。"},{"id":"ms-0175","type":"single","question":"“政府统一领导\"是做好消防工作的（）。","options":[{"value":"A","text":"核心","isCorrect":true},{"value":"B","text":"关键","isCorrect":false},{"value":"C","text":"根本","isCorrect":false},{"value":"D","text":"基础","isCorrect":false}],"answer":"A","explanation":"P011,“政府统一领导\"是做好消防工作的核心,是指政府应当从总体上指挥、部署、规划、支持和协调全国或本行政区域的消防工作。"},{"id":"ms-0176","type":"single","question":"建筑高度大于()m的工业与民用建筑应设置避难层。","options":[{"value":"A","text":"150","isCorrect":false},{"value":"B","text":"120","isCorrect":false},{"value":"C","text":"100","isCorrect":true},{"value":"D","text":"90","isCorrect":false}],"answer":"C","explanation":"基础知识61页,建筑高度大于100m的工业与民用建筑应设置避难层,且第一个避难层的楼面至消防车登高操作场地地面的高度不应大于50m。"},{"id":"ms-0177","type":"single","question":"通过自然排烟或机械排烟方式,将房间、走道等空间的火灾烟气排至建筑物外的系统是（）。","options":[{"value":"A","text":"通风空气调节系统","isCorrect":false},{"value":"B","text":"补风系统","isCorrect":false},{"value":"C","text":"防烟系统","isCorrect":false},{"value":"D","text":"排烟系统","isCorrect":true}],"answer":"D","explanation":"基础知识271页,排烟系统是指通过自然排烟或走道等空间的火灾烟机械排烟方式,将房间、机械排烟方式,将房间、走道等空间的火灾烟气排至建筑物外的系统。"},{"id":"ms-0178","type":"single","question":"将SD卡插入（）的SD卡插槽中,按下\"文件导入键,设备自动进行文件导入声频功率放大器。","options":[{"value":"A","text":"火灾报警控制器","isCorrect":false},{"value":"B","text":"消防联动控制器","isCorrect":false},{"value":"C","text":"消防应急广播主机","isCorrect":true},{"value":"D","text":"以上均可以","isCorrect":false}],"answer":"C","explanation":"中级技能34页,1.录制疏散指令音频文件(1) SD卡录制在计算机中将要导入的文件复制在SD卡根目录下;将SD卡插入消防应急机SD卡插槽中,按下\"文件导入键,设备自动进行文件导入;进度条显示文件导入进度,文件导入完毕应返回待机界面。"},{"id":"ms-0179","type":"single","question":"测试消防电话总机自检功能时,应按下面板上的（）按钮。","options":[{"value":"A","text":"自检","isCorrect":true},{"value":"B","text":"通话","isCorrect":false},{"value":"C","text":"确认","isCorrect":false},{"value":"D","text":"复位","isCorrect":false}],"answer":"A","explanation":"中级技能73页,测试消防电话总机自检功能按下面板测试(自检)按钮或选择主菜单自检功职配能,检查消防电话总机指示灯、显示器和音响器件的动作情况。"},{"id":"ms-0180","type":"single","question":"集中报警系统的控制与显示设备内部电路模板、组件及其接线保养周期至少是每（）保养一次。","options":[{"value":"A","text":"日","isCorrect":false},{"value":"B","text":"周","isCorrect":false},{"value":"C","text":"月","isCorrect":false},{"value":"D","text":"季度","isCorrect":true}],"answer":"D","explanation":"中级技能43页,表1-3-1集中报警系统的控制与显示类设备的保养内容、技术要求和保养方法中内部电路模板、组件及其接线保养保养周期:每季度保养一次。"},{"id":"ms-0181","type":"single","question":"为减少系统恢复时间,干式报警阀组报警功能建议利用( )进行测试。","options":[{"value":"A","text":"报警管路控制阀","isCorrect":false},{"value":"B","text":"末端试水装置","isCorrect":false},{"value":"C","text":"警铃试验阀","isCorrect":true},{"value":"D","text":"报警阀泄水阀","isCorrect":false}],"answer":"C","explanation":"干式报整阀组报整功能为减少系统复时间,干式报警阀组报警功能建议利用警铃试验阀进行测试。"},{"id":"ms-0182","type":"single","question":"建筑高度小于或等于( )的公共建筑、工业建筑和建筑高度小于或等于( )的住宅建筑的房间、走道及中庭等应采用自然排烟系统。","options":[{"value":"A","text":"55m,120m","isCorrect":false},{"value":"B","text":"55m,100m","isCorrect":false},{"value":"C","text":"50m,100m","isCorrect":true},{"value":"D","text":"50m,120m","isCorrect":false}],"answer":"C","explanation":"建筑高度小于或等于50m的公共建、工业建筑和建筑高度小于或等于100m的住宅建筑的房间、走道及中庭等应采用自然排烟系统。"},{"id":"ms-0183","type":"single","question":"( )主要由硬件和软件两部分组成。","options":[{"value":"A","text":"集中火灾报警控制器","isCorrect":false},{"value":"B","text":"消防联动控制器","isCorrect":false},{"value":"C","text":"区域火灾报警控制器","isCorrect":false},{"value":"D","text":"消防控制室图形显示装置","isCorrect":true}],"answer":"D","explanation":"消防控制室图形显示装置主要由硬件和软件两部分组成。"},{"id":"ms-0184","type":"single","question":"消防应急灯具按()分类可分为集中控制型消防应急灯具、非集中控制型消防应急灯具。","options":[{"value":"A","text":"工作方式","isCorrect":false},{"value":"B","text":"应急供电方式","isCorrect":false},{"value":"C","text":"应急控制方式","isCorrect":true},{"value":"D","text":"用途分类","isCorrect":false}],"answer":"C","explanation":"消防应急照明灯具是为疏散路径、与人员疏散相关的部位及发生火灾时仍需工作的场所提供必要的照度条件的灯具;消防应急标志灯具是用于指示疏散出口、安全出口、疏散路径、消防设施位置等重要信息的灯具,一般采用图形加以标示,有时会有辅助的文字信息。应急照明集中电源以蓄电池为储能装置,是为集中电源型消防应急灯具进行主电源和蓄电池电源供电的电源。按照灯具蓄电池电源供电方式的不司,集中控制型消防应急照明及疏散指示系统的组成分为两种不同的方式:灯具的蓄电池电源采用集中电源供电方式时,系统由应急照明控制器、集中电源集中控制型消防。"},{"id":"ms-0185","type":"single","question":"电阻的单位是（）。","options":[{"value":"A","text":"安培","isCorrect":false},{"value":"B","text":"欧姆","isCorrect":true},{"value":"C","text":"伏特","isCorrect":false},{"value":"D","text":"焦耳","isCorrect":false}],"answer":"B","explanation":"电阻的单位是欧姆。"},{"id":"ms-0186","type":"single","question":"()用于传输、接收、显示和记录保护区域内的火灾探测报警与各相关控制系统,以及系统中的各类消防设备(设施)运行的动态信息和消防管理信息。","options":[{"value":"A","text":"消防控制室图形显示装置","isCorrect":true},{"value":"B","text":"火灾报警装置","isCorrect":false},{"value":"C","text":"消防联动控制装置","isCorrect":false},{"value":"D","text":"火灾报警控制器","isCorrect":false}],"answer":"A","explanation":"本题考查考生对消防控制室图形显示装置功能知识点的掌握情况。消防控制室图形显示装置用于传输、接收、显示和记录保护区域内的火灾探测报警与各相关控制系统,以及系统中的各类消防设备(设施)运行的动态信息和消防管理信息。结合题意,本题应选\"消防控制室图形显示装置,其他3项均可排除。"},{"id":"ms-0187","type":"single","question":"报警阀开启,打通输水通道,水力警铃动作并发出声报警信号,该声响在3m远处声强不低于() dB。","options":[{"value":"A","text":"60","isCorrect":false},{"value":"B","text":"65","isCorrect":false},{"value":"C","text":"70","isCorrect":true},{"value":"D","text":"75","isCorrect":false}],"answer":"C","explanation":"报警阀开启,打通输水通道,水力警铃动作并发出声报警信号,该声响在3m远处声强不低于70dB."},{"id":"ms-0188","type":"single","question":"下列不属于泡沫灭火系统灭火机理的是（）。","options":[{"value":"A","text":"隔离作用","isCorrect":false},{"value":"B","text":"浸湿作用","isCorrect":true},{"value":"C","text":"冷却作用","isCorrect":false},{"value":"D","text":"室息作用","isCorrect":false}],"answer":"B","explanation":"浸湿作用不属于泡沫灭火系统灭火机理。"},{"id":"ms-0189","type":"single","question":"在规定的实验条件下,可燃性液体表面产生的蒸汽在试验火焰作用下发生闪燃的最低温度称为（）。","options":[{"value":"A","text":"闪点","isCorrect":true},{"value":"B","text":"燃点","isCorrect":false},{"value":"C","text":"自燃点","isCorrect":false},{"value":"D","text":"自燃","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材20页。闪燃是引起火灾事故的先兆之一，易燃或可燃液体表面产生闪燃的最低温度称为闪点。"},{"id":"ms-0190","type":"single","question":"Windows桌面是指系统启动完成后,屏幕显示的内容,包括\"开始\"菜单、桌面图标和（）三个部分。","options":[{"value":"A","text":"任务栏","isCorrect":true},{"value":"B","text":"我的电脑","isCorrect":false},{"value":"C","text":"背景图案","isCorrect":false},{"value":"D","text":"时间和日期","isCorrect":false}],"answer":"A","explanation":"Windows桌面是指系统启动完成后,屏幕显示的内容,包括\"开始\"菜单、桌面图标和任务栏三个部分。"},{"id":"ms-0191","type":"single","question":"《自动喷水火火系统设计规范》实施的时间为（）。","options":[{"value":"A","text":"2017年5月27日","isCorrect":false},{"value":"B","text":"2018年1月1日","isCorrect":true},{"value":"C","text":"2017年8月1日","isCorrect":false},{"value":"D","text":"2018年5月27日","isCorrect":false}],"answer":"B","explanation":"(GB50084-《自动喷水灭火系统设计规范》(GB50084-2017)于2017年5月27日颁布,自2018年1月1日起实施。"},{"id":"ms-0192","type":"single","question":"防火门监控器应能记录与其连接的防火门的状态信息,记录容量不应少于()条,并具有信息查询和将上述信息上传的功能。","options":[{"value":"A","text":"8000","isCorrect":false},{"value":"B","text":"5000","isCorrect":false},{"value":"C","text":"6000","isCorrect":false},{"value":"D","text":"10000","isCorrect":true}],"answer":"D","explanation":"本题考查考生对防火门监控器的功能知识点的掌握情况。监控器应能记录与其连接的防火门的状态信息(包括防火门地址,开、闭和故障状态及相应的时间等),记录容量不应少于10000条,并具有信息查询和将上述信息上传的功能。结合题意,本题应选\"10000条\",其他3项均可排除。"},{"id":"ms-0193","type":"single","question":"计算机软件按照使用功能,一般分为( )和应用软件两大类。","options":[{"value":"A","text":"办公软件","isCorrect":false},{"value":"B","text":"系统软件","isCorrect":true},{"value":"C","text":"游戏软件","isCorrect":false},{"value":"D","text":"后台软件","isCorrect":false}],"answer":"B","explanation":"计算机软件是指为运行、维护和管理计算机而编制的各种程序、数据和文档的总称。计算机软件系统按照使用功能,一般分为系统软件和应用软件两大类。系统软件是为扩大计算机的功能、提高计算机的工作效率以及为方便用户使用计算机而设计的软件,如操作系统、语言处理程序和服务程序等;应用软件是为解决某个应用领域中的具体任务而编制的程序,如文字处理软件、计算机辅助设计软件等。"},{"id":"ms-0194","type":"single","question":"《中华人民共和国职业分类大典(年版)》将我国职业划分为()大类。","options":[{"value":"A","text":"4","isCorrect":false},{"value":"B","text":"5","isCorrect":false},{"value":"C","text":"6","isCorrect":false},{"value":"D","text":"8","isCorrect":true}],"answer":"D","explanation":"目前,《中华人民共和国职业分类大典(2022年版)》将我国职业划分为以下八大类:第一大类,包含党的机关、国家机关、群众团体和社会组织、企事业单位负责人;第二大类,包含专业技术人员;第三大类,包含办事人员和有关人员;第四大类,包含社会生产服务和生活服务人员;第五大类,包含农、林、牧、渔业生产及辅助人员;第六大类,包含生产制造及有关人员;第七大类,包含军队人员;第八大类,包含不便分类的其他从业人员。其中,以职业活动所涉及的经济领域、知识领域以及所提供的产品和服务种类为主要参照,将职业划分为79个中类。"},{"id":"ms-0195","type":"single","question":"直流供电型火灾显示盘通常采用DC（）V，由火灭报警控制器或独立的消防应急电源来供电。","options":[{"value":"A","text":"36","isCorrect":false},{"value":"B","text":"24","isCorrect":true},{"value":"C","text":"22","isCorrect":false},{"value":"D","text":"27","isCorrect":false}],"answer":"B","explanation":"火灾显示盘按供电方式分为两类:直流供电型和交流供电型。直流供电型火灾显示盘通常采用DC24V,由火灾报警控制器或独立的消防应急电源来供电;交流供电型火灾显示盘由交流电源供电,具有主/备电自动转换、备用电源自动充电、电源故障监测和电源工作状态指示等功能。"},{"id":"ms-0196","type":"single","question":"乙类仓库与高层民用建筑和设置人员密集场所的其他民用建筑的防火间距不应小于（）m。","options":[{"value":"A","text":"20","isCorrect":false},{"value":"B","text":"30","isCorrect":false},{"value":"C","text":"40","isCorrect":false},{"value":"D","text":"50","isCorrect":true}],"answer":"D","explanation":"工业建筑应根据建筑使用性质、建筑高度、耐火等级及火灾危险性等合理确定防火间距。工业建筑的防火间距应符合下列要求。(1)甲类厂房与人员密集场所的防火间距不应小于50m,与明火或散发火花地点的防火间距不应小于30m。(2)甲类仓库与高层民用建筑和设置人员密集场所的民用建筑的防火间距不应小于50m,甲类仓库之间的防火间距不应小于20m；(3)除乙类第5项、第6项物品仓库外,乙类仓库与高层民用建筑和设置人员密集场所的其他民用建筑的防火间距不应小于50m；(4)飞机库与甲类仓库的防火间距"},{"id":"ms-0197","type":"single","question":"根据国家标准《火灾分类》(GB/T4968-2008),按照可燃物质的类型和燃烧待性,将火分为以下()种不同类别。","options":[{"value":"A","text":"5","isCorrect":false},{"value":"B","text":"6","isCorrect":true},{"value":"C","text":"7","isCorrect":false},{"value":"D","text":"8","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材28页。按照可燃物的类型和燃烧特性火灾分为A、B、C、D、E、F6类。"},{"id":"ms-0198","type":"single","question":"通过采用自然通风方式,防止火灾烟气在楼梯间、前室、避难层(间）等空间内积聚,或通过采用机械加压送风方式阻止火灾烟气侵入楼梯间、前室、避难层(间)等空间的系统是（）。","options":[{"value":"A","text":"通风空气调节系统","isCorrect":false},{"value":"B","text":"防烟系统","isCorrect":true},{"value":"C","text":"排烟系统","isCorrect":false},{"value":"D","text":"火灾自动报警系统","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材111页。防烟系统通过采用自然通风方式,防止火灾烟气在楼梯间、前室、避难层(间)等空间内积聚,或通过采用机械加压送风方式阻止火灾烟气侵入楼梯间、前室、避难层(间)等空间。"},{"id":"ms-0199","type":"single","question":"下列属于构筑物的是（）。","options":[{"value":"A","text":"水塔","isCorrect":true},{"value":"B","text":"商店","isCorrect":false},{"value":"C","text":"体育馆","isCorrect":false},{"value":"D","text":"影剧院","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材37页。构筑物是指人们不能直接在内部进行生产和生活,为工程技术需要而设置的建筑,如水塔、烟窗、堤坝等。"},{"id":"ms-0200","type":"single","question":"下列哪种场所不适合用雨淋灭火系统扑救()。","options":[{"value":"A","text":"易燃液体喷雾操作区域","isCorrect":false},{"value":"B","text":"图书馆","isCorrect":true},{"value":"C","text":"输煤栈桥转运站","isCorrect":false},{"value":"D","text":"摄影棚","isCorrect":false}],"answer":"B","explanation":"雨淋系统主要适用于需大面积喷水、快速扑灭火灾的特别危险场所。火灾的水平蔓延速度快、闭式喷头的开放不能及时使喷水有效覆盖着火区域,或室内净空高度超过一定高度且必须迅速救初期火灾,或属于严重危险II级的场所,应采用雨淋系统。图书馆一般设置湿式自动喷水灭火系统。"},{"id":"ms-0201","type":"single","question":"如果()指示灯处于()状态,表示现场设备已启动成功并将启动信息反馈回来。","options":[{"value":"A","text":"“启动”、熄灭","isCorrect":false},{"value":"B","text":"“反馈”、常亮","isCorrect":true},{"value":"C","text":"“启动\"、闪烁","isCorrect":false},{"value":"D","text":"“反馈”、闪烁","isCorrect":false}],"answer":"B","explanation":"如果\"反馈\"指示灯处于熄灭状态,表示现场设备启动信息没有反馈回来;如果\"反馈\"指示灯处于常亮状态,表示现场设备已启动成功并将启动信息反馈回来。"},{"id":"ms-0202","type":"single","question":"准工作状态时配水管道内不充水,发生火灾时由火灾自动报警系统、充气管道上的压力开关联锁控制报警阀组和启动消防水泵向配水管道供水的系统是（）。","options":[{"value":"A","text":"湿式系统","isCorrect":false},{"value":"B","text":"预作用系统","isCorrect":true},{"value":"C","text":"干式系统","isCorrect":false},{"value":"D","text":"水幕系统","isCorrect":false}],"answer":"B","explanation":"预作用自动喷水灭火系统是在准工作状态时配水管道内不充水,发生火灾时由火灾自动报警系统、充气管道上的压力开关联锁控制预作用装置和消防水泵,向配水管道供水的闭式系统。预作用自动喷水灭火系统由闭式洒水喷头、预作用装置、管道、充气设备和供水设施等组成。"},{"id":"ms-0203","type":"single","question":"具有报脏功能的探测器在报脏时应该及时清洁保养。没有报脏功能的探测器,应按产品说明书的要求进行清洁保养;产品说明书没有明确要求的,应每()年清洁或标定一次。","options":[{"value":"A","text":"2","isCorrect":true},{"value":"B","text":"3","isCorrect":false},{"value":"C","text":"1","isCorrect":false},{"value":"D","text":"4","isCorrect":false}],"answer":"A","explanation":"具有报脏功能的探测器在报脏时应该及时清洁保养。没有报脏功能的探测器应按产品说明书的要求进行清洁保养;产品说明书没有明确要求的,应每2年清洁或标定一次。"},{"id":"ms-0204","type":"single","question":"下列属于高层建筑的是（）。","options":[{"value":"A","text":"建筑高度为50m的办公楼","isCorrect":true},{"value":"B","text":"建筑高度为26m的单层厂房","isCorrect":false},{"value":"C","text":"c建筑高度为20m的门诊楼","isCorrect":false},{"value":"D","text":"建筑高度为21m的住宅楼","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材第38页。高层建筑是指建筑高度大于27m的住宅建筑和建筑高度大于24m的非单层厂房、仓库和其他民用建筑。对于有些单层建筑,如体育馆、高大的单层厂房等,因为具有相对便利的疏散和扑救条件,虽然建筑高度大于24m,但不划分为高层建筑。"},{"id":"ms-0205","type":"single","question":"地下消防水泵接合器应采用铸有\"消防水泵接合器“标识的铸铁并盖,并应在其附近设置指示其位置的（）。","options":[{"value":"A","text":"固定标识","isCorrect":false},{"value":"B","text":"醒目标识","isCorrect":false},{"value":"C","text":"永久标识","isCorrect":false},{"value":"D","text":"永久性固定标识","isCorrect":true}],"answer":"D","explanation":"新教材中级技能227页,消防水泵接合器处应设置永久性铭牌,并应标明供水系统、供水范围和额定压力。地下消防水泵接合器应采用铸有消防水泵接合器“标识的铸铁并盖,并应在其附近设置指示其位置的永久性固定标识。"},{"id":"ms-0206","type":"single","question":"当设计无要求时,报警阀组应安在便于操作的明显位置,距室内地面高度宜为（）m;两侧与墙的距离不应小于（）m,正面与墙的距离不应小于（）m,报警阀组凸出部位之间的距离不应小于（）m。","options":[{"value":"A","text":"1.00.51.21.0","isCorrect":false},{"value":"B","text":"1.20.51.20.5","isCorrect":true},{"value":"C","text":"1.20.51.01.0","isCorrect":false},{"value":"D","text":"1.30.51.21.0","isCorrect":false}],"answer":"B","explanation":"新教材中级技能121页,报警阀组安装的位置应符合设计要求;当设计无要求时,报警阀组应安装在便于操作的明显位置,距室内地面高度宜为1.2m;两侧与墙的距离不应小于0.5m;正面与墙的距离不应小于1.2m;报警阀组凸出部位之间的距离不应小于0.5m。"},{"id":"ms-0207","type":"single","question":"（）适用于不仅需要报警,同时需要联动自动消防设备,且只设置一台具有集中控制功能的火灾报警控制器和消防联动控制器的保护对象。","options":[{"value":"A","text":"区域报警系统","isCorrect":false},{"value":"B","text":"集中报警系统","isCorrect":true},{"value":"C","text":"控制中心报警系统","isCorrect":false},{"value":"D","text":"消防联动控制系统","isCorrect":false}],"answer":"B","explanation":"新教材基础知识81页,火灾自动报警系统有区域报警系统、集中报警系统和控制中心报警系统三种形式,各自有不同的适用范围。 (1)区域报警系统适用于仅需要报警、不需要联动自动消防设备的保护对象。(2)集中报警系统适用于不仅需要报警,同时需要联动自动消防设备,且只设置一台具有集中控制功能的火灾报警控制器和消防联动控制器的保护对象。(3)控制中心报警系统适用于设置两个及以上消防控制室的保护对象,也适用于已设置两个及以上集中报警系统的保护对象。"},{"id":"ms-0208","type":"single","question":"在高温潮湿环境下,消防水泵控制柜内应设置自动（）的装置。","options":[{"value":"A","text":"防潮","isCorrect":false},{"value":"B","text":"除湿","isCorrect":false},{"value":"C","text":"防潮除湿","isCorrect":true},{"value":"D","text":"烘干","isCorrect":false},{"value":"E","text":"进超柜","isCorrect":false}],"answer":"C","explanation":"暂无解析"},{"id":"ms-0209","type":"single","question":"风机电气控制柜处于备用电源工作状态时,（）应点亮。","options":[{"value":"A","text":"主电源指示灯","isCorrect":false},{"value":"B","text":"主电源故障指示灯","isCorrect":false},{"value":"C","text":"备用电源指示灯","isCorrect":true},{"value":"D","text":"备用电源故障指示灯","isCorrect":false}],"answer":"C","explanation":"技能145页,通过钥匙打开电气控制柜面板,将双电源转换开关切换至自动控制状态,断开主电源开关,查看电气控制柜是否由主电源工作状态转换为备用电源工作状态,此时,主电源指示灯应熄灭,备用电源指示灯应点亮。在备用电源工作状态下,恢复主电源供电,查看电气控制柜是否自动转换为主电源工作状态,此时,备用电源指示灯应熄灭,主电源指示灯应重新点亮。"},{"id":"ms-0210","type":"single","question":"消防联动控制器应能按设定的控制逻辑向各相关的受控设备发出（）,并接受相关设备的联动反馈信号。","options":[{"value":"A","text":"联动通讯信号","isCorrect":false},{"value":"B","text":"联动反馈信号","isCorrect":false},{"value":"C","text":"联动触发信号","isCorrect":false},{"value":"D","text":"联动控制信号","isCorrect":true}],"answer":"D","explanation":"中级60页,消防联动控制器应能按设定的控制逻辑向各相关的受控设备发出联动控制信号并接收相关设备的联动反馈信号。"},{"id":"ms-0211","type":"single","question":"探测火灾早期特征、发出火灾报警信号,为人员疏散、防止火灾蔓延和启动自动灭火设备提供控制与指示的消防系统是()。","options":[{"value":"A","text":"消防联动控制系统","isCorrect":false},{"value":"B","text":"气体灭火系统","isCorrect":false},{"value":"C","text":"火灾自动报警系统","isCorrect":true},{"value":"D","text":"火灾探测报警系统","isCorrect":false}],"answer":"C","explanation":"中级1页,火灾自动报警系统是探测火灾早期特征、发出火灾报警信号,为人员疏散、防止火灾蔓延和启动自动灭火设备提供控制与指示的消防系统。"},{"id":"ms-0212","type":"single","question":"消防电话插孔保养时,下列部件中需要予以更换的是（）。","options":[{"value":"A","text":"螺钉松动","isCorrect":false},{"value":"B","text":"端子垫片锈蚀","isCorrect":true},{"value":"C","text":"盖板脱落","isCorrect":false},{"value":"D","text":"插孔积灰","isCorrect":false}],"answer":"B","explanation":"中级46页,1.消防电话分机和消防电话插孔的保养(1)接线检查保养用旋具紧固松动的接线端子，接线端烫锡接牢。换掉有锈蚀痕迹的螺钉、端子垫片等接线部件。"},{"id":"ms-0213","type":"single","question":"电解液不流动的电池是（）。","options":[{"value":"A","text":"原电池","isCorrect":false},{"value":"B","text":"蓄电池","isCorrect":false},{"value":"C","text":"干电池","isCorrect":true},{"value":"D","text":"电解池","isCorrect":false}],"answer":"C","explanation":"基础知识67页,干电池是指电解液不流动的电池。通常是指锌锰干电池。"},{"id":"ms-0214","type":"single","question":"线型感温火灾探测器在发生故障时,应在（）s内输出故障报警信号,点亮故障指示灯。","options":[{"value":"A","text":"60","isCorrect":false},{"value":"B","text":"80","isCorrect":false},{"value":"C","text":"100","isCorrect":true},{"value":"D","text":"120","isCorrect":false}],"answer":"C","explanation":"中级26页,线型感温火灾探测器在发生故障时,应在100S内输出故障报警信号,点亮故障指示灯。"},{"id":"ms-0215","type":"single","question":"通过消防控制室总线手动控制单元远程启动防火卷帘,应先进入消防联动控制器的（）操作权限,再按下总线手动控制单元的防火卷帘启动按钮。","options":[{"value":"A","text":"自动允许","isCorrect":false},{"value":"B","text":"自动禁止","isCorrect":false},{"value":"C","text":"手动允许","isCorrect":true},{"value":"D","text":"手动禁止","isCorrect":false}],"answer":"C","explanation":"中级166页,消防控制室总线手动控制单元远程启动防火卷帘,进入消防联动控制器的\"手动允许\"操作权限,按下总线手动控制单元防火卷帘启动按钮,观察防火卷帘启动灯是否点亮,防火卷帘下降到楼板后反馈灯是否点亮。"},{"id":"ms-0216","type":"single","question":"风机、风管(道)、风机电气控制柜的保养周期为（）保养一次。","options":[{"value":"A","text":"每月","isCorrect":false},{"value":"B","text":"每季度","isCorrect":true},{"value":"C","text":"每半年","isCorrect":false},{"value":"D","text":"每年","isCorrect":false}],"answer":"B","explanation":"中级技能141,风机电气控制柜的保养技术要求:(1)无变形、损伤、腐蚀(2)仪表、指示灯、开关和控制按钮状态均正常(3)柜内电气连接牢固,无松动、打火、烧蚀现象(4)电气原理图清晰,粘贴牢固保养周期:每季度一次。"},{"id":"ms-0217","type":"single","question":"手动停止排烟风机时,应先将排烟风机电气控制柜置于（）运行模式,再按下（）按钮,使排烟风机停止运行。","options":[{"value":"A","text":"手动,启动","isCorrect":false},{"value":"B","text":"手动,停止","isCorrect":true},{"value":"C","text":"自动,启动","isCorrect":false},{"value":"D","text":"自动,停止","isCorrect":false}],"answer":"B","explanation":"中级154页,停止送风机时,先将送风机电气控制柜置于“手动\"运行模式,再按下停止按钮,使送风机停止运行。"},{"id":"ms-0218","type":"single","question":"()是对从事某一职业所具备的学识、技术、能力的基本要求。","options":[{"value":"A","text":"职业水平","isCorrect":false},{"value":"B","text":"职业能力","isCorrect":false},{"value":"C","text":"职业素养","isCorrect":false},{"value":"D","text":"职业资格","isCorrect":true}],"answer":"D","explanation":"基础知识6页,职业资格是对从事某一职业所具备的学识、技术、能力的基本要求。我国职业资格包括专业技术人员职业资格和技能人员职业资格两类,按照资格性质又分为准入类职业资格和水平评价类职业资格。"},{"id":"ms-0219","type":"single","question":"()主要用于实时监控和反馈防火门的工作状态,接收控制指令后控制常开防火门关闭,一般安装在防火门附近。","options":[{"value":"A","text":"防火门门磁开关","isCorrect":false},{"value":"B","text":"防火门电动闭门器","isCorrect":false},{"value":"C","text":"防火门监控模块","isCorrect":true},{"value":"D","text":"防火门监控器","isCorrect":false}],"answer":"C","explanation":"中级技能141页。常闭型防火门有人通过后,闭门器将门关闭不需要联动,常开型防火门平时开启。常开防火门所在防火分区内的两只独立的火灾探测器或一只火灾探测器与一只手动火灾报警按钮的报警信号,作为常开防火门关闭的联动触发信号,联动触发信号应由火灾报警控制器或消防联动控制器发出,防火门监控器是用于防火门监控的专用设备,因此防火门的联动控制应由防火门监控器执行。防火门监控模块主要用于实时监控和反馈防火门的工作状态,接收控制指令后控制常开防火门关闭。结合题意,本题应选择\"监控模块”,其他选项均可排除。"},{"id":"ms-0220","type":"single","question":"应急广播扬声器数量应能保证从一个防火分区内的任何部位到最近一个扬声器的直线距离不大于（）。","options":[{"value":"A","text":"60m","isCorrect":false},{"value":"B","text":"30m","isCorrect":false},{"value":"C","text":"25m","isCorrect":true},{"value":"D","text":"5m","isCorrect":false}],"answer":"C","explanation":"中级技能62页,应急广播扬声器数量应能保证从一个防火分区内的任何部位到最近一个扬声器的直线距离不大于25m,走道未端到最近的扬声器的距离不应大于12.5m。"},{"id":"ms-0221","type":"single","question":"挡烟垂壁是指用（）制成,垂直安装在建筑顶棚、梁或吊顶下,能在火灾时形成一定蓄烟空间的挡烟分隔设施。","options":[{"value":"A","text":"可燃材料","isCorrect":false},{"value":"B","text":"难燃材料","isCorrect":false},{"value":"C","text":"不燃材料","isCorrect":true},{"value":"D","text":"建筑材料","isCorrect":false}],"answer":"C","explanation":"基础知识50页,挡烟垂壁是指用不燃材料制成,垂直安装在建筑顶棚、梁或吊顶下,能在一定蓄烟空间的挡烟分隔设施火灾时形成一定蓄烟空间的挡烟分隔设施。"},{"id":"ms-0222","type":"single","question":"应用外部引火源使可燃物表面起火并持续燃烧一定时间所需的最低温度称为（）。","options":[{"value":"A","text":"闪点","isCorrect":false},{"value":"B","text":"燃点","isCorrect":true},{"value":"C","text":"自燃点","isCorrect":false},{"value":"D","text":"自燃","isCorrect":false}],"answer":"B","explanation":"基础知识P18,外部引火源要达到一定的温度,与可燃物接触才会发生引燃,在规定的试验条件下,应用外部引火源使可燃物表面起火并持续燃烧一定时间所需的最低温度称为燃点。"},{"id":"ms-0223","type":"single","question":"消防电话系统保养后,复检系统通话功能,在消防控制室用消防电话总机与所有消防电话分机、消防电话孔互相呼叫与通话,消防电话总机同时呼叫不少于（）消防电话分机。","options":[{"value":"A","text":"两部","isCorrect":true},{"value":"B","text":"三部","isCorrect":false},{"value":"C","text":"四部","isCorrect":false},{"value":"D","text":"五部","isCorrect":false}],"answer":"A","explanation":"中级技能46页,3.系统功能接入复检(1)通话功能 在消防控制室用消防电话总机与所有消防电话分机、消防电话插孔互相呼叫与通消防电话插孔互相呼叫与通话,消防电话总机同时呼叫不少于两部消防电话分机。"},{"id":"ms-0224","type":"single","question":"下列建筑可采用自然通风方式防烟的是（）。","options":[{"value":"A","text":"建筑高度为57m的公共建筑","isCorrect":false},{"value":"B","text":"建筑高度为58m的仓库","isCorrect":false},{"value":"C","text":"建筑高度为54m的厂房","isCorrect":false},{"value":"D","text":"建筑高度为90m的住宅建筑","isCorrect":true}],"answer":"D","explanation":"中级技能24页,建筑高度大于50m的公共建筑、工业建筑和建筑高度大于的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室及消防电梯前室应采用机械加压送风系统;建筑高度小于或等于50m的公共建筑、工业建筑和建筑高度小于或等于100m的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室及消防(除共用前室与消防电梯前室合用外)及消防电梯前室应采用自然通风系统；当不能设置自然通风系统时,应采用机械加压送风系统。ABC选项应设机械加压送风系统,D选项正确。"},{"id":"ms-0225","type":"single","question":"室内火灾燃烧形成的可燃气体和未充分燃烧的气体充满房间,达到一定浓度时形成爆燃,导致室内所有可燃物都被点燃而开始燃烧,这种现象称为（）。","options":[{"value":"A","text":"闪燃","isCorrect":false},{"value":"B","text":"回燃","isCorrect":false},{"value":"C","text":"轰燃","isCorrect":true},{"value":"D","text":"爆炸","isCorrect":false}],"answer":"C","explanation":"室内火灾燃烧形成的可燃气体和未充分燃烧的气体充满房间,达到一定浓度时,形成爆燃,导致室内所有可燃物都被点燃而开始燃烧,这种现象称为轰燃。"},{"id":"ms-0226","type":"single","question":"物质是否发生了燃烧反应,可根据发生（）、放出热量、发出光亮这3个特征来判断。","options":[{"value":"A","text":"物理反应","isCorrect":false},{"value":"B","text":"光电反应","isCorrect":false},{"value":"C","text":"化学反应","isCorrect":true},{"value":"D","text":"氧化反应","isCorrect":false}],"answer":"C","explanation":"物质是否发生了燃烧反应,可根据发生化学反应、放出热量、发出光亮这3个特征来判断。"},{"id":"ms-0227","type":"single","question":"下列火灾中,不可以采用七氟丙烷气体灭火系统进行扑救的是（）。","options":[{"value":"A","text":"固体表面火灾","isCorrect":false},{"value":"B","text":"金属氢化物","isCorrect":true},{"value":"C","text":"电气火灾","isCorrect":false},{"value":"D","text":"灭火前可切断气源的气体火灾","isCorrect":false}],"answer":"B","explanation":"基础知识94页,气体灭火系统不适用于扑救下列火灾:硝化纤维、硝酸钠等氧化剂或含氧化剂的化学制品火灾;钾、镁、钠、钛、错、铀等活泼金属火灾;氢化钾、氢化钠等金属氢化物火灾;过氧化氢、联胺等能自行分解的化学物质火灾;可燃固体物质的深位火灾;能发生自燃的物质火灾,如白磷、某些金属有机化合物等。"},{"id":"ms-0228","type":"single","question":"在消防水泵启停泵操作前,应打开试水管路阀门或利用相应用水设备形成（）,切忌野蛮操作。","options":[{"value":"A","text":"泄水通道","isCorrect":false},{"value":"B","text":"排水通道","isCorrect":false},{"value":"C","text":"排气通道","isCorrect":false},{"value":"D","text":"泄压通道","isCorrect":true}],"answer":"D","explanation":"中级97页,在消防水泵启停泵操作前,应打开试水管路阀门或利用相应用水设备形成泄压通道,严守操作规程。"},{"id":"ms-0229","type":"single","question":"将直接手动控制单元解锁为（）,将消防泵组电气控制柜设置为（）状态,消防控制室才能远程启停消防水泵。","options":[{"value":"A","text":"手动允许自动","isCorrect":true},{"value":"B","text":"手动禁止自动","isCorrect":false},{"value":"C","text":"手动允许手动","isCorrect":false},{"value":"D","text":"手动禁止手动","isCorrect":false}],"answer":"A","explanation":"中级110页,将直接手动控制单元解锁为\"手动允许\",将消防泵组电气控制柜设置为\"自动\"状态。消防控制室才能远程启停消防水泵。"},{"id":"ms-0230","type":"single","question":"现场按下电磁释放器或电动闭门器的（）,常开式防火门即可在闭门器作用下自行关闭。","options":[{"value":"A","text":"手动释放按钮","isCorrect":true},{"value":"B","text":"复位按钮","isCorrect":false},{"value":"C","text":"手动开关","isCorrect":false},{"value":"D","text":"复位开关","isCorrect":false}],"answer":"A","explanation":"中级166页，现场按下手动释放按钮,常开式防火门即可在闭门器作用下自行关闭。"},{"id":"ms-0231","type":"single","question":"消防电话总机可呼叫任意一部消防电话分机,并能同时呼叫至少()部消防电话分机。","options":[{"value":"A","text":"两","isCorrect":true},{"value":"B","text":"三","isCorrect":false},{"value":"C","text":"四","isCorrect":false},{"value":"D","text":"五","isCorrect":false}],"answer":"A","explanation":"消防电话总机可呼叫任意一部消防电话分机,并能同时呼叫至少两部消防电话分机。故而本题选A。"},{"id":"ms-0232","type":"single","question":"消防救援口的净高度和净宽度均不应小于()m。","options":[{"value":"A","text":"2","isCorrect":false},{"value":"B","text":"1.5","isCorrect":false},{"value":"C","text":"1","isCorrect":true},{"value":"D","text":"0.8","isCorrect":false}],"answer":"C","explanation":"基础知识53页,消防救援口的净高度和净宽度均不应小于1.0m。"},{"id":"ms-0233","type":"single","question":"下列属于一类高层建筑的是（）。","options":[{"value":"A","text":"建筑高度为30m的普通办公楼","isCorrect":false},{"value":"B","text":"建筑高度为30m的普通旅馆","isCorrect":false},{"value":"C","text":"建筑高度为30m的养老院","isCorrect":true},{"value":"D","text":"建筑高度为30m的住宅楼","isCorrect":false}],"answer":"C","explanation":"建筑高度大于24米的独立建造的老年人照料设施属于一类高层公共建筑,养老院属于老年人照料设施。"},{"id":"ms-0234","type":"single","question":"下列不属于线型感烟、感温火灾探测器保养步骤的是()。","options":[{"value":"A","text":"稳定性检查时,线型光束感烟火灾探测器A应紧紧固定在墙壁或其他固定位置上,探测位置不发生偏移。","isCorrect":false},{"value":"B","text":"外观保养时,使用清洁的干软布和酒精轻轻擦拭线型光束感烟火灾探测器的发射和接收窗口、反射器、指示灯表面的污染物。","isCorrect":false},{"value":"C","text":"接线检直时,检查线型烟感温火灾探测器的接线端子,将连接松动的端子重新紧固连接,换掉有锈蚀痕迹的螺钉、端子垫片等接线部件。","isCorrect":false},{"value":"D","text":"保养结束后填写《建筑消防设施巡查记录《建筑消防设施巡查记录表》","isCorrect":true}],"answer":"D","explanation":"保养结束后应填写《建筑消防设施维护保养记录表》。"},{"id":"ms-0235","type":"single","question":"()是指响应悬浮悬浮在大气中燃烧和(或)热()解产生的固体或液体微粒的探测器。","options":[{"value":"A","text":"火焰探测器","isCorrect":false},{"value":"B","text":"感温火灾探测器","isCorrect":false},{"value":"C","text":"感烟火灾探测器","isCorrect":true},{"value":"D","text":"气体火灾探测器","isCorrect":false}],"answer":"C","explanation":"基础知识83页,感烟火灾探测器:响应悬浮在大气中燃烧和(或)热解产生的固体或液体微粒的探测器,进一步可分为离子感烟、光电感烟、红外光束、吸气型等类型。"},{"id":"ms-0236","type":"single","question":"不用安装,下载解压后可以直接使用的软件又称（）。","options":[{"value":"A","text":"绿色软件","isCorrect":true},{"value":"B","text":"OFFICE系列软件","isCorrect":false},{"value":"C","text":"系统软件","isCorrect":false},{"value":"D","text":"应用软件","isCorrect":false}],"answer":"A","explanation":"基础知识160页,软件的安装分为两种:一种是不用安装的绿色软件,下载解压后可以直接使用;另一种是需要安装的软件,如MicrosoftOffice,双击setup.exe(有的软件双击install.exe)就可以安装。"},{"id":"ms-0237","type":"single","question":"系统在正常监控状态下,手动按下应急照明控制器（）按钮,应急照明控制器发出手动应急启动信号。","options":[{"value":"A","text":"启动","isCorrect":false},{"value":"B","text":"复位","isCorrect":false},{"value":"C","text":"强启","isCorrect":true},{"value":"D","text":"自检","isCorrect":false}],"answer":"C","explanation":"中级技能168页,1.手动控制系统的应急启动在系统正常监控状态下,手动按下应急照明控制器的\"强启\"按钮,应急照明控制器应发出系统手动应急启动信号控制应急启动输出出系统手动应急启动信号,控制应急启动输出干接点动作,发出启动声光信号,显示并记录系统应急启动类型和系统应急启动时间。"},{"id":"ms-0238","type":"single","question":"通过操作防火门监控器远程关闭常开式防火门,应将防火门监控器的联动模式设置为（）。","options":[{"value":"A","text":"全部自动","isCorrect":false},{"value":"B","text":"部分自动","isCorrect":false},{"value":"C","text":"全部手动","isCorrect":true},{"value":"D","text":"部分手动","isCorrect":false}],"answer":"C","explanation":"通过操作防火门监控器远程关闭常开式防火，应将防火门监控器的联动模式设置为全部手动 。"},{"id":"ms-0239","type":"single","question":"蛋白泡沫火火剂的流动性能较差,抵抗油质污染的能力较弱,不能用于（）喷射灭火。","options":[{"value":"A","text":"液上","isCorrect":false},{"value":"B","text":"液下","isCorrect":true},{"value":"C","text":"顶部","isCorrect":false},{"value":"D","text":"底部","isCorrect":false}],"answer":"B","explanation":"基础知识123页,蛋白泡沫灭火剂的流动性能较差,抵抗油质污染的能力较弱,不能用于液下喷射灭火,也不能与干粉灭火剂联用。"},{"id":"ms-0240","type":"single","question":"承担火灭探测报管产品保养的企业应制订保养作业（）。","options":[{"value":"A","text":"指导书","isCorrect":true},{"value":"B","text":"说明书","isCorrect":false},{"value":"C","text":"申请书","isCorrect":false},{"value":"D","text":"任务书","isCorrect":false}],"answer":"A","explanation":"中级42页,承担保养的企业应制订保养作业指导书,对保养人员进行相关培训,确保各项保养操作符合产品使用说明书和作业指导书的要求。"},{"id":"ms-0241","type":"single","question":"甲类厂房与人员密集场所的防火间距不应小于（）m。","options":[{"value":"A","text":"20","isCorrect":false},{"value":"B","text":"30","isCorrect":false},{"value":"C","text":"40","isCorrect":false},{"value":"D","text":"50","isCorrect":true}],"answer":"D","explanation":"基础知识52页,(1)甲类厂房与人员密集场所的防火间距不应小于50m,与明火或散发火花地点的防火间距不应小于30m。"},{"id":"ms-0242","type":"single","question":"当主泵发生故障时,备用泵自动延时投入,水泵启动时间不应大于()min。","options":[{"value":"A","text":"10","isCorrect":false},{"value":"B","text":"5","isCorrect":false},{"value":"C","text":"3","isCorrect":false},{"value":"D","text":"2","isCorrect":true}],"answer":"D","explanation":"消防水泵机组应由水泵、驱动器和专用控制柜等组成;一组消防水泵可由同一消防给水系统的工作泵和备用泵组成。 根据系统操作控制和维护管理的需要,湿式、干式自动喷水灭火系统电气控制柜应具备主/备泵切换功能。当主泵发生故障时,备发生故障时,备用泵自动延时投入。水泵启动时间不应大于2min。结合题意,本题应选择\"2min\",其他选项均可排除。"},{"id":"ms-0243","type":"single","question":"一般使用（）在接收器端遮挡光路,测试线型光束感烟探测器的报警功能。","options":[{"value":"A","text":"外包装箱","isCorrect":false},{"value":"B","text":"减光片","isCorrect":true},{"value":"C","text":"手套","isCorrect":false},{"value":"D","text":"防尘罩","isCorrect":false}],"answer":"B","explanation":"中级25页,一般采用线型光束感烟探测器减光片在接收器端遮挡光路的方法,测试其报警功能。"},{"id":"ms-0244","type":"single","question":"操作火灾自动报警系统总线手动控制单元时,进入集中控制器当前的操作权限,当总线手动控制单元处于\"手动禁止\"时,应将其切换为\"手动（）”方式。","options":[{"value":"A","text":"通过","isCorrect":false},{"value":"B","text":"启动","isCorrect":false},{"value":"C","text":"允许","isCorrect":true},{"value":"D","text":"应答","isCorrect":false}],"answer":"C","explanation":"中级p31页,进入集中控制器当前的操作权限。当总线手动控制单元处于手动禁止\"时,应先将其切换为\"手动允许\"方式。"},{"id":"ms-0245","type":"single","question":"操作火灾自动报警系统总线手动控制单元的启动按键,在集中控制器上按下总线手动控制单元上相应（）的控制按钮。","options":[{"value":"A","text":"控制设备","isCorrect":false},{"value":"B","text":".联动设备","isCorrect":true},{"value":"C","text":"报警设备","isCorrect":false},{"value":"D","text":"灭火设备","isCorrect":false}],"answer":"B","explanation":"中级31页,操作总线手动控制单元的启动按键。在集中控制器上按下总线手动控制单元上相应联动设备的控制按钮。"},{"id":"ms-0246","type":"single","question":"风机电气控制柜的手动/自动转换开关处于\"手动\"位置时,下列说法正确的有（）。","options":[{"value":"A","text":"不能通过电气控制柜启/停按钮现场控制风机","isCorrect":false},{"value":"B","text":"消防控制室远程手动控制有效","isCorrect":false},{"value":"C","text":"消防控制室联动控制有效","isCorrect":false},{"value":"D","text":"消防控制室联动控制失效","isCorrect":true}],"answer":"D","explanation":"中级140页,当手动/自动转换开关处于\"手动\"位置时,风机只能通过风机控制柜启动或停止按钮现场控制,消防控制室远程手动和自动联动控制均失效;当开关处于\"自动\"位置时,则相反。"},{"id":"ms-0247","type":"single","question":"自动排烟窗可通过温控释放装置启动,释放温度应大于环境温度（）。","options":[{"value":"A","text":"30","isCorrect":true},{"value":"B","text":"10","isCorrect":false},{"value":"C","text":"15","isCorrect":false},{"value":"D","text":"20","isCorrect":false}],"answer":"A","explanation":"中级书P150页,自动排烟窗可通过现场操作电气控制柜手动开启,也可以通过与火灾自动报警系统联动或与温控释放装置联动的方式启动。当通过温控释放装置启动时,释放温度大于环境温度30°C且小于100°C。"},{"id":"ms-0248","type":"single","question":"灭火剂瓶组中的灭火剂依靠自身压力输送的灭火系统是（）。","options":[{"value":"A","text":"外储压式气体灭火系统","isCorrect":false},{"value":"B","text":"内储压式气体灭火系统","isCorrect":false},{"value":"C","text":"自压式气体灭火系统","isCorrect":true},{"value":"D","text":"储气瓶式灭火系统","isCorrect":false}],"answer":"C","explanation":"基础知识94页,气体灭火系统按照加压方式为内储压式气体灭火系统、外储压式气体灭火系统、自压式气体灭火系统。"},{"id":"ms-0249","type":"single","question":"()是在较短时间和较小空间内,能量从一种形式向另一种或几种形式转化并伴有强烈机械效应过程。","options":[{"value":"A","text":"爆炸","isCorrect":true},{"value":"B","text":"闪燃","isCorrect":false},{"value":"C","text":"自燃","isCorrect":false},{"value":"D","text":"着火","isCorrect":false}],"answer":"A","explanation":"基础知识23页,爆炸是一种极为迅速的物理或化学的能量释放过程,是在较短的时间和较小空间内,能量从一种形式向另一种或几种形式转化并伴有强烈机械效应的过程。"},{"id":"ms-0250","type":"single","question":"()应当组织有关部门针对本行政区域内的火灾特点制定应急预案,建立应急反应和处置机制,为火灾扑救和应急救援工作提供人员、装备等保障。","options":[{"value":"A","text":"县级以上地方人民政府","isCorrect":true},{"value":"B","text":"乡级以上地方人民政府","isCorrect":false},{"value":"C","text":"市级以上地方人民政府","isCorrect":false},{"value":"D","text":"省级以上地方人民政府","isCorrect":false}],"answer":"A","explanation":"基础知识10页知识点13,县级以上地方人民政府应当组织有关部门针对本行政区域内的火灾特点制定应急预案,建立应急反应和处置机制,为火灾扑救和应急救援工作提供人员、装备等保障。"},{"id":"ms-0251","type":"single","question":"部门依法监管“是做好消防工作的（）。","options":[{"value":"A","text":"核心","isCorrect":false},{"value":"B","text":"关键","isCorrect":true},{"value":"C","text":"根本","isCorrect":false},{"value":"D","text":"基础","isCorrect":false}],"answer":"B","explanation":"新教材基础知识11页,\"部门依法监管\"是做好消防工作的关键,要求政府有关部门对消防工作齐抓共管,政府各部门在各自的职责范围内切实加大执法力度,依法加强监管。"},{"id":"ms-0252","type":"single","question":"火灾报警控制器/消防联动控制器按下\"查询“键后,可选择（）功能来判别现场消防设备的工作状态。","options":[{"value":"A","text":"历史信息查询","isCorrect":false},{"value":"B","text":"设备历史信息查询","isCorrect":false},{"value":"C","text":"设备信息查询","isCorrect":true},{"value":"D","text":"设备操作信息查询","isCorrect":false}],"answer":"C","explanation":"中级技能28页,按下火灾报警控制器/消防联动控制器操作面板上的\"查询\"键,通过数字键或上下方向键选择\"设备信息查询\"功能,进入设备信息查询界面后选择\"设备状态查询并按下\"确认”键。通过显示器显示信息,可查看控制器所连接现场设备的工作状态。"},{"id":"ms-0253","type":"single","question":"扑救D类火灾应选用（）。","options":[{"value":"A","text":"水系灭火剂","isCorrect":false},{"value":"B","text":"自行熄灭","isCorrect":false},{"value":"C","text":"专用干粉灭火剂","isCorrect":true},{"value":"D","text":"化学泡沫灭火剂","isCorrect":false}],"answer":"C","explanation":"D类干粉灭火剂适用于扑救D类火灾。"},{"id":"ms-0254","type":"single","question":"可能产生蒸汽和油雾的场所不宜选择（）火灾探测器。","options":[{"value":"A","text":"线型缆式感温","isCorrect":false},{"value":"B","text":"线型光纤感温","isCorrect":false},{"value":"C","text":"线型光束感烟","isCorrect":true},{"value":"D","text":"线型定温","isCorrect":false}],"answer":"C","explanation":"符合下列条件之一的场所,不宜选择线型光束感烟火灾探测器:1)有大量粉尘、水雾滞留的场所。2)可能产生蒸气和油雾的场所。 3)在正常情况下有烟滞留的场所。4)固定探测器的建筑结构由于振动等原因会产生较大位移的场所。"},{"id":"ms-0255","type":"single","question":"建筑发生火灾时,机械加压送风系统打开,各部位压力比较正确的是（）。","options":[{"value":"A","text":"房间压力>走道压力","isCorrect":false},{"value":"B","text":"走道压力>前室压力","isCorrect":false},{"value":"C","text":"防烟楼梯间压力<前室压力","isCorrect":false},{"value":"D","text":"防烟楼梯间压力>走道压力","isCorrect":true}],"answer":"D","explanation":"机械加压送风方式的防烟系统是通过送风机送风,使需要加压送风的部位风,使需要加压送风的部位(如防烟楼梯间、消防前室等)压力大于周围环境的压力,以阻止火灾烟气侵入楼梯间、前室、避难层(间)等空间。为保证疏散通道不受烟气侵害,使人员能够安全疏散,发生火灾时,加压送风应做到:防烟楼梯间压力>前室压力>走道压力>房间压力。"},{"id":"ms-0256","type":"single","question":"消防泵组电气控制柜机械应急启动时,应确保消防水泵在报警（）min内正常工作。","options":[{"value":"A","text":"3","isCorrect":false},{"value":"B","text":"2","isCorrect":false},{"value":"C","text":"5","isCorrect":true},{"value":"D","text":"0.5","isCorrect":false}],"answer":"C","explanation":"消防泵组电气控制柜机械应急启动时,应确保消防水泵在报警5.0min内正常工作。"},{"id":"ms-0257","type":"single","question":"（）是指控制信号通过消防电气控制装置间接作用到连接的消防电动装置,进而实现对受控消防设备的控制。","options":[{"value":"A","text":"间接控制","isCorrect":true},{"value":"B","text":"直接控制","isCorrect":false},{"value":"C","text":"总线控制","isCorrect":false},{"value":"D","text":"手动控制","isCorrect":false}],"answer":"A","explanation":"直接控制是指控制信号通过消防联动控制器本身的输出接点或模块直接作用到连接的消防电动装置,进而实现对受控消防设备的控制。间接控制是指控制信号通过消防电气控制装置间接作用到连接的消防电动装置,进而实现对受控消防设备的控制。"},{"id":"ms-0258","type":"single","question":"应急照明控制器设直在消防控制室地面上时,设备面板后的维修距离不宜小于()m。","options":[{"value":"A","text":"0.5","isCorrect":false},{"value":"B","text":"1.2","isCorrect":false},{"value":"C","text":"0.8","isCorrect":false},{"value":"D","text":"1","isCorrect":true}],"answer":"D","explanation":"应急照明控制器的设置应符合下列规定:2.在消防控制室地面上设置时,应符合下列规定:3)设备面板后的维修距离不宜小于1m。"},{"id":"ms-0259","type":"single","question":"()是指控制信号通过消防联动控制器本身的输出接点或模块直接作用到连接的消防电动装置，进而实现对受控消防设备的控制。","options":[{"value":"A","text":"间接控制","isCorrect":false},{"value":"B","text":"直接控制","isCorrect":true},{"value":"C","text":"总线控制","isCorrect":false},{"value":"D","text":"手动控制","isCorrect":false}],"answer":"B","explanation":"直接控制是指控制信号通过消防联动控制器本身的输出接点或模块直接作用到连接的消防电动装置,进而实现对受控消防设备的控制。间接控制是指控制信号通过消防电气控制装置间接作用到连接的消防电动装置,进而实现对受控消防设备的控制。"},{"id":"ms-0260","type":"single","question":"自动喷水灭火系统的洒水喷头按照不同的分类方式可分为不同的种类,下列不属于按照喷头安装方式分类的是（）。","options":[{"value":"A","text":"玻璃球酒水喷头","isCorrect":true},{"value":"B","text":"下垂型洒水喷头","isCorrect":false},{"value":"C","text":"直立型洒水喷头","isCorrect":false},{"value":"D","text":"边墙型洒水喷头","isCorrect":false}],"answer":"A","explanation":"洒水喷头按照喷头安装方式可分为:通用型喷喷头按照喷头、直立型喷头、下垂型喷头、边墙型喷头。"},{"id":"ms-0261","type":"single","question":"扑救C类火灾应选用（）。","options":[{"value":"A","text":"水系灭火剂","isCorrect":false},{"value":"B","text":"自行熄灭","isCorrect":false},{"value":"C","text":"干粉灭火剂","isCorrect":true},{"value":"D","text":"化学泡沫灭火剂","isCorrect":false}],"answer":"C","explanation":"扑救C类火灾应选用干粉灭火剂。"},{"id":"ms-0262","type":"single","question":"火灾现场的保护时间应从()起。","options":[{"value":"A","text":"发现火灾前","isCorrect":false},{"value":"B","text":"发现火灾时","isCorrect":true},{"value":"C","text":"发现火灾后","isCorrect":false},{"value":"D","text":"扑灭火灾时","isCorrect":false}],"answer":"B","explanation":"火灾现场的保护时间应从发现火灾时起,到火现轻勒验特市为上灾现场勘验结束为止。"},{"id":"ms-0263","type":"single","question":"下列不属于消防水箱保养要求的是（）。","options":[{"value":"A","text":"设备铭牌标志清晰,叶轮转动灵活、无卡滞","isCorrect":true},{"value":"B","text":"进出水和溢流、排污等管路阀门启闭状态正确,阀门转动灵活,无锈蚀","isCorrect":false},{"value":"C","text":"冬季防冻措施有效","isCorrect":false},{"value":"D","text":"合用水箱消防用水不作他用的技术措施完好","isCorrect":false}],"answer":"A","explanation":"消防水箱保养:(1)水箱箱体和支架外观完好,组件齐全,无破损、渗漏(2)进出水和溢流、排污等管路阀门启闭状态正确,阀门转动灵活,无锈蚀(3)水位传感器和就地水位显示装置外观及功能正常(4)水箱水量和水质符合设计要求(5)合用水箱消防用水不作他用的技术措施完好(6)冬季防冻措施有效，A选项为消防水泵及稳压泵保养要求。"},{"id":"ms-0264","type":"single","question":"在扬声器正前方（）处,用数字声级计测量应急广I播声压级(权计)。","options":[{"value":"A","text":"10m","isCorrect":false},{"value":"B","text":"3m","isCorrect":true},{"value":"C","text":"5m","isCorrect":false},{"value":"D","text":"15m","isCorrect":false}],"answer":"B","explanation":"中级技能48页,应急广播声压级测试在扬声器正前方3m处,用数字声级计测量应急广播声压级(权计)。一般情况下,测试声压级不应小于65dB,且不应大于115dB;在环境噪声大于60dB的场所,在其播放范围内最远点的播放声压级应高于背景噪声15dB。对声压级测试存在问题的扬声器应进行调整或更换。"},{"id":"ms-0265","type":"single","question":"消防电话系统保养后,系统功能接入复检不包括（）。","options":[{"value":"A","text":"声、光报警功能","isCorrect":true},{"value":"B","text":"通话功能","isCorrect":false},{"value":"C","text":"显示功能","isCorrect":false},{"value":"D","text":"录音功能","isCorrect":false}],"answer":"A","explanation":"中级技能46页,3.系统功能接入复检(1)通话功能在消防控制室用消防电话总机与所有消防电话分机、消防电话插孔互相呼叫与通话,消防电话总机同时呼叫不少于两部消防电话分机。(2)显示功能检查消防电话总机是否能显示每部消防电话分机或消防电话插孔的位置,呼叫铃声和通话语音是否清晰。(3)录音功能选择录音回放选项,播放电话录音,检查录音等功能是否符合要求。"},{"id":"ms-0266","type":"single","question":"确认消防广播声频功率放大器电源开关处于打开状态,调整（）输出音量旋钮至现场音量适中。","options":[{"value":"A","text":"广播分配盘","isCorrect":false},{"value":"B","text":"声频功率放大器","isCorrect":true},{"value":"C","text":"专用工具","isCorrect":false},{"value":"D","text":"火灾报警按钮","isCorrect":false}],"answer":"B","explanation":"中级技能35页,确认消防广播声频功率放大器电源开关处于打开状态,调整声频功率放大器输出音量旋钮至现场音量适中。"},{"id":"ms-0267","type":"single","question":"测试消防电话总机消音功能时,按下面板静音(消音)键,检查当前报警声消除情况,（）应点亮。","options":[{"value":"A","text":"消音指示灯","isCorrect":true},{"value":"B","text":"故障指示灯","isCorrect":false},{"value":"C","text":"通话指示灯","isCorrect":false},{"value":"D","text":"录音指示灯","isCorrect":false}],"answer":"A","explanation":"中级技能74页,测试消防电话总机消音功能按下面板静音(消音)键,检查当前报警声消除情况,消音指示灯应点亮"},{"id":"ms-0268","type":"single","question":"消防应急广播系统的测试步骤为,触发同一（） 的两个独立的报警触发装置,核查建筑内的所有火灾声光警报器是否启动,消防应急广播系统是否同时向全楼进行广播。","options":[{"value":"A","text":"楼层","isCorrect":false},{"value":"B","text":"建筑","isCorrect":false},{"value":"C","text":"防火分区","isCorrect":true},{"value":"D","text":"防烟分区","isCorrect":false}],"answer":"C","explanation":"中级技能60页,触发同一防火分区的两个独立的报警触发装置,核查建筑内的所有火灾声光警报器是否启动,消防应急广播系统是否同时向全楼进行广播。"},{"id":"ms-0269","type":"single","question":"需要火灾自动报警系统联动控制的消防设备,其联动触发信号应采用（）独立的报警触发装置报警信号的\"与\"逻辑。","options":[{"value":"A","text":"一个","isCorrect":false},{"value":"B","text":"两个","isCorrect":true},{"value":"C","text":"三个","isCorrect":false},{"value":"D","text":"四个","isCorrect":false}],"answer":"B","explanation":"中级技能60页,需要火灾自动报警系统联动联动控制的消防没备，其联动触发信号应采用两个独立的报警触发装置报警信号的\"与\"逻辑。"},{"id":"ms-0270","type":"single","question":"点型感温火灾探测器在宽度小于3m的内走道顶棚上居中布置时,其安装间距不应超过（）m。","options":[{"value":"A","text":"5.0","isCorrect":false},{"value":"B","text":"10.0","isCorrect":true},{"value":"C","text":"15.0","isCorrect":false},{"value":"D","text":"18.0","isCorrect":false}],"answer":"B","explanation":"在宽度小于3m的内走道顶棚上设置点型探测器时,宜居中布置。感温火灾探测器的安装间距不应超过10m;感烟火灾探测器的安装间距不应超过15m;探测器至端墙的距离,不应大于探测器安装间距的1/2。结合题意,本题应选\"10\",其他选项均可排除。"},{"id":"ms-0271","type":"single","question":"以下哪项不能修复\"火灾警报装置不发出声、光警示信息\"故障( )。","options":[{"value":"A","text":"修复电源,使电压正常","isCorrect":false},{"value":"B","text":"重新编码","isCorrect":true},{"value":"C","text":"重新安装不牢固的底座,拧紧底座接线端子","isCorrect":false},{"value":"D","text":"更换损坏的火灾警报装置","isCorrect":false}],"answer":"B","explanation":"中级技能50页,维修内容:火灾警报装置不发出声、光警示信息;火灾声警报装置无法同时启动;具有语音提示功能的火灾声警报器无法同步发出语音提示。维修方法:(1)修复电压(1)修复电压过低的电源,使电压正常(2)重新安装不牢固的探测器底座,拧紧底座接线端子(3)更换损坏的火灾警报装置"},{"id":"ms-0272","type":"single","question":"()是将水流信号转换为电信号的一种报警装置,一般安装在自动喷水灭火系统的分区配水管上。","options":[{"value":"A","text":"水流指示器","isCorrect":true},{"value":"B","text":"压力开关","isCorrect":false},{"value":"C","text":"信号蝶阀","isCorrect":false},{"value":"D","text":"水力警铃","isCorrect":false}],"answer":"A","explanation":"水流指示器是将水流信号转换为电信号的一种报整装置，一般安装在自动喷水灭火系统的分区配水管上。"},{"id":"ms-0273","type":"single","question":"消防电梯的井底应设置排水设施,排水泵的排水量不应小于（） L/s。","options":[{"value":"A","text":"5","isCorrect":false},{"value":"B","text":"20","isCorrect":false},{"value":"C","text":"15","isCorrect":false},{"value":"D","text":"10","isCorrect":true}],"answer":"D","explanation":"消防电梯的井底应设置排水设施,排水泵的排水量不应小于10L/s。"},{"id":"ms-0274","type":"single","question":"主电工作指示灯(绿色)点亮,火灾报警控制器由AC （）v电源供电工作。","options":[{"value":"A","text":"24","isCorrect":false},{"value":"B","text":"36","isCorrect":false},{"value":"C","text":"220","isCorrect":true},{"value":"D","text":"380","isCorrect":false}],"answer":"C","explanation":"主电工作指示灯(绿色)点亮,火灾报警控制器由AC220v电源供电工作。"},{"id":"ms-0275","type":"single","question":"消防联动控制器通过接收()发出的火灾报警信息,按预设逻辑对建筑中设置的自动消防系统(设施)进行联动控制。","options":[{"value":"A","text":"报警装置","isCorrect":false},{"value":"B","text":"火灾报警控制器","isCorrect":true},{"value":"C","text":"触发装置","isCorrect":false},{"value":"D","text":"火灾探测器","isCorrect":false}],"answer":"B","explanation":"消防联动控制器通过接收火灾报警控制器发出的火灾报警信息,按预设逻辑对建筑中设置的自动消防系统(设施)进行联动控制。"},{"id":"ms-0276","type":"single","question":"低倍泡沫灭火剂是指发泡倍数为（）的泡沫灭火剂。","options":[{"value":"A","text":"1~10","isCorrect":false},{"value":"B","text":"1~201 ~ 20","isCorrect":true},{"value":"C","text":"1~30","isCorrect":false},{"value":"D","text":"1 ~40","isCorrect":false}],"answer":"B","explanation":"泡沫灭火系统的分类方法:1按结构形式:分为固定式系统、半固定系统、移动式系统。2按发泡倍数:分为低倍数泡沫灭火系统、中倍数泡沫灭火系统、高倍数泡沫灭火系统。3按系统形式:分为全淹没泡沫灭火系统、局部应用泡沫灭火系统、移动式泡沫灭火系统、泡沫-水喷淋系统、泡沫喷雾系统、压缩空气泡沫灭火系统。泡沫灭火系统按发泡倍数分为低倍数泡沫灭火系统、中倍数泡沫灭火系统、高倍数泡沫灭火系统,其中,低倍数泡沫灭火系统是指发泡倍数低于20的泡沫灭火系统,中倍数泡沫灭火系统是指发泡倍数为21~200的泡沫灭火系统,高倍数泡沫灭火。"},{"id":"ms-0277","type":"single","question":"环境温度低于4°C或高于70°C的场所应安装（）。","options":[{"value":"A","text":"干式系统","isCorrect":true},{"value":"B","text":"湿式系统","isCorrect":false},{"value":"C","text":"水幕系统","isCorrect":false},{"value":"D","text":"雨淋系统","isCorrect":false}],"answer":"A","explanation":"环境温度低于4°C或高于70°C的场所应安装干式系统。"},{"id":"ms-0278","type":"single","question":"难燃材料(制品)的燃烧等级为()。","options":[{"value":"A","text":"A级","isCorrect":false},{"value":"B","text":"B1级","isCorrect":true},{"value":"C","text":"B2级","isCorrect":false},{"value":"D","text":"B3级","isCorrect":false}],"answer":"B","explanation":"难燃材料(制品)的燃烧等级为B1级。"},{"id":"ms-0279","type":"single","question":"电气火灾监控设备应能在( )内发出与监控报警信号有明显区别的声、光故障信号,显示故障部位。","options":[{"value":"A","text":"60s","isCorrect":false},{"value":"B","text":"100s","isCorrect":true},{"value":"C","text":"80s","isCorrect":false},{"value":"D","text":"120s","isCorrect":false}],"answer":"B","explanation":"电气火灾监控设备应能在100s内发出与监控报警信号有明显区别的声、光故障信号,显示故障部位。"},{"id":"ms-0280","type":"single","question":"《城市消防远程监控系统技术规范》实施的时间为( )。","options":[{"value":"A","text":"2007年10月23日","isCorrect":false},{"value":"B","text":"2008年10月23日","isCorrect":false},{"value":"C","text":"2007年1月1日","isCorrect":false},{"value":"D","text":"2008年1月1日","isCorrect":true}],"answer":"D","explanation":"《城市消防远程监控系统技术规范》实施的时间为2008年1月1日。"},{"id":"ms-0281","type":"single","question":"电位的单位是( )。","options":[{"value":"A","text":"安培","isCorrect":false},{"value":"B","text":"欧姆","isCorrect":false},{"value":"C","text":"伏特","isCorrect":true},{"value":"D","text":"焦耳","isCorrect":false}],"answer":"C","explanation":"电位的单位是伏特。"},{"id":"ms-0282","type":"single","question":"挡烟垂壁是用()材料制成,能在火灾时形成一定蓄烟空间的挡烟分隔设施。","options":[{"value":"A","text":"不燃","isCorrect":true},{"value":"B","text":"难燃","isCorrect":false},{"value":"C","text":"易燃","isCorrect":false},{"value":"D","text":"可燃","isCorrect":false}],"answer":"A","explanation":"挡烟垂壁是用不燃材料制成,能在火灾时形成一定蓄烟空间的挡烟分隔设施。"},{"id":"ms-0283","type":"single","question":"下列属于戊类仓库的是（）。","options":[{"value":"A","text":"钢材仓库","isCorrect":true},{"value":"B","text":"面粉仓库","isCorrect":false},{"value":"C","text":"甲醇仓库","isCorrect":false},{"value":"D","text":"樟脑仓库","isCorrect":false}],"answer":"A","explanation":"钢材仓库属于戊类仓库。"},{"id":"ms-0284","type":"single","question":"历史记录包括火警记录、设备故障记录等,每种数量最多为()条,存满后新事件产生时覆盖一个最远的事件。","options":[{"value":"A","text":"1200","isCorrect":false},{"value":"B","text":"500","isCorrect":false},{"value":"C","text":"1000","isCorrect":true},{"value":"D","text":"800","isCorrect":false}],"answer":"C","explanation":"历史记录包括火警记录、设备故障记录等,每种数最多为1000条,存满后新事件产生时覆盖一个最远的事件。"},{"id":"ms-0285","type":"single","question":"关闭电气火灾监控设备备用电源,电气火灾监控设备处于()状态。","options":[{"value":"A","text":"主、备电源故障","isCorrect":false},{"value":"B","text":"主电工作,备电故障","isCorrect":true},{"value":"C","text":"主备电同时工作","isCorrect":false},{"value":"D","text":"主电故障,备电工作","isCorrect":false}],"answer":"B","explanation":"电气火灾监控设备备用电源,电气火灾监控设备处于主电工作,备电故障状态。"},{"id":"ms-0286","type":"single","question":"消防设施操作员职业一共设()个职业技能等","options":[{"value":"A","text":"4","isCorrect":false},{"value":"B","text":"5","isCorrect":true},{"value":"C","text":"6","isCorrect":false},{"value":"D","text":"8","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材6页。消防设施操作员职业一共设五个等级。"},{"id":"ms-0287","type":"single","question":"桌面图标可分为（）和应用程序快捷方式图标两类。","options":[{"value":"A","text":"回收站","isCorrect":false},{"value":"B","text":"我的电脑","isCorrect":false},{"value":"C","text":"系统图标","isCorrect":true},{"value":"D","text":"我的文档","isCorrect":false}],"answer":"C","explanation":"桌面图标可分为系统图标和应用程序快捷方式图标两类。"},{"id":"ms-0288","type":"single","question":"消防水泵接合器距室外消火栓或消防水池的距离宜为() m。","options":[{"value":"A","text":"15~40","isCorrect":true},{"value":"B","text":"15~45","isCorrect":false},{"value":"C","text":"25~40","isCorrect":false},{"value":"D","text":"20~45","isCorrect":false}],"answer":"A","explanation":"消防水泵接合器距室外消火栓或消防水池的距离宜为15~40m。"},{"id":"ms-0289","type":"single","question":"（）可对烟雾、温度、火焰辐射、气体浓度等灾参数进行响应,并自动产生火灾报警信号。","options":[{"value":"A","text":"火灾探测器","isCorrect":true},{"value":"B","text":"手动火火报警按钮","isCorrect":false},{"value":"C","text":"火灾声光警报器","isCorrect":false},{"value":"D","text":"火灾报警控制器","isCorrect":false}],"answer":"A","explanation":"本题所述为火灾探测器的作用。火灾探测器和手动火灾报警按钮是常用的火灾触发器件。"},{"id":"ms-0290","type":"single","question":"《中华人民共和国消防法》的立法宗旨是为了预防火灾和减少火灾危害,加强应急救援工作,保护( )安全,维护公共安全。","options":[{"value":"A","text":"生命","isCorrect":false},{"value":"B","text":"人身、财产","isCorrect":true},{"value":"C","text":"财产","isCorrect":false},{"value":"D","text":"公民人身","isCorrect":false}],"answer":"B","explanation":"《中华人民共和国消防法》的立法宗旨是为了预防火灾和减少火灾危害,加强应急救援工作,保护人身、财产安全,维护公共安全。"},{"id":"ms-0291","type":"single","question":"燃烧是可燃物与()作用发生的放热反应,通常伴有火焰、发光和(或)发烟现象。","options":[{"value":"A","text":"氧化剂","isCorrect":true},{"value":"B","text":"氧气","isCorrect":false},{"value":"C","text":"还原剂","isCorrect":false},{"value":"D","text":"催化剂","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材16页。燃烧是可燃物与氧化剂作用发生的放热反应,通常伴有火焰、发光和(或)发烟现象。"},{"id":"ms-0292","type":"single","question":"雨淋系统主要由()、雨淋报警阀组、管道及供供水设施等组成。","options":[{"value":"A","text":"开式喷头","isCorrect":true},{"value":"B","text":"闭式喷头","isCorrect":false},{"value":"C","text":"玻璃球喷头","isCorrect":false},{"value":"D","text":"水幕喷头","isCorrect":false}],"answer":"A","explanation":"雨淋系统主要由开式喷头、雨淋报警阀组、管道及供水设施等组成"},{"id":"ms-0293","type":"single","question":"安卓((Android)是一种基于Linux内核(不包含GNU组件)的自由及开放源代码的操作系统。主要使用于(),如智能手机和平板电脑。","options":[{"value":"A","text":"终端设备","isCorrect":false},{"value":"B","text":"固定设备","isCorrect":false},{"value":"C","text":"专用设备","isCorrect":false},{"value":"D","text":"移动设备","isCorrect":true}],"answer":"D","explanation":"安卓(Android)是一种基于Linux内核(不包含GNU组件)的自由及开放源代码的操作系统。主要使用于移动设备,如智能手机和平板电脑。"},{"id":"ms-0294","type":"single","question":"清水灭火器通过冷却作用灭火,主要用于扑救()的初期火灾。","options":[{"value":"A","text":"可燃固体","isCorrect":true},{"value":"B","text":"可燃液体","isCorrect":false},{"value":"C","text":"可燃气体","isCorrect":false},{"value":"D","text":"金属","isCorrect":false}],"answer":"A","explanation":"清水灭火器通过冷却作用灭火,主要用于扑救可燃固体的初期火灾。"},{"id":"ms-0295","type":"single","question":"( )采用手动或电动开启,常用于前室或合用前室。","options":[{"value":"A","text":"常开式送风口","isCorrect":false},{"value":"B","text":"自垂百叶式送风口","isCorrect":false},{"value":"C","text":"排烟口","isCorrect":false},{"value":"D","text":"常闭式送风口","isCorrect":true}],"answer":"D","explanation":"送风口分为常开式、常闭式和自垂百叶式。常开式送风口即普通的固定叶片式百叶风口;常闭式送风口采用手动或电动开启,常用于前室或合用前室;自垂百叶式送风口平时靠百叶重力自行关闭,加压时自行开启,常用于防烟楼梯间。排烟口用于房间、走道。结合题意,本题选D。"},{"id":"ms-0296","type":"single","question":"预防为主就是在消防工作的指导思想上,要立足于防患于未然,把()的工作作为重点,放在首位。","options":[{"value":"A","text":"灭火救援","isCorrect":false},{"value":"B","text":"火灾预防","isCorrect":true},{"value":"C","text":"防火检查","isCorrect":false},{"value":"D","text":"火灾扑救","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材10页。“预防为主\"就是在消防工作的指导思想上,要立足于防患于未然,把火灾预防的工作作为重点,放在首位,积极贯彻落实各项防火措施,力求做到不发生火灾。"},{"id":"ms-0297","type":"single","question":"公民道德建设有()项重点任务。","options":[{"value":"A","text":"3","isCorrect":false},{"value":"B","text":"4","isCorrect":true},{"value":"C","text":"5","isCorrect":false},{"value":"D","text":"8","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材2页。公民道德建设有：(1)筑牢理想信念之基。(2)培育和践行社会主义核心价值观。(3)传承中华传统美德。(4)弘扬民族精神和时代精神。"},{"id":"ms-0298","type":"single","question":"依照我国劳动法的规定,劳动者的劳动权力不包括()。","options":[{"value":"A","text":"平等就业权","isCorrect":false},{"value":"B","text":"休息休假权","isCorrect":false},{"value":"C","text":"罢工权","isCorrect":true},{"value":"D","text":"结社权","isCorrect":false}],"answer":"C","explanation":"根据新版教材《基础知识》194页,劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社提请劳动争议处理的权会保险和福利的权利会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。不包括罢工权。"},{"id":"ms-0299","type":"single","question":"在空气中遇明火或高温作用时不起火、不微燃、不炭化的建筑材料属于（）。","options":[{"value":"A","text":"不燃材料","isCorrect":true},{"value":"B","text":"难燃材料","isCorrect":false},{"value":"C","text":"易燃材料","isCorrect":false},{"value":"D","text":"可燃材料","isCorrect":false}],"answer":"A","explanation":"在空气中遇明火或高温作用时不起火、不微燃、不炭化的建筑材料属于不燃材料。"},{"id":"ms-0300","type":"single","question":"火灾发生时,()通过接收火灾探测器和手动火灾报警按钮的报警信号,按照预设的控制时序启动相应的自动消防系统(设施),实现预设的消防功能。","options":[{"value":"A","text":"火灾报警控制器","isCorrect":false},{"value":"B","text":"图形显示装置","isCorrect":false},{"value":"C","text":"电气控制装置","isCorrect":false},{"value":"D","text":"消防联动控制器","isCorrect":true}],"answer":"D","explanation":"怎样理解消防联动控制系统的工作原理火灾发生时,火灾探测器和手动火灾报警按钮的报警信号等联动触发信号传输至消防联动控制器,消防联动控制器按照预设的逻辑关系对接收到的触发信号进行识别、判断,在满足逻辑关系条件时,消防联动控制器按照预设的控制时序启动相应的自动消防系统启动相应的自动消防系统(设施),实现预设(设施),实现预设的消防功能;消防控制室的消防管理人员也可以通过操作消防联动控制器的手动控制盘直接后启动相应的消防系统(设施),从而实现预设的消防功能。消防联动控制器接收并显示消防系统(设施)动作的反馈信息。"},{"id":"ms-0301","type":"single","question":"由供水装置、过滤装置、控制阀、细水雾喷头等组件和供水管道组成,能自动和人工启动并喷放细水雾进行灭火或控火的自动灭火系统是（）。","options":[{"value":"A","text":"细水雾灭火系统","isCorrect":true},{"value":"B","text":"水喷雾灭火系统","isCorrect":false},{"value":"C","text":"雨淋系统","isCorrect":false},{"value":"D","text":"泡沫一水喷淋灭火系统","isCorrect":false}],"answer":"A","explanation":"由供水装置、过滤装置、控制阀、细水雾喷头等组件和供水管道组成,能自动和人工启动并喷放细水雾进行灭火或控火的自动灭火系统是细水雾灭火系统。"},{"id":"ms-0302","type":"single","question":"()是指在时间或空间上失去控制的燃烧所造成灾害。","options":[{"value":"A","text":"火灾","isCorrect":true},{"value":"B","text":"燃烧","isCorrect":false},{"value":"C","text":"着火","isCorrect":false},{"value":"D","text":"自燃","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材28页。火灾是指在时间或空间上失去控制的燃烧所造成的灾害。"},{"id":"ms-0303","type":"single","question":"()是从事建(构)筑物消防设施运行、操作和维修、保养、检测等工作的人员。","options":[{"value":"A","text":"消防设施操作员","isCorrect":true},{"value":"B","text":"消防员","isCorrect":false},{"value":"C","text":"消防安全管理员","isCorrect":false},{"value":"D","text":"建(构)筑物消防员","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材6页。消防设施操作员是从事建(构)筑物消防设施运行、操作和维修、保养、检测等工作的人员。"},{"id":"ms-0304","type":"single","question":"使物质开始燃烧的外部热源,统称为（）。","options":[{"value":"A","text":"引火源","isCorrect":true},{"value":"B","text":"助燃物","isCorrect":false},{"value":"C","text":"点火能","isCorrect":false},{"value":"D","text":"火源","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材17页。引火源也称点火源,是使物质开始燃烧的外部热源(能源),常见的引火源主要有明火、电弧、电火花、雷击、高温以及自燃引火源。"},{"id":"ms-0305","type":"single","question":"()是使常开防火门保持打开状态,在收到指令后释放防火门使其关闭,并将本身的状态信息反馈至防火门监控器的电动装置。","options":[{"value":"A","text":"防火门门磁开关","isCorrect":false},{"value":"B","text":"防火门电动闭门器","isCorrect":false},{"value":"C","text":"防火门电磁释放器","isCorrect":true},{"value":"D","text":"防火门监控器","isCorrect":false}],"answer":"C","explanation":"防火门电磁释放器是使常开防火门保持打开状假态,在收到指令后释放防火门使其关闭,并将本身的状态信息反馈至防火门监控器的电动装置。"},{"id":"ms-0306","type":"single","question":"非水溶性可燃液体的初起火灾,在未形成热波之前,以较强的水雾射流或滴状射流灭火,可在液体表面形成\"油包水\"型乳液,重质油品甚至可以形成含水油泡沫。水的()作用可使液体表面冷却,使可燃蒸气产生的速率降低,致使燃烧终止。","options":[{"value":"A","text":"冷却","isCorrect":false},{"value":"B","text":"稀释","isCorrect":false},{"value":"C","text":"乳化","isCorrect":true},{"value":"D","text":"覆盖","isCorrect":false}],"answer":"C","explanation":"122页。非水溶性可燃液体的初起火灾,在未形成热波之前,以较强的水雾射流或滴状射流灭火,可在液体表面形成\"油包水\"型乳液,重质油品甚至可以形成含水油泡沫。水的乳化作用可使液体表面冷却,使可燃蒸气产生的速率降低,致使燃烧终止。"},{"id":"ms-0307","type":"single","question":"衡量电场力做功大小的物理量是（）。","options":[{"value":"A","text":"电流","isCorrect":false},{"value":"B","text":"电压","isCorrect":true},{"value":"C","text":"电位","isCorrect":false},{"value":"D","text":"电动势","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材64页。电压又称电势差,是衡量电场力做功大小的物理量,用字母U表示,其大小为电场力将电荷从A点移到B点所做的功与电荷量的比值。电压不但有大小而且有方向。电压的单位为伏特,简称伏,用字母V表示。"},{"id":"ms-0308","type":"single","question":"对于一些重要联动设备(如消防泵组、防烟和排烟风机)的控制,除采用联动控制方式外,火灾报警控制器还应采用()控制方式。","options":[{"value":"A","text":"多线控制盘","isCorrect":true},{"value":"B","text":"总线控制盘","isCorrect":false},{"value":"C","text":"直接控制盘","isCorrect":false},{"value":"D","text":"间接控制盘","isCorrect":false}],"answer":"A","explanation":"火灾报警控制器(联动型)多线制控制盘也称(联动型)作多线制手动控制盘或直接手动控制盘。为确保操作受控消防设备的可靠性,对于一些重要(如消防泵组、防烟和排烟风机)的联动设备(如消防泵组、防烟和排烟风机)的控制,除采用联动控制方式外,火灾报警控制器还应采用多线控制盘控制方式,实现直接手动控制。"},{"id":"ms-0309","type":"single","question":"单独建造的消防控制室,耐火等级不应低于（）。","options":[{"value":"A","text":"一级","isCorrect":false},{"value":"B","text":"二级","isCorrect":true},{"value":"C","text":"三级","isCorrect":false},{"value":"D","text":"四级","isCorrect":false}],"answer":"B","explanation":"消防控制室的布置和防火分隔应符合下列规定。(1)单独建造的消防控制室,耐火等级不应低于二级。 (2)附设在建筑内的消防控制室应采用防火门、防火窗、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.50h的楼板与其他部位分隔。 (3)消防控制室应位于建筑的首层或地下一层,疏散门应直通室外或安全出口。(4)消防控制室的环境条件不应干扰或影响消防控制室内火灾报警与控制设备的正常运行。(5)消防控制室内不应敷设或穿过与消防控制室无关的管线。(6)消防控制室应采取防水淹、防潮、防啮齿动物等的措施。"},{"id":"ms-0310","type":"single","question":"风机正常启动时（）应点亮。","options":[{"value":"A","text":"运行指示灯","isCorrect":true},{"value":"B","text":"电源指示灯","isCorrect":false},{"value":"C","text":"故障指示灯","isCorrect":false},{"value":"D","text":"巡检指示灯","isCorrect":false}],"answer":"A","explanation":"中级技能140页,风机电气控制柜具有下列功能。(1)指示功能风机电气控制柜面板共设有三处指示信息:1)电源指示灯,控制柜通电时点亮。2)运行指示灯,风机运转时点亮。3)手动/自动转换开关,通过开关指向指示当前风机处于手动或自动控制状态,"},{"id":"ms-0311","type":"single","question":"线型感温火灾探测器按( )可分为定温、差温和差定温线型感温探测器。","options":[{"value":"A","text":"敏感部件形式","isCorrect":false},{"value":"B","text":"动作性能","isCorrect":true},{"value":"C","text":"可恢复性能","isCorrect":false},{"value":"D","text":"定位方式","isCorrect":false}],"answer":"B","explanation":"线型感温火灾探测器按敏感部件形式可分为缆式、空气管式、分布式光纤、光栅光纤和线式多点型。线型感温火灾探测器按动作性能可分为定温、差温和差定温线型感温探测器。故而本题选B。"},{"id":"ms-0312","type":"single","question":"防火卷帘的温控释放装置周围温度达到（）°C时，防火卷帘可以靠自重下降至完全关闭状态。","options":[{"value":"A","text":"63±0.5","isCorrect":false},{"value":"B","text":"69±0.5","isCorrect":false},{"value":"C","text":"73±0.5","isCorrect":true},{"value":"D","text":"79 ±0.5","isCorrect":false}],"answer":"C","explanation":"本题考查考生对防火卷帘的组成知识点的掌握情况。防火卷帘主要由卷门机、帘板(面)、座板、卷轴、导轨、防护罩(箱体)、控制器、手动按钮盒、温控释放装置等组成。其中温控释放装置是一种温控连锁装置,当温控释放装置的感温元件周围的温度达到73±0.5°C时,温控释放装置动作,牵引开启卷门机的制动机构,松开刹车盘,卷帘依靠自重下降关闭。"},{"id":"ms-0313","type":"single","question":"消防水泵接合器应设置（）标志铭牌。","options":[{"value":"A","text":"活动式","isCorrect":false},{"value":"B","text":"固定式","isCorrect":false},{"value":"C","text":"永久性","isCorrect":true},{"value":"D","text":"临时性","isCorrect":false}],"answer":"C","explanation":"新教材中级技能227页,消防水泵接合器处应设置永久性铭牌,并应标明供水系统、供水范围和额定压力。地下消防水泵接合器应采用铸有“消防水泵接合器\"标识的铸铁井盖,并应在其附近设置指示其位置的永久性固定标识。"},{"id":"ms-0314","type":"single","question":"火灭发生时,如果弱电信号因故障不能后动滑防泵时,可依靠消防泵房设置的（）装置启动消防泵。","options":[{"value":"A","text":"自动启泵","isCorrect":false},{"value":"B","text":"手动启泵","isCorrect":false},{"value":"C","text":"机械应急启动","isCorrect":true},{"value":"D","text":"远程启泵","isCorrect":false}],"answer":"C","explanation":"火灾发生时,如果弱电信号因故障不能自动或手动启动消防泵时,可依靠消防泵房设置的机械应急启动装置启动消防泵。"},{"id":"ms-0315","type":"single","question":"更换防火卷帘手动按钮盒前,应先关闭防火卷帘控制器电源,并将手动按钮盒手动钥匙设置在（）状态。","options":[{"value":"A","text":"允许","isCorrect":false},{"value":"B","text":"关闭","isCorrect":true},{"value":"C","text":"复位","isCorrect":false},{"value":"D","text":"停止","isCorrect":false}],"answer":"B","explanation":"中级技能214页,1.更换防火卷帘手动按钮盒(1)核查新换件规格型号和性能参数,应与原组件匹配或一致。 (2)关闭防火卷帘控制器电源。(3)将手动按钮盒手动钥匙设置在\"关闭”状态。(4)使用旋具拆开手动按钮盒的面板,拆开面板与防火卷帘控制器连接的线路,取下手动按钮盒。(5)将新手动按钮盒按产品说明书接线将，将新手动按钮盒安装到原位置,使用旋具紧固新手动按钮盒面板的螺钉。(6)开启防火卷帘控制器电源。(7)测试手动按钮盒的上升、下降、停止功能。"},{"id":"ms-0316","type":"single","question":"查询火灾报警控制器消防联动控制器的故障报警信息,根据显示的消防应急广播故障信息,结合系统平面布置图,确定故障部件的具体位置,并记录()的编码信息。","options":[{"value":"A","text":"故障部件","isCorrect":true},{"value":"B","text":"火灾报警控制器","isCorrect":false},{"value":"C","text":"消防联动控制器","isCorrect":false},{"value":"D","text":"火灾报警按钮","isCorrect":false}],"answer":"A","explanation":"中级技能56页,查询火灾报警控制器/消防联动控制器的故障报警信息,根据显示的消防应急广播故障信息,结合系统平面布置图,确定故障部件的具体位置,并记录故障器件的编码信息。"},{"id":"ms-0317","type":"single","question":"在（）下,设置消防应急广播与火灾声警报分时交替循环播放功能,监听消防应急广播扬声器和火灾声警报声音的交替循环播放。","options":[{"value":"A","text":"自动状态","isCorrect":true},{"value":"B","text":"手动状态","isCorrect":false},{"value":"C","text":"手动状态和自动状态","isCorrect":false},{"value":"D","text":"以上均不对","isCorrect":false}],"answer":"A","explanation":"中级技能48页,应急广播与火灾声警报循环交替播放功能在自动状态下,设置消防应急广播与火灾声警报分时交替循环播放功能,监听消防应急广播扬声器和火灾声警报声音的交替循环播放。"},{"id":"ms-0318","type":"single","question":"对送风机未端配电装置进行保养前,应使用钥匙打开箱门,切断未端配电装置的（）。","options":[{"value":"A","text":"主电源","isCorrect":false},{"value":"B","text":"备用电源","isCorrect":false},{"value":"C","text":"主、备电源","isCorrect":true},{"value":"D","text":"电源线路","isCorrect":false}],"answer":"C","explanation":"中级178页,送风机未端配电装置的保养,使用钥匙打开箱门,切断未端配电装置的主备电源。"},{"id":"ms-0319","type":"single","question":"消防泵组电气控制柜内的控制线路发生敌障时,当采用机械应急启动,消防水泵应能在报警后（）min内进入正常运行状态。","options":[{"value":"A","text":"2","isCorrect":false},{"value":"B","text":"3","isCorrect":false},{"value":"C","text":"4","isCorrect":false},{"value":"D","text":"5","isCorrect":true}],"answer":"D","explanation":"中级95页,机械应急启动时,应确保消防水泵在报警后5min内正常工作。"},{"id":"ms-0320","type":"single","question":"（）是指可燃液体挥发的蒸气与空气混合达到一定浓度遇明火发生一闪即逝的燃烧,或者将可燃固体加热到一定温度后,遇明火发生一闪即灭的燃烧现象。","options":[{"value":"A","text":"阴燃","isCorrect":false},{"value":"B","text":"着火","isCorrect":false},{"value":"C","text":"自燃","isCorrect":false},{"value":"D","text":"闪燃","isCorrect":true}],"answer":"D","explanation":"基础知识20页,闪燃是指可燃液体挥发的蒸气与空气混合达到一定浓度时遇明火发生一闪即灭的燃烧,或者将可燃固体加热到一定温度后,遇明火发生一闪即灭的燃烧现象。"},{"id":"ms-0321","type":"single","question":"（）是指Windows快速执行程序、打开文件、打开文件、打开文件夹、访问系统资源的特殊图形对象。","options":[{"value":"A","text":"开始菜单","isCorrect":false},{"value":"B","text":"文件夹","isCorrect":false},{"value":"C","text":"文件","isCorrect":false},{"value":"D","text":"快捷方式","isCorrect":true}],"answer":"D","explanation":"基础知识162页,快捷方式是指Windows快速执行程序、打开文件(文件夹)、访问系统资源的特殊图形对象,"},{"id":"ms-0322","type":"single","question":"我国消防工作是一项由政府统一领导、部门依法监管、单位全面负责、公民积极参与、专业队伍与社会各方面协同、群防群治地预防和减少火灾危害,开展应急救援的公共消防安全的（）工作。","options":[{"value":"A","text":"专业性","isCorrect":false},{"value":"B","text":"特殊性","isCorrect":false},{"value":"C","text":"专门性","isCorrect":true},{"value":"D","text":"独立性","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材7页。我国消防工作是一项由政府统一领导、部门依法监管、单位全面负责、公民积极参与、专业队伍与社会各方面协同、群防群治地预防和减少火灾危害,开展应急救援的公共消防安全的专门性工作。"},{"id":"ms-0323","type":"single","question":"设置在避难层内的可燃液体管道、可燃或助燃气体管道应集中布置,设备管道区应采用耐火极限不低于()的防火隔墙与避难区及其他公共区分隔。","options":[{"value":"A","text":"3.00h","isCorrect":true},{"value":"B","text":"2.50h","isCorrect":false},{"value":"C","text":"2.00h","isCorrect":false},{"value":"D","text":"1.50h","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材62页。除可布置设备用房外,避难层不应用于其他用途。设置在避难层内的可燃液体管道、可燃或助燃气体管道应集中布置,设备管道区应采用耐火极限不低于3.00h的防火隔墙与避难区及其他公共区分隔。管道井和设备间应采用耐火极限不低2.00的防火隔墙与避难区及其他公共区分隔。设备管道区、管道井和设备间与避难区或疏散走道连通时,应设置防火隔间,防火隔间的门应为甲级防火门。"},{"id":"ms-0324","type":"single","question":"下列物质中,（）火灾属于C类火灾。","options":[{"value":"A","text":"木材","isCorrect":false},{"value":"B","text":"钾金属","isCorrect":false},{"value":"C","text":"天然气","isCorrect":true},{"value":"D","text":"石蜡","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材28页。C类火灾:气体火灾,如煤气、天然气、甲烷、乙烷、氢气、乙炔等。"},{"id":"ms-0325","type":"single","question":"石蜡的燃烧属于（）。","options":[{"value":"A","text":"蒸发燃烧","isCorrect":true},{"value":"B","text":"分解燃烧","isCorrect":false},{"value":"C","text":"表面燃烧","isCorrect":false},{"value":"D","text":"沸溢燃烧","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材20页。可熔化的可燃性固体受热后熔融蒸发,蒸气与氧气混合发生燃烧,称为蒸发燃烧,如石蜡、松香、硫、钾、磷、沥青等的燃烧,均为蒸发燃烧。"},{"id":"ms-0326","type":"single","question":"输入设备(InputDevice)是指机输入( )的设备。","options":[{"value":"A","text":"字体和符号","isCorrect":false},{"value":"B","text":"图像和视频","isCorrect":false},{"value":"C","text":"数据和信息","isCorrect":true},{"value":"D","text":"优盘和磁盘","isCorrect":false}],"answer":"C","explanation":"输入设备(InputDevice)是指向计算机输入数据和信息的设备。"},{"id":"ms-0327","type":"single","question":"（）是程序加文档的集合体,是一系列按照特定顺序组织的计算机数据和指令的集合。","options":[{"value":"A","text":"CPU","isCorrect":false},{"value":"B","text":"WORD","isCorrect":false},{"value":"C","text":"硬件","isCorrect":false},{"value":"D","text":"软件","isCorrect":true}],"answer":"D","explanation":"软件是程序加文档的集合体,是一系列按照特定顺序组织的计算机数据和指令的集合。"},{"id":"ms-0328","type":"single","question":"属于开式系统的是（）。","options":[{"value":"A","text":"雨淋系统","isCorrect":true},{"value":"B","text":"干式系统","isCorrect":false},{"value":"C","text":"预作用系统","isCorrect":false},{"value":"D","text":"重复启闭预作用系统","isCorrect":false}],"answer":"A","explanation":"属于开式系统的有雨淋系统和水幕系统"},{"id":"ms-0329","type":"single","question":"()是安装在机械排烟系统各支管端部（烟气吸入口)处,平时呈()状态并满足漏风量要求，火灾时可手动和电动启闭,起排烟作用的阀门。","options":[{"value":"A","text":"排烟防火阀关闭","isCorrect":false},{"value":"B","text":"排烟阀关闭","isCorrect":true},{"value":"C","text":"排烟阀开启","isCorrect":false},{"value":"D","text":"排烟防火阀开启","isCorrect":false}],"answer":"B","explanation":"排烟阀是安装在机械排烟系统各支管端部(烟气吸入口)处,平时呈关闭状态并满足漏风量要求,火灾时可手动和电动启闭,起排烟作用的阀门。排烟防火阀是安装在机械排烟系统的管道上,平时呈开启状态,火灾时当排烟管道内烟气温度达到280°C时关闭,并在一定时间内能满足漏烟量和耐火完整性要求,起隔烟阻火作用的阀门。结合题意,本题选B。"},{"id":"ms-0330","type":"single","question":"火灾探测器直水平安装,当确需倾斜安装时,倾斜角不应大于（）°","options":[{"value":"A","text":"15.0","isCorrect":false},{"value":"B","text":"30.0","isCorrect":false},{"value":"C","text":"45.0","isCorrect":true},{"value":"D","text":"50.0","isCorrect":false}],"answer":"C","explanation":"中级技能58页,火灾探测器宜水平安装,当确需倾斜安装时,倾斜角不应大于45°"},{"id":"ms-0331","type":"single","question":"在空气中遇明火或高温作用时难起火、难微燃、难炭化,火源移走后燃烧或微燃停止的材料属于（）。","options":[{"value":"A","text":"不燃材料","isCorrect":false},{"value":"B","text":"难燃材料","isCorrect":true},{"value":"C","text":"易燃材料","isCorrect":false},{"value":"D","text":"可燃材料","isCorrect":false}],"answer":"B","explanation":"其础出知识43页,难燃材料(制品)是在空气中遇明火或高温作用时难起火、难微燃、难炭化,火源移走后燃烧或微燃停止。"},{"id":"ms-0332","type":"single","question":"下列属于输出设备的是（）。","options":[{"value":"A","text":"键盘","isCorrect":false},{"value":"B","text":"鼠标","isCorrect":false},{"value":"C","text":"显示器","isCorrect":true},{"value":"D","text":"优盘","isCorrect":false}],"answer":"C","explanation":"P147,常见的输出设备有显示器、打印机、绘图仪、投影仪等影像输出系统,语音输出设备,磁记录设备等。"},{"id":"ms-0333","type":"single","question":"下列属于应用软件的是（）。","options":[{"value":"A","text":"WPS","isCorrect":true},{"value":"B","text":"Windows","isCorrect":false},{"value":"C","text":"数据库管理系统","isCorrect":false},{"value":"D","text":"故障检查和诊断程序","isCorrect":false}],"answer":"A","explanation":"基础知识151-152页,WPS是文字处理应用软件, Windows、数据库管理系统、故障检查和诊断程序属于系统软件。"},{"id":"ms-0334","type":"single","question":"标准Windows键盘采有（）个键。","options":[{"value":"A","text":"103","isCorrect":false},{"value":"B","text":"104","isCorrect":true},{"value":"C","text":"105","isCorrect":false},{"value":"D","text":"106","isCorrect":false}],"answer":"B","explanation":"基础知识146页,标准Windows键盘共有104个键,分为主键盘区、功能键区、控制键区、数字键区和状态指示区5个部分。"},{"id":"ms-0335","type":"single","question":"（）是评定可燃气体爆炸危险性的主要依据。","options":[{"value":"A","text":"燃点","isCorrect":false},{"value":"B","text":"自燃点","isCorrect":false},{"value":"C","text":"闪点","isCorrect":false},{"value":"D","text":"爆炸极限","isCorrect":true}],"answer":"D","explanation":"基础知识27页,爆炸极限是评估可燃的气体、蒸气或粉尘等物质火灾危险性的重要参数,一般来说爆炸下限越低或爆炸极限范围越大,可燃物的火灾爆炸危险性就越大。"},{"id":"ms-0336","type":"single","question":"送风口、排风口、排烟防火阀、挡烟垂壁的保养周期为（）保养一次。","options":[{"value":"A","text":"每月","isCorrect":false},{"value":"B","text":"每季度","isCorrect":false},{"value":"C","text":"每半年","isCorrect":true},{"value":"D","text":"每年","isCorrect":false}],"answer":"C","explanation":"中级172页,送风口、排风口、排烟防火阀、挡烟垂壁的保养周期为每半年一次。"},{"id":"ms-0337","type":"single","question":"《建筑火火器配置设计规范》适用于()内设置灭火器。","options":[{"value":"A","text":"生产火药、炸药的场所","isCorrect":false},{"value":"B","text":"贮存火药、炸药的场所","isCorrect":false},{"value":"C","text":"生产花炮的厂房或库房","isCorrect":false},{"value":"D","text":"储存可燃物工业与民用建筑","isCorrect":true}],"answer":"D","explanation":"基础知识200页,本规范适用于生产、使用或储存可燃然物的新建改建、扩建的工业与民用建存可燃物的新建、改建、扩建的工业与民用建筑工程,不适用于生产或诸存炸药、弹药、火工品、花炮的厂房或库房。"},{"id":"ms-0338","type":"single","question":"消防电话总机设置在（）。","options":[{"value":"A","text":"消防控制室","isCorrect":true},{"value":"B","text":"消防水泵房","isCorrect":false},{"value":"C","text":"发电机房","isCorrect":false},{"value":"D","text":"配变电室","isCorrect":false}],"answer":"A","explanation":"中级62页,消防电话总机应安装在消防控制室,设备应安装牢固,不倾斜。"},{"id":"ms-0339","type":"single","question":"通过总线手动控制单元手动启停送风机,应确认送风机电气控制柜处于（）运行模式,同时进入消防联动控制器的（）操作权限。","options":[{"value":"A","text":"自动,手动允许","isCorrect":true},{"value":"B","text":"自动,手动禁止","isCorrect":false},{"value":"C","text":"手动,手动允许","isCorrect":false},{"value":"D","text":"手动,手动禁止","isCorrect":false}],"answer":"A","explanation":"中级154页,通过总线手动控制单元手动启停送风机,确认送风机电气控制柜处于\"自动\"运行模式,同时进入消防联动控制器的\"手动允许\"操作权限。"},{"id":"ms-0340","type":"single","question":"下列说法正确的是( )。","options":[{"value":"A","text":"湿式系统在准工作状态下,报警阀后的管道中充满有压气体","isCorrect":false},{"value":"B","text":"干式系统在准工作状态下,报警阀前后的管道中都充满水","isCorrect":false},{"value":"C","text":"预作用系统在准工作状态下,报警阀前后的管道中都充满有压气体","isCorrect":false},{"value":"D","text":"干式系统的启动原理与湿式系统相似,只是将传输喷头开放信号的介质由有压水改为有压气体","isCorrect":true}],"answer":"D","explanation":"中级78页,同湿式系统相比,干式系统传输喷头开放信号的介质由有压水改为有压气体,干式系统中干式报警阀组替代了湿式系统中的湿式报警阀组,同时还增设了充气和气压维持装置。"},{"id":"ms-0341","type":"single","question":"火灾声警报器与消防应急广播分时交替循环播放时,火灾声警报器单次发出火灾警报时间宜为（）。","options":[{"value":"A","text":"8~20s","isCorrect":true},{"value":"B","text":"5 ~20s","isCorrect":false},{"value":"C","text":"8~30s","isCorrect":false},{"value":"D","text":"5~30s","isCorrect":false}],"answer":"A","explanation":"中级62页,消防应急广播系统应与火灾声警报器分时交替工作。根据消防设计文件核查其交替工作情况,设计文件未明确的,可来取1次火灾声警报器播放、1次或2次消防应急广播播放的交替工作方式循环播放。消防应急广播的单次语音播放时间宜为10一30s,火灾声警报器单次发出火灾警报时间宜为8~20s。"},{"id":"ms-0342","type":"single","question":"（）是一款具备检测低压配电线路中剩余电流和线路温度功能,且能够独立使用的电气火灾监控探测器。","options":[{"value":"A","text":"剩余电流式电气火灾监控探测器","isCorrect":false},{"value":"B","text":"故障电弧探测器","isCorrect":false},{"value":"C","text":"测温式电气火灾监控探测器","isCorrect":false},{"value":"D","text":"独立式电气火灾监控探测器","isCorrect":true}],"answer":"D","explanation":"独立式电气火灾监控探测器是一款具备检测低压配电线路中剩余电流和线路温度功能,且能够独立使用的电气火灾监控探测器。"},{"id":"ms-0343","type":"single","question":"扑救水溶性B类火灾不得选用（）。","options":[{"value":"A","text":"水系灭火剂","isCorrect":false},{"value":"B","text":"气体灭火剂","isCorrect":false},{"value":"C","text":"干粉灭火剂","isCorrect":false},{"value":"D","text":"化学泡沫灭火剂","isCorrect":true}],"answer":"D","explanation":"(1) A类火灾是指固体物质火灾,这种物质通常具有有机物的性质,一般在燃烧时能产生灼热的余。例如,木材、煤、棉、毛、麻、纸张等物质火灾。扑救A类火灾应选用水系、泡沫、干粉等灭火剂。(2) B类火灾是指液体或可熔化的固体物质火灾。例如,煤油、柴油、原油、甲醇、乙醇、沥青、石蜡等物质火灾。扑救B类火灾应选用干粉、泡沫、卤代烷、二氧化碳等灭火剂,扑救水溶性B类火灾不得选用化学泡沫灭火剂。(3) C类火灾是指气体火灾。例如,煤气、天然气、甲烷、乙烷、丙烷、氢气等气体火灾。"},{"id":"ms-0344","type":"single","question":"下列属于外存储器的是( )。","options":[{"value":"A","text":"只读存贮器","isCorrect":false},{"value":"B","text":"随机存贮器","isCorrect":false},{"value":"C","text":"高速缓冲存储器","isCorrect":false},{"value":"D","text":"优盘","isCorrect":true}],"answer":"D","explanation":"1)内存主要包括随机存取存储器、只读存储器，随机存取存储器,可以随时读写(刷新时除外),而且速度很快,一旦断电所存储的数据将随之丢失；2)只读存储器,信息一旦写入后就固定下来,即使切断电源,信息也不会丢失,所以又称为固定存储器；(2)外存主要包括硬盘、光盘、移动硬盘、U盘等；3)硬盘。硬盘主要分为固态硬盘、机械硬盘、混合硬盘等固态硬盘采用闪存颗粒来存储,机几种类型。 固态硬盘采用闪存颗粒来存储,机械硬盘采用磁性碟片来存储,混合硬盘是把磁性碟片和闪存颗粒集成到一起的一种硬盘。机械硬盘最主要的性能指标是转速和容量。转速是指硬盘盘片旋转的速度。"},{"id":"ms-0345","type":"single","question":"蛋白泡沫火火剂由含蛋白的原料经部分水解制成,是一种()的黏稠液体,具有天然蛋白质分解后的臭味。","options":[{"value":"A","text":"黑褐色","isCorrect":true},{"value":"B","text":"黄色","isCorrect":false},{"value":"C","text":"奶白色","isCorrect":false},{"value":"D","text":"青绿色","isCorrect":false}],"answer":"A","explanation":"蛋白泡沫灭火剂由含蛋白的原料经部分水解制成,是一种黑褐色的黏稠液体,具有天然蛋白质分解后的臭味。"},{"id":"ms-0346","type":"single","question":"消防安全重点单位应至少每()组织一次演练。","options":[{"value":"A","text":"月","isCorrect":false},{"value":"B","text":"季度","isCorrect":false},{"value":"C","text":"半年","isCorrect":true},{"value":"D","text":"年","isCorrect":false}],"answer":"C","explanation":"消防安全重点单位应至少每半年组织一次演练,火灾高危单位应至少每季度组织一次演练,其他单位应至少每年组织一次演练。在火灾多发季节或有重大活动保卫任务的单位,应组织全要素综合演练。单位内的有关部门应结合实际适时组织专项演练,宜每月组织开展一次疏散演练。"},{"id":"ms-0347","type":"single","question":"防火卷帘控制器及手动按钮盒的安装应牢固可靠,其底边距地面高度宜为()安装。","options":[{"value":"A","text":"1.1 ~ 1.3m","isCorrect":false},{"value":"B","text":"1.0~ 1.5m","isCorrect":false},{"value":"C","text":"1.0~1.2m","isCorrect":false},{"value":"D","text":"1.3~1.5m","isCorrect":true}],"answer":"D","explanation":"防火卷帘控制器及手动按钮盒的安装应牢固可靠,其底边距地面高度宜为1.3~1.5m安装。"},{"id":"ms-0348","type":"single","question":"联动型火灭报警控制器,有时也把压力开关、水流指示器、信号蝶阀等传递的信号设为()。","options":[{"value":"A","text":"火警信号","isCorrect":false},{"value":"B","text":"启动信号","isCorrect":false},{"value":"C","text":"屏蔽信号","isCorrect":false},{"value":"D","text":"监管信号","isCorrect":true}],"answer":"D","explanation":"联动型火灾报警控制器,有时也把压力开关水流指示器、信号蝶阀等传递的信号设为监管信号。"},{"id":"ms-0349","type":"single","question":"中倍数泡沫灭火系统是指发泡倍数为()的泡沫灭火系统。","options":[{"value":"A","text":"小于20","isCorrect":false},{"value":"B","text":"21 ~ 200","isCorrect":true},{"value":"C","text":"201~1000","isCorrect":false},{"value":"D","text":"大于1000","isCorrect":false}],"answer":"B","explanation":"泡沫灭火系统的分类方法:1按结构形式:分为固定式系统、半固定系统、移动式系统。2按发泡倍数:分为低倍数泡沫灭火系统、中倍数泡沫灭火系统、高倍数泡沫灭火系统。3按系统形式:分为全淹没泡沫灭火系统、局部应用泡沫灭火系统、移动式泡沫灭火系统、泡沫-水喷淋系统、泡沫喷雾系统、压缩空气泡沫灭火系统。泡沫灭火系统按发泡倍数分为低倍数泡沫灭火系统、中倍数泡沫灭火系统、高倍数泡沫灭火系统、,其中,低倍数泡沫灭火系统是指发泡倍数低于20的泡沫灭火系统,中倍数泡沫灭火系统是指发泡倍数为21~200的泡沫灭火系统,。"},{"id":"ms-0350","type":"single","question":"多线控制盘与火灾报警控制器连接,一台火灾报警控制器(联动型)可设置()多线控制盘。","options":[{"value":"A","text":"一个","isCorrect":false},{"value":"B","text":"多个","isCorrect":true},{"value":"C","text":"两个","isCorrect":false},{"value":"D","text":"至少两个","isCorrect":false}],"answer":"B","explanation":"多线控制盘与火灾报警控制器连接一台火灾报警控制器(联动型)，可设置多个多线控制盘。"},{"id":"ms-0351","type":"single","question":"消防应急照明和疏散指示系统按()可分为集中电源集中控制型系统、集中电源非集中控制型系统、自带电源集中控制型系统和自带电源非集中控制型系统。","options":[{"value":"A","text":"系统形式","isCorrect":true},{"value":"B","text":"供电方式","isCorrect":false},{"value":"C","text":"应急控制方式","isCorrect":false},{"value":"D","text":"工作方式","isCorrect":false}],"answer":"A","explanation":"消防应急照明和疏散指示系统按系统形式可分为集中电源集中控制型系统、集中电源非集中控制型系统、自带电源集中控制型系统和自带电源非集中控制型系统。"},{"id":"ms-0352","type":"single","question":"（）是指响应火焰发出的特定波段电磁( )辐射的探测器。","options":[{"value":"A","text":"感光火灾探测器","isCorrect":true},{"value":"B","text":"感温火火探测器","isCorrect":false},{"value":"C","text":"感烟火灾探测器","isCorrect":false},{"value":"D","text":"线型火灾探测器","isCorrect":false}],"answer":"A","explanation":"感光火灾探测器是指响应火焰发出的特定波段电磁辐射的探测器"},{"id":"ms-0353","type":"single","question":"下列不属于消防泵组及电气控制柜保养要求的是( )。","options":[{"value":"A","text":"控制柜工作环境良好,无积灰和蛛网,无杂物堆放","isCorrect":false},{"value":"B","text":"控制柜平时应处于手动状态","isCorrect":true},{"value":"C","text":"消防水泵运转正常,无异常震动或声响","isCorrect":false},{"value":"D","text":"主/备泵互换功能正常","isCorrect":false}],"answer":"B","explanation":"控制柜平时应处于自动状态。结合题意,本题选B。"},{"id":"ms-0354","type":"single","question":"线型感温火灾探测器按()可分为缆式、空气管式、分布式光纤、光栅光纤和线式多点型。","options":[{"value":"A","text":"敏感部件形式","isCorrect":true},{"value":"B","text":"动作性能","isCorrect":false},{"value":"C","text":"可恢复性能","isCorrect":false},{"value":"D","text":"定位方式","isCorrect":false}],"answer":"A","explanation":"中级技能81页,按敏感部件形式可分为缆式、空气管式、分布式光纤、光栅光纤和线式多点型线型感温探测器。"},{"id":"ms-0355","type":"single","question":"火灾扑灭后,故意破坏或伪造现场,尚不构成犯罪的,情节较轻的,处警告或者()元以下罚款。","options":[{"value":"A","text":"二百","isCorrect":false},{"value":"B","text":"三百","isCorrect":false},{"value":"C","text":"五百","isCorrect":true},{"value":"D","text":"一干","isCorrect":false}],"answer":"C","explanation":"根据《中华人民共和国消防法》第六十四条违反本法规定,有下列行为之一,尚不构成犯罪的,处十日以上十五日以下拘留,可以并处五百元以下罚款;情节较轻的,处警告或者五百元以下罚款:(一)指使或者强令他人违反消防安全规定,冒险作业的;(二)过失引起火灾的;(三)在火灾发生后阻拦报警,或者免有报告职责的人员不及时报整的:(四)扰负有报告职责的人员不及时报警的;(四)扰乱火灾现场秩序,或者拒不执行火灾现场指挥员指挥,影响灭火救援的;(五)故意破坏或者伪造火灾现场的;(六)擅自拆封或者使用被消防救援机构查封的场所、部位的。"},{"id":"ms-0356","type":"single","question":"公众聚集场所未经（）许可的,不得投入使用、营业。","options":[{"value":"A","text":"公安机关","isCorrect":false},{"value":"B","text":"应急管理部门","isCorrect":false},{"value":"C","text":"地方人民政府","isCorrect":false},{"value":"D","text":"消防救援机构","isCorrect":true}],"answer":"D","explanation":"基础知识14页,公众聚集场所未经消防救援机构许可的,不得投入使用、营业。消防安全检查的具体办法,由国务院应急管理部门制定。"},{"id":"ms-0357","type":"single","question":"职业分类是指以工作性质的()为基本原则,对社会职业进行的系统划分与归类。","options":[{"value":"A","text":"统一性","isCorrect":false},{"value":"B","text":"相似性","isCorrect":false},{"value":"C","text":"同一性","isCorrect":true},{"value":"D","text":"相关性","isCorrect":false}],"answer":"C","explanation":"基础知识第5页,职业分类是指以工作性质的同一性为基本原则,对社会职业进行的系统划分与归类。"},{"id":"ms-0358","type":"single","question":"消滑防安全重点单位微型滑防站接到火情信息后，消防员应按照（）分钟到场的要求赶赴现场处置。","options":[{"value":"A","text":"1","isCorrect":false},{"value":"B","text":"3","isCorrect":true},{"value":"C","text":"5","isCorrect":false},{"value":"D","text":"7","isCorrect":false}],"answer":"B","explanation":"消防安全重点单位微型消防站接到火警信息后,控制室值班员应迅速核实火情,启动灭火处置程序。消防员应按照3min到场的要求赶赴现场处置。"},{"id":"ms-0359","type":"single","question":"测试湿式报警延时器延迟时间,打开警铃试验凝时按下秒表开始计时,待警铃响起的同时停止秒表,水力警铃应在（）s内发出报警铃声。","options":[{"value":"A","text":"5-90","isCorrect":true},{"value":"B","text":"10-90","isCorrect":false},{"value":"C","text":"20-90","isCorrect":false},{"value":"D","text":"60-90","isCorrect":false}],"answer":"A","explanation":"新教材中级技能129页,测试湿式报警阀组延迟器延迟时间,打开水力警铃试验阀,同时按下秒表开始计时,待警铃响起时,停止秒表,通过秒表显示核香延迟时间。水力警铃应在5~90s内发出报警铃声。"},{"id":"ms-0360","type":"single","question":"对于疏散通道上设置的防火卷帘,由防火分区内任两只独立的感烟火灾探测器或任一只专门用于联动防火卷帘的感烟火灾探测器的报警信号联动控制防火卷帘下降至距楼板面()处。","options":[{"value":"A","text":"1.2m","isCorrect":false},{"value":"B","text":"1.3m","isCorrect":false},{"value":"C","text":"1.8m","isCorrect":true},{"value":"D","text":"1.5m","isCorrect":false}],"answer":"C","explanation":"对于疏散通道上设置的防火卷帘,由防火分区内任两只独立的感烟火灾探测器或任一只专门用于联动防火卷帘的感烟火灾探测器的报警信号联动控制防火卷帘下降至距楼板面1.8m处;由任一只专门用于联动防火卷帘的感温火灾探测器的报警信号联动控制防火卷帘下降到楼板面。在卷帘的任一侧距卷帘纵深0.5~5m内应设置不少于2只专门用于联动防火卷帘的感温火灾探测器。"},{"id":"ms-0361","type":"single","question":"下列不属于湿式、干式自动喷水灭火系统组件保养要求的是（）。","options":[{"value":"A","text":"系统上所有控制阀门外观完好无渗漏,启闭功能正常,状态正确","isCorrect":false},{"value":"B","text":"管道及附件外观应完好、无损伤,管道接头无渗漏、锈蚀","isCorrect":false},{"value":"C","text":"报警阀组外观完好,标识清晰,注明系统名称和保护区域","isCorrect":false},{"value":"D","text":"应设有自动防潮除湿装置","isCorrect":true}],"answer":"D","explanation":"湿式、干式自动喷水灭火系统组件的保养内容及要求:系统上所有控制阀门外观完好无渗漏,启闭功能正常,状态正确,标识清晰,铅封、锁链完好;管道及附件外观应完好、无损伤,管道接头无渗漏、锈蚀;报警阀组外观完伤,管道接头无渗漏、锈蚀;报警阀组外观完好,标识清晰,并注明系统名称和保护区域自动喷水灭火系统组件的保养无自动防潮除湿装置的要求。"},{"id":"ms-0362","type":"single","question":"通过手动开启排烟阀(排烟口)联动启动排烟风机,应先将排烟风机电气控制柜处于（）运行模式,同时进入消防联动控制器的（）操作权限。","options":[{"value":"A","text":"自动,自动允许","isCorrect":true},{"value":"B","text":"自动,自动禁止","isCorrect":false},{"value":"C","text":"手动,手动允许","isCorrect":false},{"value":"D","text":"手动,手动禁止","isCorrect":false}],"answer":"A","explanation":"1.手动开启排烟阀(排烟口)联动启动排烟风机：(1)设置排烟风机电气控制柜和消防联动控制器控制状态确认排烟风机电气控制柜处于\"自动”运行模式,同时进入消防联动控制器的\"自动允许\"操作权限。(2)手动打开排烟阀(排烟口)以板式排烟口操作为例,拨动板式排烟口远程执行机构的火警开关,板式排烟口即可开启。排烟口开启后,相应的排烟风机、补风机应能联动启动,查看消防联动控制器能否收到排烟风机、补风机启动反馈信号。(3)手动停止排烟风机先将排烟风机电气控制柜置于“手动“运行模式,再按下停止按钮使风机停止运行。"},{"id":"ms-0363","type":"single","question":"当室内通风不良、燃烧处于缺氧状态时,由于氧气的引入导致热烟气发生的爆炸性或快速的燃烧现象,称为（）。","options":[{"value":"A","text":"闪燃","isCorrect":false},{"value":"B","text":"回燃","isCorrect":true},{"value":"C","text":"轰燃","isCorrect":false},{"value":"D","text":"爆炸","isCorrect":false}],"answer":"B","explanation":"P034,当室内通风不良、燃烧处于缺氧状态时,由于氧气的引入导致热烟气发生的爆炸性或快速的燃烧现象称为回燃。"},{"id":"ms-0364","type":"single","question":"室内消防给水系统按（）分为湿式消火栓系统和干式消火栓系统。","options":[{"value":"A","text":"管网状态","isCorrect":true},{"value":"B","text":"给水范围","isCorrect":false},{"value":"C","text":"用途","isCorrect":false},{"value":"D","text":"水压","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》老教材270页。室内消防给水系统按管网状态分为湿式消火栓系统和干式消火栓系统。"},{"id":"ms-0365","type":"single","question":"()的作用是接收、显示和传递火灾报警信号,记录报警的具体部位及时间,监视探测器及系统自身的工作状态,并执行相应辅助控制等任务。","options":[{"value":"A","text":"手动火灾报警按钮","isCorrect":false},{"value":"B","text":"火灾报警控制器","isCorrect":true},{"value":"C","text":"火灾声光警报器","isCorrect":false},{"value":"D","text":"火灾探测器","isCorrect":false}],"answer":"B","explanation":"本题所述为火灾报警控制器的作用,它能发出区别于环境声、光的火灾报警信号,警示人们迅速进行安全疏散和采取火灾扑救措施。结合结合题意,本题应选\"火灾报警控制器”,其他项均可排除。"},{"id":"ms-0366","type":"single","question":"排烟防火阀安装在机戒排烟系统的管道上,平的呈开启状态,火灾时当排烟管道内烟气温度达到（）时关闭。","options":[{"value":"A","text":"240°C","isCorrect":false},{"value":"B","text":"280°C","isCorrect":true},{"value":"C","text":"200°C","isCorrect":false},{"value":"D","text":"220°C","isCorrect":false}],"answer":"B","explanation":"排烟防火阀安装在机械排烟系统的管道上,平时呈开启状态,火灾时当排烟管道内烟气温度达到280时关闭。"},{"id":"ms-0367","type":"single","question":"职业标准依据（）制定。","options":[{"value":"A","text":"职业种类","isCorrect":false},{"value":"B","text":"职业类别","isCorrect":false},{"value":"C","text":"职业分类","isCorrect":true},{"value":"D","text":"职业名称","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材5页。职业分类作为制定职业标准的依据,是促进人力资源科学化、规范化管理的重要基础性工作。"},{"id":"ms-0368","type":"single","question":"凡与可燃物质相结合能导致燃烧的物质称为（）。","options":[{"value":"A","text":"可燃物","isCorrect":false},{"value":"B","text":"助燃物","isCorrect":true},{"value":"C","text":"氧化物","isCorrect":false},{"value":"D","text":"导热体","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材17页。助燃物也称氧化剂,是指能与可燃物质发生燃烧反应的物质,通常燃烧过程中的助燃物主要是氧。"},{"id":"ms-0369","type":"single","question":"通过集中控制器查询历史信息时,按下集中控制器键盘区域的\"（）\"键,即可查看历史事件信息。","options":[{"value":"A","text":"F9历史事件","isCorrect":true},{"value":"B","text":"F2火警查看","isCorrect":false},{"value":"C","text":"F7历史事件","isCorrect":false},{"value":"D","text":"F7启动","isCorrect":false}],"answer":"A","explanation":"中级技能29页,1.通过集中控制器查询历史信息(1)进入历史记录查询界面按下集中控制器键盘区域的\"F9历史事件\"键,即可查看历史事件信息。(2)选择事件类型查看信息进入主菜单界面,选择\"查看\"菜单,移动光标至\"历史事件”,可显示火警报警事件、联动历史事件、全部历史事件等情况,可通过左右方向键切换不同的信息界面。"},{"id":"ms-0370","type":"single","question":"通过单击（）右侧的中/英按钮,可以切换中英文输入法。","options":[{"value":"A","text":"桌面","isCorrect":false},{"value":"B","text":"开始菜单","isCorrect":false},{"value":"C","text":"任务栏","isCorrect":true},{"value":"D","text":"软件窗口","isCorrect":false}],"answer":"C","explanation":"通过单击任务栏右侧的中/英按钮,可以切换中英文输入法。"},{"id":"ms-0371","type":"single","question":"当被保护线路剩余电流达到报警设定值时,剩余电流式电气火灾监控探测器应能在（）内发出报警信号,点亮报警指示灯,向电气火灾监控设备发送报警信号。","options":[{"value":"A","text":"10s","isCorrect":false},{"value":"B","text":"30s","isCorrect":true},{"value":"C","text":"40s","isCorrect":false},{"value":"D","text":"20s","isCorrect":false}],"answer":"B","explanation":"中级技能36页,当被保护线路剩余电流达到报警设定值时,剩余电流式电气火灾监控探测器应能在30s内发出报警信号,点亮报警指示灯,向电气火灾监控设备发送报警信号。故而本题选B."},{"id":"ms-0372","type":"single","question":"下列不属于电气火灾监控器的保养步骤的是（）。","options":[{"value":"A","text":"使用钥匙打开箱门,将监控器主、备电源切断","isCorrect":false},{"value":"B","text":"用小毛刷将机柜(壳)内设备空隙和线材(壳)内设备空隙和线材上的灰尘和杂质清扫出来,然后用吸尘器清理干净","isCorrect":false},{"value":"C","text":"检查线路接头处有无氧化或锈蚀痕迹,若有则应采取防潮、防锈措施,如镀锡和涂凡士林等","isCorrect":false},{"value":"D","text":"保养结束后,给监控器送电,钥匙放入箱内。","isCorrect":true}],"answer":"D","explanation":"中级技能170页,保养工作完成后,保养人员需要仔细检查并确保没有异物落入且遗留在机柜(壳)内、电器元件及线路中,检查完成后方可上电。保养结束后,给控制器送电,用钥匙将箱门锁闭。"},{"id":"ms-0373","type":"single","question":"下列不属于老年人照料设施的是（）。","options":[{"value":"A","text":"敬老院","isCorrect":false},{"value":"B","text":"养老院","isCorrect":false},{"value":"C","text":"老年人日间照料中心","isCorrect":false},{"value":"D","text":"老年大学","isCorrect":true}],"answer":"D","explanation":"基础知识41页,老年人照料设施是指为老年人提供集中照料服务的设施,是老年人全日照料设施和老年人日间照料设施的统称,属于公共建筑。其中,老年人全日照料设施是指为老年人提供住宿、生活照料服务及其他服务项目的设施,是养老院、老人院、福利院、敬老院、老年养护院等的统称;老年人日间照料设施是指为老年人提供日间休息、生活照料服务及其他服务项目的设施,是托老所、日托站、老年人日间照料室、老年人日间照料中心等的统称。其他专供老年人使用的、非集中照料的设施或场所,如老年大学、老年人活动中心等不属于老年人照料设施"},{"id":"ms-0374","type":"single","question":"通过采用自然通风方式,防止火灾烟气在楼梯间、前室、避难层(间)等空间内积聚,或通过采用机械加压送风方式阻止火灾烟气侵入楼梯间、前室、避难层(间)等空间的系统是（）。","options":[{"value":"A","text":"通风空气调节系统","isCorrect":false},{"value":"B","text":"防烟系统","isCorrect":true},{"value":"C","text":"排烟系统","isCorrect":false},{"value":"D","text":"火灾自动报警系统","isCorrect":false}],"answer":"B","explanation":"基础出知识111页,建筑防烟系统主要有自然通风和机械加压送风两种形式。防烟系统通过采用自然通风方式,防止火灾烟气在楼梯间、前室、避难层(间)等空间内积聚,或通过采用机械加压送风方式阻止火灾烟气侵入楼梯间、前室、避难层(间)等空间。"},{"id":"ms-0375","type":"single","question":"下列部位可不设置消防电话分机的是（）。","options":[{"value":"A","text":"消防水泵房","isCorrect":false},{"value":"B","text":"发电机房","isCorrect":false},{"value":"C","text":"配变电室","isCorrect":false},{"value":"D","text":"会议室","isCorrect":true}],"answer":"D","explanation":"中级63页,消防水泵房、发电机房、配变电室、计算机网络机房、主要通风和空调机房、防排烟机房、灭火控制系统操作装置处或控制室、企业消防站、消防值班室、总调度室、消防电梯轿厢、消防电梯机房及其他与消防联动控制有关的且经常有人值班的机房应设置消防电话分机。"},{"id":"ms-0376","type":"single","question":"下列不属于稳压泵组保养要求的是（）。","options":[{"value":"A","text":"稳压泵交替运行功能正常","isCorrect":false},{"value":"B","text":"电动机绝缘正常,紧固螺栓无松动,电缆无老化、破损和连接松动","isCorrect":false},{"value":"C","text":"冬季防冻措施有效","isCorrect":true},{"value":"D","text":"润滑油充足,泵体、泵轴无渗水、砂眼","isCorrect":false}],"answer":"C","explanation":"冬季防冻措施有效属于消防水箱的保养要求。结合题意,本题C选项不属于稳压泵组的的保养要求。"},{"id":"ms-0377","type":"single","question":"水力警铃的设置位置应正确,直距水力警铃（）m远处警铃声声强不应小于（）dB。","options":[{"value":"A","text":"2,65","isCorrect":false},{"value":"B","text":"3,65","isCorrect":false},{"value":"C","text":"3,70","isCorrect":true},{"value":"D","text":"5,70","isCorrect":false}],"answer":"C","explanation":"新教材中级技能122页,水力警铃的工作压力不应小于0.05MPa,应设在有人值班的地点附近或公共通道的外墙上;与报警阀连接的管道,其管径应为20mm,总长不宜大于20m;水力警铃的设置位置应正确,且距水力警铃3m远处警铃声强不应小于70dB。"},{"id":"ms-0378","type":"single","question":"下列属于公共建筑的是（）。","options":[{"value":"A","text":"住宅楼","isCorrect":false},{"value":"B","text":"砖厂","isCorrect":false},{"value":"C","text":"图书馆","isCorrect":true},{"value":"D","text":"物流仓库","isCorrect":false}],"answer":"C","explanation":"A属王住宅,B属于厂房,D属于仓库,BD属于工业建筑。"},{"id":"ms-0379","type":"single","question":"手动停止送风机时,应先将送风机电气控制柜置于（）运行模式,再按下（）按钮,使送风机停止运行。","options":[{"value":"A","text":"自动,启动","isCorrect":false},{"value":"B","text":"自动,停止","isCorrect":false},{"value":"C","text":"手动,启动","isCorrect":false},{"value":"D","text":"手动,停止","isCorrect":true}],"answer":"D","explanation":"中级技能154页停止送风机时，先将送风机电气控制柜置于\"手动\"运行模式,再按下停止按钮,使送风机停止运行。"},{"id":"ms-0380","type":"single","question":"自动喷水灭火系统的管道材质、管径、接头、管道连接方式及采取的（）等措施,应符合标准和消防设计文件要求。","options":[{"value":"A","text":"防锈","isCorrect":false},{"value":"B","text":"防腐、防冻","isCorrect":true},{"value":"C","text":"防腐","isCorrect":false},{"value":"D","text":"防冻","isCorrect":false}],"answer":"B","explanation":"新教材中级技能119页，管道材质、管径、接头、管道连接方式及采取的防腐、防冻等措施,应符合标准和消防设计文件要求。"},{"id":"ms-0381","type":"single","question":"干式系统有压充气管道的快速排气阀入口前应设（）。","options":[{"value":"A","text":"信号阀","isCorrect":false},{"value":"B","text":"电磁阀","isCorrect":true},{"value":"C","text":"试水阀","isCorrect":false},{"value":"D","text":"报警阀","isCorrect":false}],"answer":"B","explanation":"暂无解析"},{"id":"ms-0382","type":"single","question":"线型光束感烟火灾探测器每（）年进行一次报警功能测试。","options":[{"value":"A","text":"3","isCorrect":false},{"value":"B","text":"半","isCorrect":true},{"value":"C","text":"1","isCorrect":false},{"value":"D","text":"2","isCorrect":false}],"answer":"B","explanation":"线型光束感烟火灾探测器每半年进行一次报警功能测试。"},{"id":"ms-0383","type":"single","question":"做好消防工作是为了（）。","options":[{"value":"A","text":"预防火灾","isCorrect":false},{"value":"B","text":"减少火灾危害","isCorrect":false},{"value":"C","text":"预防火灾和减少火灾危害","isCorrect":true},{"value":"D","text":"开展灭火救援行动","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材7页。开展消防工作是为了预防火灾和减少火灾危害,加强应急救援工作,保护人身、财产安全,维护公共安全。"},{"id":"ms-0384","type":"single","question":"对集中火灾报警控制器、消防联动控制器、消防控制室图形显示装置的开关按键、键盘鼠标的保养方法正确的是（）。","options":[{"value":"A","text":"发现油漆脱落应及时涂补","isCorrect":false},{"value":"B","text":"用清洁剂擦拭表面,确保干净清洁","isCorrect":false},{"value":"C","text":"用小毛刷将孔隙内的灰尘和杂质清扫出来,再用吸尘器清理干净","isCorrect":true},{"value":"D","text":"发现标注的文字、标签脱落可暂缓修复","isCorrect":false}],"answer":"C","explanation":"《中级》老教材166页。(1)用小毛刷将孔隙内的灰尘和杂质清扫出来,再用吸尘器清理干;(2)用湿布擦拭表面,确保干净清洁;(3)发现标注的文字、标签脱落应及时恢复标注。"},{"id":"ms-0385","type":"single","question":"火灭高危单位应至少每（）组织一次演练。","options":[{"value":"A","text":"月","isCorrect":false},{"value":"B","text":"季度","isCorrect":true},{"value":"C","text":"半年","isCorrect":false},{"value":"D","text":"年","isCorrect":false}],"answer":"B","explanation":"基础知识134页,消防安全重点单位应至少每半年组织一次演练,火灾高危单位应至少每季度组织一次演练,其他单位应至少每年组织一次演练。"},{"id":"ms-0386","type":"single","question":"挡烟垂壁按安装方式可分为固定式挡烟垂壁和（）挡烟垂壁。","options":[{"value":"A","text":"半固定式","isCorrect":false},{"value":"B","text":"隐藏式","isCorrect":false},{"value":"C","text":"活动式","isCorrect":true},{"value":"D","text":"隐蔽式","isCorrect":false}],"answer":"C","explanation":"挡烟垂壁按安装方式可分为固定式挡烟垂壁和活动式挡烟垂壁。"},{"id":"ms-0387","type":"single","question":"排烟防火阀、排烟阀的阀体、叶片、执行机构等部件组成相似,保养要求基本一致,主要区别在于排烟防火阀比排烟阀多了（）。","options":[{"value":"A","text":"易熔元件","isCorrect":false},{"value":"B","text":"温控装置","isCorrect":true},{"value":"C","text":"复位装置","isCorrect":false},{"value":"D","text":"手动拉环","isCorrect":false}],"answer":"B","explanation":"中级180页,排烟防火阀、排烟阀的阀体、叶片、执行机构等部件组成相似,主要区别在于排烟防火阀比排烟阀多了温控装置(温感器件)。"},{"id":"ms-0388","type":"single","question":"建筑的下列场所或部位可不设置防烟设施的是（）。","options":[{"value":"A","text":"防烟楼梯间及其前室","isCorrect":false},{"value":"B","text":"消防电梯间前室或合用前室","isCorrect":false},{"value":"C","text":"疏散走道","isCorrect":true},{"value":"D","text":"避难走道的前室、避难层(间)","isCorrect":false}],"answer":"C","explanation":"基础知识111页,《《建筑防火通用规范>(GB55037一2022)中规定,下列部位应采取防烟措施：(1)封闭楼梯间。(2)防烟楼梯间及其前室及其前室。(3)消防电梯的前室或合用前室。(4)避难层、避难间。(5)避难走道的前室,地铁工程中的避难走道。"},{"id":"ms-0389","type":"single","question":"地下消防水泵接合器并的砌筑应有（）。","options":[{"value":"A","text":"防水","isCorrect":false},{"value":"B","text":"排水","isCorrect":false},{"value":"C","text":"防水和排水","isCorrect":true},{"value":"D","text":"泄压和排水","isCorrect":false}],"answer":"C","explanation":"新教材中级技能243页,检查消防水泵接合器管井,止回阀、安全阀、控制阀的安装应牢固可靠不松动,连接应严密无渗漏,止回阀安装方向正确,控制阀启闭灵活且开启完全。地下消防水泵接合器并的砌筑应有防水和排水设施。"},{"id":"ms-0390","type":"single","question":"通过直接手动控制单元手动停止排烟风机操作后,应恢复直接手动控制单元的（）操作权限。","options":[{"value":"A","text":"自动允许","isCorrect":false},{"value":"B","text":"自动禁止","isCorrect":false},{"value":"C","text":"手动允许","isCorrect":false},{"value":"D","text":"手动禁止","isCorrect":true}],"answer":"D","explanation":"中级技能159页,2.通过直接手动控制单元手动启停排烟风机操作进入直接手动控制单元的“手动允许\"操作权限,按下排烟风机启动按钮,排烟风机启动后观察反馈信号指示灯是否点亮;再次按下排烟风机启动按钮,观察排烟风机是否停止,风机停止后反馈信号指示灯应自动熄灭;恢复直接手动控制单元的“手动禁止“操作权限。"},{"id":"ms-0391","type":"single","question":"电缆隧道、电缆竖井、电缆夹层等场所或部宜选择（）火灾探测器。","options":[{"value":"A","text":"线型缆式感温","isCorrect":true},{"value":"B","text":"线型光纤感温","isCorrect":false},{"value":"C","text":"线型定温","isCorrect":false},{"value":"D","text":"线型光束感烟","isCorrect":false}],"answer":"A","explanation":"下列场所或部位,宜选择线型缆式感温火灾探测器:(1)电缆隧道、电缆竖井、电缆夹层、电缆桥架。(2)不易安装点型探测器的夹层、闷顶。(3)各种皮带输送装置。(4)其他因环境恶劣不适合点型探测器安装的场所。"},{"id":"ms-0392","type":"single","question":"下列不属于应急照明控制器保养方法的有（）。","options":[{"value":"A","text":"用吸尘器、清洁的干软布等清除机壳表面、通风格栅内及所有接线端子处灰尘","isCorrect":false},{"value":"B","text":"对所有按键进行按下、弹起操作","isCorrect":false},{"value":"C","text":"用螺丝刀紧固,接线端烫锡","isCorrect":false},{"value":"D","text":"对影响执行机构动作的建筑装饰或杂物及时清除","isCorrect":true}],"answer":"D","explanation":"应急照明控制器的保养内容、要求和方法:用吸尘器、清洁的干软布等清除机壳表面、通风格栅内及所有接线端子处的灰尘;对所有按键进行按下弹起操作;用螺丝刀紧固,接线端烫锡。D选项是排烟防火阀、送风口、排烟口的保养内容。"},{"id":"ms-0393","type":"single","question":"断开集中火灾报警控制器和火灾探测器之间连接线,集中火灾报警控制器处于（）状态。","options":[{"value":"A","text":"监管","isCorrect":false},{"value":"B","text":"故障","isCorrect":true},{"value":"C","text":"火警","isCorrect":false},{"value":"D","text":"屏蔽","isCorrect":false}],"answer":"B","explanation":"-业断开集中火灾报警控制器和火灾探测器之间连接线,集中火灾报警控制器处于故障状态。"},{"id":"ms-0394","type":"single","question":"疏散楼梯间及其前室的门应向（）开启。","options":[{"value":"A","text":"内","isCorrect":false},{"value":"B","text":"外","isCorrect":false},{"value":"C","text":"疏散方向","isCorrect":true},{"value":"D","text":"无特殊要求","isCorrect":false}],"answer":"C","explanation":"一般来说,疏散出口门的设置应符合下列规定。(1)净宽度要求1)疏散出口门的净宽度不应小于0.80m。2)住宅建筑中直通室外地面的住宅户门的净宽度不应小于0.80m。3)首层疏散外门净宽度不应小于1.1m。 (2)开启方向要求除设置在丙、丁、戊类仓库首层靠墙外侧的推拉门或卷帘门可用于疏散门外,疏散出口门应为平开门或在火灾时具有平开功能的门,且下列场所或部位的疏散出口门应向疏散方向开启。1)甲、乙类生产场所。2)甲、乙类物质的储存场所。3)平时使用的人民防空工程中的公共场所。4)其他建筑中使用人数大于60人的房间。"},{"id":"ms-0395","type":"single","question":"在消防控制室将（）从消防电话总机的支架上摘下,系统自动进入呼叫准备。","options":[{"value":"A","text":"话筒","isCorrect":true},{"value":"B","text":"电话分机","isCorrect":false},{"value":"C","text":"电话插孔","isCorrect":false},{"value":"D","text":"电话手柄","isCorrect":false}],"answer":"A","explanation":"中级技能32页,在消防控制室将话筒从总机的话筒支架上摘下,系统自动进入呼叫准备。"},{"id":"ms-0396","type":"single","question":"通过直接手动控制单元启动相关联动设备时,确认对应受控设备标签名称书写无误,按下相应联动设备启动按键,观察设备的\"（）\"指示灯点亮情况。","options":[{"value":"A","text":"启动/反馈","isCorrect":true},{"value":"B","text":"启动/停止","isCorrect":false},{"value":"C","text":"联动/应答","isCorrect":false},{"value":"D","text":"启动/故障","isCorrect":false}],"answer":"A","explanation":"中级技能31页,如何操作直接手动控制单元(1)进入当前操作权限级别。确认直接手动控制单元处于“手动充许“状态,同时确认当前联动设备无故障。(2)启动相关联动设备动作。确认对应受控设备标签名称书写无误,按下相应联动设备启动按键,观察设备的“启动/反馈\"指示灯点亮情况。(3)停止相关联动设备动作。按下对应设备的\"停止\"键,观察停止按键指示灯点亮情况。(4)操作完毕后,按规定做好记录。"},{"id":"ms-0397","type":"single","question":"下列属于可燃性构件的是( )。","options":[{"value":"A","text":"水泥刨花板","isCorrect":false},{"value":"B","text":"钢柱","isCorrect":false},{"value":"C","text":"砖墙","isCorrect":false},{"value":"D","text":"木梁","isCorrect":true}],"answer":"D","explanation":"木梁属于可燃性构件,其他选项均可排除,本题选择D。"},{"id":"ms-0398","type":"single","question":"消防水箱设置在建筑物高处,是保证扑救（）用水量的可靠供水设施。","options":[{"value":"A","text":"初期火灾","isCorrect":true},{"value":"B","text":"重大火灾","isCorrect":false},{"value":"C","text":"特别重大火灾","isCorrect":false},{"value":"D","text":"全面燃烧火灾","isCorrect":false}],"answer":"A","explanation":"暂无解析"},{"id":"ms-0399","type":"single","question":"可燃物质,在没有外部火花、火焰等火源的作用下,因受热或自身发热并蓄热所产生的燃烧现象,称为（）。","options":[{"value":"A","text":"阴燃","isCorrect":false},{"value":"B","text":"着火","isCorrect":false},{"value":"C","text":"自燃","isCorrect":true},{"value":"D","text":"着火点","isCorrect":false}],"answer":"C","explanation":"基础知识18页,自燃就是可燃物在空气中没有外部引火源的作用,靠自热或外热而发生燃烧的现象。"},{"id":"ms-0400","type":"single","question":"防火门监控器应能接收来自火灾自动报警系统的火灾报警信号,并在（）S内向电动闭门器或电磁释放器发出启动信号,点亮启动总指示灯。","options":[{"value":"A","text":"15","isCorrect":false},{"value":"B","text":"30","isCorrect":true},{"value":"C","text":"10","isCorrect":false},{"value":"D","text":"60","isCorrect":false}],"answer":"B","explanation":"中级技能142页,属于防火门监控器的控制功能。防火门监控器应能接收来自火灾自动报警系统的火灾报警信号,并在30s内向电动闭门器或电磁释放器发出启动信号,点亮启动总指示灯。"},{"id":"ms-0401","type":"single","question":"用万用表测量集中火火报警控制器总线回路最末端（）或模块的供电电压,发现和确认需要保养的线路。","options":[{"value":"A","text":"火灾探测器","isCorrect":true},{"value":"B","text":"手动火灾报警按钮","isCorrect":false},{"value":"C","text":"声报警器","isCorrect":false},{"value":"D","text":"光警报器","isCorrect":false}],"answer":"A","explanation":"中级43页,用万用表测量控制总线回路最末端火灾探测器或模块的输入电压,应满足设计要求。"},{"id":"ms-0402","type":"single","question":"火灾自动报警系统控制器显示“模块故障\",但模块的\"巡检灯\"闪亮,此时下列维修方法错误的是（）。","options":[{"value":"A","text":"检查设备反馈端输出,要求反馈信号为无源反馈","isCorrect":false},{"value":"B","text":"重新对编码错误的模块进行编码","isCorrect":false},{"value":"C","text":"修复总线故障或修复故障电源使电压正常","isCorrect":true},{"value":"D","text":"检修模块的启动控制线路至正常","isCorrect":false}],"answer":"C","explanation":"中级50页,火灾自动报警系统组件常见故障:总线短路隔离器和模块:控制器显示\"模块故障\",但模块\"巡检灯\"闪亮;维修方法:(1)检查设备反馈端输出,要求反馈信号为无源反馈;(2)重新对编码错误的模块进行编码;(3)检修模块的启动控制线路至正常。"},{"id":"ms-0403","type":"single","question":"无遮挡的大空间或有特殊要求的房间,宜选择( )火灾探测器。","options":[{"value":"A","text":"线型缆式感温","isCorrect":false},{"value":"B","text":"线型光纤感温","isCorrect":false},{"value":"C","text":"线型定温","isCorrect":false},{"value":"D","text":"线型光束感烟","isCorrect":true}],"answer":"D","explanation":"无遮挡的大空间或有特殊要求的房间,宜选择线型光束感烟火灾探测器。"},{"id":"ms-0404","type":"single","question":"安全色是表达安全信息含义的颜色,表示禁止、停止的颜色为（）。","options":[{"value":"A","text":"红色","isCorrect":true},{"value":"B","text":"黄色","isCorrect":false},{"value":"C","text":"蓝色","isCorrect":false},{"value":"D","text":"绿色","isCorrect":false}],"answer":"A","explanation":"安全色是表达安全信息含义的颜色,表示禁止、停止的颜色为红色。"},{"id":"ms-0405","type":"single","question":"（）是道德体系中一个重要的组成部分,它是指从事一定职业劳动的人们,在特定的工作和劳动中以其内心信念和特殊社会手段来维系的,以善恶进行评价的心理意识、行为原则和行为规范的总和。","options":[{"value":"A","text":"职业道德","isCorrect":true},{"value":"B","text":"职业作风","isCorrect":false},{"value":"C","text":"职业资格","isCorrect":false},{"value":"D","text":"职业荣誉","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材3页。职业道德是道德体系中一个重要的组成部分,它是指从事一定职业劳动的人们,在特定的工作和劳动中以其内心信念和特殊社会手段来维系的,以善恶进行评价的心理意识、行为原则和行为规范的总和。"},{"id":"ms-0406","type":"single","question":"当采用与火灾自动报警系统联动启动时,自动排烟窗应在（）内或小于烟气充满储烟仓时间内开启完毕。","options":[{"value":"A","text":"10s","isCorrect":false},{"value":"B","text":"15s","isCorrect":false},{"value":"C","text":"30s","isCorrect":false},{"value":"D","text":"60s","isCorrect":true}],"answer":"D","explanation":"机械排烟系统应与火灾自动报警系统联动,自动排烟窗可采用与火灾自动报警系统联动和温度释放装置联动的控制方式。当采用与火灾自动报警系统自动启动时,自动排烟窗应在60s内或小于烟气充满储烟仓时间内开启完毕。在大空间场所的自然排烟窗设置位置通常较高且区域较广,为了将烟气层控制在设计清晰高度以上,确保人员安全疏散,所以要求排烟窗应在烟气层未充满储烟仓前及时开启。带有温控功能自动排烟窗,其温控释放温度应大于环境温度30°C且小于100°C。结合题意,本题应选择\"60s内\",其他选项均可排除。"},{"id":"ms-0407","type":"single","question":"风机电气控制柜通电时,（）应点亮。","options":[{"value":"A","text":"运行指示灯","isCorrect":false},{"value":"B","text":"电源指示灯","isCorrect":true},{"value":"C","text":"故障指示灯","isCorrect":false},{"value":"D","text":"巡检指示灯","isCorrect":false}],"answer":"B","explanation":"新教材中级技能140页,风机电气控制柜具有下列功能。 (1)指示功能风机电气控制柜面板共设有三处指示信息:1)电源指示灯,控制柜通电时点亮；2)运行指示灯,风机运转时点亮；3)手动/自动转换开关,通过开关指向指示当前风机处于手动或自动控制状态。"},{"id":"ms-0408","type":"single","question":"延迟器安装在（）后的报警管路上,可最大限度减少因水源压力波动或冲击而造成误报警。","options":[{"value":"A","text":"预作用报警阀","isCorrect":false},{"value":"B","text":"干式报警阀","isCorrect":false},{"value":"C","text":"雨淋阀","isCorrect":false},{"value":"D","text":"湿式报警阀","isCorrect":true}],"answer":"D","explanation":"延迟器安装在湿式报警阀后的报警管路上,可最大限度减少因水源压力波动或冲击而造成误报警。"},{"id":"ms-0409","type":"single","question":"操作直接手动控制单元,首先进入当前操作权限级别,确认直接手动控制单元处于（）状态,同时确认当前联动设备无故障。","options":[{"value":"A","text":"自动允许","isCorrect":false},{"value":"B","text":"手动允许","isCorrect":true},{"value":"C","text":"自动","isCorrect":false},{"value":"D","text":"手动","isCorrect":false}],"answer":"B","explanation":"中级技能31页,如何操作直接手动控制单元(1)进入当前操作权限级别。确认直接手动控制单元处于\"手动充许\"状态,同时确认当前联动设备无故障。 (2)启动相关联动设备动作。确认对应受控设备标签名称书写无误,按下相应联动设备启动按键,观察设备的“启动/反馈“指示灯点亮情况。(3)停止相关联动设备动作。按下对应设备的\"停止\"键,观察停止按键指示灯点亮情况。(4)操作完毕后,按规定做好记录。"},{"id":"ms-0410","type":"single","question":"（）通常设置在防烟分区内需要排烟的走道、房间的顶棚或靠近顶棚的墙面上。","options":[{"value":"A","text":"排烟口","isCorrect":true},{"value":"B","text":"排烟阀","isCorrect":false},{"value":"C","text":"送风口","isCorrect":false},{"value":"D","text":"排烟防火阀","isCorrect":false}],"answer":"A","explanation":"中级技能138页,机械排烟系统排烟口是带有装饰口或进行过装饰处理的排烟阀,是机械排烟系统中烟气的入口,通常设置在防烟分区内需要排烟的走道、房间的顶棚或靠近顶棚的墙面上。"},{"id":"ms-0411","type":"single","question":"消防增(稳)压设施按（）可分为上置式和下置式两种。","options":[{"value":"A","text":"稳压工作形式","isCorrect":false},{"value":"B","text":"结构形式","isCorrect":false},{"value":"C","text":"气压罐设置方式","isCorrect":false},{"value":"D","text":"安装位置","isCorrect":true}],"answer":"D","explanation":"消防增(稳)压设施按安装位置可分为上置式和下置式两种。"},{"id":"ms-0412","type":"single","question":"通过自然排烟或机械排烟方式,将房间、走道等空间的火灾烟气排至建筑物外的系统是（）。","options":[{"value":"A","text":"通风空气调节系统","isCorrect":false},{"value":"B","text":"补风系统","isCorrect":false},{"value":"C","text":"防烟系统","isCorrect":false},{"value":"D","text":"排烟系统","isCorrect":true}],"answer":"D","explanation":"老教材基础知识271页,排烟系统是指通过自然排烟或机械排烟方式,将房间、走道等空间的火灾烟气排至建筑物外的系统。"},{"id":"ms-0413","type":"single","question":"（）每个操作按钮对应一个控制输出,控制火灾声光报警器、消防广播、加压送风口、加压送风机排烟阀、防火卷帘、常开型防火门、非消防电源和电梯等消防设备的启动。","options":[{"value":"A","text":"直接控制盘","isCorrect":false},{"value":"B","text":"多线控制盘","isCorrect":false},{"value":"C","text":"总线控制盘","isCorrect":true},{"value":"D","text":"手动控制盘","isCorrect":false}],"answer":"C","explanation":"总线控制盘每个操作按钮对应一个控制输出,控制火灾声光警报器、消防广播加压送风口、加压送风机排烟阀、排烟机、防火卷帘、常开型防火门、非消防电源和电梯等消防设备的启动,可根据需要按下目标操作按钮启动对应的消防设备。"},{"id":"ms-0414","type":"single","question":"二氧化碳灭火系统不适用于扑救以下火灾类型:（）。","options":[{"value":"A","text":"固体表面火灾及棉毛、织物、纸张等部分固体深位火灾","isCorrect":false},{"value":"B","text":"硝化纤维、火药等含氧化剂的化学制品火灾","isCorrect":true},{"value":"C","text":"灭火前可切断气源的气体火灾","isCorrect":false},{"value":"D","text":"液体火灾或石蜡、沥青等可熔化的固体火灾","isCorrect":false}],"answer":"B","explanation":"二氧化碳灭火剂是一种惰情性气体,对燃烧具有良好的室息作用,喷射出的液态和固态二氧化碳在汽化过程中要吸热,具有一定的冷却作用。适用扑救的火灾类型:1灭火前可切断气源的气体火灾;2液体火灾或石蜡、沥青等可熔化的固体火灾;3固体表面火灾及棉毛、织物、纸张等部分固体深位火灾;4电气火灾。不适用于扑救的火灾类型:1硝化纤维、火药等含氧化剂的化学制品火灾;2钾、钠、镁、钛、锆等活泼金属火灾;3氰化钾、氰化钠等金属氰化物火灾。结合题意,本题应选\"硝化纤维、火药等含氧化剂的化学制品火灾,其他项均可排除。"},{"id":"ms-0415","type":"single","question":"在不采暖地区的寒冷场所应安装（）。","options":[{"value":"A","text":"湿式系统","isCorrect":false},{"value":"B","text":"干式系统","isCorrect":true},{"value":"C","text":"水喷雾系统","isCorrect":false},{"value":"D","text":"雨淋系统","isCorrect":false}],"answer":"B","explanation":"在不采暖地区的寒冷场所应安装干式系统。干式系统适用于安装温度低于4°C或高于70°C的地方。"},{"id":"ms-0416","type":"single","question":"下列关于防烟排烟系统主要组件的工作情况说法错误的是（）。","options":[{"value":"A","text":"风机及控制柜外观完好,组件齐全,有关系统名称和编号的标识牢固、清晰、正确","isCorrect":false},{"value":"B","text":"风机安装气流方向正确,启停功能正常,风机运转无异常振动或声响","isCorrect":false},{"value":"C","text":"排烟管道隔热材料应为难燃材料,且与可燃物保持不小于150mm的距离","isCorrect":true},{"value":"D","text":"排烟防火阀设置位置及所在墙体的耐火完整性符合规定要求","isCorrect":false}],"answer":"C","explanation":"排烟管道隔热材料应为不燃材料,且与可燃物保持不小于150mm的距离。"},{"id":"ms-0417","type":"single","question":"当有限空间发生火灾时,可采取（）等方法,阻止空气进入燃烧区域,或向封闭空间内注入惰性气体降低氧气浓度,以达到室息灭火的效果。","options":[{"value":"A","text":"封堵孔洞、门窗","isCorrect":true},{"value":"B","text":"开窗通风","isCorrect":false},{"value":"C","text":"自行熄灭","isCorrect":false},{"value":"D","text":"使用气体灭火剂","isCorrect":false}],"answer":"A","explanation":"当有限空间发生火灾时,可采取封堵孔洞、门阳止空气进入燃烧区域或向封闭窗等方法,阻止空气进入燃烧区域,或向封闭空间内注入惰性气体降低氧气浓度,以达到室息灭火的效果。"},{"id":"ms-0418","type":"single","question":"剪切功能的快捷组合键是（）。","options":[{"value":"A","text":"\"Ctrl\"+\"C”","isCorrect":false},{"value":"B","text":"\"Ctrl\"+\"V\"","isCorrect":false},{"value":"C","text":"\"Ctrl\"+\"X\"","isCorrect":true},{"value":"D","text":"\"Ctrl\"+\"Z\"","isCorrect":false}],"answer":"C","explanation":"按下快捷键Ctrl+X键,执行\"剪切\"命令"},{"id":"ms-0419","type":"single","question":"劳动法是（）。","options":[{"value":"A","text":"《中华人民共和国劳动法》","isCorrect":false},{"value":"B","text":"调整劳动关系以及与劳动关系密切联系的一些关系的法律","isCorrect":true},{"value":"C","text":"调整劳动人事法律规范的总称","isCorrect":false},{"value":"D","text":"调整管理劳动力方面社会关系的法律规范的总称","isCorrect":false}],"answer":"B","explanation":"劳动法是调整劳动关系以及与劳动关系有密切联系的其他社会关系的法律规范的总称。"},{"id":"ms-0420","type":"single","question":"在空气中极易燃烧,火灾危险性大的建筑材料属于( )。","options":[{"value":"A","text":"不燃材料","isCorrect":false},{"value":"B","text":"难燃材料","isCorrect":false},{"value":"C","text":"易燃材料","isCorrect":true},{"value":"D","text":"可燃材料","isCorrect":false}],"answer":"C","explanation":"基础知识43页,表4-2-1建筑材料及制品燃烧性能等级划分:易燃材料(制品)极易燃烧,火灾危险性大。"},{"id":"ms-0421","type":"single","question":"消防电话故障部位检查确认时,要根据（）显示的故障信息,确定故障部件的部位并记录其编码。","options":[{"value":"A","text":"火灾报警控制器","isCorrect":true},{"value":"B","text":"消防电话总机","isCorrect":false},{"value":"C","text":"火灾显示盘","isCorrect":false},{"value":"D","text":"电气火灾监控器","isCorrect":false}],"answer":"A","explanation":"中级技能55页,1.确定消防电话故障部位更换前应检查确认消防电话所处的报警、故障、屏蔽等工作状态。根据火灾报警控制器/消防联动控制器显示的故障信息,确定故障部件的部位并记录其编码。"},{"id":"ms-0422","type":"single","question":"微型消防站应建立24h值守制度,分班编组值守,每班不少于（）人。","options":[{"value":"A","text":"1","isCorrect":false},{"value":"B","text":"3","isCorrect":true},{"value":"C","text":"5","isCorrect":false},{"value":"D","text":"7","isCorrect":false}],"answer":"B","explanation":"P138,微型消防站应建立24h值守制度,分班编组值守,每班不少于3人。"},{"id":"ms-0423","type":"single","question":"电流的单位是（）。","options":[{"value":"A","text":"安培","isCorrect":true},{"value":"B","text":"欧姆","isCorrect":false},{"value":"C","text":"伏特","isCorrect":false},{"value":"D","text":"焦耳","isCorrect":false}],"answer":"A","explanation":"基础知识64页,电流大小以安培为单位计量。"},{"id":"ms-0424","type":"single","question":"安装在通道上的防火卷帘,应在一个相关探测器报警后下降至距地面（）处停止,另一个相关探测器报警后,防火卷帘应继续下降至地面,并向火灾报警控制器反馈信号。","options":[{"value":"A","text":"1.3m","isCorrect":false},{"value":"B","text":"1.5m","isCorrect":false},{"value":"C","text":"1.8m","isCorrect":true},{"value":"D","text":"2.0m","isCorrect":false}],"answer":"C","explanation":"中级技能230页,安装在疏散通道上的防火卷帘,应在一个相关探测器报警后下降至距地面1.8m处停止;另一个相关探测器报警后,防火卷帘应继续下降至地面,并向火灾报警控制器反馈信号。"},{"id":"ms-0425","type":"single","question":"消防电梯能每层停靠,其载重量不小于（）。","options":[{"value":"A","text":"500kg","isCorrect":false},{"value":"B","text":"800kg","isCorrect":true},{"value":"C","text":"1000kg","isCorrect":false},{"value":"D","text":"1200kg","isCorrect":false}],"answer":"B","explanation":"基础知识119页,消防电梯应符合下列规定。1)应能在所服务区域每层停靠。2)电梯的载重量不应小于800kg。"},{"id":"ms-0426","type":"single","question":"在消防设施操作员职业中,消防设施检测维修保养职业方向分为（）个职业等级。","options":[{"value":"A","text":"4","isCorrect":true},{"value":"B","text":"5","isCorrect":false},{"value":"C","text":"2","isCorrect":false},{"value":"D","text":"3","isCorrect":false}],"answer":"A","explanation":"新教材基础知识6页,消防设施操作员职业一共设五个等级,其中,消防设施监控操作职业方向分为：五级/初级工、四级/中级工、三级/高级工、二级/技师;消防设施检测维修保养职业方向分为：四级/中工、三级/高级工、二级/技师、一级/高级技师。"},{"id":"ms-0427","type":"single","question":"采用主电源为220V、50Hz交流电源供电的火灾显示盘应具有主电源和备用电源转换等功能,主电源应能保证火灾显示盘在火灾报警态下连续工作( )h,且应有过流保护措施。","options":[{"value":"A","text":"3","isCorrect":false},{"value":"B","text":"4","isCorrect":true},{"value":"C","text":"2","isCorrect":false},{"value":"D","text":"5","isCorrect":false}],"answer":"B","explanation":"采用主电源为220V、50Hz交流电源供电的火灾显示盘,主电源应能保证火灾显示盘在火灾报警状态下连续工作4h,且应有过流保护措施。"},{"id":"ms-0428","type":"single","question":"（）适用于设置两个及以上消防控制室的保护对象,也适用于已设置两个及以上集中报警系统的保护对象。","options":[{"value":"A","text":"区域报警系统","isCorrect":false},{"value":"B","text":"集中报警系统","isCorrect":false},{"value":"C","text":"控制中心报警系统","isCorrect":true},{"value":"D","text":"消防联动控制系统","isCorrect":false}],"answer":"C","explanation":"控制中心报警系统适用于设置两个及以上消防控制室的保护对象,也适用于已设置两个及以上集中报警系统的保护对象。"},{"id":"ms-0429","type":"single","question":"举办大型群众性活动,承办人应当依法向（）申请安全许可。","options":[{"value":"A","text":"公安机关","isCorrect":true},{"value":"B","text":"应急管理部门","isCorrect":false},{"value":"C","text":"地方人民政府","isCorrect":false},{"value":"D","text":"消防救援机构","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材14页。举办大型群众性活动,承办人应当依法向公安机关申请安全许可。"},{"id":"ms-0430","type":"single","question":"在串联电路中,各电阻分得的电压与其阻值（） 。","options":[{"value":"A","text":"相等","isCorrect":false},{"value":"B","text":"成正比","isCorrect":true},{"value":"C","text":"成反比","isCorrect":false},{"value":"D","text":"之和","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材65页。电阻串联电路特点有：(1)流过每个电阻的电流相等；(2)总电压(串联电路两端的电压)等于分电压(每个电阳阻两端的电压之和；(3)总电阻等于分电阻之和；(4)各个电阻两端的电压与其阻值成正比；(5)各个电阻消耗的功率与其阻值成正。"}]},{"name":"维保方向 · 多选题","type":"multi","questions":[{"id":"mm-0431","type":"multi","question":"泡沫灭火系统可按照（）等进行分类。","options":[{"value":"A","text":"喷射方式","isCorrect":true},{"value":"B","text":"系统结构","isCorrect":false},{"value":"C","text":"发泡倍数","isCorrect":false},{"value":"D","text":"系统形式","isCorrect":false},{"value":"E","text":"安装方式","isCorrect":false}],"answer":"A","explanation":"基础知识97页,泡沫灭火系统可以按系统结构、发泡倍数、系统形式、喷射方式分类。"},{"id":"mm-0432","type":"multi","question":"火灾信息主要包括哪些内容","options":[{"value":"A","text":"起火时间","isCorrect":true},{"value":"B","text":"起火部位","isCorrect":false},{"value":"C","text":"起火原因","isCorrect":false},{"value":"D","text":"报警方式","isCorrect":false},{"value":"E","text":"灭火方式","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材133页。火灾信息主要包括起火时间、起火部位、起火原因、报警方式(指自动、人工等)、灭火方式(指气体、喷水、喷雾、泡沫、干粉灭火系统,水基型、干粉、二氧化碳、洁净气体灭火器,消防力量等)。"},{"id":"mm-0433","type":"multi","question":"关于消防电话各组件的设置要求,说法正确的是（）。","options":[{"value":"A","text":"多线制消防电话系统中的每个电话分机应与总机单独连接","isCorrect":true},{"value":"B","text":"消防电话分机应固定安装在明显且便于使用的部位","isCorrect":false},{"value":"C","text":"设有手动火灾报警按钮或消火栓按钮等处宜设置电话插孔,并宜选择带有电话插孔的手动火灾报警按钮","isCorrect":false},{"value":"D","text":"电话插孔在墙上安装时,其底边距地面高度宜为1.1~1.3m","isCorrect":false},{"value":"E","text":"消防控制室应设置消防电话总机","isCorrect":false}],"answer":"A","explanation":"消防电话各组件的设置要求:(2)消防控制室应设置消防电话总机。(3)多线制消防电话系统中的每个电话分机应与总机单独连接。(4)电话分机或电话插孔的设置应符合下列规定:1)消防电话分机应固定安装在明显且便于使用的部位,并应有区别于普通电话的标识。2)设有手动火灾报警按钮或消火栓按钮等处宜设置电话插孔,并宜选择带有电话插孔的手动火灾报警按钮。4)电话插孔在墙上安装时,其底边距地面高度宜为1.3~1.5m。"},{"id":"mm-0434","type":"multi","question":"防火卷帘按照材质可以分成（）类。","options":[{"value":"A","text":"钢质防火卷帘","isCorrect":true},{"value":"B","text":"无机纤维复合防火卷帘","isCorrect":false},{"value":"C","text":"木质防火卷帘","isCorrect":false},{"value":"D","text":"特级防火卷帘","isCorrect":false},{"value":"E","text":"单帘面防火卷帘","isCorrect":false}],"answer":"A","explanation":"防火卷帘按材质可分为钢质防火卷帘、无机纤维复合防火卷帘和特级防火卷帘。"},{"id":"mm-0435","type":"multi","question":"防火卷帘通常可按照()等进行分类。","options":[{"value":"A","text":"厚度","isCorrect":false},{"value":"B","text":"材质","isCorrect":true},{"value":"C","text":"启闭方式","isCorrect":false},{"value":"D","text":"动作温度","isCorrect":false},{"value":"E","text":"帘面数量","isCorrect":false}],"answer":"B","explanation":"防火卷帘通常可按照材质、 帘面数量启闭方式等进行分类。"},{"id":"mm-0436","type":"multi","question":"湿式自动喷水灭火系统主要由（）、管道和供水设施等组成。","options":[{"value":"A","text":"闭式喷头","isCorrect":true},{"value":"B","text":"开式喷头","isCorrect":false},{"value":"C","text":"报整测组湿式报警阀组","isCorrect":false},{"value":"D","text":"水流指示器","isCorrect":false},{"value":"E","text":"未端试水装置","isCorrect":false}],"answer":"A","explanation":"湿式自动喷水灭火系统主要由闭式喷头、湿式报警阀组、水流指示器、末端试水装置、管道和供水设施等组成。"},{"id":"mm-0437","type":"multi","question":"电气火灾监控系统主要由（）组成。","options":[{"value":"A","text":"电气火灾监控设备","isCorrect":true},{"value":"B","text":"剩余电流式电气火灾监控探测器","isCorrect":false},{"value":"C","text":"测温式电气火灾监控探测器","isCorrect":false},{"value":"D","text":"图形显示装置","isCorrect":false},{"value":"E","text":"故障电弧探测器","isCorrect":false}],"answer":"A","explanation":"根据《中级》新教材第5页。电气火灾监控系统由电气火灾监控设备(也称为电气火灾监控器)、剩余电流式电气火灾监控探测器、测温式电气火灾监控探测器、故障电弧探测器等组成,能和消防控制室图形显示装置连接并上传信息。"},{"id":"mm-0438","type":"multi","question":"下列建筑耐火等级应为一级的是()。","options":[{"value":"A","text":"建筑高度为26m的门诊楼","isCorrect":true},{"value":"B","text":"建筑高度为30m的住宅楼","isCorrect":false},{"value":"C","text":"建筑高度为54m的高层厂房","isCorrect":false},{"value":"D","text":"多层丁类厂房","isCorrect":false},{"value":"E","text":"丁类物流建筑","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材第47页。下列民用建的筑耐火等级应为一级:1)一类高层民用建筑。2)二层和二层半式、多层式民用机场航站楼。3)A类广播电影电视建筑。4)四级生物安全实验室。下列工业建筑的耐火等级应为一级:1)建筑高度大于50m的高层厂房。2)建筑高度大于32m的高层丙类仓库,储存可燃液体的多层丙类仓库,每个防火分隔间建筑面积大于3000m的其他多层丙类仓库。3)类飞机库。建筑高度为26m的门诊楼为一类高层建筑。另,建筑高度为30m的住宅楼为二类高层民用建筑,不应低于二级;多层丁类厂房不应低于三级;"},{"id":"mm-0439","type":"multi","question":"人员密集场所室闪装修、装饰,应当按照消防技术标准的要求,使用（）材料。","options":[{"value":"A","text":"可燃","isCorrect":false},{"value":"B","text":"易燃","isCorrect":false},{"value":"C","text":"不可燃","isCorrect":false},{"value":"D","text":"难燃","isCorrect":true},{"value":"E","text":"不燃","isCorrect":false}],"answer":"D","explanation":"人员密集场所室内装修、装饰,应当按照消防技术标准的要求,使用不燃、难燃材料。"},{"id":"mm-0440","type":"multi","question":"满足下列（）条件之一,即可认定为重大火灾。","options":[{"value":"A","text":"造成10人以上30人以下死亡","isCorrect":true},{"value":"B","text":"50人以上100人以下重伤","isCorrect":false},{"value":"C","text":"5000万元以上1亿元以下直接财产损失","isCorrect":false},{"value":"D","text":"造成3人以上10人以下死亡","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材28页。重大火灾:造成10人以上30人以下死亡,或者50人以上100人以下重伤,或者5000万元以上1亿元以下直接财产损失的火灾。"},{"id":"mm-0441","type":"multi","question":"欧姆定律适用于() 。","options":[{"value":"A","text":"纯电阻电路","isCorrect":true},{"value":"B","text":"金属导电","isCorrect":false},{"value":"C","text":"电解液导电","isCorrect":false},{"value":"D","text":"气体导电","isCorrect":false},{"value":"E","text":"半导体元件","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材65页。欧姆定律适用于纯电阻电路、金属导电和电解液导电,不适用于气体导电和半导体元件。"},{"id":"mm-0442","type":"multi","question":"《消防给水及消火栓系统技术规范》主要内容报告（）。","options":[{"value":"A","text":"消防水源","isCorrect":true},{"value":"B","text":"供水设施","isCorrect":false},{"value":"C","text":"给水形式","isCorrect":false},{"value":"D","text":"消火栓系统","isCorrect":false},{"value":"E","text":"系统调试与验收","isCorrect":false}],"answer":"A","explanation":"《消防给水及消火栓系统技术规范》(GB50974-2014)主要内容包括:主要内容包括总则、术语和符号、基本参数、消防水源、供水设施、给水形式、消火栓系统、管网、消防排水、水力计算、控制与操作、施工、系统调试与验收、维护管理等。"},{"id":"mm-0443","type":"multi","question":"友布火警要利用()的方式友布火情信息。","options":[{"value":"A","text":"应急广播系统","isCorrect":true},{"value":"B","text":"警铃","isCorrect":false},{"value":"C","text":"喊话","isCorrect":false},{"value":"D","text":"室内电话","isCorrect":false},{"value":"E","text":"逐个通知","isCorrect":false}],"answer":"A","explanation":"利用应急广播系统、警铃、室内电话等设施设备以及通过喊话等方式发布火警信息。"},{"id":"mm-0444","type":"multi","question":"可燃物起火一般分为（）和（）两种方式。","options":[{"value":"A","text":"引燃","isCorrect":true},{"value":"B","text":"自燃","isCorrect":false},{"value":"C","text":"爆炸","isCorrect":false},{"value":"D","text":"闪燃","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材18页。起火又称着火,是最常见的燃烧现象,可燃物起火一般分为引燃和自燃两种方式,以出现火焰为主要特征。"},{"id":"mm-0445","type":"multi","question":"下列场所或部位中疏散出口门应向疏散方向开启的是（）。","options":[{"value":"A","text":"甲、乙类生产场所","isCorrect":true},{"value":"B","text":"平时使用的人民防空工程中的公共场所","isCorrect":false},{"value":"C","text":"疏散楼梯间的门","isCorrect":false},{"value":"D","text":"室内通向室外疏散楼梯的门","isCorrect":false},{"value":"E","text":"疏散楼梯间前室的门","isCorrect":false}],"answer":"A","explanation":"甲、乙类生产场所、平时使用的人民防空工程中的公共场所、疏散楼梯间的门、室内通向室外疏散楼梯的门、疏散楼梯间前室的门疏散出口门应向疏散方向开启。"},{"id":"mm-0446","type":"multi","question":"依据物质产生爆炸的原因和性质,通常将爆炸分为（）。","options":[{"value":"A","text":"物理爆炸","isCorrect":true},{"value":"B","text":"化学爆炸","isCorrect":false},{"value":"C","text":"粉尘爆炸","isCorrect":false},{"value":"D","text":"核爆炸","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材24页。依据物质产生根据《基础知识》爆炸的原因和性质,通常将爆炸分为物理爆炸、化学爆炸、核爆炸,其中最常见的是物理爆炸和化学爆炸。"},{"id":"mm-0447","type":"multi","question":"组成区域报警系统的组件主要有（）。","options":[{"value":"A","text":"火灾探测器","isCorrect":true},{"value":"B","text":"手动火灾报警按钮","isCorrect":false},{"value":"C","text":"火灾声光警报器","isCorrect":false},{"value":"D","text":"消防联动控制器","isCorrect":false},{"value":"E","text":"火灾报警控制器","isCorrect":false}],"answer":"A","explanation":"区域报警系统的组件:火灾探测器, 手动火灾报警按钮, 火灾声光警报器,火灾报警控制器。"},{"id":"mm-0448","type":"multi","question":"防火卷帘按照启闭方式可以分成（）类。","options":[{"value":"A","text":"垂直式防火卷帘","isCorrect":true},{"value":"B","text":"侧向式防火卷帘","isCorrect":false},{"value":"C","text":"水平式防火卷帘","isCorrect":false},{"value":"D","text":"竖式防火卷帘","isCorrect":false},{"value":"E","text":"单帘面防火卷帘","isCorrect":false}],"answer":"A","explanation":"防火卷帘按照启闭方式可以分成垂直式防火卷帘、侧向式防火卷帘、水平式防火卷帘类。"},{"id":"mm-0449","type":"multi","question":"更换消防应急广播模块的操作包括（）。","options":[{"value":"A","text":"拆卸并更换故障模块","isCorrect":true},{"value":"B","text":"对新模块编码","isCorrect":false},{"value":"C","text":"对新模块进行读编码确认","isCorrect":false},{"value":"D","text":"更换底座","isCorrect":false},{"value":"E","text":"将新模块与底座卡扣对准并沿垂直于底座方向用力按下","isCorrect":false}],"answer":"A","explanation":"中级p57,更换消防应急广播模块:拆卸故障模使其与底座脱离块,对新模块编码并进行块,使其与底座脱离,对新模块编码,并进行读编码确认,确认后将新模块与底座卡扣对准,垂直于底座方向用力按下。"},{"id":"mm-0450","type":"multi","question":"集中报警系统中的火灾报警控制器、消防联动控制和消防联动控制设备具有（）控制状态。","options":[{"value":"A","text":"手动","isCorrect":true},{"value":"B","text":"自动","isCorrect":false},{"value":"C","text":"联动","isCorrect":false},{"value":"D","text":"联锁","isCorrect":false},{"value":"E","text":"火警","isCorrect":false}],"answer":"A","explanation":"中级技能4页,集中报警系统的工作状态集中报警系统的工作状态主要包括:手动控制状态/自动控制状态、正常监视状态/报警状态(含火灾(含火灾报警、监管报警、故障报警及屏蔽状态)/联动状态、主电/备电工作状态、主电/备电故障状态等。1.手动控制状态/自动控制状态集中报警系统中的火灾报警控制器、消防联动控制器和消防联动控制设备对各类受控消防设备的控制功能可以通过手动、自动两种方式完成,相应的控制状态即集中报警系统当前所处的手动控制状态、自动控制状态。"},{"id":"mm-0451","type":"multi","question":"多线控制盘每个操作按钮对应一个控制输出,控制（）等消防设备的启动。","options":[{"value":"A","text":"喷淋泵组","isCorrect":true},{"value":"B","text":"消火栓泵组","isCorrect":false},{"value":"C","text":"防烟风机","isCorrect":false},{"value":"D","text":"排烟风机","isCorrect":false},{"value":"E","text":"消防广播","isCorrect":false}],"answer":"A","explanation":"中级技能77页,多线控制盘每个操作按钮对应一个控制输出,控制喷淋泵组、消火栓泵组、防烟和排烟风机等消防设备的启动,可根据需要按下目标操作按钮启动对应的消防设备。"},{"id":"mm-0452","type":"multi","question":"湿式、干式系统组件保养内容包括（）等等。","options":[{"value":"A","text":"阀门保养","isCorrect":true},{"value":"B","text":"管道保养","isCorrect":false},{"value":"C","text":"报警阀组保养","isCorrect":false},{"value":"D","text":"消防水池、高位消防水箱保养","isCorrect":false},{"value":"E","text":"消防水泵接合器保养","isCorrect":false}],"answer":"A","explanation":"中级100页,湿式、干式系统组件的保养内容包括阀门保养、管道保养、报警阀组保养、水流指示器保养、试验装置保养、消防水池、高位消防水箱保养、消防水泵接合器保养。"},{"id":"mm-0453","type":"multi","question":"泡沫灭火剂的灭火原理是什么（）。","options":[{"value":"A","text":"中和","isCorrect":false},{"value":"B","text":"室息","isCorrect":true},{"value":"C","text":"隔离","isCorrect":false},{"value":"D","text":"淹没","isCorrect":false},{"value":"E","text":"冷却","isCorrect":false}],"answer":"B","explanation":"基础知识123页,泡沫灭火剂通过冷却、室息、隔离、淹没等综合作用实现灭火。在可燃易燃液体表面生成凝聚的泡沫漂浮层,可起到室息和冷却作用。"},{"id":"mm-0454","type":"multi","question":"下列属于文件(夹)的基本操作的是（）。","options":[{"value":"A","text":"建立文件夹","isCorrect":true},{"value":"B","text":"重命名文件 (夹)","isCorrect":false},{"value":"C","text":"选中文件(夹)选中文件 (夹)","isCorrect":false},{"value":"D","text":"复制、移动、剪切文件 (夹)","isCorrect":false},{"value":"E","text":"删除文件(夹),查找文件或文件夹","isCorrect":false}],"answer":"A","explanation":"老教材基础知识337-338页,本题选择ABCDE。"},{"id":"mm-0455","type":"multi","question":"按装配形式的不同,气体灭火系统分为（）。","options":[{"value":"A","text":"管网灭火系统","isCorrect":true},{"value":"B","text":"预制灭火系统","isCorrect":false},{"value":"C","text":"全淹没灭火系统","isCorrect":false},{"value":"D","text":"悬挂灭火系统","isCorrect":false},{"value":"E","text":"外储压式灭火系统","isCorrect":false}],"answer":"A","explanation":"基础知识95页,根据表6-2-2气体灭火系统的分类可见,按装配形式不同分为管网灭火系统和预制灭火系统(柜式气体灭火装置)。"},{"id":"mm-0456","type":"multi","question":"下列属于人员密集场所的是（）。","options":[{"value":"A","text":"学校教学楼","isCorrect":true},{"value":"B","text":"医院门诊楼","isCorrect":false},{"value":"C","text":"幼儿园","isCorrect":false},{"value":"D","text":"公共展览馆的展厅","isCorrect":false}],"answer":"A","explanation":"基础知识14页,知识点19:人员密集场所是指公众聚集场所,医院的门诊楼、病房楼,学校的教学楼、图书馆、食堂和集体宿舍,养老院,福利院,托儿所,幼儿园,公共图书馆的阅览室,公共展览馆、博物馆的展示厅,劳动密集型企业的生产加工车间和员工集体宿舍,旅游、宗教活动场所等。"},{"id":"mm-0457","type":"multi","question":"关于火灾自动报警系统的接地电阻测试,下列说法正确的是（）。","options":[{"value":"A","text":"接地保护装置的主要作用是利用接地体把故障电流或雷电流快速地泄放到大地中","isCorrect":true},{"value":"B","text":"采用共用接地装置时,接地电阻值不应大于1Ω","isCorrect":false},{"value":"C","text":"采用共用接地装置时,接地电阻值不应大于4Ω","isCorrect":false},{"value":"D","text":"采用专用接地电阻时,接地电阻值不应大于1Ω","isCorrect":false},{"value":"E","text":"采用专用接地电阻时,接地电阻值不应大于4Ω","isCorrect":false}],"answer":"A","explanation":"教材中级61页,火灾自动报警系统接地装置的接地电阻值应符合下列规定:来用共用接地装置时,接地电阻值不应大于1Ω;采用专用接地装置时,接地电阻值不应大于4Ω。"},{"id":"mm-0458","type":"multi","question":"测试火灾自动报警系统联动功能测试时,通过消防控制室内火灾报警控制器的显示器查看（）等消防联动设备动作的反馈信号。","options":[{"value":"A","text":"声光警报器","isCorrect":true},{"value":"B","text":"消防应急广播","isCorrect":false},{"value":"C","text":"防排烟系统","isCorrect":false},{"value":"D","text":"防火卷帘","isCorrect":false},{"value":"E","text":"消防应急照明和疏散指示系统","isCorrect":false}],"answer":"A","explanation":"中级68页,通过消防控制室内火灾报警控制器消防应急广播、防的显示器香看声光警报器、的显示器查看声光警报器、消防应急广播、防烟排烟系统、防火卷帘、消防应急照明和疏散指示系统、非消防电源、电梯和消防水泵等消防联动设备动作的反馈信号。"},{"id":"mm-0459","type":"multi","question":"下列外壳组件中,应予涂补或更换的有（）。","options":[{"value":"A","text":"标识不清晰","isCorrect":true},{"value":"B","text":"涂覆层脱落","isCorrect":false},{"value":"C","text":"起泡严重","isCorrect":false},{"value":"D","text":"积灰严重","isCorrect":false},{"value":"E","text":"使用超过五年","isCorrect":false}],"answer":"A","explanation":"中级教材46页,外壳标识不清晰或涂覆层脱落、起泡严重的,应进行涂补或更换外壳组件。"},{"id":"mm-0460","type":"multi","question":"直接手动控制单元主要是解决（）等重要消防设施设备的手动直接控制。","options":[{"value":"A","text":"消防水泵","isCorrect":true},{"value":"B","text":"防烟风机","isCorrect":false},{"value":"C","text":"预作用阀组","isCorrect":false},{"value":"D","text":"排烟风机","isCorrect":false},{"value":"E","text":"消防电话","isCorrect":false}],"answer":"A","explanation":"中级21页,直接手动控制单元(也称多线控制盘)主要是解决消防水泵、防烟和排烟风机、预作用阀组等重要消防设施设备的手动直接控制。"},{"id":"mm-0461","type":"multi","question":"操作火灾自动报警系统总线手动控制单元时,总线手动控制单元包含的指示灯状态有（）。","options":[{"value":"A","text":"联动","isCorrect":false},{"value":"B","text":"启动","isCorrect":true},{"value":"C","text":"反馈","isCorrect":false},{"value":"D","text":"报警","isCorrect":false},{"value":"E","text":"故障","isCorrect":false}],"answer":"B","explanation":"中级21页,总线手动控制单元示,每一个(组)启动/停止按键对应有一组\"启动\"和\"反馈指示灯。"},{"id":"mm-0462","type":"multi","question":"集控制器的历史信息包括（）等。","options":[{"value":"A","text":"火警信息","isCorrect":true},{"value":"B","text":"故障信息","isCorrect":false},{"value":"C","text":"反馈信息","isCorrect":false},{"value":"D","text":"操作信息","isCorrect":false},{"value":"E","text":"系统故障消息","isCorrect":false}],"answer":"A","explanation":"中级29页,集中控制器的历史信息包括火警信息、故障信息、反馈信息、操作信息等,最多能记录999条相关信息,存满后新事件产生时覆盖最早的事件。"},{"id":"mm-0463","type":"multi","question":"现场各类消防设备的工作状态可分为（）。","options":[{"value":"A","text":"正常(监视)","isCorrect":true},{"value":"B","text":"火警","isCorrect":false},{"value":"C","text":"故障","isCorrect":false},{"value":"D","text":"消音","isCorrect":false},{"value":"E","text":"屏蔽","isCorrect":false}],"answer":"A","explanation":"中级28页,现场各类消防设备的工作状态可分为正常(监视)、火警、故障、启动、屏蔽、反馈等。"},{"id":"mm-0464","type":"multi","question":"集中报警系统中的火灾报警控制器、消防联动控制器和消防联动控制设备具有（）控制状态。","options":[{"value":"A","text":"手动","isCorrect":true},{"value":"B","text":"自动","isCorrect":false},{"value":"C","text":"联动","isCorrect":false},{"value":"D","text":"联锁","isCorrect":false},{"value":"E","text":"火警","isCorrect":false}],"answer":"A","explanation":"中级04页,集中报警系统中的火灾报警控制品器、消防联动控制器和消防联动控制设备对各类受控消防设备的控制功能可以通过手动、自动两种方式完成。"},{"id":"mm-0465","type":"multi","question":"消防水泵按用途可分为( )。","options":[{"value":"A","text":"供水消防泵","isCorrect":true},{"value":"B","text":"稳压消防泵","isCorrect":false},{"value":"C","text":"潜水消防泵","isCorrect":false},{"value":"D","text":"深井消防泵","isCorrect":false},{"value":"E","text":"供泡沫液消防泵","isCorrect":false}],"answer":"A","explanation":"消防水泵的分类方法:1按出口压力等级:分为低压消防泵、中压消防泵、中低压消防泵、高压消防泵和高低压消防泵；2按用途:分为供水消防泵、稳压消防泵、供泡沫液消防泵；3按辅助特征:分为普通消防泵、深井消防泵和潜水消防泵。结合题意,本题应选\"供水消防泵\"、“稳压消防泵\"、“供泡沫液消防泵\"3项,其他项均可排除。"},{"id":"mm-0466","type":"multi","question":"下列关于老年人照料设施平面布置的说法,正确的是( )。","options":[{"value":"A","text":"对于一、二级耐火等级建筑,不应布置在楼地面设计标高大于54m的楼层上","isCorrect":true},{"value":"B","text":"对于三级耐火等级建筑,应布置在首层或二层","isCorrect":false},{"value":"C","text":"老年人公共活动用房、康复与医疗用房,应布置在地下一层及以上楼层,当布置在半地下或地下一层、地上四层及以上楼层时,每个房间的建筑面积不应大于200m且使用人数不应大于30人","isCorrect":false},{"value":"D","text":"居室和休息室不应布置在地下或半地下","isCorrect":false},{"value":"E","text":"老年人照料设施应采用防火门、防火窗、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.00h的楼板与其他区","isCorrect":false}],"answer":"A","explanation":"对于一、二级耐火等级建筑,不应布置在楼地面设计标高大于54m的楼层上,对于三级耐火等级建筑,应布置在首层或二层,老年人公共活动用房、康复与医疗用房,应布置在地下一层及以上楼层,当布置在半地下或地下一层、地上四层及以上楼层时每个房间的建筑面和地上四层及以上楼层时,每个房间的建筑面积不应大于200m且使用人数不应大于30人,居室和休息室不应布置在地下或半地下,老年人照料设施应采用防火门、防火窗、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.00h的楼板与其他区域分隔。"},{"id":"mm-0467","type":"multi","question":"水系灭火剂的灭火原理是什么（）。","options":[{"value":"A","text":"冷却灭火","isCorrect":true},{"value":"B","text":"室息灭火","isCorrect":false},{"value":"C","text":"覆盖灭火","isCorrect":false},{"value":"D","text":"稀释灭火","isCorrect":false},{"value":"E","text":"对非水溶性可燃液体的乳化","isCorrect":false}],"answer":"A","explanation":"水系灭火剂是指由水、渗透剂、阻燃剂以及其他添加剂组成,一般以液滴或以液滴和泡沫混合的形式灭火的液体灭火剂,灭火原理为冷却、室息、稀释、对非水溶性可燃液体的乳化。"},{"id":"mm-0468","type":"multi","question":"消防应急灯具按用途可分为（）。","options":[{"value":"A","text":"消防应急照明灯具","isCorrect":true},{"value":"B","text":"消防应急标志灯具","isCorrect":false},{"value":"C","text":"消防应急照明标志复合灯具","isCorrect":false},{"value":"D","text":"集中电源型消防应急灯具","isCorrect":false},{"value":"E","text":"自带电源型消防应急灯具","isCorrect":false}],"answer":"A","explanation":"消防应急灯具按用途分为：消防应急标志灯具、消防应急照明灯具、消防应急照明标志复合灯具。"},{"id":"mm-0469","type":"multi","question":"消防水泵包括（）。","options":[{"value":"A","text":"固定消防水泵","isCorrect":true},{"value":"B","text":"消防车消防水泵","isCorrect":false},{"value":"C","text":"移动消防水泵","isCorrect":false},{"value":"D","text":"高位消防水泵","isCorrect":false},{"value":"E","text":"应急消防水泵","isCorrect":false}],"answer":"A","explanation":"消防水泵包括：固定消防水泵、消防车消防水泵、移动消防水泵。"},{"id":"mm-0470","type":"multi","question":"消防应急灯具按用途分为( )。","options":[{"value":"A","text":"消防应急标志灯具","isCorrect":true},{"value":"B","text":"消防应急照明灯具","isCorrect":false},{"value":"C","text":"消防应急照明标志复合灯具","isCorrect":false},{"value":"D","text":"自带电源型消防应急灯具","isCorrect":false},{"value":"E","text":"集中电源型消防应急灯具","isCorrect":false}],"answer":"A","explanation":"消防应急灯具按用途分为：消防应急标志灯具、消防应急照明灯具、消防应急照明标志复合灯具。"},{"id":"mm-0471","type":"multi","question":"消防应急广播系统主要包括（）等组件。","options":[{"value":"A","text":"广播主机","isCorrect":true},{"value":"B","text":"分配盘","isCorrect":false},{"value":"C","text":"声频功率放大器","isCorrect":false},{"value":"D","text":"输出模块","isCorrect":false},{"value":"E","text":"音频线路及扬声器","isCorrect":false}],"answer":"A","explanation":"消防应急广播系统主要由：消防应急广播主机、功放机、分配盘、输出模块、音频线路及扬声器等组成。"},{"id":"mm-0472","type":"multi","question":"下列关于医疗建筑中住院病房平面布置的说法正确的是（）。","options":[{"value":"A","text":"不应布置在地下或半地下","isCorrect":true},{"value":"B","text":"对于三级耐火等级建筑,应布置在首层或二层","isCorrect":false},{"value":"C","text":"建筑内相邻护理单元之间应采用耐火极限不低于2.00h的防火隔墙和甲级防火门分隔","isCorrect":false},{"value":"D","text":"设置在I级本结构建筑中时，应布置在首层、二层或三层","isCorrect":false},{"value":"E","text":"当设置在II级木结构建筑中时,应布置在首层或二层","isCorrect":false}],"answer":"A","explanation":"基础知识55页,医疗建筑中住院病房的布置和分隔应符合下列规定。(1) 不应布置在地下或半地下。(2) 对于三级耐火等级建筑,应布置在首层或二层。(3)建筑内相邻应采用耐火极限不低于2.00h的防火隔墙和甲级防火门分隔。当医疗建筑中住院病房设置在级木结构建筑中时,应布置在首层、二层或三层;当设置在川级木结构建筑中时,应布置在首层或二层。"},{"id":"mm-0473","type":"multi","question":"消防应急厂播的单次语音播放时间宜为（）。","options":[{"value":"A","text":"10S","isCorrect":true},{"value":"B","text":"15S","isCorrect":false},{"value":"C","text":"20S","isCorrect":false},{"value":"D","text":"25S","isCorrect":false},{"value":"E","text":"30S","isCorrect":false}],"answer":"A","explanation":"中级p62,消防应急广播的单次语音播放时间宜为10~30s。"},{"id":"mm-0474","type":"multi","question":"下列属于爆炸性粉尘的是（）。","options":[{"value":"A","text":"煤","isCorrect":false},{"value":"B","text":"木炭","isCorrect":false},{"value":"C","text":"淀粉","isCorrect":true},{"value":"D","text":"铝粉","isCorrect":false},{"value":"E","text":"镁粉","isCorrect":false}],"answer":"C","explanation":"本题题干强调是\"..粉尘\",故选CDE。"},{"id":"mm-0475","type":"multi","question":"泡沫灭火系统按发泡倍数分为（）。","options":[{"value":"A","text":"低倍数泡沫灭火系统","isCorrect":true},{"value":"B","text":"中倍数泡沫灭火系统","isCorrect":false},{"value":"C","text":"中高倍数泡沫灭火系统","isCorrect":false},{"value":"D","text":"高倍数泡沫灭火系统","isCorrect":false},{"value":"E","text":"超高倍数泡沫灭火系统","isCorrect":false}],"answer":"A","explanation":"基础知识96页,泡沫灭火系统的分类方法:1按结构形式:分为固定式系统、半固定系统、移动式系统。2按发泡倍数:分为低倍数泡沫灭火系统、中倍数泡沫灭火系统、高倍数泡沫灭火系统。3按系统形式:分为全淹没泡沫灭火系统、局部应用泡沫灭火系统、移动式泡沫灭火系统、泡沫-水喷淋系统、泡沫喷雾系统、压缩空气泡沫灭火系统。"},{"id":"mm-0476","type":"multi","question":"测试消防电话总机故障报警功能时,下列做法正确的有（）。","options":[{"value":"A","text":"用秒表测量消防电话总机故障报警响应时间","isCorrect":true},{"value":"B","text":"香看总机显示的故障发生时间","isCorrect":false},{"value":"C","text":"查看总机显示的故障分机位置","isCorrect":false},{"value":"D","text":"查看故障指示灯是否点亮","isCorrect":false},{"value":"E","text":"查看总机自动录音情况","isCorrect":false}],"answer":"A","explanation":"中级教材74页,测试故障报警功能,分别使消防电话总机与任一消防电话分机或消防电话插孔之间的连接线断路、短路,用秒表测量消防电适总机故障报警响应时间。查看消防电话总机显示器显示的故障消防电话分机或消防电话插孔位置和故障发生时间,故障指示灯应点亮。"},{"id":"mm-0477","type":"multi","question":"消防泵组及电气控制柜的保养项目包含（）等。","options":[{"value":"A","text":"控制柜工作环境","isCorrect":true},{"value":"B","text":"控制柜外观","isCorrect":false},{"value":"C","text":"控制柜电气部件","isCorrect":false},{"value":"D","text":"控制柜功能","isCorrect":false},{"value":"E","text":"泵组","isCorrect":false}],"answer":"A","explanation":"消防泵组及电气控制柜的保养项目:包含控制柜工作环境、控制柜外观、控制柜电气部件、控制柜功能、泵组。"},{"id":"mm-0478","type":"multi","question":"按材质可将防火门分为( )。","options":[{"value":"A","text":"木质防火门","isCorrect":true},{"value":"B","text":"钢质防火门","isCorrect":false},{"value":"C","text":"钢木质防火门","isCorrect":false},{"value":"D","text":"特级防火门","isCorrect":false},{"value":"E","text":"双扇防火门","isCorrect":false}],"answer":"A","explanation":"防火门是指由门框、门扇及五金配件等组成具有一定耐火性能的门组件,其四种分类方法如下:1按耐火极限不同:分为甲级防火门、乙级防火门和丙级防火门,耐火极限分别不低于1.5h、1.0h和0.5h。2按制造材料不同:分为木质防火门钢木质防火门和为木质防火门、钢质防火门、钢木质防火门和其他材质防火门。3按开闭形式不同:分为常闭式防火门、常开式防火门。结合题意,本题选择ABC,其他选项均可排除"},{"id":"mm-0479","type":"multi","question":"消防增(稳)压设施的保养项目包含（）等。","options":[{"value":"A","text":"机房环境检查","isCorrect":true},{"value":"B","text":"消防水箱保养","isCorrect":false},{"value":"C","text":"电气控制柜保养","isCorrect":false},{"value":"D","text":"稳压泵组保养","isCorrect":false},{"value":"E","text":"气压罐及供水附件保养","isCorrect":false}],"answer":"A","explanation":"消防增(稳)压设施的保养项目包含：机房环境检查;消防水箱保养;电气控制柜保养;稳压泵组保养;气压罐及供水附件保养等。结合题意:本题全选。"},{"id":"mm-0480","type":"multi","question":"固体可燃物的燃烧方式大致分为（）。","options":[{"value":"A","text":"蒸发燃烧","isCorrect":true},{"value":"B","text":"分解燃烧","isCorrect":false},{"value":"C","text":"表面燃烧","isCorrect":false},{"value":"D","text":"阴燃","isCorrect":false}],"answer":"A","explanation":"根据各类可燃固体的燃烧方式和燃烧特性,其燃烧大致可分为4种形式:(1)蒸发燃烧(2)分解燃烧(3)表面燃烧(4)阴燃"},{"id":"mm-0481","type":"multi","question":"自动喷水灭火系统洒水喷头按安装位置和水的分布可分为（）。","options":[{"value":"A","text":"通用型喷头","isCorrect":true},{"value":"B","text":"直立型喷头","isCorrect":false},{"value":"C","text":"下垂型喷头","isCorrect":false},{"value":"D","text":"边墙型喷头","isCorrect":false},{"value":"E","text":"齐平式喷头","isCorrect":false}],"answer":"A","explanation":"自动喷水灭火系统酒水喷头按安装位置和水的分布可分为：通用型喷头、直立型喷头、下垂型喷头、边墙型喷头。"},{"id":"mm-0482","type":"multi","question":"下列关于火灾自动报警系统消防联动控制要求的说法中,正确的是（）。","options":[{"value":"A","text":"消防联动控制器应能按设定的控制逻辑向各相关受控设备发出联动控制信号,并接收相关设备的联动反馈信号。","isCorrect":true},{"value":"B","text":"消防联动控制器应具有发出联动控制信号强制所有电梯停于首层或电梯转换层的功能。","isCorrect":false},{"value":"C","text":"消防联动控制器应具有自动打开涉及疏散的电动栅杆等的功能。","isCorrect":false},{"value":"D","text":"消防应急广播系统的联动控制信号应由消防联动控制器发出。当确认火灾后,应向起火楼层及相邻楼层进行广播。","isCorrect":false},{"value":"E","text":"消防联动控制器应具有启动消火栓泵的功能。","isCorrect":false}],"answer":"A","explanation":"火灾自动报警系统消防联动控制要求消防应急广播系统的联动控制信号应由消防联动控制器发出。当确认火灾后,应同时向全楼进行广播。结合题意,本题应排除D选项。"},{"id":"mm-0483","type":"multi","question":"干粉灭火剂的类型有（）。","options":[{"value":"A","text":"普通干粉灭火剂","isCorrect":true},{"value":"B","text":"多用途干粉灭火剂","isCorrect":false},{"value":"C","text":"超细干粉灭火剂","isCorrect":false},{"value":"D","text":"D类干粉灭火剂","isCorrect":false},{"value":"E","text":"E类干粉灭火剂","isCorrect":false}],"answer":"A","explanation":"干粉灭火剂的类型有:(1)普通干粉灭火剂,又称BC干粉灭火剂。这类灭火剂可扑救B类、C类、E类火灾。 (2)多用途干粉灭火剂,又称ABC干粉灭火剂。这类灭火剂可扑救A类、B类、C类、E类火灾。类、C类、E类火灾。(3)超细干粉灭火剂。该类灭火剂按其灭火性能分为BC超细干粉灭火剂和ABC超细干粉灭火剂两类。(4)D类干粉灭火剂,即能扑救D类火灾的干粉灭火剂。"},{"id":"mm-0484","type":"multi","question":"避难层可分为（）。","options":[{"value":"A","text":"敞开式","isCorrect":true},{"value":"B","text":"半敞开式","isCorrect":false},{"value":"C","text":"封闭式","isCorrect":false},{"value":"D","text":"通用式","isCorrect":false},{"value":"E","text":"常规式","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材61页。避难层可分为敞开式、半敞开式、封闭式三种类型。"},{"id":"mm-0485","type":"multi","question":"火灾自动报警系统中的（）一般应设置在消防控制室内或有人值班的房间和场所。","options":[{"value":"A","text":"集中火灾报警控制器","isCorrect":true},{"value":"B","text":"触发装置","isCorrect":false},{"value":"C","text":"声光报警装置","isCorrect":false},{"value":"D","text":"消防联动控制器","isCorrect":false},{"value":"E","text":"消防控制室图形显示装置","isCorrect":false}],"answer":"A","explanation":"本题考查考生对集中火灾报警控制器、消防联动控制器、消防控制室图形显示装置的组成和功能知识点的掌握情况。火灾自动报警系统肩负看探测火灾早期特征、发出火灾报警信号,为人员疏散、防止火灾蔓延和启动自动灭火设备提供控制与指示的消防任务。系统中的集中火灾报警控制器、消防联动控制器、消防控制室图形显示装置一般应设置在消防控制室内或有人值班的房间和场所。"},{"id":"mm-0486","type":"multi","question":"防火门监控器应具备（）、显示功能、反馈功能及自检功能","options":[{"value":"A","text":"备用电源功能","isCorrect":true},{"value":"B","text":"控制功能","isCorrect":false},{"value":"C","text":"主、备电源转换功能","isCorrect":false},{"value":"D","text":"故障报警功能","isCorrect":false},{"value":"E","text":"信息记录、查询与上传功能","isCorrect":false}],"answer":"A","explanation":"为及时掌握防火门的开闭状态,确保发生火灾时防火门能够有效发挥作用,防火门监控器应具备以下功能:1.显示功能2.控制功能3.反馈功能  4.故障报警功能5.信息记录、查询与上传功能6.自检功能7.备用电源功能8.主、备电源转换功能"},{"id":"mm-0487","type":"multi","question":"城乡消防安全布局不符合消防安全要求的,应当（）。","options":[{"value":"A","text":"整顿","isCorrect":false},{"value":"B","text":"调整","isCorrect":true},{"value":"C","text":"改善","isCorrect":false},{"value":"D","text":"完善","isCorrect":false},{"value":"E","text":"改建","isCorrect":false}],"answer":"B","explanation":"城乡消防安全布局不符合消防安全要求的,应当调整、完善。"},{"id":"mm-0488","type":"multi","question":"集中火灾报警系统由( )、手动火灾报警按钮、火灾声光报警器、消防应急广播、消防专用电话等组成。","options":[{"value":"A","text":"集中火灾报警控制器","isCorrect":true},{"value":"B","text":"区域火灾报警控制器","isCorrect":false},{"value":"C","text":"消防联动控制器","isCorrect":false},{"value":"D","text":"消防控制室图形显示装置","isCorrect":false},{"value":"E","text":"火灾探测器","isCorrect":false}],"answer":"A","explanation":"集中火灾报警系统由集中火灾报警控制器,消防联动控制器,消防控制室图形显示装置,火灾探测器、手动火灾报警按钮、灾声光报警器、消防应急广播、消防专用电话等组成。"},{"id":"mm-0489","type":"multi","question":"下列（）部位应设置排烟防火阀。","options":[{"value":"A","text":"垂直主排烟管道与每层水平排烟管道交接处的水平管段","isCorrect":true},{"value":"B","text":"垂直主排烟管道与每层水平排烟管道交接处的垂直管段","isCorrect":false},{"value":"C","text":"负担多个防烟分区的排烟支管处","isCorrect":false},{"value":"D","text":"排烟风机入口处","isCorrect":false},{"value":"E","text":"排烟管道穿越防火分区处","isCorrect":false}],"answer":"A","explanation":"中级150页,机械排烟系统的垂直主排烟管道与每层水平排烟管道交接处的水平管段、负担多个防烟分区的排烟支管处、排烟风机入口处、排烟管道穿越防火分区处均应设置排烟防火阀。"},{"id":"mm-0490","type":"multi","question":"更换火灾自动报警系统总线短路隔离器和模块的步骤包括（）。","options":[{"value":"A","text":"确定发生故障的组件部位","isCorrect":true},{"value":"B","text":"确定组件故障的原因类型","isCorrect":false},{"value":"C","text":"更换总线短路隔离器和模块","isCorrect":false},{"value":"D","text":"测试更换后的组件功能","isCorrect":false},{"value":"E","text":"填写记录","isCorrect":false}],"answer":"A","explanation":"中级p54,更换总线短路隔离器和模块包括:1.确定发生故障的组件部位2.确定组件故障的原因类型3.更换总线短路隔离器和模块4.测试更换后的组件功能5.填写记录"},{"id":"mm-0491","type":"multi","question":"集中报警系统的控制与显示类设备内部吹扫主要包括各种( )。","options":[{"value":"A","text":"电路模板","isCorrect":true},{"value":"B","text":"组件","isCorrect":false},{"value":"C","text":"电池","isCorrect":false},{"value":"D","text":"接线端子","isCorrect":false},{"value":"E","text":"线材","isCorrect":false}],"answer":"A","explanation":"吹扫设备内部的各种电路模板、组件、电池、线材控制接线瑞子熔试外部的品作面板接线端子、线材,擦拭外部的操作面板、控制开关、机箱外壳及缝隙等(含指示灯、按键、显示屏、键盘与鼠标)。"},{"id":"mm-0492","type":"multi","question":"计算机的安全工作环境包括（）等方面。","options":[{"value":"A","text":"温度","isCorrect":true},{"value":"B","text":"湿度","isCorrect":false},{"value":"C","text":"电源","isCorrect":false},{"value":"D","text":"灰尘","isCorrect":false},{"value":"E","text":"震动和噪音,静电","isCorrect":false}],"answer":"A","explanation":"P144-P145,知识点3:计算机的安全工作环境需要满足哪几个方面的条件:(1)温度;(2)湿度;(3)电源;(4)灰尘;(5)振动和噪声;(6)静电。本题没有F项,全选。"},{"id":"mm-0493","type":"multi","question":"公民道德建设的重点任务有（）、（）、（）、（）。","options":[{"value":"A","text":"筑牢理想信念之基","isCorrect":true},{"value":"B","text":"培育和践行社会主义核心价值观","isCorrect":false},{"value":"C","text":"传承中华传统美德","isCorrect":false},{"value":"D","text":"弘扬民族精神和时代精神","isCorrect":false}],"answer":"A","explanation":"P002,公民道德建设的重点任务有:1.筑牢理想信念之基。2.培育和践行社会主义核心价值观。3.传承中华传统美德。4.弘扬民族精神和时代精神。"},{"id":"mm-0494","type":"multi","question":"防火门按照启闭状态分为（）。","options":[{"value":"A","text":"常开防火门","isCorrect":true},{"value":"B","text":"常闭防火门","isCorrect":false},{"value":"C","text":"平开防火门","isCorrect":false},{"value":"D","text":"推拉防火门","isCorrect":false},{"value":"E","text":"折叠防火门","isCorrect":false}],"answer":"A","explanation":"基础知识113-114页,(1)防火门按照启闭状态分为常开防火门和常闭防火门两种。(2)防火门按照耐火性能可分为隔热防火门、部分隔热防火门和非隔热防火门三类。(3)按材质可将防火门分为木质防火门、钢质防火门、钢木质防火门和其他材质防火门。(4)按门扇数量可将防火门分为单扇防火门、双扇防火门和多扇防火门(含有两个以上门扇的防火门)。(5)按结构形式可将防火门分为门扇上带防火玻璃的防火门、无玻璃防火门等。"},{"id":"mm-0495","type":"multi","question":"（）应设置消防应急广播。","options":[{"value":"A","text":"集中报警系统","isCorrect":true},{"value":"B","text":"控制中心报警系统","isCorrect":false},{"value":"C","text":"区域报警系统","isCorrect":false},{"value":"D","text":"独立式报警系统","isCorrect":false},{"value":"E","text":"消防应急照明和疏散指示系统","isCorrect":false}],"answer":"A","explanation":"中级62页,集中报警系统和控制中心报警系统应设置消防应急广播。"},{"id":"mm-0496","type":"multi","question":"火灾自动报警系统各组件产品现场一致性检查时,应按消防设计文件核查系统各组件的（）以及备品备件的数量,以保与设计文件一致。","options":[{"value":"A","text":"数量","isCorrect":true},{"value":"B","text":"规格","isCorrect":false},{"value":"C","text":"型号","isCorrect":false},{"value":"D","text":"生产日期","isCorrect":false},{"value":"E","text":"生产批号","isCorrect":false}],"answer":"A","explanation":"中级63页,按消防设计文件核查系统各类组件的数量、规格、型号以及备品备件的数量,以确保与设计文件一致。"},{"id":"mm-0497","type":"multi","question":"可使用（）清洗线型光束感烟火灾探测器的外壳指示灯和光路通过的窗口等部件。","options":[{"value":"A","text":"专用清洁工具","isCorrect":true},{"value":"B","text":"软布","isCorrect":false},{"value":"C","text":"适当的清洁剂","isCorrect":false},{"value":"D","text":"纸壳","isCorrect":false},{"value":"E","text":"油抹布","isCorrect":false}],"answer":"A","explanation":"中级教材45页,用专用清洁工具或软布及适当的清洁剂清洗线型光束感烟火灾探测器的外壳、指示灯和光路通过的窗口等部件,清洗线型感温火灾探测器终端盒的外壳、指示灯。"},{"id":"mm-0498","type":"multi","question":"社会单位消防工作4个能力是指（）。","options":[{"value":"A","text":"检查消除火灾隐惠能力检查消除火灾隐患能力","isCorrect":true},{"value":"B","text":"扑救初起火灾能力","isCorrect":false},{"value":"C","text":"组织人员疏散逃生能力","isCorrect":false},{"value":"D","text":"消防宣传教育培训能力","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材14页。社会单位消防工作4个能力是什么。(1)检查消除火灾隐患能力。(2)扑救初起火灾能力。(3)组织人员疏散逃生能力。(4)消防宣传教育培训能力。"},{"id":"mm-0499","type":"multi","question":"下列属于老年人照料设施的是( )。","options":[{"value":"A","text":"养老院","isCorrect":true},{"value":"B","text":"托老所","isCorrect":false},{"value":"C","text":"老年人日间照料中心","isCorrect":false},{"value":"D","text":"老年人活动中心","isCorrect":false},{"value":"E","text":"老年人大学","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材41页。老年人照料设施是老年人全日照料设施和老年人日间照料设施的统称。其中,老年人全日照料设施是养老院、老人院、福利院、敬老院、老年养护院等的统称。老年人日间照料设施是托老所、日托站、老年人日间照料室、老年人日间照料中心等的统称。其他专供老年人使用的、非集中照料的设施或场所,如老年大学、老年人活动中心等不属于老年人照料设施。"},{"id":"mm-0500","type":"multi","question":"下列属于文件(夹)的基本操作的是( )。","options":[{"value":"A","text":"建立文件夹","isCorrect":true},{"value":"B","text":"重命名文件(夹)","isCorrect":false},{"value":"C","text":"选中文件(夹)","isCorrect":false},{"value":"D","text":"复制、移动、剪切文件(夹)","isCorrect":false},{"value":"E","text":"删除文件(夹)","isCorrect":false}],"answer":"A","explanation":"文件(夹)的基本操作有:1.建立文件夹;2.重命名文件(夹);3.选中文件(夹);4.复制、移动、剪切文件(夹);5.删除文件(夹) 。"},{"id":"mm-0501","type":"multi","question":"集中报警系统主要由火灾探测器、手动火灾报警按钮、火灾声光警报器、( )等组成。","options":[{"value":"A","text":"消防应急广播","isCorrect":true},{"value":"B","text":"消防专用电话","isCorrect":false},{"value":"C","text":"消防控制室图形显示装置","isCorrect":false},{"value":"D","text":"火灾报警控制器","isCorrect":false},{"value":"E","text":"消防联动控制器","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材82页。集中报警系统应由火灾探测器、手动火灾报警按钮、火灾声光警报器、消防专用电话、消防应急广播、消防控制室图形显示装置、火灾报警控制器、消防联动控制器等组成。"},{"id":"mm-0502","type":"multi","question":"（）等空间宜采用机械加压送风方式阻止火灾烟火灾烟气侵入。","options":[{"value":"A","text":"楼梯间","isCorrect":true},{"value":"B","text":"房间","isCorrect":false},{"value":"C","text":"走廊","isCorrect":false},{"value":"D","text":"前室","isCorrect":false},{"value":"E","text":"避难层 (间)","isCorrect":false}],"answer":"A","explanation":"防烟系统是通过采用自然通风方式,防止火灾烟气在楼梯间、前室、避难层(间)等空间内积聚,或通过采用机械加压送风方式阻止火灾烟气侵入楼梯间、前室、避难层(间)等空间的系统。 《建筑防火通用规范>(GB550372022)中规定，下列部位应采取防烟措施。封闭楼梯间。防烟楼梯间及其前室。消防电梯的前室或合用前室。避难层、避难间。避难走道的前室,地铁工程中的避难走道。"},{"id":"mm-0503","type":"multi","question":"固定消防炮灭火系统按安装形式可分为（）。","options":[{"value":"A","text":"固定式消防炮系统","isCorrect":true},{"value":"B","text":"移动式消防炮系统网","isCorrect":false},{"value":"C","text":"半固定式消防炮系统","isCorrect":false},{"value":"D","text":"远控消防炮系统","isCorrect":false},{"value":"E","text":"智能型消防炮灭火系统","isCorrect":false}],"answer":"A","explanation":"基础知识104页,固定消防炮灭火系统的3种分类方法:1按喷射介质:分为水炮系统、泡沫炮系统、干粉炮系统。2按控制方式:分为远控消防炮系统、非远控消防炮系统。3按安装形式:固定式消防炮系统、移动式消防炮系统。"},{"id":"mm-0504","type":"multi","question":"相邻两组探测器光束轴线的水平距离符合要求的有（）。","options":[{"value":"A","text":"17.0","isCorrect":false},{"value":"B","text":"16.0","isCorrect":false},{"value":"C","text":"15.0","isCorrect":false},{"value":"D","text":"13.0","isCorrect":true},{"value":"E","text":"12.0","isCorrect":false}],"answer":"D","explanation":"中级58页,相邻两组探测器光束轴线的水平距离不应大于14m，探测器光束轴线至侧墙水平距离不应大于7m,且不应小于0.5m。"},{"id":"mm-0505","type":"multi","question":"防火卷帘一般设置在( )部位。","options":[{"value":"A","text":"电梯厅、自动扶梯周围","isCorrect":true},{"value":"B","text":"中庭与楼层走道、过厅相通的开口部位","isCorrect":false},{"value":"C","text":"生产车间中大面积工艺洞口","isCorrect":false},{"value":"D","text":"设置防火墙有困难的部位","isCorrect":false},{"value":"E","text":"建筑中需要防火分隔的","isCorrect":false}],"answer":"A","explanation":"防火卷帘一般设置在电梯厅、自动扶梯周围,中庭与楼层走道、过厅相通的开口部位,生产车间中大面积工艺洞口,设置防火墙有困难的部位部位。"},{"id":"mm-0506","type":"multi","question":"段落的格式化是指对段落前后( )等属性的设置。","options":[{"value":"A","text":"间距大小","isCorrect":true},{"value":"B","text":"行距大小","isCorrect":false},{"value":"C","text":"段落的缩进","isCorrect":false},{"value":"D","text":"段落的编号","isCorrect":false},{"value":"E","text":"项目符号","isCorrect":false}],"answer":"A","explanation":"段落的格式化是指对段落前后间距大小、行距大小、段落的缩进等属性的设置。"},{"id":"mm-0507","type":"multi","question":"下列选项不属于机械排烟系统组件的是（）。","options":[{"value":"A","text":"排烟阀","isCorrect":false},{"value":"B","text":"排烟风机","isCorrect":false},{"value":"C","text":"防火阀","isCorrect":true},{"value":"D","text":"排烟防火阀","isCorrect":false},{"value":"E","text":"补风机","isCorrect":false}],"answer":"C","explanation":"防火阀和补风机属于正压送风系统"},{"id":"mm-0508","type":"multi","question":"下列燃烧产物中,（）是不完全燃烧产物。","options":[{"value":"A","text":"水","isCorrect":false},{"value":"B","text":"一氧化碳","isCorrect":true},{"value":"C","text":"氨气","isCorrect":false},{"value":"D","text":"二氧化碳","isCorrect":false}],"answer":"B","explanation":"根据《基础知识》新教材22页。其中完全燃烧产物是指可燃物中的碳被氧化生成二氧化碳气体、氢被氧化生成液态水、硫被氧化生成二氧化硫气体等;而燃烧生成的一氧化碳、氨气、醇类、醛类、醚类等是不完全燃烧产物。"},{"id":"mm-0509","type":"multi","question":"消滑防水泵接合器处应设置久性铭牌,并应标明（）。","options":[{"value":"A","text":"供水系统","isCorrect":true},{"value":"B","text":"供水方向","isCorrect":false},{"value":"C","text":"供水范围","isCorrect":false},{"value":"D","text":"额定压力","isCorrect":false},{"value":"E","text":"出厂编号","isCorrect":false}],"answer":"A","explanation":"消防水泵接合器处应设置永久性铭牌,并应标明供水系统、供水范围和额定压力。"},{"id":"mm-0510","type":"multi","question":"泡沫灭火系统按系统结构形式分为（）。","options":[{"value":"A","text":"固定式","isCorrect":true},{"value":"B","text":"半固定式","isCorrect":false},{"value":"C","text":"移动式","isCorrect":false},{"value":"D","text":"全淹没系统","isCorrect":false},{"value":"E","text":"局部应用系统","isCorrect":false}],"answer":"A","explanation":"泡沫灭火系统按系统结构形式分为固定式、半固定式、移动式。"},{"id":"mm-0511","type":"multi","question":"中倍泡沫灭火剂一般用于扑灭（）。","options":[{"value":"A","text":"可燃气体","isCorrect":false},{"value":"B","text":"易燃可燃液体","isCorrect":true},{"value":"C","text":"电气设备火灾","isCorrect":false},{"value":"D","text":"固体表面火灾","isCorrect":false},{"value":"E","text":"固体深位阴燃火灾","isCorrect":false}],"answer":"B","explanation":"中倍泡沫灭火剂一般用于扑灭易燃可燃液体，固体表面火灾,固体深位阴燃火灾。"},{"id":"mm-0512","type":"multi","question":"下列属于防火分隔设施的是（）。","options":[{"value":"A","text":"楼板","isCorrect":true},{"value":"B","text":"防火墙","isCorrect":false},{"value":"C","text":"防火门","isCorrect":false},{"value":"D","text":"防火卷帘","isCorrect":false},{"value":"E","text":"挡烟垂壁","isCorrect":false}],"answer":"A","explanation":"防火分隔设施可分为固定式和活动式两种类型。固定式防火分隔设施包括楼板、防火墙等,活动式防火分隔设施包括防火门、防火卷帘等。"},{"id":"mm-0513","type":"multi","question":"下列哪些物质易发生自燃（）。","options":[{"value":"A","text":"黄磷","isCorrect":true},{"value":"B","text":"硝化棉","isCorrect":false},{"value":"C","text":"活性炭","isCorrect":false},{"value":"D","text":"稻草","isCorrect":false},{"value":"E","text":"锯末","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材19页。知识点12:哪些物质容易发生自燃。其中包括有黄磷、硝化棉、活性炭、稻草、锯末等。"},{"id":"mm-0514","type":"multi","question":"下列属于控制面板功能的是（）。","options":[{"value":"A","text":"添加硬件","isCorrect":true},{"value":"B","text":"添加或删除程序","isCorrect":false},{"value":"C","text":"创建快捷方式","isCorrect":false},{"value":"D","text":"创建文件夹","isCorrect":false}],"answer":"A","explanation":"添加硬件、添加或删除程序属于控制面板功能。"},{"id":"mm-0515","type":"multi","question":"消防应急广播系统主要由()及扬声器等组成。","options":[{"value":"A","text":"消防应急广播主机","isCorrect":true},{"value":"B","text":"功放机","isCorrect":false},{"value":"C","text":"分配盘","isCorrect":false},{"value":"D","text":"输出模块","isCorrect":false},{"value":"E","text":"音频线路","isCorrect":false}],"answer":"A","explanation":"消防应急广播系统主要由消防应急广播主机、功放机、分配盘、输出模块、音频线路及扬声器等组成。"},{"id":"mm-0516","type":"multi","question":"消防供水设施通常包括(),主要用于为自动喷水灭火系统提供水量和水压保证。","options":[{"value":"A","text":"消防水泵","isCorrect":true},{"value":"B","text":"消防水源","isCorrect":false},{"value":"C","text":"高位消防水箱","isCorrect":false},{"value":"D","text":"增 (稳)压设施","isCorrect":false},{"value":"E","text":"消防水泵接合器","isCorrect":false}],"answer":"A","explanation":"消防供水设施通常包括消防水源、高位消防水箱、增(稳)压设施、消防水泵和消防水泵接合器,主要用于为自动喷水灭火系统提供水量和水压保证,是自动喷水灭火系统的重要组成部分。"},{"id":"mm-0517","type":"multi","question":"防火卷帘具有（）、现场机械控制和限位控制等几种主要控制方式。","options":[{"value":"A","text":"现场手动电控","isCorrect":true},{"value":"B","text":"自动控制","isCorrect":false},{"value":"C","text":"消防控制室远程手动控制","isCorrect":false},{"value":"D","text":"温控释放控制","isCorrect":false},{"value":"E","text":"速放控制","isCorrect":false}],"answer":"A","explanation":"防火卷帘具有现场手动电控、自动控制、消防控制室远程手动控制、温控释放控制、速放控制、现场机械控制和限位控制等几种主要控制方式。"},{"id":"mm-0518","type":"multi","question":"湿式、干式自动喷水灭火系统主要由（）等组件,以及管道和供水设施等组成。","options":[{"value":"A","text":"闭式喷头","isCorrect":true},{"value":"B","text":"开式喷头","isCorrect":false},{"value":"C","text":"报警阀组","isCorrect":false},{"value":"D","text":"水流报警装置","isCorrect":false},{"value":"E","text":"火灾探测器","isCorrect":false}],"answer":"A","explanation":"湿式、干式自动喷水灭火系统主要由闭式喷头、报警阀组、水流报警装置(水流指示器或压力开关)等组件,以及管道和供水设施等组成。"},{"id":"mm-0519","type":"multi","question":"当控制器内部、控制器与其连接的部件间发生故障时,控制器应能显示()等所有故障信息。","options":[{"value":"A","text":"故障部位","isCorrect":true},{"value":"B","text":"故障原因","isCorrect":false},{"value":"C","text":"故障程度","isCorrect":false},{"value":"D","text":"故障类型","isCorrect":false},{"value":"E","text":"故障次数","isCorrect":false}],"answer":"A","explanation":"当控制器内部、控制器与其连接的部件间发生故障时,控制器应能显示故障部位、故障类型等所有故障信息。"},{"id":"mm-0520","type":"multi","question":"串联电路的特点是（）。","options":[{"value":"A","text":"流过每个电阻的电流相等","isCorrect":true},{"value":"B","text":"总电压(串联电路两端的电压)等于分电压(每个电阻两端的电压)之和","isCorrect":false},{"value":"C","text":"总电阻等于分电阻之和","isCorrect":false},{"value":"D","text":"各个电阻分得的电压与其阻值成正比","isCorrect":false},{"value":"E","text":"各个电阻分得的功率与其阻值成正比","isCorrect":false}],"answer":"A","explanation":"电阻串联电路的特点:(1) 流过每个电阻的电流相等。 (2) 总电压(串联电路两端的电压)等于分电压(每个电阻两端的电压)之和。 (3) 总电阻等干分电阻之和。 (4) 各个电阻两端的电压与其阻值成正比。(5) 各个电阻消耗的功率与其阻值成正比。"},{"id":"mm-0521","type":"multi","question":"有()故障时,监控器应在100s内发出与报警信号有明显区别的声、光故障信号。","options":[{"value":"A","text":"监控器的主电源断电","isCorrect":true},{"value":"B","text":"监控器与电动闭门器、电磁释放器、门磁开关间连接线断路、短路","isCorrect":false},{"value":"C","text":"电动闭门器、电磁释放器、门磁开关的供电电源故障","isCorrect":false},{"value":"D","text":"备用电源与充电器之间的连接线断路、短路","isCorrect":false},{"value":"E","text":"备用电源发生故障","isCorrect":false}],"answer":"A","explanation":"有下述故障时,监控器应在100s内发出与报警信号有明显区别的声、光故障信号,故障声信号应能手动消除,再有故障信号输入时应能再启动,故障光信号应保持至故障排除:(1)监控器的主电源断电。(2)监控器与电动闭门器、电磁释放器、门磁开关间连接线断路、短路。(3)电动闭门器、电磁释放器、门磁开关的供电电源故障。(4)备用电源与充电器之间的连接线断路、短路。(5)备用电源发生故障。"},{"id":"mm-0522","type":"multi","question":"下列关于消防控制室平面布置的说法,正确的是（）。","options":[{"value":"A","text":"附设在建筑内的消防控制室应采用防火门门、防火窗、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.50h的楼板与其他部位分隔","isCorrect":true},{"value":"B","text":"消防控制室的疏散门应直通室外或安全出口","isCorrect":false},{"value":"C","text":"消防控制室的环境条件不应干扰或影响消防控制室内火灾报警与控制设备的正常运行","isCorrect":false},{"value":"D","text":"消防控制室内不应敷设或穿过与消防控制室无关的管线","isCorrect":false},{"value":"E","text":"消防控制室应采取防水淹、防潮、防啮齿动物等的措施","isCorrect":false}],"answer":"A","explanation":"基础知识55页,消防控制室的布置和防火分隔应符合下列规定。(1) 单独建造的消防控制室,耐火等级不应低于二级。 (2)附设在建筑内的消防控制室应采用防火门、防火窗、耐火极限不低于2.00h 的防火隔墙和耐火极限不低于1.50h的楼板与其他。(3) 消防控制室应位于建筑的首层或地下一层,疏散门应直通室外或安全出口。(4) 消防控制室的环境条件不应干扰或影响消防控制室内火灾报警与控制设备 的正常运行。(5) 消防控制室内不应敷设或穿"},{"id":"mm-0523","type":"multi","question":"下列属于国产操作系统的有( )。","options":[{"value":"A","text":"鸿蒙","isCorrect":true},{"value":"B","text":"银河麒麟","isCorrect":false},{"value":"C","text":"MacOs","isCorrect":false},{"value":"D","text":"安卓","isCorrect":false},{"value":"E","text":"Windows","isCorrect":false}],"answer":"A","explanation":"银河麒麟是我国自主研发的闭源服务器操作系统,广泛应用于金融、海关、能源等众多行业。鸿蒙是由华为公司开发的一款基于微内核,面向5G物联网、全场景的分布式操作系统,英文名称为HarmonyOS,意为和谐,是与安卓不一样的操作系统,能兼容安卓的所有网络应用。银河麒麟和鸿蒙都是国产的操作系统。"},{"id":"mm-0524","type":"multi","question":"消防水池(水箱)需设（）、水位信号装置、人孔、扶梯等,合用水池(水箱)还需设置消防用水不作他用的技术保证措施。","options":[{"value":"A","text":"进水管","isCorrect":true},{"value":"B","text":"出水管","isCorrect":false},{"value":"C","text":"溢流管","isCorrect":false},{"value":"D","text":"放空管","isCorrect":false},{"value":"E","text":"通气管","isCorrect":false}],"answer":"A","explanation":"消防水池(水箱)需设进水管、出水管、溢流管、放空管、通气管、水位信号装置、人孔、扶梯等,合用水池(水箱)还需设置消防用水不作他用的技术保证措施。"},{"id":"mm-0525","type":"multi","question":"消防联动控制器的主要功能有（）、电源功能。","options":[{"value":"A","text":"控制功能","isCorrect":true},{"value":"B","text":"火灾报警控制功能","isCorrect":false},{"value":"C","text":"故障报警功能","isCorrect":false},{"value":"D","text":"自检功能","isCorrect":false},{"value":"E","text":"信息显示与查询功能","isCorrect":false}],"answer":"A","explanation":"消防联动控制器的主要功能有控制功能、故障故障报警功能、自检功能、信息显示与查询功能、电源功能。"},{"id":"mm-0526","type":"multi","question":"气体燃烧方式分为（）。","options":[{"value":"A","text":"扩散燃烧","isCorrect":true},{"value":"B","text":"预混燃烧","isCorrect":false},{"value":"C","text":"分解燃烧","isCorrect":false},{"value":"D","text":"蒸发燃烧","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材21页。根据燃烧前可燃气体与氧气混合情况的不同,其燃烧方式分为扩散燃烧和预混燃烧。"},{"id":"mm-0527","type":"multi","question":"根据现场设备功能的不同,工作状态可分（）、反馈等。","options":[{"value":"A","text":"正常","isCorrect":true},{"value":"B","text":"火警","isCorrect":false},{"value":"C","text":"故障","isCorrect":false},{"value":"D","text":"启动","isCorrect":false},{"value":"E","text":"屏蔽","isCorrect":false}],"answer":"A","explanation":"根据现场消防设备功能的不同,工作状态可分为正常、火警、故障、启动、屏蔽、反馈等。"},{"id":"mm-0528","type":"multi","question":"字符的格式化是指对文档中字符的（）进行选择和设定。","options":[{"value":"A","text":"字体","isCorrect":true},{"value":"B","text":"字形","isCorrect":false},{"value":"C","text":"字号","isCorrect":false},{"value":"D","text":"颜色","isCorrect":false},{"value":"E","text":"间距","isCorrect":false}],"answer":"A","explanation":"字符格式化就是设置字符的字体、字形、字号、颜色及间距等进行设定和选择。"},{"id":"mm-0529","type":"multi","question":"常用的接地电阻测量仪器主要有（）两种。","options":[{"value":"A","text":"地网接地电阻测试仪","isCorrect":false},{"value":"B","text":"手摇式接地电阻测试仪","isCorrect":false},{"value":"C","text":"钳形接地电阻测试仪","isCorrect":true},{"value":"D","text":"数字式接地电阻测试仪","isCorrect":false},{"value":"E","text":"电子接地电阻测试仪","isCorrect":false}],"answer":"C","explanation":"根据《中级》新教材61页。常用的接地电阻测量仪器主要有两种:数字手摇式接地电阻测试仪和钳形接地电阻测试仪。老教材为手摇式接地电阻测试仪和钳形接地电阻测试仪。"},{"id":"mm-0530","type":"multi","question":"《中华人民共和国消防法》规定,任何单位和个人都有（）的义务。","options":[{"value":"A","text":"维护消防安全","isCorrect":true},{"value":"B","text":"保护消防设施","isCorrect":false},{"value":"C","text":"预防火灾","isCorrect":false},{"value":"D","text":"报告火警","isCorrect":false},{"value":"E","text":"扑灭火灾","isCorrect":false}],"answer":"A","explanation":"P131,《中华人民共和国消防法》规定,任何单位和个人都有维护消防安全、保护消防设施、预防火灾、报告火警的义务。"},{"id":"mm-0531","type":"multi","question":"消防设备末端配电装置外壳上的明显位置应设置产品铭牌,内容应包括（）等。","options":[{"value":"A","text":"产品名称","isCorrect":true},{"value":"B","text":"规格型号","isCorrect":false},{"value":"C","text":"产品编号","isCorrect":false},{"value":"D","text":"额定电压","isCorrect":false},{"value":"E","text":"防护等级","isCorrect":false}],"answer":"A","explanation":"在消防设备未端配电装置外壳上的明显位置应设置产品铭牌,产品铭牌内容应至少包括:产品名称、规格型号、产品编号、额定电压、额定电流、防护等级、执行标准、制造日期、生产单位名称或商标等。"},{"id":"mm-0532","type":"multi","question":"(水箱)消防水池(水箱)应设置于（）的场所。","options":[{"value":"A","text":"便于维护","isCorrect":true},{"value":"B","text":"通风良好","isCorrect":false},{"value":"C","text":"不结冰","isCorrect":false},{"value":"D","text":"不受污染","isCorrect":false},{"value":"E","text":"空间较大","isCorrect":false}],"answer":"A","explanation":"消防水池(水箱)应设置于便于维护、通风良好、不结冰、不受污染的场所。"},{"id":"mm-0533","type":"multi","question":"消防联动控制器主要包括:（）指示灯、音响器件、回路板、接口组件、电源装置(含电池)、外壳等部分。","options":[{"value":"A","text":"主板","isCorrect":true},{"value":"B","text":"多线控制盘","isCorrect":false},{"value":"C","text":"总线控制盘","isCorrect":false},{"value":"D","text":"消防电话","isCorrect":false},{"value":"E","text":"消防广播","isCorrect":false}],"answer":"A","explanation":"本题考查考生对消防联动控制器组成知识点的掌握情况。消防联动控制器主要包括:主板、直接手动控制单元(多线控制盘)、总线控制盘、指示灯、音响器件、盘、指示灯、音响器件、回路板、接口组件、电源装置(含电池)、外壳等部分。消防电话和应急广播都属于单独的系统,不属于消防联动控制器的组件。"},{"id":"mm-0534","type":"multi","question":"火灾自动报警系统包括（）。","options":[{"value":"A","text":"火灾探测报警系统","isCorrect":true},{"value":"B","text":"消防联动控制系统","isCorrect":false},{"value":"C","text":"消防应急广播系统","isCorrect":false},{"value":"D","text":"消防电话系统","isCorrect":false},{"value":"E","text":"图形显示系统","isCorrect":false}],"answer":"A","explanation":"火灾自动报警系统包括火灾探测报警系统、消防联动控制系统、可燃气体探测报警系统、电气火灾监控系统。"},{"id":"mm-0535","type":"multi","question":"未端试水装置可以测试( )的动作是否正常,配水管道是否畅通,以及系统最不利点处的工作压力等,也可以检测干式系统和预作用系统的充水时间。","options":[{"value":"A","text":"水流指示器","isCorrect":true},{"value":"B","text":"报警阀","isCorrect":false},{"value":"C","text":"压力开关","isCorrect":false},{"value":"D","text":"洒水喷头","isCorrect":false},{"value":"E","text":"水力警铃","isCorrect":false}],"answer":"A","explanation":"未端试水装置可以测试水流指示器,报警阀,压力开关,水力警铃的动作是否正常,配水管道是否畅通,以及系统最不利点处的工作压力等,也可以检测干式系统和预作用系统的充水时间。"},{"id":"mm-0536","type":"multi","question":"火灭显示盘按显示方式分为( )三种。","options":[{"value":"A","text":"数字式","isCorrect":true},{"value":"B","text":"图形式","isCorrect":false},{"value":"C","text":"汉字/英文式","isCorrect":false},{"value":"D","text":"图像式","isCorrect":false},{"value":"E","text":"液晶式","isCorrect":false}],"answer":"A","explanation":"火灾显示盘按显示方式分为数字式,图形式汉字/英文式三种。"},{"id":"mm-0537","type":"multi","question":"历史记录包括（）、操作记录、监管记录、气灭记录和其他故障记录。","options":[{"value":"A","text":"火警记录","isCorrect":true},{"value":"B","text":"设备故障记录","isCorrect":false},{"value":"C","text":"启动记录","isCorrect":false},{"value":"D","text":"请求记录","isCorrect":false},{"value":"E","text":"反馈记录","isCorrect":false}],"answer":"A","explanation":"本题考查考生对通过集中火灾报警控制器查询历史信息知识点的掌握情况。历史记录包括火警记录、设备故障记录、请求记录、启动记录、反馈记录、操作记录、监管记录、气灭记录和其他故障记录等，每种数量最多为1000条,存满后新事件产生时覆盖一个最远的事件。结合题意,本题应选全选。"},{"id":"mm-0538","type":"multi","question":"下列工具中,可以用于清扫电话机表面和接线端子处的灰尘的有（）。","options":[{"value":"A","text":"吸尘器","isCorrect":true},{"value":"B","text":"清洁的干软布","isCorrect":false},{"value":"C","text":"钢丝球","isCorrect":false},{"value":"D","text":"湿巾","isCorrect":false},{"value":"E","text":"清洁剂","isCorrect":false}],"answer":"A","explanation":"中级46页,用吸尘器、清洁的干软布等清除电话机表面、电话插孔内及所有接线端子处的灰尘。外壳标识不清晰或涂覆层脱落、起泡严重的,应进行涂补或更换外壳组件。"},{"id":"mm-0539","type":"multi","question":"液体燃烧主要有()等特殊现象。","options":[{"value":"A","text":"闪燃","isCorrect":true},{"value":"B","text":"爆炸","isCorrect":false},{"value":"C","text":"沸溢","isCorrect":false},{"value":"D","text":"喷溅","isCorrect":false}],"answer":"A","explanation":"基础知识20页,常见的液体燃烧主要有以下3类特殊现象。闪燃、沸溢、喷溅。"},{"id":"mm-0540","type":"multi","question":"火灾报警的方法有（）。","options":[{"value":"A","text":"拨打\"119\"火灾报警电话","isCorrect":true},{"value":"B","text":"使用报警设施设备如报警按钮报警","isCorrect":false},{"value":"C","text":"通过应急广播系统发布火警信息和疏散指示","isCorrect":false},{"value":"D","text":"条件充许时,可派人至就近消防站报警","isCorrect":false},{"value":"E","text":"使用预先约定的信号或方法报警","isCorrect":false}],"answer":"A","explanation":"P131,火灾报警的方法有(1)拨拔打\"119\"火灾报警电话。(2)使用报警设施设备如报警按钮报警。(3)通过应急广播系统发布火警信息和疏散指示。(4)条件允许时,可派人至就近消防站报警。(5)使用预先约定的信号或方法报警。"},{"id":"mm-0541","type":"multi","question":"火灾自动报警系统的基本形式可分为（）。","options":[{"value":"A","text":"独立报警系统","isCorrect":false},{"value":"B","text":"区域报警系统","isCorrect":true},{"value":"C","text":"集中报警系统","isCorrect":false},{"value":"D","text":"控制中心报警系统","isCorrect":false},{"value":"E","text":"城市远程控制系统","isCorrect":false}],"answer":"B","explanation":"基础知识81页,火灾自动报警系统有区域报警系统、集中报警系统和控制中心报警系统三种形式,各自有不同的适用范围。"},{"id":"mm-0542","type":"multi","question":"建筑火灾逃生避难器材按器材结构可分为（）。","options":[{"value":"A","text":"绳索类","isCorrect":true},{"value":"B","text":"滑道类","isCorrect":false},{"value":"C","text":"梯类","isCorrect":false},{"value":"D","text":"呼吸器类","isCorrect":false},{"value":"E","text":"灭火类","isCorrect":false}],"answer":"A","explanation":"基础知识119页,建筑火灾逃生避难器材按器材结构可分为绳索类、滑道类、梯类、呼吸器类。"},{"id":"mm-0543","type":"multi","question":"更换火灾警报装置后的功能测试内容包括（）。","options":[{"value":"A","text":"采用手动启动方式,检查火灾警报装置的声光启动功能","isCorrect":true},{"value":"B","text":"采用联动启动方式,检查火灾警报装置的声光启动功能","isCorrect":false},{"value":"C","text":"火灾报警控制器上应显示xxx编码的声光启动事件争","isCorrect":false},{"value":"D","text":"对火灾报警控制器进行复位操作","isCorrect":false},{"value":"E","text":"对火灾报警控制器进行自检操作","isCorrect":false}],"answer":"A","explanation":"中级教材54页,测试更换后的火灾警报装置功能:采用手动和联动启动方式,检查火灾警报装置的声光启动功能,具有语音提示功能的火灾声警报器还应检查其语音同步功能。火灾报警控制器上应显示XXX编码的声光启动事件。测试后对火灾报警控制器进行复位、自检操作。"},{"id":"mm-0544","type":"multi","question":"点型火灾探测器距墙壁、梁边及遮挡物的距离符合要求的有（）m。","options":[{"value":"A","text":"0.3","isCorrect":false},{"value":"B","text":"0.4","isCorrect":false},{"value":"C","text":"0.6","isCorrect":true},{"value":"D","text":"0.8","isCorrect":false},{"value":"E","text":"1.0","isCorrect":false}],"answer":"C","explanation":"中级技能p58,点型火灾探测器距墙壁、遮挡物不应小于0.5m距空调送风口最近边的水平距离不应小于1.5m,距多孔送风顶棚孔口的水平距离不应小于0.5m。"},{"id":"mm-0545","type":"multi","question":"固定消防炮灭火系统按喷射介质可分为( )。","options":[{"value":"A","text":"水炮系统","isCorrect":true},{"value":"B","text":"泡沫炮系统","isCorrect":false},{"value":"C","text":"远控消防炮系统","isCorrect":false},{"value":"D","text":"干粉炮系统","isCorrect":false},{"value":"E","text":"热气溶胶消防炮灭火系统","isCorrect":false}],"answer":"A","explanation":"固定消防炮灭火系统的3种分类方法:1按喷射介质:分为水炮系统、泡沫炮系统、干粉炮系统。2按控制方式:分为远控消防炮系统、非远控消防炮系统。3按安装形式:固定式消防炮系统、移动式消防炮系统。"},{"id":"mm-0546","type":"multi","question":"下列现象属于发生轰燃征兆的是（）。","options":[{"value":"A","text":"室内顶棚热烟气层开始出现火焰","isCorrect":true},{"value":"B","text":"顶棚处火焰由于空气卷吸,形成似手指的滚动状","isCorrect":false},{"value":"C","text":"室内温度突然升高,让人难以忍受","isCorrect":false},{"value":"D","text":"空气中烟气降至离地面1m左右","isCorrect":false}],"answer":"A","explanation":"》根据《基础知识》新教材34页。轰燃发生前可能出现4种征兆:(1)室内顶棚热烟气层开始出现火焰。(2)顶棚处火焰由于空气卷吸,形成于指的滚动状。(3)室内温度突然升高让人难以忍受。(4)空气中烟气降至离地面1m左右。"},{"id":"mm-0547","type":"multi","question":"有关室内消火栓设备的安装质量要求,说法正确的是（）。","options":[{"value":"A","text":"消防电梯前室应设置室内消火栓,并应计入消火栓使用数量","isCorrect":true},{"value":"B","text":"同一楼梯间及其附近不同层设置的消火栓,其平面位置宜相同","isCorrect":false},{"value":"C","text":"同一建筑物内设置的消火栓可以视情况采用不同规格的栓口、水枪、水带及配件","isCorrect":false},{"value":"D","text":"室内消火栓栓口不应安装在门轴侧","isCorrect":false},{"value":"E","text":"箱门的开启不应小于90°","isCorrect":false}],"answer":"A","explanation":"室内消火栓设备的安装质量要求:同一建筑物内没置的消火栓应采用统一规格的栓口、水枪、水带及配件;箱门的开启不应小于120°结合题意,应排除C、E选项,其他正确"},{"id":"mm-0548","type":"multi","question":"闭式酒水喷头根据热敏性能指标不同分为（）。","options":[{"value":"A","text":"玻璃球洒水喷头","isCorrect":false},{"value":"B","text":"易熔元件洒水喷头","isCorrect":false},{"value":"C","text":"快速响应酒水喷头","isCorrect":true},{"value":"D","text":"特殊响应洒水喷头","isCorrect":false},{"value":"E","text":"标准响应洒水喷头","isCorrect":false}],"answer":"C","explanation":"根据《基础知识》新教材92页。表6-2-1自动喷水灭火系统闭式洒水喷头热敏性能指标的响应时间指数,其中类别分为快速响应洒水喷头,特殊响应酒水喷头和标准响应酒水喷头三种"},{"id":"mm-0549","type":"multi","question":"检查消防应急广播设备的主机外壳,确保消防应急广播设备的( )。","options":[{"value":"A","text":"产品标识清晰明显","isCorrect":true},{"value":"B","text":"机壳表面清洁","isCorrect":false},{"value":"C","text":"涂覆层脱落和起泡现象","isCorrect":false},{"value":"D","text":"无腐蚀现象","isCorrect":false},{"value":"E","text":"产品标识破损或脱落","isCorrect":false}],"answer":"A","explanation":"中级47页,检查消防应急广播设备的主机外壳,确保消防应急广播设备的产品标识清晰明显,机壳表面清洁,无腐蚀、涂覆层脱落和起泡现象。C选项缺一个\"无\"字故错误。"},{"id":"mm-0550","type":"multi","question":"对应急广播设备外观进行保养,应使用吸尘器、清洁的干软布等清除（）的灰尘。","options":[{"value":"A","text":"主机外壳","isCorrect":true},{"value":"B","text":"扬声器表面","isCorrect":false},{"value":"C","text":"接线端子","isCorrect":false},{"value":"D","text":"主机电源","isCorrect":false},{"value":"E","text":"主机内部线路板","isCorrect":false}],"answer":"A","explanation":"中级47页,对应急广播设备进行保养,应使用吸尘器、清洁的干软布等清除主机外壳和扬声器表面及所有接线端子处的灰尘。"},{"id":"mm-0551","type":"multi","question":"按物理状态不同,可燃物可以分为（）。","options":[{"value":"A","text":"固体可燃物","isCorrect":true},{"value":"B","text":"气体可燃物","isCorrect":false},{"value":"C","text":"液体可燃物","isCorrect":false},{"value":"D","text":"活泼金属","isCorrect":false}],"answer":"A","explanation":"基础知识17页,按化学组成不同,可燃物可分为有机可燃物和无机可燃物;按物理状态不同,可燃物可以分为固体可燃物、气体可燃物和液体可燃物。"},{"id":"mm-0552","type":"multi","question":"保养前,消防控制室图形显示装置应断开（）,使装置完全处于无电源状态。","options":[{"value":"A","text":"交流供电","isCorrect":true},{"value":"B","text":"UPS电源","isCorrect":false},{"value":"C","text":"网络连接","isCorrect":false},{"value":"D","text":"EPS电源","isCorrect":false},{"value":"E","text":"蓄电池电源","isCorrect":false}],"answer":"A","explanation":"中级44页,使用专用钥匙打开设备箱(柜)门,先断开设备的备用电源开关,再断开主电源开关。对于消防控制室图形显示装置应断开交流供电、UPS电源和网络连接,使装置完全处于无源状态。"},{"id":"mm-0553","type":"multi","question":"下列关于避难间设置要求说法正确的是（）。","options":[{"value":"A","text":"避难区的净面积应满足避难间所在区域设计避难人数避难的要求","isCorrect":true},{"value":"B","text":"避难间应靠近疏散楼梯间,不应在可燃物库房、锅炉房、发电机房、变配电站等火灾危险性大的场所的正下方、正上方或贴邻","isCorrect":false},{"value":"C","text":"避难间应采用耐火极限不低于2.00h的防火隔墙和甲级防火门与其他部位分隔","isCorrect":false},{"value":"D","text":"避难间应采取防止火灾烟气进入或积聚的措施,并应设置可开启外窗,除外窗和疏散门外,避难间不应设置其他开口","isCorrect":false},{"value":"E","text":"避难间内应设置消防软管卷盘、灭火器、消防专线电话和应急广播","isCorrect":false}],"answer":"A","explanation":"基础知识61页,避难间的设置应符合下列规定。1.避难区的净面积应满足避难间所在区域设计避难人数避难的要求。2.避难间兼作其他用途时,应采取保证人员安全避难的措施。3.避难间应靠近疏散楼梯间,不应在可燃物库房、锅炉房、发电机房、变配电站等火灾危险性大的场所的正下方、正上方或贴邻。4.避难间应采用耐火极限不低于2.00h的防火隔墙和甲级防火门与其他部位分隔。5.避难间应采取防止火灾烟气进入或积聚的措施,并应设置可开启外窗,除外窗和疏散门外,避难间不应设置其他开口。6.避难间内不应敷设或穿过输送可燃液体、可燃或易燃物。"},{"id":"mm-0554","type":"multi","question":"红外光束线型感烟火灾探测器分为（）两种。","options":[{"value":"A","text":"对射型","isCorrect":true},{"value":"B","text":"反射型","isCorrect":false},{"value":"C","text":"折射型","isCorrect":false},{"value":"D","text":"辐射型","isCorrect":false},{"value":"E","text":"角射型","isCorrect":false}],"answer":"A","explanation":"中级技能80页,线型光束感烟火灾探测器分为激光光束线型感烟火灾探测器和红外光束线型感烟火灾探测器两种类型,自前广泛使用的是红外光束线型感烟火灾探测器。红外光束线型感烟火灾探测器又分为对射型和反射型两种。"},{"id":"mm-0555","type":"multi","question":"燃烧过程的发生和发展必须同时具备（）3个必要条件。","options":[{"value":"A","text":"可燃物","isCorrect":true},{"value":"B","text":"助燃物","isCorrect":false},{"value":"C","text":"氧气","isCorrect":false},{"value":"D","text":"引火源","isCorrect":false},{"value":"E","text":"链式反应自由基","isCorrect":false}],"answer":"A","explanation":"基础知识17页,燃烧过程的发生和发展必须同时具备可燃物、助燃物、引火源3个必要条件,通常称为\"燃烧三要素\"。但要导致燃烧发生,不仅需要满足三要素条件,而且需要三者达到一定量的要求并目存在相互作用的过程。因此,燃烧的充分条件可以进一步表述为:具备足够数量或浓度的可燃物,具备足够数量或浓度的助燃物,具备足够能量的引火源。"},{"id":"mm-0556","type":"multi","question":"下列属于不燃性构件的是0下列属于不燃然性构件的定()","options":[{"value":"A","text":"钢柱","isCorrect":true},{"value":"B","text":"混凝土楼板","isCorrect":false},{"value":"C","text":"砖墙","isCorrect":false},{"value":"D","text":"水泥刨花板","isCorrect":false},{"value":"E","text":"竹质构件","isCorrect":false}],"answer":"A","explanation":"基础知识43页,不燃性构件是指用不燃材料制成的构件,如钢柱、混凝土楼板、砖墙、石膏板等。"},{"id":"mm-0557","type":"multi","question":"下列属于消防电话总机呼叫分机的步骤的有（）。","options":[{"value":"A","text":"查看总机状态","isCorrect":true},{"value":"B","text":"摘下总机话筒","isCorrect":false},{"value":"C","text":"呼叫分机","isCorrect":false},{"value":"D","text":"按下录音按键","isCorrect":false},{"value":"E","text":"挂机","isCorrect":false}],"answer":"A","explanation":"中级32页,总机呼叫分机通话时自动录音,不需要按录音按键。"},{"id":"mm-0558","type":"multi","question":"多线控制盘操作面板上设有多个手动控制单元,每个单元包括一个操作按钮和( )三个状态指示灯。","options":[{"value":"A","text":"启动","isCorrect":true},{"value":"B","text":"反馈","isCorrect":false},{"value":"C","text":"故障","isCorrect":false},{"value":"D","text":"停止","isCorrect":false},{"value":"E","text":"动作","isCorrect":false}],"answer":"A","explanation":"多线控制盘操作面板上设有多个手动控制单元,每个单元包括一个操作按钮和启动,反馈,故障三个状态指示灯。"},{"id":"mm-0559","type":"multi","question":"常用火灾报警触发设备有（）等。","options":[{"value":"A","text":"感烟火灾探测器","isCorrect":true},{"value":"B","text":"手动火灾报警按钮","isCorrect":false},{"value":"C","text":"红外火焰探测器","isCorrect":false},{"value":"D","text":"感温火灾探测器","isCorrect":false},{"value":"E","text":"压力开关","isCorrect":false}],"answer":"A","explanation":"本题考查考生对区分集中火灾报警控制器的火警、联动监管、屏蔽(隔离)和故障报警信号知识点的掌握情况。常用火灾报警触发设备有感烟探测器、感温探测器、手动火灾报警按钮、红外火焰探测器等。结合题意,本题排除“压力开关”,其余正确。"},{"id":"mm-0560","type":"multi","question":"消防电话系统由（）和专用消防电话线路组成。","options":[{"value":"A","text":"消防电话总机","isCorrect":true},{"value":"B","text":"消防电话分机","isCorrect":false},{"value":"C","text":"消防电话座机","isCorrect":false},{"value":"D","text":"消防电话插孔","isCorrect":false},{"value":"E","text":"消防电话手柄","isCorrect":false}],"answer":"A","explanation":"消防电话系统由消防电话总机、消防电话分机、消防电话插孔、消防电话手柄和专用消防电话线路组成。结合题意,本题应选ABDE"},{"id":"mm-0561","type":"multi","question":"下列选项中,属于闭式系统的有( )。","options":[{"value":"A","text":"湿式系统","isCorrect":true},{"value":"B","text":"干式系统","isCorrect":false},{"value":"C","text":"预作用系统","isCorrect":false},{"value":"D","text":"重复启闭预作用系统","isCorrect":false},{"value":"E","text":"雨淋系统","isCorrect":false}],"answer":"A","explanation":"自动喷水灭火系统按照洒水喷头形式的不同分为开式系统和闭式系统两类,其中闭式系统指采用闭式洒水喷头的自动喷水灭火系统,包括湿式系统、干式系统、预作用系统、重复启闭预作用系统。“雨淋系统\"属于开式系统,故此项可排除。结合题意,本题应选\"湿式系统”、“于式系统\"、“预作用系统\"、“重复启闭预作用系统\"4项,其他项可排除。"},{"id":"mm-0562","type":"multi","question":"水系灭火剂的适用范围是什么（）。","options":[{"value":"A","text":"用直流水或开花水可扑救一般固体物质的表面火灾及闪点在120°C以上的重油火灾。","isCorrect":true},{"value":"B","text":"用雾状水可扑救阴燃物质火灾、可燃粉尘火灾、电气设备火灾。","isCorrect":false},{"value":"C","text":"用水蒸气可以扑救封闭空间内(如船舱)的火灾。","isCorrect":false},{"value":"D","text":"凡遇水会发生燃烧和爆炸的物质,不能用水进行扑救。","isCorrect":false},{"value":"E","text":"但凡是燃烧物体都可以用水流扑灭","isCorrect":false}],"answer":"A","explanation":"水系灭火剂的适用范围:(1) 用直流水或开花水可扑救一般固体物质的表面火灾及闪点在120C以上的重油火灾。(2)用雾状水可扑救阴燃物质火灾、可燃粉尘火灾、电气设备火灾。(3) 用水蒸气可以扑救封闭空间内(如船舱)的火灾。(4) 凡遇水会发生燃烧和爆炸的物质,不能用水进行扑救。"},{"id":"mm-0563","type":"multi","question":")消防泵组电气控制柜具有（）保护、反馈及机械应急启动功能。","options":[{"value":"A","text":"启/停","isCorrect":true},{"value":"B","text":"主/备泵切换","isCorrect":false},{"value":"C","text":"手/自动转换","isCorrect":false},{"value":"D","text":"双电源切换","isCorrect":false},{"value":"E","text":"巡检","isCorrect":false}],"answer":"A","explanation":"消防泵组电气控制柜具有启/停，主/备泵切换，手/自动转换,双电源切换,巡检、保护、反馈及机械应急启动功能。结合题意,本题全选"},{"id":"mm-0564","type":"multi","question":"初期火灾扑救的基本程序（）。","options":[{"value":"A","text":"发现起火后,应利用就近消火栓、灭火器等设施灭火,触动手动火灾报警按钮或拨打报警电话,及时通知消防控制室值班人员。","isCorrect":true},{"value":"B","text":"火灾确认后,应及时启动灭火和应急疏散预案,迅速开启消防设施,第一时间组织力量灭火,并向相关人员通报火灾情况。","isCorrect":false},{"value":"C","text":"组织、引导人员有序疏散,协助有需要的人员撤离。","isCorrect":false},{"value":"D","text":"设立警戒,阻止无关人员进入火场,维护现场秩序。","isCorrect":false},{"value":"E","text":"迅速扑灭火灾。","isCorrect":false}],"answer":"A","explanation":"初期火灾扑救的基本程序是:1.发现起火后,应利用就近消火栓、灭火器等设施灭火,触动手动火灾报警按钮或拨打报警电话,及时通知消防控制室值班人员。2.火灾确认后,应及时启动灭火和应急疏散预案,迅速开启消防设施,第一时间组织力量灭火,并向相关人员通报火灾情况。3.组织、引导人员有序疏散,协助有需要的人员撤离。4.设立警戒,阻止无关人员进入火场,维护现场秩序。"},{"id":"mm-0565","type":"multi","question":"室内消火栓系统田（）等组成。","options":[{"value":"A","text":"供水设施","isCorrect":true},{"value":"B","text":"消防给水管网","isCorrect":false},{"value":"C","text":"室内消火栓设备","isCorrect":false},{"value":"D","text":"报警控制设备","isCorrect":false},{"value":"E","text":"系统附件","isCorrect":false}],"answer":"A","explanation":"室内消火栓系统由供水设施、消防给水管网、室内消火栓设备、报警控制设备及系统附件等组成。"},{"id":"mm-0566","type":"multi","question":"未端试水装置的作用是（）。","options":[{"value":"A","text":"检验自动喷水灭火系统的可靠性","isCorrect":true},{"value":"B","text":"测试系统能否在开启一只喷头的最不利条件下可靠报警并正常启动","isCorrect":false},{"value":"C","text":"测试水流指示器、报警阀、压力开关、水力警铃的动作是否正常","isCorrect":false},{"value":"D","text":"配水管道是否畅通,以及系统最不利点处的工作压力","isCorrect":false},{"value":"E","text":"可用于检测干式系统和预作用系统的充水时间","isCorrect":false}],"answer":"A","explanation":"检验自动喷水灭火系统的可靠性;测试系统能否在开启一只喷头的最不利条件下可靠报警并正常启动;测试水流指示器、报警阀、压力开关、水力警铃的动作是否正常;配水管道是否畅通,以及系统最不利点处的工作压力;可用于检测干式系统和预作用系统的充水时间。"},{"id":"mm-0567","type":"multi","question":"消防应急灯具按应急供电方式可分为（）。","options":[{"value":"A","text":"非集中控制型消防应急灯具","isCorrect":false},{"value":"B","text":"集中控制型消防应急灯具","isCorrect":false},{"value":"C","text":"持续型消防应急灯具","isCorrect":false},{"value":"D","text":"集中电源型消防应急灯具","isCorrect":true},{"value":"E","text":"自带电源型消防应急灯具","isCorrect":false}],"answer":"D","explanation":"消防应急灯具按应急供电方式可分为自带电源型消防应急灯具、集中电源型消防应急灯具、子母型消防应急灯具。"},{"id":"mm-0568","type":"multi","question":"消防设备末端配电装置的保养项目包含含（）、熔断器保养、断路器保养及柜体保养。","options":[{"value":"A","text":"指示灯保养","isCorrect":true},{"value":"B","text":"操作按钮保养","isCorrect":false},{"value":"C","text":"切换开关保养","isCorrect":false},{"value":"D","text":"自动空气开关保养","isCorrect":false},{"value":"E","text":"母线保养","isCorrect":false}],"answer":"A","explanation":"消防设备未端配电装置的保养项目包含:1.指示保美；2.操作按钮保养；3.切换开关保养；4.自动空气开关保养；5.母线保养；6.熔断器保养；7.断路器保养；8.柜体保养。"},{"id":"mm-0569","type":"multi","question":"下列关于避难层设置要求说法正确的是()。","options":[{"value":"A","text":"第一个避难层的楼面至消防车登高操作场地地面的高度不应大于50m","isCorrect":true},{"value":"B","text":"除可布置设备用房外,避难层不应用于其他用途","isCorrect":false},{"value":"C","text":"设备管道区、管道井和设备间与避难区或疏散走道连通时,应设置防火隔间,防火隔间的门应为甲级防火门","isCorrect":false},{"value":"D","text":"避难层应设置消防电梯出口、消火栓、消防软管卷盘、火火器、消防专线电话和应急广播","isCorrect":false},{"value":"E","text":"在避难层进入楼梯间的入口处和疏散楼梯通向避难层的出口处,均应在明显位置设置标示避难层和楼层位置的灯光指示标识","isCorrect":false}],"answer":"A","explanation":"建筑高度大于100m的工业与民用建筑应设置避难层,且第一个避难层的楼面至消防车登高操作场地地面的高度不应大于50m。避难层应符合下列规定。(1)避难区的净面积应满足该避难层与上一避难层之间所有楼层的全部使用人数避难的要求。(2)除可布置设备用房外,避难层不应用于其他用途。设置在避难层内的可燃液体管道、可燃或助燃气体管道应集中布燃液体管道、可燃或助燃气体管道应集中布置,设备管道区应采用耐火极限不低于3.00h的防火隔墙与避难区及其他公共区分隔。管道井和设备间应采用耐火极限不低于2.00h的防火隔墙与避难区及其他公共区分隔。"},{"id":"mm-0570","type":"multi","question":"《公民道德建设实施纲要》》明确提出,”()、()、()、()、()“是从业人员职业道德规范的主要内容。","options":[{"value":"A","text":"爱岗敬业","isCorrect":true},{"value":"B","text":"诚实守信","isCorrect":false},{"value":"C","text":"办事公道","isCorrect":false},{"value":"D","text":"热情服务","isCorrect":false},{"value":"E","text":"奉献社会","isCorrect":false}],"answer":"A","explanation":"《新时代公民道德建设实施纲要》提出,爱岗敬业、诚实守信、办事公道、热情服务、奉献社会是从业人员职业道德规范的主要内容。"},{"id":"mm-0571","type":"multi","question":"室内消火栓给水系统按照用途不同,可分为（）。","options":[{"value":"A","text":"生产、生活、消防合用给水系统","isCorrect":true},{"value":"B","text":"生产、消防合用给水系统","isCorrect":false},{"value":"C","text":"生活、消防合用给水系统","isCorrect":false},{"value":"D","text":"生产、生活合用给水系统","isCorrect":false},{"value":"E","text":"独立消防给水系统","isCorrect":false}],"answer":"A","explanation":"室内消火栓给水系统按用途不同可分为生产、生活、消防合用给水系统；生产、消防合用给水系统；生活、消防合用给水系统；独立消防给水系统四类;"},{"id":"mm-0572","type":"multi","question":"加强公民道德建设有（）、（）、（）、（）4个着力点。","options":[{"value":"A","text":"社会公德","isCorrect":true},{"value":"B","text":"职业道德","isCorrect":false},{"value":"C","text":"中华传统美德","isCorrect":false},{"value":"D","text":"家庭美德","isCorrect":false},{"value":"E","text":"个人品德","isCorrect":false}],"answer":"A","explanation":"加强公民道德建设有哪4个着力点要把社会公德、职业道德、家庭美德、个人品德建设作为着力点。(1) 推动践行以文明礼貌、助人为乐、爱护公物、保护环境、遵纪守法为主要内容的社会公德,鼓励人们在社会上做一个好公民。(2) 推动践行以爱岗敬业、诚实守信、办事公道、热情服务、奉献社会为主要内容的职业道德,鼓励人们在工作中做一个好建设者。(3) 推动践行以尊老爱幼、男女平等、夫妻和睦、勤俭持家、邻里互助为主要内容的家庭美德,鼓励人们在家庭里做一个好成员。(4) 推动践行以爱国奉献......"},{"id":"mm-0573","type":"multi","question":"（）等开关信号应能直接自动启动消防水泵。","options":[{"value":"A","text":"消防水泵出水干管上设置的压力开关","isCorrect":true},{"value":"B","text":"高位消防水箱出水管上的流量开关","isCorrect":false},{"value":"C","text":"湿式报警阀的压力开关","isCorrect":false},{"value":"D","text":"干式报警阀组的压力开关","isCorrect":false},{"value":"E","text":"信号蝶阀开关","isCorrect":false}],"answer":"A","explanation":"消防水泵出水干管上设置的压力开关、高位消防水箱出水管上的流量开关、湿式报整阀的压力开关和干式报警阀组的压力开关等开关信号应能直接自动启动消防水泵。"},{"id":"mm-0574","type":"multi","question":"消防水源包括（）。","options":[{"value":"A","text":"市政给水","isCorrect":true},{"value":"B","text":"消防水池","isCorrect":false},{"value":"C","text":"高位消防水箱","isCorrect":false},{"value":"D","text":"天然水源","isCorrect":false},{"value":"E","text":"消防水泵接合器","isCorrect":false}],"answer":"A","explanation":"消防水源是指向水灭火设施、车载或手抬等移动消防水泵、固定消防水泵等提供消防用水的水源,是灭火成功的基本保证。消防水源有市政给水、消防水池、天然水源三类。“高位消防水箱\"、“消防水泵接合器\"属于消防给水基础设施,可排除。结合题意,本题应选\"市政给水\"“消防水池\"、“天然水源\"3项,其他项均可排除。"},{"id":"mm-0575","type":"multi","question":"消防设施操作员职业守则是（）。","options":[{"value":"A","text":"以人为本,生命至上","isCorrect":true},{"value":"B","text":"忠于职守,严守规程","isCorrect":false},{"value":"C","text":"钻研业务,精益求精","isCorrect":false},{"value":"D","text":"临危不乱,科学处置","isCorrect":false}],"answer":"A","explanation":"消防设施操作员职业守则是:(1)以人为本,生命至上。(2)忠于职守,严守规程。(3)钻研业务,精益求精。(4)临危不乱,科学处置。"},{"id":"mm-0576","type":"multi","question":"集中火灾报警控制器、消防联动控制器、消防控制室图形显示装置的保养项目包含（）等。","options":[{"value":"A","text":"外壳外观保养","isCorrect":true},{"value":"B","text":"指示灯保养","isCorrect":false},{"value":"C","text":"显示屏保养","isCorrect":false},{"value":"D","text":"开关按键、键盘、鼠标保养","isCorrect":false},{"value":"E","text":"打印机保养","isCorrect":false}],"answer":"A","explanation":"集中火灾报警控制器、消防联动控制器、消防控制室图形显示装置的保养项目包含外壳外观保养、指示灯保养、显示屏保养、开关按键、键盘、鼠标保养、打印机保养等。"},{"id":"mm-0577","type":"multi","question":"挡烟垂壁不能通过（）方式控制。","options":[{"value":"A","text":"火灾自动报警系统联动启动","isCorrect":false},{"value":"B","text":"电气控制柜手动启动","isCorrect":true},{"value":"C","text":"现场手动启动","isCorrect":false},{"value":"D","text":"温控释放装置启动","isCorrect":false},{"value":"E","text":"排烟防火阀联锁启动","isCorrect":false}],"answer":"B","explanation":"教材150页,挡烟垂壁可以通过火灾自动报警系统自动启动和现场手动启动。"},{"id":"mm-0578","type":"multi","question":"机械排烟系统主要由( )和排烟出口等组成。","options":[{"value":"A","text":"挡烟壁","isCorrect":true},{"value":"B","text":"排烟防火阀","isCorrect":false},{"value":"C","text":"排烟阀","isCorrect":false},{"value":"D","text":"排烟道","isCorrect":false},{"value":"E","text":"排烟风机","isCorrect":false}],"answer":"A","explanation":"本题考查考生对机械排烟系统的主要组件知识点的掌握情况。机械排烟系统主要由挡烟壁(活动式或固定式挡烟垂壁,或挡烟隔墙、挡烟梁)、排烟防火阀、排烟阀(或带有排烟阀的排烟口)、排烟道、挡烟风机和排烟出口等组成。结合题意,本题全选。"},{"id":"mm-0579","type":"multi","question":"挡烟垂壁能通过（）方式控制。","options":[{"value":"A","text":"火灾自动报警系统联动启动","isCorrect":true},{"value":"B","text":"电气控制柜手动启动","isCorrect":false},{"value":"C","text":"现轻手动动现场手动启动","isCorrect":false},{"value":"D","text":"温控释放装置启动","isCorrect":false},{"value":"E","text":"排烟防火阀联锁启动","isCorrect":false}],"answer":"A","explanation":"中级150页,挡烟垂壁可以通过火灾自动报警系统自动启动和现场手动启动。"},{"id":"mm-0580","type":"multi","question":"高层民用建筑的耐火等级可为（）。","options":[{"value":"A","text":"一级","isCorrect":true},{"value":"B","text":"二级","isCorrect":false},{"value":"C","text":"三级","isCorrect":false},{"value":"D","text":"四级","isCorrect":false},{"value":"E","text":"上述均可以","isCorrect":false}],"answer":"A","explanation":"基础知识47页,(1)下列民用建筑的耐火等级应为一级:一类高层民用建筑。(2)下列民用建筑的耐火等级不应低于二级:二类高层民用建筑。"},{"id":"mm-0581","type":"multi","question":"应急照明控制器的保养项目包含（）。","options":[{"value":"A","text":"外观检查","isCorrect":true},{"value":"B","text":"稳定性检查","isCorrect":false},{"value":"C","text":"切换开关检查","isCorrect":false},{"value":"D","text":"接线检查","isCorrect":false},{"value":"E","text":"功能检查","isCorrect":false}],"answer":"A","explanation":"应急照明控制器的保养项目包含:1.外观检查2稳定性检查3.接线检查4.功能检查"},{"id":"mm-0582","type":"multi","question":"下列关于消防车道的说法正确的是（）。","options":[{"value":"A","text":"道路的净宽度和净空高度应满足消防车安全、快速通行的要求","isCorrect":true},{"value":"B","text":"转弯半径应满足消防车转弯的要求","isCorrect":false},{"value":"C","text":"路面及其下面的建筑结构、管道、管沟等,应满足承受消防车满载时压力的要求","isCorrect":false},{"value":"D","text":"长度大于40m的尽头式消防车道应设置满足消防车回转要求的场地或道路","isCorrect":false},{"value":"E","text":"消防车道与建筑消防扑救面之间不应有妨碍消防车操作的障碍物,不应有影响消防车安全作业的架空高压电线","isCorrect":false}],"answer":"A","explanation":"P052,消防车道或兼作消防车道的道路应符合下列规定。(1)道路的净宽度和净空高度应满足消防车安全、快速通行的要求。(2)转弯半径应满足消防车转弯的要求。(3)路面及其下面的建筑结构、管道、管沟等,应满足承受消防车满载时压力的要求。(4)坡度应满足消防车满载时正常通行的要求,且不应大于10%,兼作消防救援场地的消防车道,坡度尚应满足消防车停靠和消防救援作业的要求。(5)消防车道与建筑外墙的水平距离应满足消防车安全通行的要求,位于建筑消防扑救面一侧兼作消防救援场地的消防车道应满足消防救援作业的要求。"},{"id":"mm-0583","type":"multi","question":"计算机键盘主要功能分区包括（）。","options":[{"value":"A","text":"主键盘键区","isCorrect":true},{"value":"B","text":"功能键区","isCorrect":false},{"value":"C","text":"控制键区","isCorrect":false},{"value":"D","text":"数字键区","isCorrect":false},{"value":"E","text":"状态指示区","isCorrect":false}],"answer":"A","explanation":"标准Windows键盘共有104个键,分为主键盘区、功能键区、控制键区、数字键区和状态指示区5个部分。"},{"id":"mm-0584","type":"multi","question":"水幕系统的适用范围是（）。","options":[{"value":"A","text":"设置防火卷帘或防火幕等简易防火分隔物的上部","isCorrect":true},{"value":"B","text":"不能使用防火墙分隔的开口部位","isCorrect":false},{"value":"C","text":"相邻建筑物之间的防火间距不能满足要求时,建筑物外墙上的门、窗、洞口处","isCorrect":false},{"value":"D","text":"石油化工企业中的防火分区或生产装置、设备之间","isCorrect":false},{"value":"E","text":"其他需要进行水幕保护或防火隔断的部位","isCorrect":false}],"answer":"A","explanation":"水幕系统的适用范围是:1.设置防火卷帘或防火幕等简易防火分隔物的上部2.不能使用防火墙分隔的开口部位(如舞台口)3.相邻建筑物之间的防火间距不能满足要求时,建筑物外墙上的防火间距不能满足要求时,建筑物外墙上的门、窗、洞口处4.石油化工企业中的防火分区或生产装置、设备之间5.其他需要进行水幕保护或防火隔断的部位"},{"id":"mm-0585","type":"multi","question":"火灾显示盘具有（）功能。","options":[{"value":"A","text":"火灾报警显示","isCorrect":true},{"value":"B","text":"故障显示","isCorrect":false},{"value":"C","text":"自检","isCorrect":false},{"value":"D","text":"信息显示与查询","isCorrect":false},{"value":"E","text":"电源","isCorrect":false}],"answer":"A","explanation":"火灾显示盘具有火灾报警显示、故障显示、自检、信息显示与查询、电源功能。"},{"id":"mm-0586","type":"multi","question":"消防炮按驱动方式不同分为（）。","options":[{"value":"A","text":"手动消防炮","isCorrect":true},{"value":"B","text":"电动消防炮","isCorrect":false},{"value":"C","text":"液动消防炮","isCorrect":false},{"value":"D","text":"气动消防炮","isCorrect":false},{"value":"E","text":"机械消防炮","isCorrect":false}],"answer":"A","explanation":"消防炮按驱动方式不同分为手动消防炮、电动消防炮、液动消防炮、气动消防炮。"},{"id":"mm-0587","type":"multi","question":"下列现象属于发生回燃征兆的是（）。","options":[{"value":"A","text":"从室外观察着火房间,开口处流出脉动式热烟气","isCorrect":true},{"value":"B","text":"有烟气被倒吸入室内的现象","isCorrect":false},{"value":"C","text":"身处室内时,听到吸气声或呼啸声","isCorrect":false},{"value":"D","text":"室内热烟气层中出现蓝色火焰","isCorrect":false}],"answer":"A","explanation":"P034,回燃发生前通常也可能出现一些征兆。如果身处室外,可能观察到的征兆包括:着火房间开口较少,通风不良,蓄积大量烟气;着火房间的门或窗户上有油状沉积物;门、窗及其把手温度高;开口处流出脉动式热烟气;有烟气被倒吸入室内的现象。如果身处室内,或向室内看去,可能观察到的征兆包括:室内热烟气层中出现蓝色火焰(表明燃烧缺氧,燃烧产物中含有较多一氧化碳,其燃烧呈蓝色听到吸气声或呼啸声。但回燃发生前的征兆并不稳定,有时回燃发生前只能观察到一两种征兆。"},{"id":"mm-0588","type":"multi","question":"消防控制室图形显示装置用于()和记录保护区域内的火灾探测报警与各相关控制系统,以及系统中的各类消防设备(设施)运行的动态信息和消防管理信息。","options":[{"value":"A","text":"传输","isCorrect":true},{"value":"B","text":"接收","isCorrect":false},{"value":"C","text":"显示","isCorrect":false},{"value":"D","text":"发送","isCorrect":false},{"value":"E","text":"查询","isCorrect":false}],"answer":"A","explanation":"消防控制室图形显示装置用于传输、接收、显示和记录保护区域内的火灾探测报警与各相关控制系统,以及系统中的各类消防设备(设施)运行的动态信息和消防管理信息。"},{"id":"mm-0589","type":"multi","question":"初起火灭扑救的基本原则是( )。","options":[{"value":"A","text":"救人第一","isCorrect":true},{"value":"B","text":"先控制,后消灭","isCorrect":false},{"value":"C","text":"先重点,后一般","isCorrect":false},{"value":"D","text":"第一时间扑救","isCorrect":false},{"value":"E","text":"迅速抢救财物","isCorrect":false}],"answer":"A","explanation":"初起火灾扑救的基本原则是救人第一,先控生凯制,后消灭,先重点,后一般。"},{"id":"mm-0590","type":"multi","question":"推车式灭火器的使用注意事项是什么（）。","options":[{"value":"A","text":"使用时注意喷射软管不能打折或打圈","isCorrect":true},{"value":"B","text":"灭火时对准火焰根部,应由近及远扫射推进,注意死角,防止复燃。","isCorrect":false},{"value":"C","text":"使用二氧化碳灭火器灭火时,手一定要握在喷筒木柄处,接触喷筒或金属管要戴防护手套,应避免触碰喇叭筒喷嘴前部,防止冻伤。在狭小空间喷射灭火剂时,应提前采取预防措施,防止人员室息。","isCorrect":false},{"value":"D","text":"扑救可燃液体火灾时，应避免灭火剂直接冲击燃烧液面,防止可燃液体流散扩大火势。","isCorrect":false},{"value":"E","text":"扑救电气火灾时,应先断电,后灭火。","isCorrect":false}],"answer":"A","explanation":"新教材基础知识130页,(1)使用时注意喷射软管不能打折或打圈。(2)灭火时对准火焰根部,应由近及远扫射推进,注意死角,防止复燃。(3)使用二氧化碳灭火器灭火时,手一定要握在喷筒木柄处,接触喷筒或金属管要戴防护手套,应避免触碰喇叭筒喷嘴前部,防止冻伤。在狭小空间喷射灭火剂时,应提前采取预防措施,防止人员室息。(4)扑救可燃液体火灾时,应避免灭火剂直接冲击燃烧液面,防止可燃液体流散扩大火势。(5)扑救电气火灾时,应先断电,后灭火。"},{"id":"mm-0591","type":"multi","question":"常用灭火剂有哪些类型( )。","options":[{"value":"A","text":"水系灭火剂","isCorrect":true},{"value":"B","text":"泡沫灭火剂","isCorrect":false},{"value":"C","text":"气体灭火剂","isCorrect":false},{"value":"D","text":"干粉灭火剂","isCorrect":false},{"value":"E","text":"二氧化碳灭火剂","isCorrect":false}],"answer":"A","explanation":"暂无解析"},{"id":"mm-0592","type":"multi","question":"下列关于火灾时用于辅助人员疏散的电梯及其设置说法正确的是( )。直说法止确的是( )。","options":[{"value":"A","text":"应具有在火灾时仅停靠特定楼层和首层的功能","isCorrect":true},{"value":"B","text":"电梯附近的明显位置应设置标示电梯用途的标志和操作说明","isCorrect":false},{"value":"C","text":"电梯轿厢内部装修材料的燃烧性能应为A级","isCorrect":false},{"value":"D","text":"电梯轿厢内部应设置专用消防对讲电话和视频监控系统的终端设备","isCorrect":false},{"value":"E","text":"电梯的载重量不应小于800kg","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材62页。火灾时用于辅助人员疏散的电梯及其设置应符合下列规定。(1)应具有在火灾时仅停靠特定楼层和首层的功能。(2)电梯附近的明显位置应设置标示电梯用途的标志和操作说明。(3)其他要求应符合消防电梯的相关规定。119页。消防电梯应符合下列规定。1)应能在所服务区域每层停靠。2)电梯的载重量不应小于800kg。3)电梯的动力和控制线缆与控制面板的连接处、控制面板的外壳防水性能等级不应低于IPX5。4)在消防电梯的首层入口处,应设置明显的标识和供消防救援人员专用的操作按钮。"},{"id":"mm-0593","type":"multi","question":"（）等部位应采取防烟措施。","options":[{"value":"A","text":"封闭楼梯间","isCorrect":true},{"value":"B","text":"防烟楼梯间及其前室","isCorrect":false},{"value":"C","text":"消防电梯的前室","isCorrect":false},{"value":"D","text":"避难走道的前室","isCorrect":false},{"value":"E","text":"避难层、避难间","isCorrect":false}],"answer":"A","explanation":"P111,《建筑防火通用规范》(GB55037一2022)中规定,下列部位应采取防烟措施。(1)封闭楼梯间。(2)防烟楼梯间及其前室。(3)消防电梯的前室或合用前室。(4)避难层、避难间。(5)避难走道的前室,地铁工程中的避难走道。"},{"id":"mm-0594","type":"multi","question":"灭火器按结构形式不同,分为（）。","options":[{"value":"A","text":"手提式灭火器","isCorrect":true},{"value":"B","text":"推车式灭火器","isCorrect":false},{"value":"C","text":"投郑式灭火器","isCorrect":false},{"value":"D","text":"悬挂式灭火器","isCorrect":false},{"value":"E","text":"壁挂式灭火器","isCorrect":false}],"answer":"A","explanation":"灭火器分类方法:1按结构形式不同:分为手提式和推车式等。2按充装的灭火剂不同:分为水基型灭火器、干粉型灭火器、二氧化碳灭火器、洁净气体型灭火器等。3按驱动灭火剂的形式:分为贮气瓶式灭火器、贮压式灭火器等。"},{"id":"mm-0595","type":"multi","question":"机械加压送风系统主要由（）以及电气控制柜等组成。","options":[{"value":"A","text":"净化设备","isCorrect":false},{"value":"B","text":"送风机","isCorrect":true},{"value":"C","text":"风道","isCorrect":false},{"value":"D","text":"送风口","isCorrect":false},{"value":"E","text":"可开启外窗","isCorrect":false}],"answer":"B","explanation":"机械加压送风系统主要由送风机、风道、送风口以及电气控制柜等组成。“净化设备\"与机械加压送风系统并无关联,“可开启外窗\"属于自然通风系统的组件,而不是机械加压送风系统组成部件。因此,\"净化设备\"和\"可开启外窗\"应当排除。结合题意,本题应选送风机、风道、送风口3个选项。"},{"id":"mm-0596","type":"multi","question":"管网气体灭火系统的启动方式有（）。","options":[{"value":"A","text":"自动控制","isCorrect":true},{"value":"B","text":"手动控制","isCorrect":false},{"value":"C","text":"机械应急操作","isCorrect":false},{"value":"D","text":"电动控制","isCorrect":false},{"value":"E","text":"压力控制","isCorrect":false}],"answer":"A","explanation":"气体灭火系统按装配形式的不同,分为管网灭火系统和预制灭火系统(亦称无管网灭火装置)。管网气体灭火系统有自动控制、手动控制和机械应急操作三种启动方式。预制灭火系预制灭火系统具有自动和手动两种控制方式。结合题意,本题应选\"自动控制”、“手动控制”、“机械应急操作3项,其他项均可排除。"},{"id":"mm-0597","type":"multi","question":"情性气体灭火剂可以扑救（）。","options":[{"value":"A","text":"救灭火前可切断气源的气体火灾","isCorrect":true},{"value":"B","text":"液体火灾或固体火灾","isCorrect":false},{"value":"C","text":"石蜡、沥青等可熔化的固体火灾","isCorrect":false},{"value":"D","text":"成卷装或堆垛类的棉毛、织物、纸张等部分固体深位火灾","isCorrect":false},{"value":"E","text":"电气火灾","isCorrect":false}],"answer":"A","explanation":"惰性气体灭火剂可以扑救灭火前可切断气源的气体火灾、石蜡、沥青等可熔化的固体火灾、成卷装或堆垛类的棉毛、织物、纸张等部分固体深位火灾以及电气火灾。"},{"id":"mm-0598","type":"multi","question":"排烟系统的测试步骤为,触发同一防烟分区的两个独立的火灾探测器,核查排烟系统（）是否联动启动。","options":[{"value":"A","text":"电动挡烟垂壁","isCorrect":true},{"value":"B","text":"排烟口","isCorrect":false},{"value":"C","text":"排烟窗","isCorrect":false},{"value":"D","text":"排烟阀","isCorrect":false},{"value":"E","text":"排烟风机","isCorrect":false}],"answer":"A","explanation":"中级60页,触发同一防烟分区的两个独立的火灾探测器,核查排烟系统电动挡烟垂壁、排烟口、排烟窗、排烟阀、排烟风机是否联动启动。"},{"id":"mm-0599","type":"multi","question":"更换消防应急广播模块后,应检查模块的启动、切换功能,并待其功能正常后进行消防应急广播（）操作,观察2min,系统应处于正常监视状态。","options":[{"value":"A","text":"系统复位","isCorrect":true},{"value":"B","text":"自检","isCorrect":false},{"value":"C","text":"重新启动","isCorrect":false},{"value":"D","text":"待机","isCorrect":false},{"value":"E","text":"查询","isCorrect":false}],"answer":"A","explanation":"中级57页,功能正常后进行消防应急广播系统复位、自检操作,观察2min,系统应处于正常监视状态。"},{"id":"mm-0600","type":"multi","question":"集中火灾报警控制器主要包括:（）、输入/输出控制板、音响器件、网络接口组件、电源装置(含电池)、外壳等器件。","options":[{"value":"A","text":"显示板(含显示屏)","isCorrect":true},{"value":"B","text":"指示灯","isCorrect":false},{"value":"C","text":"开关和按钮","isCorrect":false},{"value":"D","text":"打印机","isCorrect":false},{"value":"E","text":"主板","isCorrect":false}],"answer":"A","explanation":"集中火灾报警控制器主要包括:显示板(含显示板示屏)、指示灯、开关和按钮、打印机、主板、输入/输出控制板、音响器件、网络接口组件、电源装置(含电池)、外壳等器件。"},{"id":"mm-0601","type":"multi","question":"建筑一般由基础、墙或柱、（）、窗等组成。","options":[{"value":"A","text":"楼板","isCorrect":true},{"value":"B","text":"地坪","isCorrect":false},{"value":"C","text":"楼梯","isCorrect":false},{"value":"D","text":"屋面","isCorrect":false},{"value":"E","text":"门","isCorrect":false}],"answer":"A","explanation":"建筑一般由基础、墙或柱、楼板、地坪、楼梯、屋面、门、窗等组成。"},{"id":"mm-0602","type":"multi","question":"常用火灾报警触发设备有（）。","options":[{"value":"A","text":"感烟探测器","isCorrect":true},{"value":"B","text":"感温探测器","isCorrect":false},{"value":"C","text":"手动火灾报警按钮","isCorrect":false},{"value":"D","text":"水力警铃","isCorrect":false},{"value":"E","text":"红外火焰探测器","isCorrect":false}],"answer":"A","explanation":"常用火实报警触发设备有感烟探测器、感温探测器、手动火灾报警按钮、红外火焰探测器等。"},{"id":"mm-0603","type":"multi","question":"消防工作的长期实践表明,具( )的特点。","options":[{"value":"A","text":"社会性","isCorrect":true},{"value":"B","text":"行政性","isCorrect":false},{"value":"C","text":"经常性","isCorrect":false},{"value":"D","text":"技术性","isCorrect":false},{"value":"E","text":"长期性","isCorrect":false}],"answer":"A","explanation":"根据《基础知识》新教材8页。消防工作的长期实践表明,其具有以下特点:社会性、行政性、经常性、技术性。"},{"id":"mm-0604","type":"multi","question":"室内消火栓管道必须穿过伸缩缝及沉降缝时,应采用（）等技术措施。","options":[{"value":"A","text":"套管","isCorrect":false},{"value":"B","text":"波纹管","isCorrect":true},{"value":"C","text":"法兰","isCorrect":false},{"value":"D","text":"补偿器","isCorrect":false},{"value":"E","text":"弯头","isCorrect":false}],"answer":"B","explanation":"中级p226,管道穿过墙体或楼板时应加设套管,套管长度不应小于墙体厚度或应高出楼面或地面50mmo，套管与管道的间隙应采用不燃材料，填管道管道必须穿过伸缩缝及沉降缝时,应采用波纹管和补偿器等技术措施。"},{"id":"mm-0605","type":"multi","question":"使用钳形接地电阻测试仪进行火灾自动报警系统接地电阻测试时,下列说法正确的是（）。","options":[{"value":"A","text":"钳形接地电阻测试仪开机后会进行自校准","isCorrect":true},{"value":"B","text":"校准完成后,测试仪如果处于电流测量模式,需要按\"Q\"切换到电阻测量模式","isCorrect":false},{"value":"C","text":"钳形接地电阻测试仪有辅助接地钉","isCorrect":false},{"value":"D","text":"在校准过程中,能张开钳头或钳住被测体","isCorrect":false},{"value":"E","text":"检测完毕后,需按规定做好记录","isCorrect":false}],"answer":"A","explanation":"中级教材298页,校准完成后,测试仪如果处于电流测量模式,需要按\"Q\"切换到电阻测量模式,排除B选项;数字接地电阻测试仪有辅助接地钉,排除C选项,在校准过程中,不能张开钳头或钳住被测体,排除D选项。"},{"id":"mm-0606","type":"multi","question":"自动喷水灭火系统是由（）等组件以及管道、供水设施等组成,能在发生火灾时喷水的自动灭火系统。","options":[{"value":"A","text":"洒水喷头","isCorrect":true},{"value":"B","text":"报警阀组","isCorrect":false},{"value":"C","text":"水流报警装置","isCorrect":false},{"value":"D","text":"火灾显示器","isCorrect":false},{"value":"E","text":"火灾报警控制器","isCorrect":false}],"answer":"A","explanation":"基础知识219页,自动喷水灭火系统是由洒水喷头、报警阀组、水流报警装置等组件以及管头、报警阀组、水流报警装置等组件以及管道、供水设施等组成,能在发生火灾时喷水的自动灭火系统。火灾显示器和火灾报警控制器属于火灾自动报警系统内容。"}]},{"name":"维保方向 · 判断题","type":"judge","questions":[{"id":"mj-0607","type":"judge","question":"地下室外消火栓应设置固定标识。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级P225,地下室外消火栓应设置永久性固定标识。"},{"id":"mj-0608","type":"judge","question":"湿式、干式系统维修作业前,应采取关闭相关区域阀门,调整消防水泵控制状态等管理措施,避免出现消防水泵意外启动。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级P108,维修作业前,应采取关闭相关区域阀门、调整消防水泵控制状态等措施,避免发生消防水泵意外启动。组件更换完成后,必须开展调试和验收工作,以保证系统完好有效。"},{"id":"mj-0609","type":"judge","question":"对电气元器件的清洁应使用吸尘器或软毛刷等工具,其他组件可使用潮湿的布进行擦拭。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级教材103页,对电气元器件的清洁应使用吸尘器或软毛刷等工具,其他组件可使用潮湿的的布进行擦试。"},{"id":"mj-0610","type":"judge","question":"水喷雾灭火系统不得用于扑救遇水能发生化学反应造成燃烧的火灾。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识p100页,水喷雾灭火系统不得用于扑救遇水能发生化学反应造成燃烧、爆炸的火灾,以及水雾会对保护对象造成明显损害的火灾。"},{"id":"mj-0611","type":"judge","question":"应急照明控制器主电源应设置明显的永久性标识,并与消防电源采用电源插头连接。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p234页,应急照明控制器主电源应设置明显的永久性标识,并应直接与消防电源连接，严禁使用电源插头;应急照明控制器与其外接备用电源之间应直接连接。"},{"id":"mj-0612","type":"judge","question":"对送风机的未端配电装置保养时,如发现线路接头处有氧化、锈蚀痕迹,应采取镀锡和涂抹凡士林等防潮、防锈措施。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能178页,2.送风机未端配电装置的保养(3)用软布将配电装置壳体、柜内设备和线路清洁干净,确保表面无污渍。如发现配电柜有水渍受潮现象,应用干软布擦拭干净,确保配电装置干燥后再通电。"},{"id":"mj-0613","type":"judge","question":"区域报警系统应由火灾探测器、手动火灾报警按钮、火灾声光警报器及火灾报警控制器等组成。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识82页,区域报警系统应由火灾探测器、手动火灾报警按钮、火灾声光警报器及火灾报警控制器等组成,系统中可包括消防控制室图形显示装置和指示楼层的区域显示器。"},{"id":"mj-0614","type":"judge","question":"进入主菜单界面,选择\"查看\"菜单,移动光标至\"历史事件”,可显示火警报警事件、联动历史事件、全部历史事件等情况。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级29页,进入主菜单界面,选择\"查看\"菜单,移动光标至\"历史事件\",可显示火警报警事件、联动历史事件、全部历史事件等情况,可通过左右方向键切换不同的信息界面。"},{"id":"mj-0615","type":"judge","question":"湿式系统喷头开启后管道先排气后充水再出水灭火,时效性低于干式系统。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"新教材中级技能97页,湿式系统喷头开启后立即出水灭火,干式系统喷头开启后管道先排气后充水再出水灭火,时效性低于湿式系统。"},{"id":"mj-0616","type":"judge","question":"涉电作业应注意安全,风机出现异常振动或声响、电动机反转时,应立即停止相关设备。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"本题考查考生对判断防烟排烟系统工作状态知识点的掌握情况。风机出现异常振动或声响、电动机反转时,应立即停止相关设备,严防事故发生。结合题意,本题正确。"},{"id":"mj-0617","type":"judge","question":"消防应急灯具按照工作方式分为集中控制型消防应急灯具和非集中控制型消防应急灯具。","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识117页,消防应急灯具按照工作方式分为持续型和非持续型灯具。"},{"id":"mj-0618","type":"judge","question":"劳动法调整的对象是指劳动关系以及与劳动关系有密切联系的其他关系。其中,劳动关系是我国劳动法调整的主要对象。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识194页知识点3,劳动法的调整对象是指劳动关系以及与劳动关系密切相关的其他社会关系。其中,劳动关系是我国劳动法调整的主要对象。"},{"id":"mj-0619","type":"judge","question":"消防水池的总蓄水有效容积大于1000m³时,应设置两座能独立使用的消防水池。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识105页,消防水池容积过大也会影响供水的可靠性,所以消防水池的总蓄水有效容积大于500 m³时,宜设两格能独立使用的消防水池;当大于1000m3时,应设置两座能独立使用的消防水池。"},{"id":"mj-0620","type":"judge","question":"疏散走道、人员密集的场所,不应低于3.0x。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"P116,《建筑防火通用规范》(GB55037-2022)中规定,建筑内疏散照明的地面最低水平照度应符合下列规定。1.疏散楼梯间、疏散楼梯间的前室或合用前室、避难走道及其前室、避难层、避难间、消防专用通道,不应低于10.0lx。 2.疏散走道、人员密集的场所,不应低于3.0lx。3.上述规定场所外的其他场所,不应低于1.0lx。"},{"id":"mj-0621","type":"judge","question":"湿式自动喷水灭火系统在准工作状态时,仅由稳压泵维持管道内充水的压力。","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级技能93页,湿式系统在准工作状态时,由消防水箱或稳压泵、气压给水设备等稳压设施维持管道内充水的压力。"},{"id":"mj-0622","type":"judge","question":"可以现场对火灾显示盘进行消音和复位操作。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级技能91页,更换或复位手动火灾报警按钮的启动零件,然后按下火灾报警控制器复位键,火灾显示盘复位,恢复正常监视状态。火灾显示盘面板上一般只有消音键,可以现场对火灾显示盘进行消音,复位要到火灾报警控制器上操作。"},{"id":"mj-0623","type":"judge","question":"干粉灭火系统按安装方式分为组合分配和单元独立两类。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识99页,干粉灭火系统按结构特点分为组合分配干粉灭火系统和单元独立干粉灭火系统。干粉灭火系统按安装方式分为半固定式干粉灭火系统和固定式干粉灭火系统。"},{"id":"mj-0624","type":"judge","question":"电气火灭监控器在接收到电气火灭监控探测器的报警信息后,经报警确认判断,将驱动安装在保护区域现场的声光警报装置发出声光警报。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识83页知识点8,电气火灾监控器在接收到电气火灾监控探测器的报警信息后,经报警确认判断,显示电气火灾监控探测器的位置信息,记录电气火灾监控探测器的报警时间,同时驱动安装在保护区域现场的声光警报装置,发出声光警报"},{"id":"mj-0625","type":"judge","question":"水灭火时覆盖隔离发挥着主要作用（）。","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识35页。用水扑灭一般固体物质的火灾,主要是通过冷却作用来实现的。"},{"id":"mj-0626","type":"judge","question":"点型可燃气体探测器一般用于通风良好的场所。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级技能37页。点型可燃气体探测器一般用于民用建筑,如厨房,不适合用于通风良好的场所。"},{"id":"mj-0627","type":"judge","question":"火灾自动报警系统采用专用接地电阻时,接地电阻值不应大于12Ω。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p61页,火灾自动报警系统采用专用接地电阻时,接地电阻值不应大于4Ω。"},{"id":"mj-0628","type":"judge","question":"采用减光率为0.4dB的减光片遭挡光路升尽可能靠近线型光束感烟火灾探测器的接收器,线型光束感烟火灾探测器不应发出火灾报警信号。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p36页,采用减光率为0.4dB的减光片(注意不是0.9dB,参考GB14003一2005《线型光束感烟火灾探测器》相关要求)遮挡光路并尽可能靠近线型光束感烟火灾探测器的接收器,线型光束感烟火灾探测器不应发出火灾报警信号。"},{"id":"mj-0629","type":"judge","question":"操作火灾自动报警系统总线手动控制单元时,进入集中控制当前的操作权限,当总线手动控制单元处于\"手动禁止\"时,应将其切换为\"手动允许”方式。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p31页,进入集中控制器当前的操作权限。当总线手动控制单元处于\"手动禁止\"时,应先将其切换为“手动允许\"方式。"},{"id":"mj-0630","type":"judge","question":"消防联动控制的电源部分应具有主电源和备用电源转换装置,当主电源断电时,需手动转换到备用电源,当主电源恢复时,能自动转换到主电源。 ( )","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防联动控制的电源部分应具有主电源和备用电源转换装置,当主电源断电时,能自动转换到备用电源,当主电源恢复时,能自动转换到主电源。结合题意,本题错误。"},{"id":"mj-0631","type":"judge","question":"水幕系统是由开式洒水喷头或水幕喷头、雨淋报警阀组或感温雨淋报警阀等组成,用于防火分隔或防护冷却的闭式系统。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"水幕系统是由开式洒水喷头或水幕喷头、雨淋报警阀组或感温雨淋报警阀等组成,用于防火分隔或防护冷却的开式系统。结合题意,本题错误。"},{"id":"mj-0632","type":"judge","question":"爆炸是一种物理变化。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"爆炸是一种极为迅速的物理或化学的能量释放过程,是在较短时间和较小空间内,能量从一种形式向另一种或几种形式转化并伴有强烈机械效应的过程。爆炸过程往往释放出大量能量,产生高温,并放出大量气体,在周围介质中造成高压的化学反应或状态变化,破坏性极强。"},{"id":"mj-0633","type":"judge","question":"建筑高度为30m的住宅楼应设置消防电梯。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"建筑高度>33m的住宅楼应设置消防电梯。"},{"id":"mj-0634","type":"judge","question":"当有两个及以上消防控制室时,各分消防控制室内消防设备之间可互相传输、显示状态信息,并能互相控制。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"当有两个及以上消防控制室时,各分消防控制室内消防设备之间可互相传输、显示状态信息,但不能互相控制。"},{"id":"mj-0635","type":"judge","question":"干式系统准工作状态时配水管道内充满用于后启动系统的有压气体,火灾发生时,喷头受热开放,配水管道排气充水后喷水灭火,系统响应速度比湿式系统慢。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"干式系统准工作状态时，配水管道内充满用于启动系统的有压气体,火灾发生时,喷头受热开放,配水管道排气充水后喷水灭火,系统响应速度比湿式系统慢。"},{"id":"mj-0636","type":"judge","question":"挡烟垂壁按挡烟部件的刚度性能可分为柔性挡烟垂壁和硬性挡烟垂壁。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"安装在建筑顶棚、梁或吊顶下,能在火灾时形成一定蓄烟空间的挡烟分隔设施。按安装方式可分为固定式挡烟垂壁和活动式挡烟垂壁;按挡烟部件的刚度性能可分为柔性挡烟垂壁和刚性挡烟垂壁。本题中的\"硬性挡烟垂壁“应改为刚性挡烟垂壁\"。结合题意,本题错误。"},{"id":"mj-0637","type":"judge","question":"建筑物内发生火灾时,排烟口、排烟窗或排烟阀开启的动作信号,作为排烟风机启动的联动触发信号。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑物内发生火灾时,排烟口、排烟窗或排烟阀开启的动作信号,作为排烟风机启动的联动触发信号。"},{"id":"mj-0638","type":"judge","question":"设置在消防电梯或疏散楼梯间前室内的非消防电梯,防火性能可略低于消防电梯的防火性能。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"设置在消防电梯或疏散楼梯间前室内的非消防电梯,防火性能不应低于消防电梯的防火性能。结合题意,本题错误。"},{"id":"mj-0639","type":"judge","question":"水喷雾灭火系统可用于扑救丙类液体火灾。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"水喷雾灭火系统可用于扑救固体物质火灾、丙类液体火灾、饮料酒火灾和电气火灾,并可用于可燃气体和甲、乙、丙类液体的生产、储存装置或装卸设施的防护冷却。"},{"id":"mj-0640","type":"judge","question":"手动状态时,当集中火灾报警控制器、消防联动控制器收到火灾报警信息时,不会联动启动声光报警、消防广播及所控制的现场消防设备。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"手动状态时,当集中火灾报警控制器、消防联动控制器收到火灾报警信息时,不会联动启动消防广广播及所控制的现场消防设备。"},{"id":"mj-0641","type":"judge","question":"电工作业项目应由具备相应等级职业资格的人员实施,作业中应严守操作规程。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"电工作业项目应由具备相应等级职业资格的人员实施,作业中应严守操作规程。"},{"id":"mj-0642","type":"judge","question":"应急照明控制器是指控制并显示非集中控制型消防应急灯具、应急照明集中电源、应急照明配电箱及相关附件等工作状态的装置。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"应急照明控制器是指控制并显示集中控制型消防应急灯具、应急照明集中电源、应急照明配电箱及相关附件等工作状态的装置。"},{"id":"mj-0643","type":"judge","question":"所谓程序,就是为解决某一问题而设计的一系列有序的指令或语句的集合。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"所谓程序,就是为解决某一问题而设计的一系列有序的指令或语句的集合。"},{"id":"mj-0644","type":"judge","question":"火灾自动报警系统控制器不可长时间处于备电工作状态,作状态,否则将导致蓄电池亏电损坏。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"火灾自动报警系统控制器不可长时间处于备电工作状态,否则将导致蓄电池亏电损坏。"},{"id":"mj-0645","type":"judge","question":"火火自动报警系统的工作状态可通过面板指示灯、提示音和文字等方式显示出来。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"火灾自动报警系统的工作状态主要包括:主/备电工作状态,火警指示状态,设备反馈指示状态,设备启动指示状态,消音状态,屏蔽状态,系统故障状态,主/备电故障状态,通信故障状态等。工作状态可通过面板指示灯、提示音和文字等方式显示出来。根据题意,本题正确。"},{"id":"mj-0646","type":"judge","question":"建筑面积为800m²的电影摄影棚应设置雨淋灭灭火系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑面积为800m²的电影摄影棚应设置雨淋灭火系统。"},{"id":"mj-0647","type":"judge","question":"在火灭多发季节或有重大活动保卫任务的单位,应组织全要素综合演练。单位内的有关部门应结合实际适时组织专项演练,宜每月组织开展一次疏散演练。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"在火灾多发季节或有重大活动保卫任务的单位,应组织全要素综合演练。单位内的有关部门应结合实际适时组织专项演练,宜每月组织开展一次疏散演练。"},{"id":"mj-0648","type":"judge","question":"排烟防火阀一般由阀体、叶片、执行机构和温感器等部件组成。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"排烟防火阀是安装在机械排烟系统的管道上,平时呈开启状态,火灾时当排烟管道内烟气温度达到280°C时关闭,并在一定时间内能满足漏烟量和耐火完整性要求,起隔烟阻火作用的阀门,一般由阀体、叶片、执行机构和温感器等部件组成。"},{"id":"mj-0649","type":"judge","question":"由于火灾警报装置、模块等为有源器件,对其更换维修时要格外小心,非专业人员不得随意拆卸火灾警报装置。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"由于火灾警报装置、模块等为有源器件,对其更换维修时要格外小心,非专业人员不得随意拆卸火灾警报装置。"},{"id":"mj-0650","type":"judge","question":"老年人照料设施的居室和休息室不应布置在地下或半地下。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"老年人照料设施的居室和休息室不应布置在地下或半地下。"},{"id":"mj-0651","type":"judge","question":"消防电梯应分别设置在不同防火分区内,且每个防火分区不应少于1台。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防电梯应分别设置在不同防火分区内,且每个防火分区不应少于1台。"},{"id":"mj-0652","type":"judge","question":"消防水泵接合器与消防通道之间不应设有妨碍消防车加压供水的障碍物。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防水泵接合器与消防通道之间不应设有妨碍消防车加压供水的障碍物。"},{"id":"mj-0653","type":"judge","question":"政府、部门、单位、公民4个方面都是消防工作的主体,只有各司其职、各负其责,才能保证消工作顺利开展。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"政府、部门、单位、公民4个方面都是消防工作的主体,只有各司其职、各负其责,才能保证消防工作顺利开展。"},{"id":"mj-0654","type":"judge","question":"需要火灾自动报警系统联动控制的消防设备,其联动触发信号应采用两个独立的报警触发装置报警信号的\"与\"逻辑组合。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"需要火灾自动报警系统联动控制的消防设备,其联动触发信号应采用两个独立的报警触发装置报警信号的\"与\"逻辑组合。"},{"id":"mj-0655","type":"judge","question":"客梯或货梯不可兼作消防电梯。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"客梯或货梯满足要求可以兼作消防电梯。结合题意,本题错误。"},{"id":"mj-0656","type":"judge","question":"《消防给水及消火栓系统技术规范》适用于新建、扩建、改建的工业、民用、市政等建设工程的消防给水及消火栓系统的设计、施工、验收和维护管理。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"《消防给水及消火栓系统技术规范》适用于新建、扩建、改建的工业、民用、市政等建设工程的消防给水及消火栓系统的设计、施工、验收和维护管理。"},{"id":"mj-0657","type":"judge","question":"若发现线型光束感烟火灾探测器的发射、接收窗口及反射器表面被灰尘或者油污污染,可以使用水及其他化学药剂除污。","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"1. 如果发现线型光束感烟火灾探测器的发射、接收窗口及反射器表面被灰尘或者油污污染,注意不要使用水(水难以清理油污)及其他化学药剂(可能损坏表面材料)除污。2. 具有报脏功能的探测器在报脏时应该及时清洁保养。没有报脏功能的探测器,应按产品说明书的要求进行清洁保养;产品说明书没有明确要求的,应每2年清洁或标定一次。3. 线型光束感烟火灾探测器每半年进行一次报警功能测试。"},{"id":"mj-0658","type":"judge","question":"当有两个及以上消防控制室时,主消防控制室应能显示所有火灾报警信号和联动控制状态信号,并应能控制重要的消防设备,并显示其状态信息。 ()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"当有两个及以上消防控制室时,主消防控制室应能显示所有火灾报警信号和联动控制状态信号,并应能控制重要的消防设备,并显示其状态信息。"},{"id":"mj-0659","type":"judge","question":"固定式泡沫灭火系统适用于单罐容量大于1000m³的甲、乙、丙类液体固定顶罐。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"固定式泡沫灭火系统适用于单罐容量大于1000m³的甲、乙、丙类液体固定顶罐。"},{"id":"mj-0660","type":"judge","question":"直接控制是指控制信号通过消防联动控制器本身的输出接点或模块直接作用到连接的消防电动装置,进而实现对受控消防设备的控制。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防联动控制器常用的联动控制方式主要有\"自动控制和手动控制”、“直接控制和间接控制”、“总线控制和直线控制\"等3种。直接控制是指控制信号通过消防联动控制器本身的输出接点或模块直接作用到连接的消防电动装置,进而实现对受控消防设备的控制。间接控制是指控制性生用购信号通过消防电气控制装置间接作用到连接的消防电动装置,进而实现对受控消防设备的控制。结合题意,本题正确。"},{"id":"mj-0661","type":"judge","question":"消防泡沫炮按泡沫液吸入方式分为自吸式消防泡沫炮和非自吸式消防泡沫炮两种。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防泡沫炮按泡沫液吸入方式分为自吸式消防泡沫炮和非自吸式消防泡沫炮两种。"},{"id":"mj-0662","type":"judge","question":"火灾报警控制器是消防联动控制系统的核心组件。 ()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防联动控制器是消防联动控制系统的核心组件。"},{"id":"mj-0663","type":"judge","question":"湿式自动喷水灭火系统适用于环境温度低于4°C或高于70°C的场所。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"干式自动喷水灭火系统适用于环境温度低于4°C或高于70°C的场所。"},{"id":"mj-0664","type":"judge","question":"对于一些重要联动设备(如消防泵组、防烟和排烟风机)的控制,除采用联动控制方式外,火灾报警控制器还应采用总线控制盘控制方式,实现直接手动控制。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"本题考香查考生多线控制盘的工作原理知识点的掌握情况。多线制控制盘也称作多线制手动控制盘或直接手动控制盘。为确保操作受控消防设备的可靠性,对于一些重要联动设备(如消防泵组、防烟和排烟风机)的控制,除采用联动控制方式外,火灾报警控制器还应采用多线控制盘控制方式,实现直接手动控制。由此可知,题于中的\"总线控制盘控制方式\"应表述为“多线控制盘控制方式\"。"},{"id":"mj-0665","type":"judge","question":"预作用自动喷水灭火系统是在准工作状态时配水管道内不充水,发生火灾时由火灾自动报警系统、充气管道上的压力开关联锁控制预作用装置和消防水泵,向配水管道供水的闭式系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"预作用自动喷水灭火系统是在准工作状态时，配水管道内不充水,发生火灾时由火灾自动报警系统、充气管道上的压力开关联锁控制预作用装置和消防水泵,向配水管道供水的闭式系统。"},{"id":"mj-0666","type":"judge","question":"干式自动喷水灭火系统报警阀以后的配水管道中(即系统侧)充有一定压力的气体,当出现大量泄漏时,可通过气压维持装置进行补压,以维持管网压力。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"根据《中级》老教材310页。干式自动喷水灭火系统报警阀以后的配水管道中(即系统侧)充有一定压力的气体,当出现少量泄漏时,可通过气压维持装置进行补压,以维持管网压力。"},{"id":"mj-0667","type":"judge","question":"手动报警按钮的设置应满足人员快速报警的要求,每个防火分区或楼层应至少设置1个手动火灾报警按钮。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p59,每个防火分区或楼层应至少设置一只手动火灾报警按钮,应设在明显和便于操作的部位;从一个防火分区内的任何位置到最邻近的手动火灾报警按钮的步行距离不应大于30m；手动火灾报警按钮宜设置在疏散通道或出入口处。"},{"id":"mj-0668","type":"judge","question":"火灾报警控制器/消防联动控制器运行模式处于\"自动允许\"时,可通过联动控制装置自动启动消防应急广播系统,进行消防应急广播。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"火灾报警控制器/消防联动控制器运行模式处于“自动允许“时,可通过联动控制装置自动启动消防应急广播系统,进行消防应急广播。"},{"id":"mj-0669","type":"judge","question":"通过直接手动控制单元手动停止送风机后,应恢复直接手动控制单元的\"手动禁止操作权限。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能155页,确认送风机电气控制柜处于\"自动运行模式,进入直接手动控制单元(也称多线控制盘)的\"手动允许\"操作权限,按下送风机启动按钮,送风机启动后,观察反馈信号指示灯是否点亮;再次按下送风机启动按钮,观察送风机是否停止,送风机停止后反馈信号指示灯应熄灭;恢复直接手动控制单元的“手动禁止\"操作权限。"},{"id":"mj-0670","type":"judge","question":"当通过温控释放装置启动自动排烟窗时,释放温度应大于环境温度30°C且小于100°C。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级书P150页,自动排烟窗可通过现场操作电气控制柜手动开启,也可以通过与火灾自动报警系统联动的方式启动。当通过温控释放装置启动时,释放温度大于环境温度30°C且小于100°C。"},{"id":"mj-0671","type":"judge","question":"打开机械加压送风系统中任一常闭式加压送风口,可以联锁启动加压送风机。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级149页,还可以通过以下方式启动加压送风机:(1)通过电气控制柜手动启动;(2)通过消防控制室多线控制盘远程启动;(3)打开系统中任一常闭式加压送风口,相应的加压送风机应能联动启动。"},{"id":"mj-0672","type":"judge","question":"固定式挡烟垂壁采用难燃材料制作,垂直安装在建筑顶棚、类建筑顶棚、梁或吊顶下。（）","options":[{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识50页,挡烟垂壁是指用不燃材料制成,垂直安装在建筑顶棚、梁或吊顶下,能在火灾时形成一定蓄烟空间的挡烟分隔设施。"},{"id":"mj-0673","type":"judge","question":"固体之间热量可以通过热对流传导。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识31页,热对流只能发生在流体(气体和液体)之中,是指流体中质点发生相对位移而引起的、由空间的一处向另一处传播热能的现象。"},{"id":"mj-0674","type":"judge","question":"干式自动喷水灭火系统准工作状态时配接的配水管道内充满用于启动系统的有压水。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"P089,知识点4:(2)干式自动喷水灭火系统(2)干式自动喷水灭火系统是在准工作状态时配水管道内充满用于启动系统的有压气体的闭式系统。"},{"id":"mj-0675","type":"judge","question":"应用软件是为满足用户不同领域、不同问题的应用需求而提供的软件。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识152页,应用软件是为满足用户不同领域、不同问题的应用需求而提供的软件。它可以拓宽计算机系统的应用领域,放大硬件的功能,包括用户可以使用的各种程序设计语言,以及用各种程序设计语言编制的应用程序的集合。"},{"id":"mj-0676","type":"judge","question":"接通电源,多线控制盘正常运行,绿色工作指示灯应处于常亮状态。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能79页,,接通电源,多线控制盘正常运行,绿色工作指示灯应处于常亮状态。"},{"id":"mj-0677","type":"judge","question":"常用的火灾监管设备有压力开关、水流指示器、水力警铃、信号蝶阀等。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级技能45页,常用火灾监管设备有压力开关、水流指示器、信号蝶阀等。"},{"id":"mj-0678","type":"judge","question":"只要具备可燃物、助燃物、引火源3个条件,必定会发生燃烧。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识17页,燃烧过程的发生和发展必须同时具备可燃物、助燃物、引火源3个必要条件,通常称为“燃烧三要素”。但要导致燃烧发生,不仅需要满足三要素条件，而且需要三者达到一定量的要求,并且存在相互作用的过程。"},{"id":"mj-0679","type":"judge","question":"侧向式防火卷帘、水平式防火卷帘在发生火灾时不能自动关闭,应用受到限制。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能131页,侧向式防火卷帘、水平式防火卷帘由于在发生火灾时不能自动关闭,应用受到限制。"},{"id":"mj-0680","type":"judge","question":"建筑材料的燃烧性能是指材料燃烧或遇火时所发生的一切化学变化。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识42页,建筑材料的燃烧性能是指材料燃烧或遇火时所发生的一切物理和化学变化,该性能由材料表面的着火性和火焰传播性、发热、发烟、炭化以及毒性生成物的产生等特性来衡量。"},{"id":"mj-0681","type":"judge","question":"线型光束感烟火灾探测器外壳外观的清洁保养中,应确认线型光束感烟火灾探测的产品标识是否清晰,表面是否有腐蚀、涂覆层脱落和起泡。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p45页,确认线型光束感烟火灾探测器或线型感温火灾探测器终端盒的产品标识是否清晰表面是否有腐蚀、涂覆层脱落和起泡。"},{"id":"mj-0682","type":"judge","question":"当线型感温火灾探测器监视区域的温度参数符合标准规定的报警条件时,探测器输出火灾报警信号,点亮火灾报警指示灯。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p25页,当线型感温火灾探测器监视区域的温度参数符合标准规定的报警条件时,探测器输出火灾报警信号,点亮火灾报警指示灯。"},{"id":"mj-0683","type":"judge","question":"消防电话总机可以组合安装在消防联动控制器的箱体内。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p22页,消防电话总机可以组合安装在火灾报警控制器/消防联动控制器的箱体内。"},{"id":"mj-0684","type":"judge","question":"使用风速仪测量送风口处风速值时,应保持风速仪风扇外壳标注气流方向与送风口气流相反的方向。 ()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p236页,使用风速仪测量送风口处风速值并记录,保持风速仪风扇外壳标注气流方向与送风口气流方向一致。"},{"id":"mj-0685","type":"judge","question":"封闭楼梯间应采取防烟措施。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"》新教材第111页。下列部位应设置防烟措施:(1)封闭楼梯间。(2)防烟楼梯间及其前室。(3)消防电梯的前室或合用避难走道前室。 (4) 避难层、避难间。(5)避难走道的前室地铁工程中的避难走道。"},{"id":"mj-0686","type":"judge","question":"集中火灾报警控制器不能间接接收来自火灾探测器及其他火灾报警触发器件的火灾报警信号,发出火灾报警声、光信号,指示火灾发生部位,记录火灾报警时间,并予以保持直至手动复位。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"火灾报警控制器应能直接或间接地接收来自火灾探测器及其他火灾报警触发器件的火灾报警光信号,指示火灾发信号,发出火灾报警声、信号,发出火灾报警声、光信号,指示火灾发生部位,记录火灾报警时间。"},{"id":"mj-0687","type":"judge","question":"湿式系统适用于环境温度低于4°C或高于70°C的场所。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"湿式系统适用于环境温度不低于4°CC且不高于70°CC的场所。"},{"id":"mj-0688","type":"judge","question":"室内消火栓栓口动压不应大于0.50MPa,当大于0.70MPa时必须设置减压装置。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"室内消火栓栓口动压和消防水枪充实水柱应符合哪些要求。室内消火栓栓口动压和消防水枪充实水柱是室内消火栓正常工作的基本保证。室内消火栓栓口动压不应大于0.50MPa;当大于0.70MPa时必须设置减压装置;高层建筑、厂房、库房和室内净空高度超过8m的民用建筑等场所,室内消火栓栓口动压不应小于0.35MPa,且消防水枪充实水柱应按13m计算;其他场所,消火栓栓口动压不应小于0.25MPa,且消防水枪充实水柱应按10m计算"},{"id":"mj-0689","type":"judge","question":"商业服务网点是指设置在住宅建筑的首层或首层及二层,每个分隔单元建筑面积不大于300m²的商店、邮政所、储蓄所、理发店等小型营业性用房。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"什么是商业服务网点?商业服务网点是指在住宅建筑的首层或首层及二层,每个分隔单元建筑面积不大于300平方的商店、邮政所、储蓄所、理发店等小型营业性用房。"},{"id":"mj-0690","type":"judge","question":"消防水泵接合器要求系统和分区标识清晰,配接阀门启闭状态正确,作业场地和环境正常。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"本题考查考生自动喷水灭火系统组件的准工作状态要求知识点的掌握情况。消防水泵接合器是指固定设置在建筑物外,用于消防车或机动泵向建筑物内消防给水系统输送消防用水和其他液体灭火剂的连接器具。自动喷水灭火系统组件的准工作状态要求消防水泵接合器系统和分区标识清晰,配接阀门启闭状态正确,作业场地和环境正常"},{"id":"mj-0691","type":"judge","question":"屏幕保护可以防止用户不在时,非授权用户看到屏幕上的内容,屏幕保护密码则是在用户从屏幕保护状态转换到运行状态时,需要输入的账户密码。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"屏幕保护可以防止用户不在时,非授权用户看到屏幕上的内容,屏幕保护密码则是在用户从屏幕保护状态转换到运行状态时,需要输入的账户密码。"},{"id":"mj-0692","type":"judge","question":"《气体灭火系统设计规范》术语和符号、设计要求、系统组件、操作与控制、安全要求等。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"《气体灭火系统设计规范》主要内容包括总则、术语和符号、设计要求、系统组件、操作与控制、安全要求等。"},{"id":"mj-0693","type":"judge","question":"对可燃气体报警控制器进行保养后,保养人员需要仔细检查并确保没有异物落入且遗留在机柜(壳)内、电器元件及线路中,检查完成后方可。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"对可燃气体报警控制器进行保养后,保养人员需要仔细检查并确保没有异物落入且遗留在机柜(壳)内、电器元件及线路中,检查完成后方可上电。"},{"id":"mj-0694","type":"judge","question":"同时设置火灾声警报器与消防应急广播时,两者应分时交替循环播放。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p73页,同时设置火灾声警报器与消防应急广播时,两者应分时交替循环播放。"},{"id":"mj-0695","type":"judge","question":"火灾自动报警系统中采用交流供电的各类控制，与指示类设备均应设置接地保护装置,接地保护装置的主要作用是利用接地体把剩余电流或雷电流快速地泄放到大地中。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p61页,火灾自动报警系统中采用交流供电的各类控制与显示类设备均应设置接地保护装置。接地保护装置的主要作用是利用接地体把故障电流或雷电流快速地泄放到大地中。"},{"id":"mj-0696","type":"judge","question":"泵组式细水雾灭火系统应具有自动、手动和机械应急操作控制方式。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识103页,泵组式细水雾灭火系统应具有自动、手动控制方式。"},{"id":"mj-0697","type":"judge","question":"消防联动控制器的电源部分应具有主电源和备用电源转换装置。当主电源断电时,需手动转换到备用电源;当主电源恢复时,能自动转换到主电源。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级技能6页。消防联动控制器的电源部分应具有主电源和备用电源转换装置。当主电源断电时,能自动转换到备用电源;当主电源恢复时,能自动转换到主电源。"},{"id":"mj-0698","type":"judge","question":"建筑高度为30m的住宅楼应设置灯光疏散指示标志。 （）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识115页(1)《建筑防火通用规范》(GB55037—2022) 中规定,除筒仓、散装粮中规定,除筒仓、散装粮食仓库和火灾发展缓慢的场所外,下列建筑应设置灯光疏散指示标志,疏散指示标志及其设置间距、照度应保证疏散路线指示明确、方向指示正确清晰、视觉连续。1)甲、乙、丙类厂房,高层丁、戊类厂房。2)丙类仓库,高层仓库。3)公共建筑。4)建筑高度大于27m的住宅建筑。5)除室内无车道且无人员停留的汽车外的其他汽车库和修车库。6)平时使用的人民防空工程。7)地铁工程中的车站、换乘通道或连接通道、车辆基地、地下区间内的纵向疏散平......"},{"id":"mj-0699","type":"judge","question":"末端试水装置(试水阀)平时应处于开启状态。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"未端试未端试水装置(试水阀)平时应处于关闭状态。"},{"id":"mj-0700","type":"judge","question":"建筑高度为30m的住宅,采用临时高压消防给水系统,其高位消防水箱的有效容积不应小于12m³。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识107页,临时高压消防给水系统的高位消防水箱的有效容积应满足初期火灾消防用水量的要求,并应符合以下6项规定。(1)一类高层公共建筑,不应小于36m³;但当建筑高度大于100m时,不应小于50m³;当建筑高度大于150m时,不应小于100m³。多层公共建筑、二类高层公共建筑和一类高层住宅,不应小于18m³;当一类高层住宅建筑高度超过100m时,不应小于36m³。二类高层住宅,不应小于12m³。(4)建筑高度大于21m的多层住宅,不应小于6m³。(5)工业建筑室内消防给水设计流量小于或等于25L/s时......"},{"id":"mj-0701","type":"judge","question":"管道最小管顶覆土应至少在冰冻线以下0.30m。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p225,埋地金属管道最小管顶覆土应按地面荷载、埋深荷载和冰冻线对管道的综合影响确定;管道最小管顶覆土不应小于0.70m,但当在机动车道下时管道最小管顶覆土应经计算确定,且不应小于0.90m;管道最小管顶覆土应至少在冰冻线以下0.30m。"},{"id":"mj-0702","type":"judge","question":"未端试水装直由试水阀、压力表、试水接头等组成。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"未端试水装置由试水阀、压力表、试水接头等组成。其作用是检验自动喷水灭火系统的可靠性,测试系统能否在开放一只喷头的最不利条件下可靠报警并正常启动,测试水流指示器、报警阀、压力开关、水力警铃的动作是否正常配水管道是否畅通,以及系统最不利点处的工作压力等,也可以检测干式系统和预作用系统的充水时间。"},{"id":"mj-0703","type":"judge","question":"图书或文物的珍藏库应设置火灾自动报警系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识83页,下列民用建筑或场所应设置火灾自动报警系统。1)商店建筑、展览建筑、财贸金融建筑、客运和货运建筑等类似用途的建筑。2)旅馆建筑。3 )建筑高度大于100m的住宅建筑。4)图书或文物的珍藏库,每座藏书超过50万册的图书馆,重要的档案馆。5)地市级及以上广播电视建筑、邮政建筑、电信建筑,城市或区域性电力、交通和防灾等指挥调度建筑。6)特等、甲等剧场,座位数超过1500个的其他等级的剧场或电影院,座位数超过2000个的会堂或礼堂,座位数超过3000个的体育馆。7)疗养院的病房楼,床位数不......"},{"id":"mj-0704","type":"judge","question":"对送风机进行保养前,应先断开主电源。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级177页,送风机的保养前,断开主电源,挂上安全标志牌,检查电动机接地是否良好。"},{"id":"mj-0705","type":"judge","question":"在雨淋系统中应设置充气和气压维持装置。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"P089,:知识点4:(2)干式自动喷水灭火系统采用干式报警阀组,并设置保持配水管道内气压的充气设施。干式自动喷水灭火系统属于闭式自动喷水灭火系统。P091,《基础知识》知识点8:(1)雨淋灭火系统属于开式自动喷水灭火系统。"},{"id":"mj-0706","type":"judge","question":"火灾显示盘按供电方式分为直流供电型和交流供电型。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"P086知点14:火灾显示盘按供电方式分为两类:直流供电型和交流供电型。"},{"id":"mj-0707","type":"judge","question":"更换防火卷帘手动按钮盒后,应测试手动按钮盒的上升、下降、停止功能是否正常。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p215页,更换防火卷帘手动按钮盒后,应测试手动按钮盒的上升、下降、停止功能是否正常。"},{"id":"mj-0708","type":"judge","question":"当防火门监控器处于手动控制状态时,常开式防火门不能通过消防联动控制器联动关闭。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p165页,当监控器处于手动控制状态时,常开式防火门不能通过消防联动控制器联动关闭。"},{"id":"mj-0709","type":"judge","question":"在湿式、干式系统中,联动控制方式仅在消防联动控制器处于自动状态时有效,若消防联动控制器处于手动状态,此种控制方式将无法实现。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p127页,湿式、干式系统中,联动控制方式仅在消防联动控制器处于自动状态时有效，若消防联动控制器处于手动状态,此种控制方式将无法实现。"},{"id":"mj-0710","type":"judge","question":"火灾发生时,干式系统喷头动作后,快速排气装置可以快速排出系统管网中的气体,使干式报警阀尽快动作,水源快速进入供水管网喷水灭火。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p83页,当确认火灾发生时,干式系统喷头动作后,快速排气装置可以快速排出系统管网中的气体,使干式报警阀尽快动作,水源快速进入供水管网喷水灭火。"},{"id":"mj-0711","type":"judge","question":"对于一些需要及时操作的受控消防设备,可以通过多线控制盘进行控制。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"对于一些需要及时操作的受控消防设备,可以通过总线控制盘进行控制。"},{"id":"mj-0712","type":"judge","question":"触电方式分为:单相触电,双相触电和三相触电。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"触电方式分为:单相触电,双相触电和跨步电压触电。结合题意,本题错误。"},{"id":"mj-0713","type":"judge","question":"闭式洒水喷头无热敏感释放机构,火灾时通过控制设备启动。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"闭式酒水喷头有热敏元件,火灾时靠达到动作动温度释放动作。如红色玻璃球喷头达到68C动作。"},{"id":"mj-0714","type":"judge","question":"实施主/备电切换时,双电源转换开关应处于自动控制状态,测试完成后恢复手动控制。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"实施主/备电切换时,双电源转换开关应处于手动控制状态,测试完成后恢复自动控制。"},{"id":"mj-0715","type":"judge","question":"细水雾灭火系统不适用于可燃固体深位火灾。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"细水雾灭火系统不适用于可燃固体深位火灾。"},{"id":"mj-0716","type":"judge","question":"火灾自动报警系统是以通过火灾早期探测和报警,向各类消防设备发出控制信号并接收设备反馈信号,进而实现预定消防功能为基本任务的一种自动消防设施。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"火灾自动报警系统是以通过火灾早期探测和报警,向各类消防设备发出控制信号并接收设备反馈信号,进而实现预定消防功能为基本任务的一种自动消防设施。"},{"id":"mj-0717","type":"judge","question":"建筑内设置消防电梯时,每个防火分区可供使用的消防电梯不应少于1部。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑内设置消防电梯时,每入防火分区可供使用的消防电梯不应少于1部。"},{"id":"mj-0718","type":"judge","question":"防火门按日常启闭状态可分为常闭式防火门和常常开式防火门。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"本题考查考生对防火门监控系统组成知识点的掌握情况。防火门按日常启闭状态可分为常闭式防火门和常开式防火门,建筑内经常有人通行处的防火门宜采用常开防火门,其他位置的防火门应采用常闭防火门。常开防火门应能在火灾时自行关闭。结合题意,本题正确"},{"id":"mj-0719","type":"judge","question":"不同生产厂家的火灾自动报警系统组件拆装方法并无差异。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"不同生产厂家的火灾自动报警系统组件拆装方法有所差异。结合题意,本题错误。"},{"id":"mj-0720","type":"judge","question":"重复启闭预作用系统扑灭火灾后能自动关闭报警阀停止喷水。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"重复启闭预作用系统扑灭火灾后能自动关闭报警阀停止喷水。"},{"id":"mj-0721","type":"judge","question":"燃烧产物的危害主要有毒性和减光性。())","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材22页。燃烧产物的危害主要有毒性和减光性。"},{"id":"mj-0722","type":"judge","question":"细水雾灭火系统按其应用方式分为瓶组式、泵组、泵组式及其他供水方式细水雾灭火系统。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"细水雾灭火系统按其应用方式分为：全没细水雾灭火系统和局部应用细水雾灭火系统。"},{"id":"mj-0723","type":"judge","question":"电气测量仪表按被测电流的性质主要分为直流表和交流表。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"电气测量仪表按被测电流的性质主要分为直流表和交流表。"},{"id":"mj-0724","type":"judge","question":"电压不但有大小而且有方向。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"电压不但有大小而且有方向。"},{"id":"mj-0725","type":"judge","question":"与火灾自动报警系统联动的防火卷帘两侧均应安装火灾探测器组和手动按钮盒。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"与火灾自动报警系统联动的防火卷帘两侧均应安装火灾探测器组和手动按钮盒。"},{"id":"mj-0726","type":"judge","question":"防烟系统可分为自然通风系统和机械加压送风系统。 ()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"本题考查考生对防烟系统的分类知识点的掌握情况。防烟系统可分为自然通风系统和机械加压送风系统。结合题意,本题正确。"},{"id":"mj-0727","type":"judge","question":"消防救援口应易于从室内和室外打开或破拆,采用玻璃窗时,应选用易于破碎的玻璃。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防救援口设置应符合哪些要求建筑外墙上便于消防救援人员出入的消防救援口,设置应符合下列规定。(1) 沿外墙的每个防火分区在对应消防救援操作面范围内设置的消防救援口不应少于2个。(2) 无外窗的建筑应每层设置消防救援口,有外窗的建筑应自第三层起每层设置消防救援口。(3) 消防救援口的净高度和净宽度均不应小于1.0m,当利用门时,净宽度不应小于0.8mo(4) 消防救援口应易于从室内和室外打开或破拆,采用玻璃窗时,应选用安全玻璃。(5)消防救援口应设置可在室内和室外识别"},{"id":"mj-0728","type":"judge","question":"当控制器内部、控制器与其连接的部件间发生故障时,控制器应能显示故障部位、故障原因等所有故障信息。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"当控制器内部、控制器与其连接的部件间发生故障时,控制器应能显示故障部位、故障类型等所有故障信息。根据题意,本题错误"},{"id":"mj-0729","type":"judge","question":"集中火灾报警控制器的自检功能会影响非自检部位、探测区和控制器本身的火灾报警功能。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"集中火灾报警控制器的自检功能也不能影响非自检部位、探测区和控制器本身的火灾报警功能。"},{"id":"mj-0730","type":"judge","question":"气体灭火系统按其应用方式分为组合分配和单元独立。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"气体灭火系统按应用方式分为:全淹没气体灭火系统和局部应用气体灭火系统"},{"id":"mj-0731","type":"judge","question":"炸药爆炸是化学爆炸。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材25页。常见的化学爆炸主要有各种炸药的爆炸及气体、液体蒸气、粉尘与空气混合后产生的爆炸。"},{"id":"mj-0732","type":"judge","question":"导体的电阻是客观存在的,是由本身决定的,与电阻本身的电阻率和尺寸大小有关。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"理想电阻元件是指能够消耗电能的元件,在一定的温度下,其电阻值与材料的长度成正比，与材料的电阻率成正比,与材料的截面积成反比。"},{"id":"mj-0733","type":"judge","question":"歌舞娱乐放映游艺场所布置在地下一层或地上四层及以上楼层时,每个房间的建筑面积不应大于200m²。 ()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材55页。歌舞娱乐放映游艺场所的布置和分隔应符合下列规定。(1)应布置在地下一层及以上且埋深不大于10m的楼层。(2)当布置在地下一层或地上四层及以上楼层时,每个房间的建筑面积不应大200m²。(3)房间之间应采用耐火极限不低于2.00h的防火隔墙分隔。(4)与建筑的其他部位之耐火极限不低于2.00h的防火间应采用防火门、市间应采用防火门、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.00的不燃性楼板分隔。当歌舞娱乐放映游艺场所设置在级木结构建筑中时,应布置在首层、二层或二层。"},{"id":"mj-0734","type":"judge","question":"操作火灾自动报警系统总线手动控制单元时,进集中控制器当前的操作权限,当总线手动控制/单元处于\"手动禁止\"时,应将其切换为\"手动允许\"方式。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p31页,进入集中控制器当前的操作权限当总线手动控制单元处于\"手动禁止\"时,应先将其切换为“手动允许\"方式。"},{"id":"mj-0735","type":"judge","question":"座位数为900个的半地下电影院应设置自动灭火系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识88页,除建筑内的游泳池、浴池、溜冰场可不设置自动灭火系统外,下列民用建筑、场所和平时使用的人民防空工程应设置自动灭火系统:位于地下或半地下且座位数大于800个的电影院、剧场或礼堂的观众厅。"},{"id":"mj-0736","type":"judge","question":"测试消防电话总机自检功能时,按下面板测试(自检)按或选择主菜单自检功能,消防电话总机自动录音启动,录音键指示灯常亮。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p76页,测试消防电话总机自动录音功能，在消防电话总机与消防电话分机通话时,观察消防电话总机显示通话时间并自动录音情况，录音键指示灯常亮。"},{"id":"mj-0737","type":"judge","question":"常开式防火门远程关闭后,需要现场手动将防火门栓恢复至开启状态。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p165页,再次按下启动按钮,设备运行灯应熄灭,在现场手动将关闭的常开式防火门恢复位至开启状态,防火门复位后再将监控器复位。"},{"id":"mj-0738","type":"judge","question":"摄像机属于输入设备。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识p145页,图像输入设备有:摄像机、扫描仪、传真机。"},{"id":"mj-0739","type":"judge","question":"附设在建筑内的消防控制室应采用防火门、防火窗、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.50h的楼板与其他部位分隔。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"附设在建筑内的消防控制室应采用防火门、防火窗、耐火极限不低于2.00h的防火隔墙和耐火极限不低于1.50h的楼板与其他部位分隔。"},{"id":"mj-0740","type":"judge","question":"联动控制不应影响连锁控制的功能。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"联动控制不应影响连锁控制的功能。"},{"id":"mj-0741","type":"judge","question":"机械加压送风系统打开后,楼层间形成\"防烟楼梯间压力<前室压力<走道压力<房间压力\"的递减压力分布,从而阻止烟气侵入,控制烟气蔓延。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"机械加压送风系统打开后,楼层间形成\"防烟楼梯间压力》前室压力 、走道压力、 房间压力\"的递减压力分布。"},{"id":"mj-0742","type":"judge","question":"手动火灾报警按钮是通过自动或手动方式产生火灾报警信号、启动火灾自动报警系统的器件。","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"手动火灾报警按钮是通过手动启动器件发出火灾报警信号的装置,结合题意,本题错误。"},{"id":"mj-0743","type":"judge","question":"火灾显示盘的信息显示应按火灾报警、故障、监管报警的顺序由高至低排列显示等级。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"火灾显示盘的信息显示应按火灾报警、监管报警、故障的顺序由高至低排列显示等级,高等级的信息应优先显示,低等级的信息显示不应影响高等级信息显示。"},{"id":"mj-0744","type":"judge","question":"选择线型定温火灾探测器,应保证其不动作温度符合设置场所的最高环境要求。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"选择线型定温火灾探测器,应保证其不动作温度符合设置场所的最高环境要求。"},{"id":"mj-0745","type":"judge","question":"消防水池容积越大也会供水可靠性越强。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防水池容积过大也会影响供水的可靠性,所以消防水池的总蓄水有效容积大于500m³时,宜设两格能独立使用的消防水池;当大于1000m³时,应设置两座能独立使用的消防水池。"},{"id":"mj-0746","type":"judge","question":"延迟器安装在湿式报警阀前的报警管路上,是可最大限度减少因水源压力波动或冲击而造成误报警的一种容积式装置。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"延迟器安装在湿式报警阀后的报警管路上,是可最大限度减少因水源压力波动或冲击而造成误报警的一种容积式装置。"},{"id":"mj-0747","type":"judge","question":"防火门按耐火性能分为甲级防火门、乙级防火门和丙级防火门。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"防火防火门按耐火极限分为甲级防火门、乙级防火门和丙级防火门。"},{"id":"mj-0748","type":"judge","question":"洒水喷头根据保护面积分为边墙型、下垂型和直立型三种。（）","options":[{"value":"正确","text":"正确用","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"洒水喷头根据保护面积不同分为标准覆盖面积洒水喷头、扩大覆盖面积洒水喷头两种"},{"id":"mj-0749","type":"judge","question":"当消防水池采用两路消防供水且在火灾情况下的连续补水能满足消防要求时,消防水池的有效容积应计算确定,但不应小于100m³,如果仅设有消火栓系统时不应小于50m³。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"当消防水池采用两路消防供水且在火灾情况下的连续补水能满足消防要求时,消防水池的有效容积应计算确定,但不应小于100m³,如果仅设有消火栓系统时不应小于50m³"},{"id":"mj-0750","type":"judge","question":"消防设备电源末端切换就是消防设备的两个电源相互切换,互为备用电源的一种供电形式。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防设备电源未端切换就是消防设备的两个电源相互切换,互为备用电源的一种供电形式。"},{"id":"mj-0751","type":"judge","question":"大数据是指数据量巨大,需要结合新的技术手段,来处理、分析、利用这些数据,挖掘其中的价值。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"大数据是指数据量巨大,需要结合新的技术手段来处理、分析、利用这些数据,挖掘其中的价值。"},{"id":"mj-0752","type":"judge","question":"发现阀门有漏水、锈蚀等情形的,应更换阀门密封垫,修理或者更换阀门,对锈蚀部位进行除锈处理。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"发现阀门有漏水、锈蚀等情形的,应更换阀门密封垫,修理或者更换阀门,对锈蚀部位进行除锈处理"},{"id":"mj-0753","type":"judge","question":"为了合理设计火灾自动报警系统,预防和减少火灾危害,保护人身和财产安全,制定《火灾自动报警系统施工及验收标准》。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"为了合理设计火灾自动报警系统,预防和减少火灾危害,保护人身和财产安全,制定《火灾自动报警系统设计规范》(GB50116)。结合题音木颠错意,本题错误"},{"id":"mj-0754","type":"judge","question":"特级防火卷帘可以应用于防火分隔部位,也可代替防火墙或防火隔墙。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"特级防火卷帘是指用钢质材料或无机纤维材料做帘面,用钢质材料做导轨、座板、夹板、门帽、箱体等,并配以卷门机和控制箱所组成的能符合耐火完整性、隔热性和防烟性能要求的卷帘。特级防火卷帘可以应用于防火分隔部位,局部代替防火墙或防火隔墙。结合题意,本题错误。"},{"id":"mj-0755","type":"judge","question":"双电源切换装置必须设置在消防泵组电气控制柜内。 ()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"双电源切换装置可设置在消防泵组电气控制柜附近,也可以设置在消防泵组电气控制柜内。结合题意,本题错误。结合题意,本题错误。"},{"id":"mj-0756","type":"judge","question":"疏散出口门应能在关闭后从任何一侧手动开启。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"疏散出口门应能在关闭后从任何一侧手动开启。"},{"id":"mj-0757","type":"judge","question":"防火卷帘按帘面数量可分为单帘面防火卷帘、双帘面防火卷帘和多帘面防火卷帘。","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"本题考查考生对手动、机械方式释放防火卷帘知识点的掌握情况。防火卷帘按帘面数量可分为单帘面防火卷帘和双帘面防火卷帘,而不是“多帘面防火卷帘\"。单帘面防火卷帘主要有钢质钢质特级防火卷防火卷帘、水雾式(汽雾式)钢质特级防火卷防火卷帘；双帘主要有无机特级防火卷帘。结合题意,本题错误。"},{"id":"mj-0758","type":"judge","question":"职业道德具有自我约束、控制的特征。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材3页。(3) 自律性。职业道德具有自我约束、控制的特征。"},{"id":"mj-0759","type":"judge","question":"检查水流指示器时若发现有异物、杂质等卡阻浆片的,应及时清除。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"检查水流指示器,发现有异物、杂质等卡阻浆片的,及时清除。根据题意,本题正确。"},{"id":"mj-0760","type":"judge","question":"消防电话总机能同时呼叫至少两部消防电话分机。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防电话总机能同时呼叫至少两部消防电话分机。"},{"id":"mj-0761","type":"judge","question":"接线检查应在消防电话总机通电状态下进行。","options":[{"value":"正确","text":"正确用","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"接线检查应在消防电话总机断电状态下进行。"},{"id":"mj-0762","type":"judge","question":"消防专用电话网络应为独立的消防通信系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防专用电话网络应为独立的消防通信系统。"},{"id":"mj-0763","type":"judge","question":"建筑高度大于250m的民用建筑应接入城市消防远程监控系统。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑高度大于250m的民用建筑应接入城市消防远程监控系统。"},{"id":"mj-0764","type":"judge","question":"消防广播能自动检查本机音响器件、面板所有指示灯和显示器的功能。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防应急广播的基本功能包括应急广播功能、故障报警功能、自检功能、电源功能。自检功能中消防应急广播能手动检查本机音响器件、面板所有指示灯和显示器的功能。是手动检香不是自动检查。结合题意,本题错误。"},{"id":"mj-0765","type":"judge","question":"消防联动控制器通过接收火灾报警控制器发出的火灾报警信息,按预设逻辑对建筑中设置的自动消防系统(设施)进行联动控制。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防联动控制器通过接收火灾报警控制器发出的火灾报警信息,按预设逻辑对建筑中设置的生自动消防系统(设施)进行联动控制。"},{"id":"mj-0766","type":"judge","question":"消防水泵有自动停泵的控制功能。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防水泵不设自动停泵的控制功能。"},{"id":"mj-0767","type":"judge","question":"集中火灾报警控制器应能检查设备本身的火灾报警功能,且在自检期间,不受其控制的外接设备和输出接点均不应动作。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"集中火灾报警控制器应能检查设备本身的火灾报警功能,且在自检期间,受其控制的外接设应备和输出接点均不应动作。"},{"id":"mj-0768","type":"judge","question":"按照火灾事故所造成的灾害损失程度,火灾分为重大火灾、较大火灾和一般火灾3个等级。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"根据《基础知识》新教材28页。按照火灾事故所造成的灾害损失程度,火灾分为特别重大火灾、重大火灾、较大火灾和一般火灾4个等级。"},{"id":"mj-0769","type":"judge","question":"消防控制室\"两屏三器两柜\"中的\"两屏\"指的是火灾监视屏、图形显示屏。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防控制室“两屏三器两柜“中的“两屏“指的是视频监控屏、图形显示屏。"},{"id":"mj-0770","type":"judge","question":"区域控制器和集中控制器之间应能相互收、发相关信息和/或指令。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《中级》老教材第5页。系统兼容功能。区域控制器和集中控制器之间应能相互收、发相关信息和/或指令。"},{"id":"mj-0771","type":"judge","question":"消防增(稳)压设施按所服务的系统可分为消火栓用、自动喷水灭火系统用和消火栓与自动喷水灭火系统合用等。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防增(稳)压设施按所服务的系统可分为消火栓用、自动喷水灭火系统用和消火栓与自动喷水灭火系统合用等。"},{"id":"mj-0772","type":"judge","question":"烟囱效应是造成烟气向上蔓延的主要因素。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材32页。在火灾过程中,烟囱效应是造成烟气向上蔓延的主要因素。"},{"id":"mj-0773","type":"judge","question":"集中火灾报警控制器的电源部分应具有主电源和备用电源转换装置。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"集中火灾报警控制器的电源部分应具有主电源和备用电源转换装置。"},{"id":"mj-0774","type":"judge","question":"氟蛋白泡沫灭火剂可用于液下喷射灭火,也可以与干粉灭火剂联用。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"氟蛋白泡沫灭火剂可用于液下喷射灭火,也可以与干粉灭火剂联用。"},{"id":"mj-0775","type":"judge","question":"建筑高度大于24m的单层体育馆属于高层建筑。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"根据《基础知识》新教材39页。对于有些单层建筑,如体育馆、高大的单层厂房等,因为具有相对便利的疏散和扑救条件,虽然建筑高度有相对便利的疏散和扑救条件,虽然建筑高度大于24m,但不划分为高层建筑。"},{"id":"mj-0776","type":"judge","question":"设直在商场四层的游艺场所,应采取排烟等烟气控制措施。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材第112页。除不适合设置排烟设施的场所、火灾发展缓慢的场所可不设置排烟设施外,工业与民用建筑的下列场所或部位应采取排烟等烟气控制措施。6)设置在地下或半地下、地上第四层及以上楼层的歌舞娱乐放映游艺场所,设置在其他楼层且房间总建筑面积大于100m²的歌舞娱乐放映游艺场所。"},{"id":"mj-0777","type":"judge","question":"建筑耐火等级是由组成建筑物的墙、柱、楼板、屋顶承重构件和吊顶等主要构件的燃烧性能和而耐火极限决定的,分为一、二、三、四级。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑耐火等级是由组成建筑物的墙、柱、楼板、屋顶承重构件和吊顶等主要构件的燃烧性能和耐火极限决定的, 分为一、 二、 三、 四级。"},{"id":"mj-0778","type":"judge","question":"火灾蔓延的主要方式为热传导、热对流。 ( )","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材31页。火灾蔓延通过热传播进行,主要方式为热传导、热辐射和热对流。结合题意,本题正确。"},{"id":"mj-0779","type":"judge","question":"线型火灾探测器是指连续探测某一路线周围火灾参数的火灾探测器,主要分为线型感烟火灾探测器和线型感温火灾探测器等类型。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"线型火灾探测器是指连续探测某一路线周围火灾参数的火灾探测器,主要分为线型感烟火灾探测器和线型感温火灾探测器等类型。"},{"id":"mj-0780","type":"judge","question":"报警阀组是使水能够自动单方向流入喷水系统配水管道同时进行报警的阀组。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"报警阀组是湿式、干式自动喷水灭火系统的重要组成部件。报警阀组是使水能够自动单方向流入喷水系统配水管道同时进行报警的阀组。"},{"id":"mj-0781","type":"judge","question":"当发生故障时,消防联动控制器应发出与火灾报警信号有明显区别的故障声、光信号。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"当发生故障时,消防联动控制器应发出与火灾报警信号有明显区别的故障声、光信号。"},{"id":"mj-0782","type":"judge","question":"应急照明控制器应设置在消防控制室内或有人值班的场所。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"应急照明控制器应设置在消防控制室内或有人值班的场所。"},{"id":"mj-0783","type":"judge","question":"风机长时间运转时,应确保相应区域的送风(排(排烟)口处于开启状态。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"风机长时间运转时,应确保相应区域的送风(排烟)口处于开启状态。"},{"id":"mj-0784","type":"judge","question":"消防设施操作员是为水平评价类职业资格。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防设施操作员是准入类职业资格。"},{"id":"mj-0785","type":"judge","question":"按照燃烧发生瞬间的特点,燃烧可分为起火和爆炸两种类型。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》》新教材17页。按照燃烧发生瞬间所具有特点的不同,燃烧可分为起火和爆炸两种类型。"},{"id":"mj-0786","type":"judge","question":"地下室是指房间地平面低于室外设计地平面的平均高度大于该房间平均净高1/2的建筑。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"地下室是指房间地平面低于室外设计地平面的平均高度大于该房间平均净高1/2的建筑。"},{"id":"mj-0787","type":"judge","question":"防火卷帘卷门机上设有手动拉链,可通过人工拉动拉链控制卷帘升降。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"防火卷帘卷门机上设有手动拉链,可通过人工拉动拉链控制卷帘升降。"},{"id":"mj-0788","type":"judge","question":"防火分区是指在建筑内部采用防火墙、楼板及其他防火分隔设施分隔而成,能在一定时间内防止火灾向同一建筑的其余部分蔓延的局部空间。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"防火分区是指在建筑内部采用防火墙、楼板及其他防火分隔设施分隔而成,能在一定时间内防止火灾向同一建筑的其余部分蔓延的局部空间。"},{"id":"mj-0789","type":"judge","question":"在保养湿式、干式自动喷水灭火系统时,应检查系统各个控制阀门,发现铅封损坏或者锁链未固定在规定状态的,及时更换铅封,并调整锁链至规定的固定状态。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"保养方法消防设施维护保养人员应根据维护保养计划,在规定的周期内对前述项目分别实施保养。保养应结合外观检查和功能测试进行,通常采用清洁、紧固、调整、润滑的方法。对电气元器件的清洁应使用吸尘器或软毛刷等工具,其他组件可使用不太湿的布进行擦试。对损坏件应及时维修或更换。(1)阀门1)检查系统各个控制阀门,发现铅封损坏或者锁链未固定在规定状态的,及时更换铅封,并调整锁链至规定的固定状态。发现阀门有漏水、锈蚀等情形的,更换阀门密封垫,修理或者更换阀门,对锈蚀部位进行除锈处理。启闭不灵活的,进行润滑处理。2)检查室外......"},{"id":"mj-0790","type":"judge","question":"计算机系统运算和控制核心,信息处理、程序运行的最终执行单元是中央处理器,简称GPU。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中央处理器(CPU)作为计算机系统的运算和控制核心,是信息处理、程序运行的最终执行单元,主要由控制器和运算器两部分组成。控制器是计算机的指挥中心,主要作用是控制管理计算机系统,它按照程序指令的操作要求向计算机的各个部分发出控制信号,使整个计算机协调一致地工作。运算器可以完成各种运算和处理,如完成各种算术运算和逻辑运算以及移位、比较等操作。"},{"id":"mj-0791","type":"judge","question":"蓄电池是指经过放电后,不能用一般的充电方法使其复原而继续使用的电池,也叫一次电池。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"原电池是指经过放电后,不能用一般的充电方法使其复原而继续使用的电池,也称一次电池。蓄电池是指可以通过充电的方法使两极活性物质复原而可再次放电的电池,也称二次电池。"},{"id":"mj-0792","type":"judge","question":"建筑之间的防火间距应保证任意一侧建筑外墙受到的相邻建筑火灾辐射热强度均低于其临界引燃辐射热强度。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑之间的防火间距应保证任意一侧建筑外墙受到的相邻建筑火灾辐射热强度均低于其临界引燃辐射热强度。"},{"id":"mj-0793","type":"judge","question":"防火门电动闭门器是使常开防火门保持打开状，在收到指令后释放防火门使其关闭,并将本身的状态信息反馈至防火门监控器的电动装置。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"防火门电动闭门器是能够在收到指令后将处于打开状态的防火门关闭,并将其状态信息反馈至防火门监控器的电动装置。防火门电磁释放器是使常开防火门保持打开状态,在收到指令后释放防火门使其关闭,并将本身的状态信息反馈至防火门监控器的电动装置。"},{"id":"mj-0794","type":"judge","question":"气体灭火系统按装配形式不同分为管网灭火系统和预制灭火系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"气体灭火系统按装配形式不同分为管网灭火系统和预制灭火系统。所以本题正确"},{"id":"mj-0795","type":"judge","question":"消防水泵控制柜应采取防止被水淹没的措施。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p102,表2-3-2消防泵组电气控制柜的保养内容和技术要求:控制柜防止被水淹没的措施完好。"},{"id":"mj-0796","type":"judge","question":"一台集中火灾报警控制器(联动型)可以设置多个总线控制盘。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能73页,一台集中火灾报警控制器(联动型)可以设置多个总线控制盘。总线控制盘为启动和停止受控消防设备提供了一种便捷的手动操作方式,可以代替烦琐的菜单操作。"},{"id":"mj-0797","type":"judge","question":"当自动喷水火火系统电气控制柜的手/自动转换开关置于\"自动\"时,消防控制室(盘)可自动启动水泵或远程手动启动水泵,并远程停止水泵。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能94页,1.消防泵组电气控制柜的功能(4)手动/自动转换功能转换开关在自动状态时,消防控制室(盘)可自动启动水泵或远程手动启动水泵,并远程停止水泵。在手动状态时,现场通过电气控制柜启停按钮操作水泵启动、停止。"},{"id":"mj-0798","type":"judge","question":"对送风机的末端配电装置保养时,如发现线路接头处有氧化、锈蚀痕迹,应采取镀锡和涂抹凡士林等防潮、防锈措施。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"对送风机的未端配电装置保养时,如发现线路接头处有氧化、锈蚀痕迹,应采取镀锡和涂抹锈蚀痕迹,应采取镀锡和涂抹凡士林等防潮、防锈措施。"},{"id":"mj-0799","type":"judge","question":"如防火卷帘的温控释放装置未自动动作,还可以通过人工手动拉动温控释放装置的手动速放装置(拉环),使温控释放器动作,防火卷帘依靠自重下降。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能168页,使温控释放装置周围温度达到(73±0.5)°C 查看温控释放装置是否动作,防火卷帘是否靠自重下降至完全关闭状态。还可以通过人工手动拉动温控释放装置的手动速放装置(拉环),使温控释放器动作防火卷帘依靠自重下降。"},{"id":"mj-0800","type":"judge","question":"风机电气控制柜的保养周期是每半年一次。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级171页,风机电气控制柜的保养周期是每季度一次。"},{"id":"mj-0801","type":"judge","question":"复制文件是将文件复制一份副本后,将副本另存到其他位置。移动文件是将文件从原来位置搬到其他位置。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识337页,复制文件是将文件复制一份副本后,将副本另存到其他位置。移动文件是将文件从原来位置搬到其他位置。"},{"id":"mj-0802","type":"judge","question":"由于人员能够进入水塔内部进行维修工作,故水塔属于建筑物。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识37页,构筑物是指人们不能直接在内部进行生产和生活,为工程技术需要而设置的建筑,如水塔、烟、堤坝等。"},{"id":"mj-0803","type":"judge","question":"消火栓系统的联动测试方法为,依据消防设备联动控制逻辑设计文件要求触发报警装置,核查消火栓泵是否联动启动。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p60页,消火栓系统的联动测试方法:依据消防设备联动控制逻辑设计文件要求触发报警装置,核香查消火栓泵是否联动启动。"},{"id":"mj-0804","type":"judge","question":"当建筑内梁突出顶棚的高度超过0.6m时,被梁隔断的每个梁间区域应至少设置一只探测器。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p58页,当建筑内梁突出顶棚的高度超过0.6m时,被梁隔断的每个梁间区域应至少设置一只探测器。"},{"id":"mj-0805","type":"judge","question":"获取送风口风速一般采用多点位测量取平均值的方法。 （）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p236页,送风口风速获取一般采用多点位测量取平均值的方法。"},{"id":"mj-0806","type":"judge","question":"组装式水泵接合器的安装中,止回阀的安装方向应使消防用水能从水泵接合器进入系统。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p227页,组装式消防水泵接合器的安装应按接口、本体、连接管、止回阀、安全阀、放空管、控制阀的顺序进行,止回阀的安装方向应使消防用水能从水泵接合器进入系统。"},{"id":"mj-0807","type":"judge","question":"冬季,室外消火栓排水阀堵塞容易造成余水结冰,从而导致室外消火栓无法开启。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p188页,表3-4-2室外消火栓系统的维修内容和维修方法。冬季如因排水阀堵塞导致余水结冰无法开启,应拆开疏通排水阀,做好防冻排水措施。"},{"id":"mj-0808","type":"judge","question":"二氧化碳灭火剂的灭火作用主要在于室息,其次是冷却。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知识p125页,二氧化碳灭火剂的灭火作用主要在于室息,其次是冷却。"},{"id":"mj-0809","type":"judge","question":"只要具备可燃物、助燃物、引火源3个条件,必定会发生燃烧。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"基础知识17页,燃烧过程的发生和发展必须同时具备可燃物、助燃物、引火源3个必要条件,通常称为“燃烧三要素\"。但要导致燃烧发生,不仅需要满足三要素条件,而且需要 三者达到一定量的要求,并且存在相互作用的过程。"},{"id":"mj-0810","type":"judge","question":"火灾探测器根据火灾特征参数的不同,可分为点型火灾探测器和线型火灾探测器。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"火灾探测器根据其探测火灾特征参数的不同,可以分为感温、感烟、感光、气体、复合五种基本类型。"},{"id":"mj-0811","type":"judge","question":"电气设备发生火灾可以用干粉灭火剂、二氧化碳、二氧化碳灭火剂灭火。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"电气设备发生火灾可以用干粉灭火剂、二氧化碳灭火剂灭火。"},{"id":"mj-0812","type":"judge","question":"消防电话总机无法显示每部分机或电话插孔的位置。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防电话总机应能与所有消防电话分机、电话插孔之间互相呼叫与通话,并显示每部分机或电话适插孔的位置。结合题意,本题错误电话插孔的位置。结合题意,本题错误。"},{"id":"mj-0813","type":"judge","question":"补气式消防稳压设施的气压罐内不设胶囊,使用时气、水共存。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防增(稳)压设施按稳压工作形式可分为胶囊式消防稳压设施、补气式消防稳压设施、消防无负压(叠压)稳压设施。其中,胶囊式消防稳压设施的气压罐内设有胶囊,使用时气、水分离;补气式消防稳压设施的气压罐内不设胶囊,使用时气、水共存;无负压(叠压)稳压设施直接串接到有压管网上取水,能有效利用其管网压力并且不产生负压危害。结合题意,本题正确。"},{"id":"mj-0814","type":"judge","question":"气溶胶火火剂适用于扑救固体表面火灾,以及通信机房、电子计算机房、电缆隧道(夹层、井)及自备发电机房等防护区火灾。( )","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"气溶胶灭火剂适用于扑救固体表面火灾,以及通信机房、电子计算机房、电缆隧道(夹层、井)及自备发电机房等防护区火灾。"},{"id":"mj-0815","type":"judge","question":"更换防火门电动闭门器滑槽时,可以采用不同规格型号和性能参数的产品代替。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p210,更换防火门电动闭门器滑槽比对核查新换件规格型号和性能参数,应与待换件匹配或一致。"},{"id":"mj-0816","type":"judge","question":"防火插销应安装在双扇门或多扇门相对固定一侧的门扇上。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"防火插销应安装在双扇门或多扇门相对固定一的完上侧的门扇上。"},{"id":"mj-0817","type":"judge","question":"一般来说爆炸下限越低或爆炸极限范围越大,可燃物的火灾爆炸危险性就越大。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"一般来说爆炸下限越低或爆炸极限范围越大，可燃物的火灾爆炸危险性就越大。"},{"id":"mj-0818","type":"judge","question":"集中报警系统适用于不仅需要报警,同时需要联动自动消防设备,且只设置一台具有集中控制功能的火灾报警控制器和消防联动控制器的保护对象。 ()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"火灾自动报警系统有区域报警系统、集中报警系统和控制中心报警系统三种形式,各自有不同的适用范围。(1)区域报警系统适用于仅需要报警、不需要联动自动消防设备的保护对象。(2)集中报警系统适用于不仅需要报警同时需要联动自动消防设备,且只设置一台具有集中控制功能的火灾报警控制器和消防联动控制器的保护对象。(3)控制中心报警系统适用于设置两个及以上消防控制室的保护对象,也适用于已设置两个及以上集中报警系统的保护对象。"},{"id":"mj-0819","type":"judge","question":"气体可燃物的燃烧速率大于固体和液体。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材21页。可燃气体的燃烧不需像固体、液体那样经过熔化、分解、蒸发等过程,而是在常温常压下就能与氧化剂相互混合扩散,当混合气体达到一定浓度后,遇到引火源即可发生燃烧或爆炸,因此,可燃气体的燃烧速率大于固体和液体的。"},{"id":"mj-0820","type":"judge","question":"激光光束线型感烟火灾探测器分为对射型和反射型两种。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"红外光束线型感烟火灾探测器又分为对射型和反射型两种。结合题意,本题错误。"},{"id":"mj-0821","type":"judge","question":"未端试水装置(试水阀)，平时应处于开启状态。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"本题考查考生对湿式、干式自动喷水灭火系统的主要组成知识点的掌握情况。未端试水装置由试水阀、压力表、试水接头等组成,其作用是检验自动喷水灭火系统的可靠性,测试系统能否在开放一只喷头的最不利条件下可靠报警并正常启动,测试水流指示器、报警阀、压力开关、水力警铃的动作是否正常,配水管道是否畅通,以及系统最不利点处的工作压力等,也可以检测于式系统和预作用系统的充水时间。试水阀平时应处于关闭状态,只有在测试时才会开启。结合题意,本题错误。"},{"id":"mj-0822","type":"judge","question":"消防控制中心或值班室等地点应设置显示消防水池 (水箱)水位的装置,同时应有最高和最低报报警水位。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"消防控制中心或值班室等地点应设置显示消防水池(水箱)水位的装置,同时应有最高和最低报警水位。"},{"id":"mj-0823","type":"judge","question":"如果\"故障\"指示灯处于黄色常亮状态,表示多线控制盘功能处于正常状态。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"本题考查多线控制盘的操作方法知识点的掌握情况。如果\"故障\"指示灯处于熄灭状态,表示多线控制盘功能处于正常状态;如果\"故障\"指示灯处于黄色常亮状态,表示多线控制盘功能处于异常状态,而不是“正常状态”。结合题意,本题错误。"},{"id":"mj-0824","type":"judge","question":"设置线型感温火灾探测器的场所有联动要求时,宜采用两只不同火灾探测器的报警信号组合。","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"设置线型感温火灾探测器的场所有联动要求时,宜采用两只不同火灾探测器的报警信号组合。（）"},{"id":"mj-0825","type":"judge","question":"具有多通道的线型感温火灾探测器应可指示出报警通道。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p25页,具有多通道的线型感温火灾探测器应指示出报警通道，并保持至复位。"},{"id":"mj-0826","type":"judge","question":"防火门监控器应有防火门故障状态总指示灯。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"防火门监控器应有防火门故障状态总指示灯,防火门处于故障状态时,该指示灯应点亮,并发出声光报警信号。声信号的声压级(正前方1m处)应为65dB~85dB;故障声信号每分钟至少提示1次,每次持续时间应为1s~3s。结合题意,本题正确。"},{"id":"mj-0827","type":"judge","question":"有大量粉尘、水雾滞留的场所宜选择线型光束感烟火灾探测器。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"1. 线型光束感烟火灾探测器:(1)无遮挡的大空间或有特殊要求的房间,宜选择线型光束感烟火灾探测器。(2)符合下列条件之一的场所,不宜选择线型光束感烟火灾探测器:1)有大量粉尘、水雾滞留的场所。2)可能产生蒸气和油雾的场所。3)在正常情况下有烟滞留的场所。4)固定探测器的建筑结构由于振动等原因会产生较大位移的场所。"},{"id":"mj-0828","type":"judge","question":"在背景环境噪声为50dB场所,利用声级计测试该场所火灾声警报器的声压级为60dB(A计权),则判定该场所的声警报器设置符合规定。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p66页,此外,在使用声级计测量火灾声警报器发出的警报信号时,至少在一个方向上3m处的声压级应高于背景噪声15dB,且不应低于60dB。"},{"id":"mj-0829","type":"judge","question":"未端试水装置由试水阀、压力表、试水接头等组()成。 ()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"未端试水装置由试水阀、压力表、试水接头等组成。其作用是检验自动喷水灭火系统的可靠性,测试系统能否在开放一只喷头的最不利条件下可靠报警并正常启动,测试水流指示器、报警阀、压力开关、水力警铃的动作是否正常，配水管道具不畅通，以及系统最不利点处的工作压力等,也可以检测干式系统和预作用系统的充水时间。"},{"id":"mj-0830","type":"judge","question":"火灾自动报警系统控制器的电源工作状态分为主备电工作状态、主电故障状态及备电故障状态。()","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《中级》新教材第4页。在集中报警系统中的火灾报警控制器、消防联动控制器、火灾报警控制器(联动控制型)等控制器的电源工作状态分为主电工作状态、备电工作状态、主电故障状态、备电故障状态。"},{"id":"mj-0831","type":"judge","question":"在消防控制室进行总机与所有消防电话分机、电话插孔之间互相呼叫与通话,呼叫铃声、通话应语音清晰,无振鸣。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"在消防控制室进行总机与所有消防电话分机、电话插孔之间互相呼叫与通话,呼叫铃声、通话应语音清晰,无振鸣。"},{"id":"mj-0832","type":"judge","question":"多线控制盘的手动启动与消防联动控制器是否正常无关,只需确保多线控制盘的电源打开,手动工作模式处于\"充许\"状态。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"多线控制盘的手动启动与消防联动控制器是否正常无关,只需确保多线控制盘的电源打开手动工作模式处于允许状态。故本题正确。"},{"id":"mj-0833","type":"judge","question":"玻璃球喷头的公称动作温度分为7档,由玻璃球工作液的不同颜色标示。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"按照现行国家标准《自动喷水灭火系统第1部分:洒水喷头》GB5135.1-2019的规定,应是“易熔元件洒水喷头的公称动作温度分为7档；玻璃球酒水喷头的公称动作温度分为13档”,结合题意,本题错误。"},{"id":"mj-0834","type":"judge","question":"测试机械加压送风系统的加压部位余压值时,通常使用数字风速仪测量前室和楼梯间余压值。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p237页,使用微压计分别测量前室和楼梯间余压值。"},{"id":"mj-0835","type":"judge","question":"同一建筑物内设置的消火栓消防软管卷盘和轻便水龙可以采用不同规格的栓口、消防水枪和水带及配件。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p226页,同一建筑物内设置的消火栓、消防软管卷盘和轻便水龙应采用统一规格的栓口、消防水枪、水带及配件。"},{"id":"mj-0836","type":"judge","question":"当风机电气控制柜的双电源转换开关控制按钮处于“手动\"位置时,只能通过人工进行供电状态切换。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能140页,控制柜内设有双电源转换开关,当控制按钮处于\"自动\"位置时,主电源发生故障后备用电源自动启用,主电源恢复后,自动切回主电源供电;当控制按钮处于“手动\"位置时,只能通过人工进行切换。"},{"id":"mj-0837","type":"judge","question":"挡烟垂壁的保养周期是每季度一次。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级172页,送风口、排风口、排烟防火阀、挡烟垂壁的保养周期为每半年一次。"},{"id":"mj-0838","type":"judge","question":"在消防控制室外增设的区域控制器可采用手动方式控制消防联动设备,且所有信息均应传送至集中控制器。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级技能28页,在消防控制室外增设的区域控制器均不应采用手动方式控制消防联动设备，且所有信息均应传送至集中控制器。"},{"id":"mj-0839","type":"judge","question":"消防控制室图形显示装置可查看报警信息和确定报警部位。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能16-17页,可通过以下两种方式查看报通过集中控制器警信息和确定报警部位:（1)通过集中控制器通过消防控查看报警信息和确定报警部位(2)通过消防控制室图形显示装置查看报警信息和确定报警部位。"},{"id":"mj-0840","type":"judge","question":"应急照明疏散指示系统在正常监视状态下,断开主电电源开关,故障指示灯点亮,主电工作指示灯熄灭,同时进入应急启动状态。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级教材169页,技能6如何操作应急照明控制器1.主电/备电切换主电测试。在系统正常监控状态下,断开主电电源开关,故障指示灯应点亮,主电工作指示灯熄灭,同时控制器应进入应急启动状态,并显示应急启动和主电故障信息。备电测试。在系统正常监控状态下,断开备电电源开关,故障指示灯应点亮,备电工作指示灯熄灭,同时控制器应进入应急启动状态,并显示应急启动和备电故障信息。"},{"id":"mj-0841","type":"judge","question":"集中火灾报警控制器不能间接地接收来自火灾探测器及其他火灾报警触发器件的火灾报警信号,发出火灾报警声、光信号,指示火灾发生部位,记录火灾报警时间。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"火灾报警控制器应能直接或间接地接收来自火灾探测器及其他火灾报警触发器件的火灾报警信号,发出火灾报警声、光信号,指示火灾发生部位,记录火灾报警时间。"},{"id":"mj-0842","type":"judge","question":"墙壁式消防水泵接合器可以安装在玻璃幕墙下方。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"墙壁式消防水泵接合器的安装应符合设计要求。设计无要求时,其安装高度距地面宜为0.7m。 与墙面上的门、窗、孔、洞的净距离不应小于2.0m,且不应安装在玻璃幕墙下方。"},{"id":"mj-0843","type":"judge","question":"消防设施操作员两个职业方向均分为5个职业技能等级。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"根据《基础知识》新教材6页。消防设施操作员职业一共设五个等级,其中,消防设施监控操作职业方向分为五级/初级工、四级/中级工、三级/高级工、二级/技师;消防设施检测维修保养职业方向分为四级/中工、三级/高级工、二级/技师、一级/高级技师。所以,两个职业方向均分为4个职业技能等级。"},{"id":"mj-0844","type":"judge","question":"气体灭火系统适用于扑救电气火灾。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"气体灭火系统适用于扑救电气火灾、固体表面火灾、液体火灾、灭火前能切断气源的气体火灾。"},{"id":"mj-0845","type":"judge","question":"正确处理个人、集体和国家三者之间的关系,这既是增强职业责任感的要求,也是职业道德的要求。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》》新教材4页。正确处理个人、集体和国家三者之间的关系,这既是增强职业责任感的要求,也是职业道德的要求。"},{"id":"mj-0846","type":"judge","question":"自动喷水灭火系统是由洒水喷头、报警阀组、水流报警装置等组件以及管道、供水设施等组成,能在发生火灾时喷水的自动灭火系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"自动喷水灭火系统是由洒水喷头、报警阀组、水流报警装置等组件以及管道、供水设施等组成,能在发生火灾时喷水的自动灭火系统。"},{"id":"mj-0847","type":"judge","question":"多线制控制盘也称作多线制手动控制盘或直接手手动控制盘。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"本题考查考生对多线控制盘的工作原理知识点的掌握情况。多线制控制盘也称作多线制手动控制盘或直接手动控制盘。结合题意,本题正确。"},{"id":"mj-0848","type":"judge","question":"计算机中的存储器按用途可分为主存储器(内存)和辅助存储器器（外存）,也有分为外部存储存和内部存储器的分类方法。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"计算机中的存诸器按用途可分为主存储器(内存)和辅助存储器(外存),也有分为外部存储器和内部存储器的分类方法。"},{"id":"mj-0849","type":"judge","question":"消防工作是一项地方性和专门性很强的行政工作,是政府履行社会管理和公共服务职能的重要内容。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"基础知8页知识点5,消防工作是一项地方性和专门性很强的行政工作,是政府履行社会管理和公共服务职能的重要内容。"},{"id":"mj-0850","type":"judge","question":"常闭式、常开式防火门的开启、关闭动作信号只能反馈至防火门监控器,不能传输至消防联动控器。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级245页,使用加烟器触发防火分区内2只独立火灾探测器或1只火灾探测器和1只手动火灾报警按钮,观察常开式防火门关闭情况、防火门监控器有关信息指示变化情况、消防控制室相关控制和信号反馈情况等。"},{"id":"mj-0851","type":"judge","question":"建筑高度大于50m的公共建筑、工业建筑和建筑高度大于100m的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室及消防电梯前室应采用机械加压送风系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级技能24页,防烟系统可分为自然通风系统和机械加压送风系统。建筑高度大于50m的公共建筑、工业建筑和建筑高度大于的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室及消防电梯前室应采用机械加压送风系统;建筑高度小于或等于50m的公共建筑、工业建筑和建筑高度小于或等于100m的住宅建筑,其防烟楼梯间、独立前室、共用前室、合用前室 (除共用前室与消防电梯前室合用外)及消防电梯前室应采用自然通风系统;当不能设置自然通风系统时,应采用机械加压送风系统。"},{"id":"mj-0852","type":"judge","question":"IG541灭火系统属于惰性气体灭火系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"1G541灭火系统属于情性气体灭火系统"},{"id":"mj-0853","type":"judge","question":"自燃点是指在规定的条件下，可燃物发生自燃的最低温度,可燃物的自燃点越低,发生火灾的危险性就越小。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"根据《基础知识》新教材18页。自燃点是指在规定的条件下，可燃物发生自燃的最低温度可燃物的自燃点越低,发生火灾的危险性就越大。"},{"id":"mj-0854","type":"judge","question":"疏散楼梯间、疏散楼梯间的前室或合用前室的疏散照明地面最低水平照度不应低于5.0lx。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"疏散楼梯间、疏散楼样间的前室或合用前室的疏散照明地面最低水平照度不应低于10.0lx。"},{"id":"mj-0855","type":"judge","question":"总线控制一般采用独立的手动控制单元,每个控制单元通过直接连接的导线和控制模块对应控制一个受控消防设备,属于点对点控制方式。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防联动控制器常用的联动控制方式主要有\"自动控制和手动控制”、“直接控制和间接控制\"、“总线控制和直线控制\"等3种。总线控制是指在总线上配接消防联动模块,当消防联动控制器接收到火灾报警信号并满足预设的逻辑时,发出启动信号,通过总线上所配接的控制模块完成消防联动控制功能。直线控制一般采用多线直线控制,即采用独立的手动控制单元,每个控制单元通过直接连接的导线和控制模块对应控制一个受控消防设备,属于点对点控制方式。"},{"id":"mj-0856","type":"judge","question":"稳压泵组的主、备泵应采用交替运行方式。投入消防运行状态后,稳压泵组应继续工作。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"本题考查考生消防增本题考查考生消防增(稳)压设施的运行控制知识点的掌握情况。稳压泵组的主、备泵应采用交替运行方式。当达到设计启动压力时,稳压泵应立即启动,当消防主泵启动时,稳压泵应停止运行。所以,投入消防运行状态后,稳压泵组应停止工作,而不是继续工作。结合题意,本题错误"},{"id":"mj-0857","type":"judge","question":"电路主要是由电源、负载、中间环节(导线和开关等)三个基本部分组成。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"电路主要是由电源、负载、中间环节（导线开关等)三个基本部分组成。"},{"id":"mj-0858","type":"judge","question":"消防应急广播系统的联动控制信号由消防联动控制器发出,当确认火灾后,应立即向着火楼层和相邻的上下两层进行广播。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"消防应急广播系统的联动控制信号应由消防联动控制器发出。当确认火灾后,应同时向全楼进行广播。"},{"id":"mj-0859","type":"judge","question":"点型火灾探测器的确认灯应面向便于人员核查的主要入口方向。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"点型火灾探测器的确认灯应面向便于人员核查的主要入口方向。"},{"id":"mj-0860","type":"judge","question":"一旦喷水灭火系统的电气控制柜出现缺相状况时,电气控制柜面板故障灯应常亮,并发出故障声、光信号。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p94页,电气控制柜具有过载、短路、过压、缺相、欠压、过热保护等功能。一旦出现以上状况,电气控制柜故障灯应常亮,并发出故障声、光信号。"},{"id":"mj-0861","type":"judge","question":"建筑高度大于54m但不大于100m的住宅建筑,其公共部位应设置火灾自动报警系统。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"建筑高度大于54m但不大于100m的住宅建筑其公共部位应设置火灾自动报警系统。"},{"id":"mj-0862","type":"judge","question":"火灾警报装置编码错误会造成火灾警报装置不发出声、光警示信息。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p50页,火灾警报装置编码错误会造成控制器显示警报装置故障。"},{"id":"mj-0863","type":"judge","question":"当手/自动转换开关处于\"手动\"位置时,风机可以通过电气控制柜启/停按钮现场控制,消防控制室远程手动控制仍然有效。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p140页,当手动/自动转换开关处于\"手动\"位置时,风机只能通过风机控制柜启动或停止按钮现场控制,消防控制室远程手动和自动联动控制均失效。"},{"id":"mj-0864","type":"judge","question":"在正常情况下有烟滞留的场所宜选择线型光束感烟火灾探测器。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"符合下列条件之一的场所,不宜选择线型光束感烟火灾探测器:1)有大量粉尘、水雾滞留的场所。2)可能产生蒸气和油雾的场所。 3)在正常情况下有烟滞留的场所。4)固定探测器的建筑结构由于振动等原因会产生较大位移的场所。"},{"id":"mj-0865","type":"judge","question":"一台集中火灾报警控制器(联动型)可以设置多个总线控制盘。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"一台集中火灾报警控制器(联动型)可以设置多个总线控制盘。"},{"id":"mj-0866","type":"judge","question":"机关、团体、企业、事业等单位是消防安全的责任主体,消防工作分管领导是本单位、本场所消防安全责任人,对本单位、本场所消防安全全面负责。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"机关、团体、企业、事业等单位是消防安全的责任主体,法定代表人、主要负责人或实际控制人是本单位、本场所消防安全责任人,对本单位、本场所消防安全全面负责。"},{"id":"mj-0867","type":"judge","question":"手动火灾报警按钮在工业和民用建筑中应用广泛,每个防火分区应至少设置2只手动火灾报警按钮。 ( )","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"防火分区是在建筑内部采用防火墙、楼板及其他防火分隔设施分隔而成,能在一定时间内防止火灾向同一建筑的其余部分蔓延的局部空间。为了确保及时发现初起火灾,充分发挥手动火灾报警按钮的作用,每个防火分区应至少口手动以报整按纽防区设置一只手动火灾报警按钮。从一个防火分区内的任何位置到最近的手动火灾报警按钮的步行距离不应大于30m。"},{"id":"mj-0868","type":"judge","question":"电气火灾监控设备关机前先断开备用电源开关再断开主电源空气开关。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"电气火灾监控设备关机前先断开备用电源开关再断开主电源空气开关。"},{"id":"mj-0869","type":"judge","question":"线型光束感烟火灾探测器分为激光光束线型感烟火灾探测器和红外光束线型感烟火灾探测器两种类型。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"线型光束感烟火灾探测器分为激光光束线型感烟火灾探测器和红外光束线型感烟火灾探测器两种类型。"},{"id":"mj-0870","type":"judge","question":"座板的功能是在防火卷帘下放后封堵洞口,阻止火灾蔓延和控制烟雾扩散。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"帘板(面)的功能是在防火卷帘下放后封堵洞口,阻止火灾蔓延和控制烟雾扩散。结合题意,本题错误。"},{"id":"mj-0871","type":"judge","question":"准入类职业资格,其所涉职业(工种)必须关系公共利益或涉及国家安全、公共安全、人身健康、生命财产安全,且只能以法律法规作为依据。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"根据《基础知识》新教材6页。准入类职业资格,其所涉职业(工种)必须关系公共利益或涉及国家安全、公共安全、人身健康、生命财产安全,且必须有法律法规或国务院决定作为依据,如消防设施操作员。所以,也可以以国务院决定作为依据。"},{"id":"mj-0872","type":"judge","question":"撤掉减光片,手动操作火灾报警控制器的复位键后,火灾报警控制应处于正常监视状态,线型光束感烟火灾探测器的火警确认灯应常亮。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p36页,撤掉减光片,手动操作火灾报警控制器的复位键后,如无其他触发器件发出报警信号,火灾报警控制器应处于正常监视状态,线型光束感烟火灾探测器的火警确认灯应熄灭。"},{"id":"mj-0873","type":"judge","question":"测试消防电话总机故障报警功能时,应使消防电话总机与所有电话分机和电话插孔之间的连接线断路、短路。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p73页,测试消防电话总机故障报警功能时,分别使消防电话总机与任一消防电话分机或消防电话插孔之间的连接线断路、短路。"},{"id":"mj-0874","type":"judge","question":"易燃、可燃液体在燃烧过程中,并不是液体本身在燃烧。( )","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"根据《基础知识》新教材20页。易燃、可燃液体在燃烧过程中,并不是液体本身在燃烧,而是液体受热时蒸发出来的蒸气被分解、氧化达到燃点而燃烧,即蒸发燃烧。"},{"id":"mj-0875","type":"judge","question":"确认现场发生火灾后,可以将集中火灾报警控制器、消防联动控制器从自动状态切换为手动状态。 ()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"确认现场发生火灾后,消防控制室值班人员应立即确认火灾报警联动控制开关处于自动状态。"},{"id":"mj-0876","type":"judge","question":"测试火灾自动报警系统联动功能时,火灾报警控制器应处于\"手动\"状态。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"测试火灾自动报警系统联动功能时,火灾报警控制器应处于\"自动\"状态。"},{"id":"mj-0877","type":"judge","question":"煤气着火属于A类火灾。()","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"煤气着火属于C类火灾。A类是指固体火灾,结合题意本题错误合题意,本题错误。"},{"id":"mj-0878","type":"judge","question":"应急照明控制器复位前,应确保火灾报警控制器已复位。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"应急照明控制器复位前,应确保火灾报警控制器已复位。"},{"id":"mj-0879","type":"judge","question":"消防电话总机能为消防电话分机供电,能与消防电话分机进行半双工通话。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级p22页,消防电话总机能为消防电话分机和能消防电话插孔供电,能与消防电话分机进行全双工通话。"},{"id":"mj-0880","type":"judge","question":"点型感温火灾探测器测试结束后,应移除热源,复位火灾报警控制器,查看点型感温火灾探测器报警确认灯是否熄灭,确认其恢复正常巡检状态。 （）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"中级p65,测试点型感温火灾探测器后,移开热源,复位火灾报警控制器,查看点型感温火灾探测器报警确认灯是否熄灭,确认其恢复正常巡检状态。"},{"id":"mj-0881","type":"judge","question":"当预先录制的播音内容不适应现场需求时,应当及时更换导入适用当前场景的播音内容后进行播音,避免因内容不符导致人员不能及时疏散。（）","options":[{"value":"正确","text":"正确","isCorrect":false},{"value":"错误","text":"错误","isCorrect":true}],"answer":"错误","explanation":"中级35页,当预先录制的播音内容不适应现场需求时,应当及时改用话筒进行临机广播。"},{"id":"mj-0882","type":"judge","question":"干式自动喷水灭火系统由于在准工作状态时配水管道内充满用于启动系统的有压气体,因此还应设置充气和气压维持装置。（）","options":[{"value":"正确","text":"正确","isCorrect":true},{"value":"错误","text":"错误","isCorrect":false}],"answer":"正确","explanation":"暂无解析"}]}]};
